function renderSeaRipples() {
  return LAND_BRIDGES.map((bridge, _index) => {
    const midX = (bridge.from.x + bridge.to.x) / 2;
    const midY = (bridge.from.y + bridge.to.y) / 2;
    const dx = bridge.to.x - bridge.from.x;
    const dy = bridge.to.y - bridge.from.y;
    const length = Math.hypot(dx, dy) || 1;
    const nx = -dy / length;
    const ny = dx / length;
    const offset = bridge.width * 0.95;
    return `
      <path class="world-sea-ripple" d="M ${formatPathNumber(midX - nx * offset - dx * 0.34)} ${formatPathNumber(midY - ny * offset - dy * 0.34)} Q ${formatPathNumber(midX - nx * offset * 1.12)} ${formatPathNumber(midY - ny * offset * 1.12)} ${formatPathNumber(midX - nx * offset + dx * 0.34)} ${formatPathNumber(midY - ny * offset + dy * 0.34)}"></path>
      <path class="world-sea-ripple" d="M ${formatPathNumber(midX + nx * offset - dx * 0.34)} ${formatPathNumber(midY + ny * offset - dy * 0.34)} Q ${formatPathNumber(midX + nx * offset * 1.12)} ${formatPathNumber(midY + ny * offset * 1.12)} ${formatPathNumber(midX + nx * offset + dx * 0.34)} ${formatPathNumber(midY + ny * offset + dy * 0.34)}"></path>
    `;
  }).join("");
}

function renderSeaSparkles(bounds = { left: 0, top: 0, right: WORLD_WIDTH, bottom: WORLD_HEIGHT, width: WORLD_WIDTH, height: WORLD_HEIGHT }) {
  const random = createSeededRandom(`sea:${WORLD_SCHEMA_VERSION}:${bounds.regionId || "world"}:${bounds.width}:${bounds.height}`);
  const sparkles = [];
  const count = Math.max(18, Math.round((bounds.width * bounds.height) / 170000));
  for (let i = 0; i < count; i += 1) {
    let x = 0;
    let y = 0;
    for (let attempt = 0; attempt < 24; attempt += 1) {
      x = Math.round(bounds.left + random() * bounds.width);
      y = Math.round(bounds.top + random() * bounds.height);
      if (!isWorldLandPoint(x, y, 120)) break;
    }
    const rx = 10 + random() * 22;
    const ry = 2.5 + random() * 5;
    const rot = random() * 180;
    const opacity = 0.22 + random() * 0.34;
    sparkles.push(`<ellipse class="world-sea-sparkle" cx="${x}" cy="${y}" rx="${formatPathNumber(rx)}" ry="${formatPathNumber(ry)}" opacity="${formatPathNumber(opacity)}" transform="rotate(${formatPathNumber(rot)} ${x} ${y})"></ellipse>`);
  }
  return sparkles.join("");
}

function renderWorldRegionShore(region) {
  return `<ellipse class="world-shore-glow" cx="${region.x}" cy="${region.y}" rx="${region.rx}" ry="${region.ry}" transform="rotate(${((region.rot || 0) * 180 / Math.PI).toFixed(2)} ${region.x} ${region.y})"></ellipse>
    <ellipse class="world-beach" cx="${region.x}" cy="${region.y}" rx="${region.rx}" ry="${region.ry}" transform="rotate(${((region.rot || 0) * 180 / Math.PI).toFixed(2)} ${region.x} ${region.y})"></ellipse>
    <ellipse class="world-shore-line" cx="${region.x}" cy="${region.y}" rx="${region.rx}" ry="${region.ry}" transform="rotate(${((region.rot || 0) * 180 / Math.PI).toFixed(2)} ${region.x} ${region.y})"></ellipse>`;
}

function renderWorldRegion(region) {
  return `<ellipse class="world-land ${region.palette || "heartland"}" cx="${region.x}" cy="${region.y}" rx="${region.rx}" ry="${region.ry}" transform="rotate(${((region.rot || 0) * 180 / Math.PI).toFixed(2)} ${region.x} ${region.y})"></ellipse>`;
}

function renderWorldBridgeShore(bridge) {
  return `<line class="world-causeway-shore" x1="${bridge.from.x}" y1="${bridge.from.y}" x2="${bridge.to.x}" y2="${bridge.to.y}" stroke-width="${bridge.width + 72}"></line>`;
}

function renderWorldBridge(bridge) {
  return `<line class="world-causeway" x1="${bridge.from.x}" y1="${bridge.from.y}" x2="${bridge.to.x}" y2="${bridge.to.y}" stroke-width="${bridge.width}"></line>`;
}

function renderWorldRegionTexture(region) {
  const random = createSeededRandom(`region-texture:${WORLD_SCHEMA_VERSION}:${region.id}`);
  const details = [];
  const clearingRatio = getRegionStrongholdReserveRatio(region);
  if (clearingRatio > 0) {
    details.push(`<ellipse class="world-center-clearing" cx="${region.x}" cy="${region.y}" rx="${formatPathNumber(region.cityRx * clearingRatio * 0.8)}" ry="${formatPathNumber(region.cityRy * clearingRatio * 0.72)}" transform="rotate(${((region.rot || 0) * 180 / Math.PI).toFixed(2)} ${region.x} ${region.y})"></ellipse>`);
  }

  for (let i = 0; i < 10; i += 1) {
    const point = getRegionTexturePoint(region, random, 0.26, 0.82);
    const rx = region.rx * (0.035 + random() * 0.045);
    const ry = region.ry * (0.025 + random() * 0.04);
    const rot = ((region.rot || 0) + (random() - 0.5) * 1.1) * 180 / Math.PI;
    details.push(`<ellipse class="world-meadow" cx="${formatPathNumber(point.x)}" cy="${formatPathNumber(point.y)}" rx="${formatPathNumber(rx)}" ry="${formatPathNumber(ry)}" transform="rotate(${formatPathNumber(rot)} ${formatPathNumber(point.x)} ${formatPathNumber(point.y)})"></ellipse>`);
  }

  for (let i = 0; i < 8; i += 1) {
    const point = getRegionTexturePoint(region, random, 0.35, 0.88);
    const rx = region.rx * (0.05 + random() * 0.05);
    const ry = region.ry * (0.018 + random() * 0.025);
    const rot = ((region.rot || 0) + (random() - 0.5) * 1.6) * 180 / Math.PI;
    details.push(`<ellipse class="world-hill" cx="${formatPathNumber(point.x)}" cy="${formatPathNumber(point.y)}" rx="${formatPathNumber(rx)}" ry="${formatPathNumber(ry)}" transform="rotate(${formatPathNumber(rot)} ${formatPathNumber(point.x)} ${formatPathNumber(point.y)})"></ellipse>`);
  }

  return details.join("");
}

function getRegionTexturePoint(region, random, minRadius, maxRadius) {
  const angle = random() * Math.PI * 2;
  const radius = minRadius + random() * (maxRadius - minRadius);
  const cos = Math.cos(region.rot || 0);
  const sin = Math.sin(region.rot || 0);
  const localX = Math.cos(angle) * region.cityRx * radius;
  const localY = Math.sin(angle) * region.cityRy * radius;
  return {
    x: region.x + localX * cos - localY * sin,
    y: region.y + localX * sin + localY * cos,
  };
}

function renderWorldSoftTerrain(shape) {
  const className = shape.type === "swamp" ? "world-swamp" : "world-forest";
  return `<ellipse class="${className}" cx="${formatPathNumber(shape.x)}" cy="${formatPathNumber(shape.y)}" rx="${shape.rx}" ry="${shape.ry}" transform="rotate(${((shape.rot || 0) * 180 / Math.PI).toFixed(2)} ${formatPathNumber(shape.x)} ${formatPathNumber(shape.y)})"></ellipse>`;
}

function renderWorldMountain(shape) {
  return `<ellipse class="world-mountain" cx="${formatPathNumber(shape.x)}" cy="${formatPathNumber(shape.y)}" rx="${shape.rx}" ry="${shape.ry}" transform="rotate(${((shape.rot || 0) * 180 / Math.PI).toFixed(2)} ${formatPathNumber(shape.x)} ${formatPathNumber(shape.y)})"></ellipse>`;
}

function renderWorldRegionLabel(region) {
  return `<text class="world-region-label" x="${region.x}" y="${region.y - region.ry * 0.05}">${escapeHtml(region.label || region.id)}</text>`;
}

function cloneBaseCities(playerName) {
  const island = createIslandStartLayout(playerName);
  return island.cities;
}

function getPlayableBaseCities() {
  if (playableBaseCitiesCache) return playableBaseCitiesCache;
  playableBaseCitiesCache = generateWorldCitySlots();
  return playableBaseCitiesCache;
}

function getPlayableBaseCityById(cityId) {
  const id = String(cityId || "");
  if (!id) return null;
  if (!playableBaseCitiesByIdCache) {
    playableBaseCitiesByIdCache = new Map(getPlayableBaseCities().map(city => [city.id, city]));
  }
  return playableBaseCitiesByIdCache.get(id) || null;
}

function getPlayableBaseCitiesByRegion(regionId = getActiveOnlineRegionId()) {
  const normalizedRegionId = normalizeRegionId(regionId);
  if (!playableBaseCitiesByRegionCache) playableBaseCitiesByRegionCache = new Map();
  if (!playableBaseCitiesByRegionCache.has(normalizedRegionId)) {
    playableBaseCitiesByRegionCache.set(
      normalizedRegionId,
      getPlayableBaseCities().filter(city => getCityRegionId(city) === normalizedRegionId)
    );
  }
  return playableBaseCitiesByRegionCache.get(normalizedRegionId) || [];
}

function createIslandStartLayout(_playerName) {
  const cities = getPlayableBaseCities().map(createNeutralCityFromBase);

  const startIds = pickStartCities(cities);
  const assignments = [
    { key: "player", owner: "player", troops: PLAYER_START_TROOPS },
  ];

  for (const slot of assignments) {
    const city = cities.find(item => item.id === startIds[slot.key]);
    if (!city) continue;
    city.owner = slot.owner;
    if (slot.name) city.name = slot.name;
    city.troops = slot.troops;
    city.troopFloat = slot.troops;
    city.level = 1;
    city.defense = 1;
    city.investedGold = 0;
    city.lastCapturedAt = null;
    city.isMainCity = slot.key === "player";
    city.relinquishedAtMs = 0;
    city.relocatedAtMs = 0;
  }

  return { cities, startIds };
}

function pickStartCities(cities) {
  const fallbackAnchors = getStartCityAnchors();

  const used = new Set();
  const result = {};

  for (const [key, config] of Object.entries(fallbackAnchors)) {
    const pool = cities.filter(city => city.startPool === config.pool && !used.has(city.id) && !isStronghold(city));
    let chosen = randomChoice(pool);
    if (!chosen) {
      const available = cities
        .filter(city => !used.has(city.id) && !isStronghold(city))
        .sort((a, b) => Math.hypot(a.x - config.x, a.y - config.y) - Math.hypot(b.x - config.x, b.y - config.y));
      chosen = available[0];
    }
    if (chosen) {
      used.add(chosen.id);
      result[key] = chosen.id;
    }
  }

  return result;
}

function pickDeterministicStartCities(cities) {
  const anchors = getStartCityAnchors();
  const used = new Set();
  const result = {};

  for (const [key, config] of Object.entries(anchors)) {
    const chosen = cities
      .filter(city => city.startPool === config.pool && !used.has(city.id) && !isStronghold(city))
      .sort((a, b) => Math.hypot(a.x - config.x, a.y - config.y) - Math.hypot(b.x - config.x, b.y - config.y))[0];
    if (chosen) {
      used.add(chosen.id);
      result[key] = chosen.id;
    }
  }

  return result;
}

function getStartCityAnchors() {
  const center = getRegionById("center") || WORLD_REGIONS[0] || { x: WORLD_WIDTH / 2, y: WORLD_HEIGHT / 2, id: "center" };
  const north = getRegionById("north") || center;
  const west = getRegionById("west") || center;
  const east = getRegionById("east") || center;
  const south = getRegionById("south") || center;
  return {
    player: { x: west.x - west.cityRx * 0.18, y: west.y, pool: west.id },
    north: { x: north.x, y: north.y - north.cityRy * 0.26, pool: north.id },
    west: { x: west.x - west.cityRx * 0.24, y: west.y, pool: west.id },
    east: { x: east.x + east.cityRx * 0.24, y: east.y, pool: east.id },
    south: { x: south.x, y: south.y + south.cityRy * 0.26, pool: south.id },
  };
}

function createOnlineIslandSeed(regionId = DEFAULT_ONLINE_REGION_ID) {
  const baseCities = getOnlineIslandBaseCities(regionId);
  const startIds = pickDeterministicStartCities(baseCities);
  const cities = baseCities.map(createNeutralCityFromBase);
  const targetRegionId = normalizeRegionId(regionId);
  const camps = WORLD_CAMPS
    .filter(camp => normalizeRegionId(camp.regionId) === targetRegionId && getRewardCampConfig(camp))
    .map(camp => {
      const config = getRewardCampConfig(camp);
      return {
        ...camp,
        name: config.name,
        mapId: targetRegionId,
        rewardType: config.rewardType,
        holdDurationMs: config.holdSeconds * 1000,
        baseReward: config.baseReward,
        baseDefenders: config.baseDefenders,
        combatVersion: config.combatVersion,
        troopPower: config.troopPower,
      };
    });

  return {
    regionId: targetRegionId,
    cities,
    camps,
    startIds,
    claimCandidateIds: getOnlineClaimCandidateIds(cities, startIds),
  };
}

function getOnlineIslandSeedMeta(regionId, seed) {
  const targetRegionId = normalizeRegionId(regionId);
  return {
    worldId: ONLINE_WORLD_ID,
    legacyWorldId: ONLINE_LEGACY_ISLAND_ID,
    regionId: targetRegionId,
    regionName: getRegionLabel(targetRegionId),
    version: WORLD_SCHEMA_VERSION,
    name: `${getRegionLabel(targetRegionId)} - ${WORLD_CONFIG.name || "Crownlands"}`,
    cityCount: seed.cities.length,
    regionCount: WORLD_REGIONS.length,
    cityCountPerRegion: REGION_CITY_COUNT,
    worldWidth: WORLD_WIDTH,
    worldHeight: WORLD_HEIGHT,
  };
}

async function ensureOnlineIslandSeeded(regionId, timeoutMs = 20000) {
  const api = getOnlineApi();
  const targetRegionId = normalizeRegionId(regionId);
  const seed = createOnlineIslandSeed(targetRegionId);
  if (!api?.ensureMainIsland || verifiedOnlineIslandSeeds.has(targetRegionId)) return seed;
  await withTimeout(api.ensureMainIsland({
    islandId: getOnlineIslandId(targetRegionId),
    regionId: targetRegionId,
  }), timeoutMs, `${getRegionLabel(targetRegionId)} setup is taking too long.`);
  verifiedOnlineIslandSeeds.add(targetRegionId);
  return seed;
}

function getOnlineClaimCandidateIds(cities, startIds) {
  const selected = [];
  const used = new Set();
  [startIds.north, startIds.south, startIds.west, startIds.east, startIds.player]
    .filter(Boolean)
    .forEach(cityId => {
      if (used.has(cityId)) return;
      selected.push(cityId);
      used.add(cityId);
    });
  const outerCities = cities.filter(city => city.regionId !== "center" && !isStronghold(city));
  const centerCities = cities.filter(city => city.regionId === "center" && !isStronghold(city));

  appendSpacedClaimCandidates(outerCities, selected, used);
  appendSpacedClaimCandidates(centerCities, selected, used);

  return selected;
}

function appendSpacedClaimCandidates(cities, selected, used) {
  while (true) {
    let bestCity = null;
    let bestSpacing = -Infinity;
    for (const city of cities) {
      if (used.has(city.id)) continue;
      const nearest = selected.length
        ? Math.min(...selected.map(id => {
            const other = cities.find(item => item.id === id);
            return other ? Math.hypot(city.x - other.x, city.y - other.y) : Infinity;
          }))
        : Infinity;
      if (nearest > bestSpacing) {
        bestSpacing = nearest;
        bestCity = city;
      }
    }
    if (!bestCity) break;
    selected.push(bestCity.id);
    used.add(bestCity.id);
  }
}

function newGame(playerName) {
  const island = createIslandStartLayout(playerName);
  return {
    version: WORLD_SCHEMA_VERSION,
    playerName,
    character: createCharacterProgress(),
    flag: createRandomFlag(),
    gold: TEST_STARTING_GOLD,
    gameSeconds: 0,
    lastRealTimeMs: Date.now(),
    upgrades: createDefaultSkills(),
    skillPresets: createDefaultSkillPresets(),
    freeSkillResetGrantVersion: 0,
    freeSkillResetCredits: 0,
    shopItems: createDefaultShopItems(),
    gear: normalizeCommonGearState(),
    itemEffects: createDefaultItemEffects(),
    itemPurchaseCooldowns: createDefaultItemPurchaseCooldowns(),
    globalStats: null,
    daily: { date: currentDailyDateKey(), neutralCaptures: 0, harvestedBonuses: 0, harvestedGoldBonuses: 0, harvestedTroopBonuses: 0 },
    harvestBonuses: [],
    harvestSpawnTimer: HARVEST_BONUS_INITIAL_SPAWN_SECONDS,
    harvestNextSpawnAtMs: Date.now() + HARVEST_BONUS_INITIAL_SPAWN_SECONDS * 1000,
    harvestNextBonusType: "gold",
    scoutReports: {},
    battleReports: [],
    reportsViewedAtMs: 0,
    realmAnnouncementSeenThroughMs: 0,
    lastRealmAnnouncementEventId: "",
    marchPercent: DEFAULT_MARCH_PERCENT,
    mainCityId: island.startIds.player,
    mainCityChangedAtMs: 0,
    lastCityRelinquishedAtMs: 0,
    islandSlots: island.startIds,
    cities: island.cities,
    attacks: [],
    log: [`Five-island conquest started with ${ISLAND_CITY_COUNT} city slots across individual island maps.`],
    gameOver: null,
  };
}

function createDefaultShopItems() {
  return SHOP_ITEMS.reduce((inventory, item) => {
    inventory[item.id] = 0;
    return inventory;
  }, {});
}

function normalizeShopItems(items) {
  const normalized = createDefaultShopItems();
  if (!items || typeof items !== "object") return normalized;
  SHOP_ITEMS.forEach(item => {
    const hasCanonicalCount = Object.prototype.hasOwnProperty.call(items, item.id);
    const canonicalCount = Math.max(0, Math.floor(Number(items[item.id]) || 0));
    const legacyCount = (item.legacyIds || []).reduce((total, legacyId) => (
      total + Math.max(0, Math.floor(Number(items[legacyId]) || 0))
    ), 0);
    const hasLegacyCount = legacyCount > 0 && (item.legacyIds || []).some(legacyId => (
      Object.prototype.hasOwnProperty.call(items, legacyId)
    ));
    normalized[item.id] = hasCanonicalCount
      ? (hasLegacyCount ? Math.min(canonicalCount, legacyCount) : canonicalCount)
      : legacyCount;
  });
  return normalized;
}

function ensureShopItems() {
  if (!state) return createDefaultShopItems();
  const normalized = normalizeShopItems(state.shopItems);
  if (!state.shopItems || typeof state.shopItems !== "object" || Array.isArray(state.shopItems)) {
    state.shopItems = normalized;
  } else {
    Object.assign(state.shopItems, normalized);
  }
  return state.shopItems;
}

function createDefaultItemPurchaseCooldowns() {
  return Object.fromEntries(
    Object.keys(ITEM_DAILY_PURCHASE_LIMITS)
      .map(itemId => [itemId, { utcDate: "", purchaseCount: 0 }])
  );
}

function getUtcDateKeyAtMs(value = Date.now()) {
  const parsed = Number(value);
  const date = new Date(Number.isFinite(parsed) ? parsed : Date.now());
  return date.toISOString().slice(0, 10);
}

function getNextUtcDayStartMs(value = Date.now()) {
  const parsed = Number(value);
  const date = new Date(Number.isFinite(parsed) ? parsed : Date.now());
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate() + 1);
}

function getCityRelinquishPolicy(lastCityRelinquishedAtMs = state?.lastCityRelinquishedAtMs, nowMs = Date.now()) {
  const parsedNow = Number(nowMs);
  const currentTime = Math.max(0, Number.isFinite(parsedNow) ? parsedNow : Date.now());
  const lastRelinquishedAtMs = normalizeTimestampMs(lastCityRelinquishedAtMs);
  const utcDate = getUtcDateKeyAtMs(currentTime);
  const used = lastRelinquishedAtMs > 0 && getUtcDateKeyAtMs(lastRelinquishedAtMs) === utcDate;
  return {
    limit: CITY_RELINQUISH_DAILY_LIMIT,
    utcDate,
    used,
    lastCityRelinquishedAtMs: lastRelinquishedAtMs,
    availableAtMs: used ? getNextUtcDayStartMs(currentTime) : 0,
  };
}

function getCityRelinquishCooldownText(nowMs = Date.now()) {
  const policy = getCityRelinquishPolicy(state?.lastCityRelinquishedAtMs, nowMs);
  const remainingMs = policy.used ? Math.max(0, policy.availableAtMs - nowMs) : 0;
  return remainingMs > 0 ? formatDuration(Math.ceil(remainingMs / 1000)) : "";
}

function normalizeItemPurchaseTimestamps(value = {}) {
  const rawTimestamps = Array.isArray(value?.purchaseTimestampsMs)
    ? value.purchaseTimestampsMs
    : Array.isArray(value?.purchaseTimestamps)
      ? value.purchaseTimestamps
      : [];
  return rawTimestamps
    .map(timestampToMs)
    .filter(timestamp => timestamp > 0)
    .sort((a, b) => a - b)
    .slice(-MAX_ITEM_DAILY_PURCHASE_LIMIT);
}

function normalizeDailyItemPurchaseCounter(value = {}, limit = 0) {
  const safeLimit = Math.max(0, Math.floor(Number(limit) || 0));
  const explicitDate = String(value?.utcDate || value?.date || "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(explicitDate)) {
    return {
      utcDate: explicitDate,
      purchaseCount: Math.min(safeLimit, Math.max(0, Math.floor(Number(value?.purchaseCount ?? value?.count) || 0))),
    };
  }

  const legacyTimestamps = normalizeItemPurchaseTimestamps(value);
  const lastPurchasedAtMs = timestampToMs(value?.lastPurchasedAtMs || value?.lastPurchasedAt);
  if (lastPurchasedAtMs > 0) legacyTimestamps.push(lastPurchasedAtMs);
  if (!legacyTimestamps.length) return { utcDate: "", purchaseCount: 0 };

  const latestPurchaseAtMs = Math.max(...legacyTimestamps);
  const utcDate = getUtcDateKeyAtMs(latestPurchaseAtMs);
  const purchaseCount = legacyTimestamps.filter(timestamp => getUtcDateKeyAtMs(timestamp) === utcDate).length;
  return {
    utcDate,
    purchaseCount: Math.min(safeLimit, purchaseCount),
  };
}

function getItemDailyPurchaseLimit(itemId) {
  return Math.max(0, Math.floor(Number(ITEM_DAILY_PURCHASE_LIMITS[itemId]) || 0));
}

function normalizeItemPurchaseCooldowns(cooldowns = {}) {
  const normalized = createDefaultItemPurchaseCooldowns();
  Object.keys(ITEM_DAILY_PURCHASE_LIMITS).forEach(itemId => {
    normalized[itemId] = normalizeDailyItemPurchaseCounter(
      cooldowns?.[itemId],
      getItemDailyPurchaseLimit(itemId)
    );
  });
  return normalized;
}

function ensureItemPurchaseCooldowns() {
  if (!state) return createDefaultItemPurchaseCooldowns();
  const normalized = normalizeItemPurchaseCooldowns(state.itemPurchaseCooldowns);
  if (!state.itemPurchaseCooldowns || typeof state.itemPurchaseCooldowns !== "object" || Array.isArray(state.itemPurchaseCooldowns)) {
    state.itemPurchaseCooldowns = normalized;
  } else {
    Object.assign(state.itemPurchaseCooldowns, normalized);
  }
  return state.itemPurchaseCooldowns;
}

function getItemPurchaseStatus(itemId, cooldowns = ensureItemPurchaseCooldowns(), now = Date.now()) {
  const limit = getItemDailyPurchaseLimit(itemId);
  const currentTime = Math.max(0, Number(now) || Date.now());
  if (limit <= 0) return { count: 0, limit: 0, remainingMs: 0, utcDate: getUtcDateKeyAtMs(currentTime) };
  const today = getUtcDateKeyAtMs(currentTime);
  const counter = normalizeDailyItemPurchaseCounter(cooldowns?.[itemId], limit);
  const count = counter.utcDate === today ? Math.min(limit, counter.purchaseCount) : 0;
  return {
    count,
    limit,
    remainingMs: count >= limit ? Math.max(0, getNextUtcDayStartMs(currentTime) - currentTime) : 0,
    utcDate: today,
  };
}

function getItemPurchaseCooldownRemainingMs(itemId, now = Date.now()) {
  return getItemPurchaseStatus(itemId, ensureItemPurchaseCooldowns(), now).remainingMs;
}

function getItemPurchaseCount(itemId, now = Date.now()) {
  return getItemPurchaseStatus(itemId, ensureItemPurchaseCooldowns(), now).count;
}

function recordItemPurchase(itemId, purchasedAtMs = Date.now()) {
  const limit = getItemDailyPurchaseLimit(itemId);
  if (limit <= 0) return;
  const cooldowns = ensureItemPurchaseCooldowns();
  const status = getItemPurchaseStatus(itemId, cooldowns, purchasedAtMs);
  cooldowns[itemId] = {
    utcDate: status.utcDate,
    purchaseCount: Math.min(limit, status.count + 1),
  };
}

function getItemPurchaseCooldownText(itemId, now = Date.now()) {
  const remainingMs = getItemPurchaseCooldownRemainingMs(itemId, now);
  return remainingMs > 0 ? formatDuration(Math.ceil(remainingMs / 1000)) : "";
}

function createDefaultItemEffects() {
  return {
    shieldExpiresAtMs: 0,
    warDrumsExpiresAtMs: 0,
    royalTaxDecreeExpiresAtMs: 0,
    veilOfSilenceExpiresAtMs: 0,
  };
}

function normalizeItemEffects(effects = {}) {
  return {
    shieldExpiresAtMs: timestampToMs(effects?.shieldExpiresAtMs || effects?.shieldExpiresAt),
    warDrumsExpiresAtMs: timestampToMs(effects?.warDrumsExpiresAtMs || effects?.warDrumsExpiresAt || effects?.troopBoostExpiresAtMs || effects?.troopBoostExpiresAt),
    royalTaxDecreeExpiresAtMs: timestampToMs(effects?.royalTaxDecreeExpiresAtMs || effects?.royalTaxDecreeExpiresAt),
    veilOfSilenceExpiresAtMs: timestampToMs(effects?.veilOfSilenceExpiresAtMs || effects?.veilOfSilenceExpiresAt || effects?.antiScoutExpiresAtMs || effects?.antiScoutExpiresAt),
  };
}

function ensureItemEffects() {
  if (!state) return createDefaultItemEffects();
  const normalized = normalizeItemEffects(state.itemEffects);
  if (!state.itemEffects || typeof state.itemEffects !== "object" || Array.isArray(state.itemEffects)) {
    state.itemEffects = normalized;
  } else {
    Object.assign(state.itemEffects, normalized);
  }
  return state.itemEffects;
}

function getActiveTimedItemEffectExpiresAtMs(effectKey) {
  const effects = ensureItemEffects();
  const expiresAtMs = normalizeTimestampMs(effects[effectKey]);
  if (expiresAtMs && expiresAtMs <= Date.now()) {
    effects[effectKey] = 0;
    return 0;
  }
  return expiresAtMs;
}

function getActivePeaceShieldExpiresAtMs() {
  return getActiveTimedItemEffectExpiresAtMs("shieldExpiresAtMs");
}

function getActiveWarDrumsExpiresAtMs() {
  return getActiveTimedItemEffectExpiresAtMs("warDrumsExpiresAtMs");
}

function getActiveRoyalTaxDecreeExpiresAtMs() {
  return getActiveTimedItemEffectExpiresAtMs("royalTaxDecreeExpiresAtMs");
}

function getActiveVeilOfSilenceExpiresAtMs() {
  return getActiveTimedItemEffectExpiresAtMs("veilOfSilenceExpiresAtMs");
}

function getInventoryItemActiveExpiresAtMs(item) {
  if (!item) return 0;
  if (item.id === ROYAL_PEACE_SHIELD_ITEM_ID) return getActivePeaceShieldExpiresAtMs();
  if (item.id === WAR_DRUMS_ITEM_ID) return getActiveWarDrumsExpiresAtMs();
  if (item.id === ROYAL_TAX_DECREE_ITEM_ID) return getActiveRoyalTaxDecreeExpiresAtMs();
  if (item.id === VEIL_OF_SILENCE_ITEM_ID) return getActiveVeilOfSilenceExpiresAtMs();
  return 0;
}

function getInventoryItemActiveRemainingSeconds(item) {
  return getPeaceShieldRemainingSeconds(getInventoryItemActiveExpiresAtMs(item));
}

function isStackableTimedInventoryItem(itemOrId) {
  const itemId = typeof itemOrId === "object" ? itemOrId?.id : itemOrId;
  return itemId === WAR_DRUMS_ITEM_ID || itemId === ROYAL_TAX_DECREE_ITEM_ID;
}

function getWarDrumsTroopProductionBonusPercent() {
  return getActiveWarDrumsExpiresAtMs() ? WAR_DRUMS_TROOP_PRODUCTION_BONUS_PERCENT : 0;
}

function getPeaceShieldRemainingSeconds(expiresAtMs = getActivePeaceShieldExpiresAtMs()) {
  return Math.max(0, Math.ceil((normalizeTimestampMs(expiresAtMs) - Date.now()) / 1000));
}

function getCityPeaceShieldExpiresAtMs(city) {
  if (!city || isStronghold(city)) return 0;
  const expiresAtMs = city.owner === "player"
    ? getActivePeaceShieldExpiresAtMs()
    : normalizeTimestampMs(city.ownerShieldExpiresAtMs);
  return expiresAtMs > Date.now() ? expiresAtMs : 0;
}

function isCityProtectedByPeaceShield(city) {
  if (!city || city.owner === "neutral" || isStronghold(city)) return false;
  return getCityPeaceShieldExpiresAtMs(city) > Date.now();
}

function isAnotherPlayerOwnedCity(city) {
  if (!city || city.owner === "neutral") return false;
  const currentUid = getCurrentOnlineUid();
  const ownerUid = String(city.ownerUid || "").trim();
  if (city.owner === "player") return false;
  if (ownerUid && currentUid) return ownerUid !== currentUid;
  if (city.ownerKind === "player") return true;
  return city.owner === "enemy";
}

function isSameAttackOwner(target, attackerOwner = "player", attackerOwnerUid = "") {
  if (!target || target.owner === "neutral") return false;
  const targetOwnerUid = String(target.ownerUid || "").trim();
  const incomingOwnerUid = String(attackerOwnerUid || "").trim();
  if (targetOwnerUid && incomingOwnerUid) return targetOwnerUid === incomingOwnerUid;
  if (attackerOwner === "player") {
    const currentUid = getCurrentOnlineUid();
    return target.owner === "player" || Boolean(currentUid && targetOwnerUid && targetOwnerUid === currentUid);
  }
  return target.owner === attackerOwner && !targetOwnerUid && !incomingOwnerUid;
}

function getPeaceShieldAttackBlockReason(target, attackerOwner = "player", attackerOwnerUid = "") {
  if (!target || isSameAttackOwner(target, attackerOwner, attackerOwnerUid)) return "";
  if (!isCityProtectedByPeaceShield(target)) return "";
  const remaining = getPeaceShieldRemainingSeconds(getCityPeaceShieldExpiresAtMs(target));
  return `${target.name} is protected by a Royal Peace Shield for ${formatDuration(remaining)}.`;
}

function refreshOwnedCityItemEffectMetadata(syncNow = true) {
  if (!state) return;
  const shieldExpiresAtMs = getActivePeaceShieldExpiresAtMs();
  playerCities().forEach(city => {
    city.ownerShieldExpiresAtMs = isStronghold(city) ? 0 : shieldExpiresAtMs;
    markOwnedCityChanged(city, false);
  });
  if (onlineOwnedCitiesCache.length) {
    onlineOwnedCitiesCache = onlineOwnedCitiesCache.map(city => (
      isStronghold(city)
        ? { ...city, ownerShieldExpiresAtMs: 0 }
        : { ...city, ownerShieldExpiresAtMs: shieldExpiresAtMs }
    ));
  }
  if (syncNow && isOnlineWorldActive()) syncOwnedCitiesToOnline(true);
}

async function syncPeaceShieldToAllOwnedCities(expiresAtMs = getActivePeaceShieldExpiresAtMs()) {
  if (!state) return false;
  if (usesServerEconomyAuthority()) {
    refreshOwnedCityItemEffectMetadata(true);
    renderCities(true);
    renderHud();
    return true;
  }
  const api = getOnlineApi();
  if (!api?.isSignedIn?.() || !api?.loadOwnedCitiesAcrossIslands || !api?.savePlayerCities) {
    refreshOwnedCityItemEffectMetadata(true);
    return false;
  }

  try {
    const islandIds = getRegionIds().map(getOnlineIslandId);
    const owned = await withTimeout(
      api.loadOwnedCitiesAcrossIslands(islandIds),
      6500,
      "Shield city lookup is taking too long."
    );
    const normalized = (Array.isArray(owned) ? owned : [])
      .map(city => normalizeOwnedCitySnapshot({
        ...city,
        islandId: city.islandId || getOnlineIslandId(getCityRegionId(city)),
      }))
      .filter(Boolean);
    const nextShieldExpiresAtMs = normalizeTimestampMs(expiresAtMs);
    const byIsland = new Map();
    normalized.forEach(city => {
      const nextCity = {
        ...city,
        ownerShieldExpiresAtMs: isStronghold(city) ? 0 : nextShieldExpiresAtMs,
      };
      const islandId = nextCity.islandId || getOnlineIslandId(getCityRegionId(nextCity));
      if (!byIsland.has(islandId)) byIsland.set(islandId, []);
      byIsland.get(islandId).push(nextCity);
    });

    await Promise.all([...byIsland.entries()].map(([islandId, cities]) => api.savePlayerCities(islandId, cities)));
    mergeOwnedCitySnapshots(normalized.map(city => ({
      ...city,
      ownerShieldExpiresAtMs: isStronghold(city) ? 0 : nextShieldExpiresAtMs,
    })), { complete: true });
    renderCities(true);
    renderHud();
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    console.warn("Could not sync peace shield across owned cities", error);
    return false;
  }
}

async function syncPlayerIdentityToAllOwnedCities({ forceLeaderboard = true } = {}) {
  if (!state) return false;
  const api = getOnlineApi();
  const currentUid = getCurrentOnlineUid();
  const nextFlag = normalizeFlag(state.flag);
  const nextOwnerName = state.playerName || getOnlineApi()?.getUser?.()?.displayName || "Ruler";
  const nextKingPower = getKingPower();
  rememberCurrentPlayerIdentity();

  playerCities().forEach(city => {
    city.ownerKind = "player";
    city.ownerUid = currentUid || city.ownerUid || null;
    city.ownerName = nextOwnerName;
    city.ownerFlag = nextFlag;
    city.ownerKingPower = nextKingPower;
    localDirtyCityIds.add(city.id);
  });

  if (onlineOwnedCitiesCache.length) {
    onlineOwnedCitiesCache = onlineOwnedCitiesCache.map(city => ({
      ...city,
      ownerName: nextOwnerName,
      ownerFlag: nextFlag,
      ownerKingPower: nextKingPower,
    }));
    updateIslandSummariesFromOwnedCityCache();
  }

  const profileSave = api?.savePlayerProfile && api?.isSignedIn?.()
    ? api.savePlayerProfile(stripServerEconomyProfileFields(getPlayerCloudStateSnapshot())).catch(error => {
      console.warn("Could not save player profile identity", error);
      return false;
    })
    : Promise.resolve(false);
  const leaderboardSave = forceLeaderboard ? publishKingPowerLeaderboard({ force: true }) : Promise.resolve(false);
  const presenceSave = publishOnlinePresence(true);

  if (!api?.isSignedIn?.() || !api?.loadOwnedCitiesAcrossIslands || !api?.savePlayerCities) {
    await Promise.allSettled([profileSave, leaderboardSave, presenceSave]);
    if (isOnlineWorldActive()) syncOwnedCitiesToOnline(true);
    return false;
  }

  try {
    const islandIds = getRegionIds().map(getOnlineIslandId);
    if (api.syncPlayerIdentity) {
      const leaderboardEntry = getKingPowerLeaderboardSnapshot();
      const syncResult = await api.syncPlayerIdentity({
        ownerName: nextOwnerName,
        ownerFlag: nextFlag,
        ownerKingPower: nextKingPower,
        mainCityId: leaderboardEntry.mainCityId,
        mainRegionId: leaderboardEntry.mainRegionId,
        mainIslandId: leaderboardEntry.mainIslandId,
      });
      if (syncResult?.globalStats) applyGlobalStatsSnapshot(syncResult.globalStats, { render: false });
      await Promise.all([profileSave, leaderboardSave, presenceSave]);
      playerCities().forEach(city => localDirtyCityIds.delete(city.id));
      onlineLastError = "";
      renderCities(true);
      renderHud();
      return Boolean(syncResult?.ok ?? true);
    }
    if (api.updateOwnedCityIdentityAcrossIslands) {
      await Promise.all([
        api.updateOwnedCityIdentityAcrossIslands(islandIds, {
          ownerName: nextOwnerName,
          ownerFlag: nextFlag,
          ownerKingPower: nextKingPower,
        }),
        profileSave,
        leaderboardSave,
        presenceSave,
      ]);
      playerCities().forEach(city => localDirtyCityIds.delete(city.id));
      onlineLastError = "";
      renderCities(true);
      renderHud();
      return true;
    }

    const owned = await withTimeout(
      api.loadOwnedCitiesAcrossIslands(islandIds),
      6500,
      "Owned city flag lookup is taking too long."
    );
    const normalized = (Array.isArray(owned) ? owned : [])
      .map(city => normalizeOwnedCitySnapshot({
        ...city,
        islandId: city.islandId || getOnlineIslandId(getCityRegionId(city)),
        ownerName: nextOwnerName,
        ownerFlag: nextFlag,
        ownerKingPower: nextKingPower,
      }))
      .filter(Boolean);
    const byIsland = new Map();
    normalized.forEach(city => {
      const islandId = city.islandId || getOnlineIslandId(getCityRegionId(city));
      if (!byIsland.has(islandId)) byIsland.set(islandId, []);
      byIsland.get(islandId).push({
        ...city,
        ownerName: nextOwnerName,
        ownerFlag: nextFlag,
        ownerKingPower: nextKingPower,
      });
    });

    await Promise.all([
      ...[...byIsland.entries()].map(([islandId, cities]) => api.savePlayerCities(islandId, cities)),
      profileSave,
      leaderboardSave,
      presenceSave,
    ]);
    mergeOwnedCitySnapshots(normalized, { complete: true });
    normalized.forEach(city => localDirtyCityIds.delete(city.id));
    onlineLastError = "";
    renderCities(true);
    renderHud();
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    console.warn("Could not sync player flag across owned cities", error);
    await Promise.allSettled([profileSave, leaderboardSave, presenceSave]);
    return false;
  }
}

function shouldDeactivatePeaceShieldForPlayerAttack(target) {
  if (!target || target.owner === "player") return false;
  return isRewardCampTarget(target) || isStronghold(target) || isAnotherPlayerOwnedCity(target);
}

function deactivatePeaceShieldForPlayerAttack(target) {
  if (!state || !shouldDeactivatePeaceShieldForPlayerAttack(target)) return false;
  if (!getActivePeaceShieldExpiresAtMs()) return false;
  const effects = ensureItemEffects();
  effects.shieldExpiresAtMs = 0;
  refreshOwnedCityItemEffectMetadata(true);
  addLog(`Royal Peace Shield deactivated because you attacked ${target.name}.`);
  saveGame();
  updateShieldStatusBadge();
  renderCities(true);
  syncPeaceShieldToAllOwnedCities(0);
  return true;
}

function getPeaceShieldAttackWarning(target) {
  const remaining = getPeaceShieldRemainingSeconds();
  if (!remaining || !shouldDeactivatePeaceShieldForPlayerAttack(target)) return "";
  return `Royal Peace Shield active: attacking ${target.name} will deactivate it and remove protection from all your cities with ${formatDuration(remaining)} remaining.`;
}

function createOnlineEntryState(playerName) {
  const entry = newGame(playerName);
  entry.mainCityId = "";
  entry.cities = getPlayableBaseCities().map(createNeutralCityFromBase);
  entry.attacks = [];
  entry.log = ["Connecting to the live Crownlands world."];
  return entry;
}

function getSkillMaxLevel(skill = "") {
  const config = SKILL_CONFIG[skill];
  if (!config || !Number.isFinite(config.maxPercent)) return Number.MAX_SAFE_INTEGER;
  return Math.max(0, Math.ceil(config.maxPercent / Math.max(1, config.percentPerLevel)));
}

function normalizeSkillUpgradeLevel(skill = "", value = 0) {
  return Math.min(Math.max(0, Math.floor(Number(value) || 0)), getSkillMaxLevel(skill));
}

function normalizeUpgrades(upgrades, sourceVersion = 6) {
  const normalized = createDefaultSkills();

  for (const key of SKILL_ORDER) {
    const value = Number(upgrades?.[key]);
    if (Number.isFinite(value) && value >= 0) normalized[key] = Math.floor(value);
  }

  const oldAttack = normalizeLegacySkillLevel(upgrades?.attack, sourceVersion, 0.08);
  const oldIncome = normalizeLegacySkillLevel(upgrades?.income, sourceVersion, 0.14);
  const oldDefense = normalizeLegacySkillLevel(upgrades?.defense, sourceVersion, 0.08);
  const oldSpeed = normalizeLegacySkillLevel(upgrades?.speed, sourceVersion, 0.06);

  normalized.swordmastery = Math.max(normalized.swordmastery, oldAttack, Math.floor(Number(upgrades?.striker) || 0));
  normalized.taxStewardship = Math.max(normalized.taxStewardship, oldIncome, Math.floor(Number(upgrades?.prosperous) || 0));
  normalized.royalGranaries = Math.max(normalized.royalGranaries, oldIncome, Math.floor(Number(upgrades?.recruiter) || 0));
  normalized.stoneworks = Math.max(normalized.stoneworks, oldDefense, Math.floor(Number(upgrades?.guardian) || 0));
  normalized.marchOrders = Math.max(normalized.marchOrders, oldSpeed, Math.floor(Number(upgrades?.rusher) || 0));
  normalized.fieldMedics = Math.max(
    normalized.fieldMedics,
    Math.floor(Number(upgrades?.fearless) || 0),
    Math.floor(Number(upgrades?.brave) || 0),
  );
  SKILL_ORDER.forEach(key => {
    normalized[key] = normalizeSkillUpgradeLevel(key, normalized[key]);
  });

  return normalized;
}

function createDefaultSkills() {
  return SKILL_ORDER.reduce((skills, key) => {
    skills[key] = 0;
    return skills;
  }, {});
}

function normalizeSkillPresetName(value = "", slot = 1) {
  const fallback = `Preset ${Math.max(1, Math.floor(Number(slot) || 1))}`;
  const cleaned = String(value || "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return [...(cleaned || fallback)].slice(0, SKILL_PRESET_NAME_MAX_LENGTH).join("") || fallback;
}

function normalizeSkillPresetAllocation(upgrades = {}) {
  const source = upgrades && typeof upgrades === "object" ? upgrades : {};
  return SKILL_ORDER.reduce((allocation, skill) => {
    allocation[skill] = Math.max(0, Math.floor(Number(source[skill]) || 0));
    return allocation;
  }, {});
}

function createDefaultSkillPresets() {
  return {
    modelVersion: SKILL_PRESET_MODEL_VERSION,
    activeSlot: 0,
    slots: SKILL_PRESET_SLOTS.map(definition => ({
      slot: definition.slot,
      unlockLevel: definition.unlockLevel,
      name: `Preset ${definition.slot}`,
      saved: false,
      upgrades: null,
      spentPoints: 0,
      savedAtMs: 0,
    })),
  };
}

function normalizeSkillPresets(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const rawSlots = Array.isArray(source.slots) ? source.slots : [];
  const slots = SKILL_PRESET_SLOTS.map(definition => {
    const raw = rawSlots.find(entry => Math.floor(Number(entry?.slot) || 0) === definition.slot) || {};
    const saved = raw.saved === true && raw.upgrades && typeof raw.upgrades === "object";
    const upgrades = saved ? normalizeSkillPresetAllocation(raw.upgrades) : null;
    return {
      slot: definition.slot,
      unlockLevel: definition.unlockLevel,
      name: normalizeSkillPresetName(raw.name, definition.slot),
      saved,
      upgrades,
      spentPoints: saved ? SKILL_ORDER.reduce((total, skill) => total + upgrades[skill], 0) : 0,
      savedAtMs: saved ? normalizeTimestampMs(raw.savedAtMs) : 0,
    };
  });
  const requestedActiveSlot = Math.floor(Number(source.activeSlot) || 0);
  return {
    modelVersion: SKILL_PRESET_MODEL_VERSION,
    activeSlot: slots.some(slot => slot.slot === requestedActiveSlot && slot.saved) ? requestedActiveSlot : 0,
    slots,
  };
}

function replaceLocalSkillPresetSlot(presets = {}, nextSlot = {}) {
  const normalized = normalizeSkillPresets(presets);
  return normalizeSkillPresets({
    modelVersion: SKILL_PRESET_MODEL_VERSION,
    activeSlot: normalized.activeSlot,
    slots: normalized.slots.map(slot => slot.slot === nextSlot.slot ? { ...slot, ...nextSlot } : slot),
  });
}

function setActiveSkillPresetSlot(presets = {}, slotNumber = 0) {
  const normalized = normalizeSkillPresets(presets);
  return normalizeSkillPresets({
    ...normalized,
    activeSlot: Math.floor(Number(slotNumber) || 0),
  });
}

function skillPresetAllocationsMatch(left = {}, right = {}) {
  const first = normalizeSkillPresetAllocation(left);
  const second = normalizeSkillPresetAllocation(right);
  return SKILL_ORDER.every(skill => first[skill] === second[skill]);
}

function isValidLocalSkillPresetAllocation(upgrades = null, character = state?.character) {
  if (!upgrades || typeof upgrades !== "object") return false;
  const allocation = normalizeSkillPresetAllocation(upgrades);
  const invalid = SKILL_ORDER.some(skill => {
    const rawLevel = Number(upgrades[skill]);
    return !Number.isFinite(rawLevel)
      || rawLevel < 0
      || Math.floor(rawLevel) !== rawLevel
      || allocation[skill] > getSkillMaxLevel(skill);
  });
  const spent = SKILL_ORDER.reduce((total, skill) => total + allocation[skill], 0);
  return !invalid && spent <= getEarnedSkillPoints(character);
}

function normalizeLegacySkillLevel(value, sourceVersion, multiplierGain) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric < 0) return 0;
  if (Number(sourceVersion) <= 3 && numeric >= 1) {
    return Math.max(0, Math.round((numeric - 1) / multiplierGain));
  }
  return Math.floor(numeric);
}
function normalizeMarchPercent(value) {
  const percent = Number(value);
  const allowed = [0.25, 0.5, 0.8, 1];
  return allowed.includes(percent) ? percent : DEFAULT_MARCH_PERCENT;
}

function createDefaultFlag() {
  return { ...PLAYER_FLAG_CONFIG.DEFAULT_FLAG };
}

function randomFrom(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function createRandomFlag() {
  return PLAYER_FLAG_CONFIG.createRandomFlag();
}

function normalizeFlag(flag, stableKey = "") {
  const identityKey = String(stableKey || getCurrentOnlineUid?.() || state?.playerName || "local-player");
  return PLAYER_FLAG_CONFIG.normalizeFlag(flag, identityKey);
}

function createDefaultClanShield() {
  return {
    version: 1,
    shape: "castilian",
    division: "quartered",
    primary: "#7a2638",
    secondary: "#d8bd78",
    borderColor: "#d8bd78",
    charge: "castle",
    secondaryCharge: "lion",
    chargeColor: "#19201d",
    secondaryChargeColor: "#7a2638",
    chargeLayout: "quartered",
    trim: "double",
    finish: "weathered",
  };
}

function normalizeClanShieldColor(value, fallback) {
  const color = String(value || "").trim().toLowerCase();
  return /^#[0-9a-f]{6}$/.test(color) ? color : fallback;
}

function normalizeClanShieldChoice(value, options, fallback) {
  const key = String(value || "").trim().toLowerCase();
  return options.some(option => option.key === key) ? key : fallback;
}

function normalizeClanShield(value = null, legacyBanner = null) {
  const defaults = createDefaultClanShield();
  const source = value && typeof value === "object"
    ? value
    : legacyBanner && typeof legacyBanner === "object"
      ? legacyBanner
      : {};
  const legacyPatternMap = { split: "pale", diagonal: "bend", band: "fess", cross: "quartered", chief: "fess" };
  const legacySymbolMap = { tower: "castle", cross: "fleur", star: "sun", moon: "sun", knight: "swords", diamond: "fleur", spire: "fleur" };
  return {
    version: 1,
    shape: normalizeClanShieldChoice(source.shape, CLAN_SHIELD_SHAPES, defaults.shape),
    division: normalizeClanShieldChoice(legacyPatternMap[source.pattern] || source.division || source.pattern, CLAN_SHIELD_DIVISIONS, defaults.division),
    primary: normalizeClanShieldColor(source.primary, defaults.primary),
    secondary: normalizeClanShieldColor(source.secondary, defaults.secondary),
    borderColor: normalizeClanShieldColor(source.borderColor, defaults.borderColor),
    charge: normalizeClanShieldChoice(legacySymbolMap[source.symbol] || source.charge || source.symbol, CLAN_SHIELD_CHARGES, defaults.charge),
    secondaryCharge: normalizeClanShieldChoice(source.secondaryCharge, CLAN_SHIELD_CHARGES, defaults.secondaryCharge),
    chargeColor: normalizeClanShieldColor(source.chargeColor, defaults.chargeColor),
    secondaryChargeColor: normalizeClanShieldColor(source.secondaryChargeColor, defaults.secondaryChargeColor),
    chargeLayout: normalizeClanShieldChoice(source.chargeLayout, CLAN_SHIELD_CHARGE_LAYOUTS, defaults.chargeLayout),
    trim: normalizeClanShieldChoice(source.trim, CLAN_SHIELD_TRIMS, defaults.trim),
    finish: normalizeClanShieldChoice(source.finish, CLAN_SHIELD_FINISHES, defaults.finish),
  };
}

function getClanShieldPath(shape = "castilian") {
  return {
    castilian: "M10 8 Q50 2 90 8 L90 56 Q88 82 50 99 Q12 82 10 56 Z",
    heater: "M12 8 H88 V51 Q86 78 50 98 Q14 78 12 51 Z",
    kite: "M18 7 Q50 2 82 7 V43 Q78 73 50 100 Q22 73 18 43 Z",
    round: "M12 8 Q50 1 88 8 V61 Q86 89 50 98 Q14 89 12 61 Z",
  }[shape] || "M10 8 Q50 2 90 8 L90 56 Q88 82 50 99 Q12 82 10 56 Z";
}

function renderClanShieldField(shield, clipId) {
  const primary = escapeHtml(shield.primary);
  const secondary = escapeHtml(shield.secondary);
  let division = "";
  if (shield.division === "pale") {
    division = `<rect x="50" width="50" height="106" fill="${secondary}"/>`;
  } else if (shield.division === "fess") {
    division = `<rect y="51" width="100" height="55" fill="${secondary}"/>`;
  } else if (shield.division === "quartered") {
    division = `<rect x="50" width="50" height="53" fill="${secondary}"/><rect y="53" width="50" height="53" fill="${secondary}"/>`;
  } else if (shield.division === "stripes") {
    division = Array.from({ length: 5 }, (_, index) => `<rect x="${10 + index * 18}" width="9" height="106" fill="${secondary}"/>`).join("");
  } else if (shield.division === "bend") {
    division = `<path d="M-18 13 L2 -7 L118 86 L98 106 Z" fill="${secondary}"/>`;
  } else if (shield.division === "saltire") {
    division = `<path d="M-13 2 L1 -10 L113 96 L99 108 Z M99 -10 L113 2 L1 108 L-13 96 Z" fill="${secondary}"/>`;
  } else if (shield.division === "chevron") {
    division = `<path d="M4 70 L50 35 L96 70 L86 82 L50 54 L14 82 Z" fill="${secondary}"/>`;
  }
  return `<g clip-path="url(#${clipId})"><rect width="100" height="106" fill="${primary}"/>${division}</g>`;
}

function renderClanShieldCharge(charge, color, x, y, scale = 1) {
  if (charge === "none") return "";
  const fill = escapeHtml(color);
  let art = "";
  if (charge === "castle") {
    art = `<path d="M23 28h12v9h9V24h12v13h9v-9h12v17h-6v32H29V45h-6zm14 17v22h9V53h8v14h9V45z" fill="${fill}"/><path d="M20 21h18v9H20zm30-4h18v13H50zm12 4h18v9H62z" fill="${fill}"/>`;
  } else if (charge === "lion") {
    art = `<circle cx="57" cy="28" r="8" fill="${fill}"/><path d="M50 34c-13 1-21 10-18 24l-9 11 7 5 11-12 7 4-5 16 8 2 7-18 9-6 8 14 8-3-8-20c-3-8-8-15-16-17l5-8-7-4z" fill="${fill}"/><path d="M38 49C20 43 29 24 16 22c8 8-1 19 6 28 4 5 10 7 16 7M60 40l16-8M58 44l19 2" fill="none" stroke="${fill}" stroke-width="5" stroke-linecap="round"/>`;
  } else if (charge === "eagle") {
    art = `<path d="M50 28l-8-10 8 3 8-3-8 10zm-4 5c-12-12-22-10-34-19 2 17 12 29 28 35l-20 2c5 11 15 16 27 14l3 20 3-20c12 2 22-3 27-14l-20-2c16-6 26-18 28-35-12 9-22 7-34 19l-4 9z" fill="${fill}"/><circle cx="46" cy="27" r="2" fill="${fill}"/><circle cx="54" cy="27" r="2" fill="${fill}"/>`;
  } else if (charge === "crown") {
    art = `<path d="M20 34l13 10 16-25 17 25 14-10-7 34H27zm8 39h44v9H28z" fill="${fill}"/><circle cx="20" cy="31" r="5" fill="${fill}"/><circle cx="50" cy="17" r="5" fill="${fill}"/><circle cx="80" cy="31" r="5" fill="${fill}"/>`;
  } else if (charge === "swords") {
    art = `<path d="M21 18l9 3 47 52-8 8-48-52zm58 0l-9 3-47 52 8 8 48-52z" fill="${fill}"/><path d="M17 72l19 19 5-5-19-19zm66 0L64 91l-5-5 19-19z" fill="${fill}"/>`;
  } else if (charge === "fleur") {
    art = `<path d="M50 15c-15 12-17 25-7 35-9-8-19-8-27 1 7 3 9 10 8 18 8-5 14-4 19 1l-6 16h26l-6-16c5-5 11-6 19-1-1-8 1-15 8-18-8-9-18-9-27-1 10-10 8-23-7-35z" fill="${fill}"/>`;
  } else if (charge === "sun") {
    art = `<circle cx="50" cy="50" r="19" fill="${fill}"/><path d="M50 12v15M50 73v15M12 50h15M73 50h15M23 23l11 11M66 66l11 11M77 23L66 34M34 66L23 77" fill="none" stroke="${fill}" stroke-width="7" stroke-linecap="round"/>`;
  }
  return `<g transform="translate(${x} ${y}) scale(${scale}) translate(-50 -50)">${art}</g>`;
}

function renderClanShieldCharges(shield, clipId) {
  const placements = shield.chargeLayout === "paired"
    ? [
        [shield.charge, shield.chargeColor, 32, 53, 0.52],
        [shield.secondaryCharge, shield.secondaryChargeColor, 68, 53, 0.52],
      ]
    : shield.chargeLayout === "quartered"
      ? [
          [shield.charge, shield.chargeColor, 31, 31, 0.38],
          [shield.secondaryCharge, shield.secondaryChargeColor, 69, 31, 0.38],
          [shield.secondaryCharge, shield.secondaryChargeColor, 31, 68, 0.38],
          [shield.charge, shield.chargeColor, 69, 68, 0.38],
        ]
      : shield.chargeLayout === "chief"
        ? [
            [shield.charge, shield.chargeColor, 25, 29, 0.3],
            [shield.charge, shield.chargeColor, 50, 27, 0.3],
            [shield.charge, shield.chargeColor, 75, 29, 0.3],
            [shield.secondaryCharge, shield.secondaryChargeColor, 50, 67, 0.55],
          ]
        : [[shield.charge, shield.chargeColor, 50, 53, 0.74]];
  return `<g clip-path="url(#${clipId})">${placements.map(placement => renderClanShieldCharge(...placement)).join("")}</g>`;
}

function getClanShieldRenderId(shield) {
  const signature = [
    shield.shape,
    shield.division,
    shield.primary,
    shield.secondary,
    shield.borderColor,
    shield.charge,
    shield.secondaryCharge,
    shield.chargeColor,
    shield.secondaryChargeColor,
    shield.chargeLayout,
    shield.trim,
    shield.finish,
  ].join("|");
  let hash = 2166136261;
  for (let index = 0; index < signature.length; index += 1) {
    hash ^= signature.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function renderClanShield(value = null, options = {}) {
  const shield = normalizeClanShield(value);
  const instance = String(options.instance || "").replace(/[^a-z0-9_-]/gi, "").slice(0, 32);
  const renderId = `${getClanShieldRenderId(shield)}${instance ? `-${instance}` : ""}`;
  const clipId = `clanShieldClip${renderId}`;
  const textureId = `clanShieldTexture${renderId}`;
  const path = getClanShieldPath(shield.shape);
  const label = escapeHtml(options.label || "Clan heraldic shield");
  const size = ["mini", "small", "large", "editor"].includes(options.size) ? options.size : "large";
  const textureOpacity = shield.finish === "battleworn" ? 0.29 : shield.finish === "weathered" ? 0.18 : 0.075;
  const doubleTrim = shield.trim === "double"
    ? `<path d="${path}" transform="translate(50 53) scale(.9) translate(-50 -53)" fill="none" stroke="${escapeHtml(shield.borderColor)}" stroke-width="1.8" opacity=".9"/>`
    : "";
  const rivets = shield.trim === "riveted"
    ? [[21,16],[39,11],[61,11],[79,16],[83,40],[76,69],[50,89],[24,69],[17,40]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="2.1" fill="${escapeHtml(shield.borderColor)}" stroke="#1b1711" stroke-width=".7"/>`).join("")
    : "";
  return `<span class="clan-shield clan-shield-size-${size} clan-shield-${escapeHtml(shield.finish)}">
    <svg viewBox="0 0 100 106" role="img" aria-label="${label}" focusable="false" overflow="hidden">
      <defs>
        <clipPath id="${clipId}" clipPathUnits="userSpaceOnUse"><path d="${path}"/></clipPath>
        <pattern id="${textureId}" width="17" height="19" patternUnits="userSpaceOnUse">
          <path d="M1 4c4-2 7 1 11-1M2 11c4 2 8-1 14 1M1 17c5-2 9 1 15-1" fill="none" stroke="#f2dfb5" stroke-width=".65" opacity=".75"/>
          <path d="M4 1c2 5-1 10 2 17M13 0c-2 5 2 11-1 19" fill="none" stroke="#17110d" stroke-width=".55" opacity=".68"/>
        </pattern>
      </defs>
      <path d="${path}" fill="#2a1c13" stroke="#15100c" stroke-width="7" stroke-linejoin="round"/>
      <g class="clan-shield-boundary" clip-path="url(#${clipId})">
        ${renderClanShieldField(shield, clipId)}
        <g class="clan-shield-planks" fill="none" stroke="#24190f" stroke-width="1.1" opacity=".28">
          <path d="M25 4v91M49 2v98M73 4v91"/>
        </g>
        ${renderClanShieldCharges(shield, clipId)}
        <rect width="100" height="106" fill="url(#${textureId})" opacity="${textureOpacity}"/>
        <g fill="none" stroke="#291b11" stroke-width=".9" opacity="${shield.finish === "polished" ? ".08" : ".2"}"><path d="M18 23l18 13M65 17L49 48M73 56L57 84M22 72l13-9"/></g>
        ${shield.finish === "battleworn" ? `<g fill="none" stroke="#efe2c4" stroke-width="1.2" opacity=".28"><path d="M18 24l24 17M66 15L43 68M71 55L52 90M20 71l15-10"/></g>` : ""}
        <path d="${path}" fill="none" stroke="${escapeHtml(shield.borderColor)}" stroke-width="4.5" stroke-linejoin="round"/>
        ${doubleTrim}${rivets}
        <path d="${path}" fill="none" stroke="#17120d" stroke-width="1.15" opacity=".45" transform="translate(50 53) scale(.96) translate(-50 -53)"/>
        <path d="${path}" fill="none" stroke="#fff4d0" stroke-width=".7" opacity=".18"/>
      </g>
    </svg>
  </span>`;
}

function setTextIfChanged(element, value) {
  if (!element) return;
  const text = String(value);
  if (element.textContent !== text) element.textContent = text;
}


function createCharacterProgress() {
  return { level: CHARACTER_START_LEVEL, xp: CHARACTER_START_XP, skillPoints: 0 };
}

function normalizeCharacterProgress(character) {
  const normalized = createCharacterProgress();
  if (character && typeof character === "object") {
    normalized.level = Math.max(1, Math.floor(Number(character.level) || CHARACTER_START_LEVEL));
    normalized.xp = Math.max(0, Math.floor(Number(character.xp) || CHARACTER_START_XP));
    normalized.skillPoints = Math.max(0, Math.floor(Number(character.skillPoints) || 0));
  }

  // If an old save somehow has enough stored XP, cleanly apply all earned levels.
  while (normalized.xp >= getXpRequiredForLevel(normalized.level)) {
    normalized.xp -= getXpRequiredForLevel(normalized.level);
    normalized.level += 1;
  }
  return normalized;
}

function syncCharacterSkillPoints(character, upgrades, rawSkillPoints = undefined) {
  if (!character) return;
  const expectedPoints = getAvailableSkillPoints(character, upgrades);
  const rawSavedPoints = Number.isFinite(Number(rawSkillPoints)) ? Number(rawSkillPoints) : Number(character.skillPoints);
  const savedPoints = Math.max(0, Math.floor(Number.isFinite(rawSavedPoints) ? rawSavedPoints : 0));
  character.skillPoints = expectedPoints;
  return savedPoints !== expectedPoints;
}

function getEarnedSkillPoints(character = state?.character) {
  return Math.max(0, Math.floor(Number(character?.level) || 1) - 1);
}

function getSpentSkillPoints(upgrades = state?.upgrades) {
  const normalized = normalizeUpgrades(upgrades);
  return SKILL_ORDER.reduce((total, key) => total + normalizeSkillUpgradeLevel(key, normalized[key]), 0);
}

function getAvailableSkillPoints(character = state?.character, upgrades = state?.upgrades) {
  return Math.max(0, getEarnedSkillPoints(character) - getSpentSkillPoints(upgrades));
}

function reconcileSkillPoints(character = state?.character, upgrades = state?.upgrades) {
  if (!character) return false;
  return syncCharacterSkillPoints(character, upgrades, character.skillPoints);
}

function getXpRequiredForLevel(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  const legacyRequirement = value => Math.floor(
    150 + value * 65 + Math.pow(value, 2.05) * 35
  );
  if (current <= HERO_XP_EXPONENTIAL_START_LEVEL) return legacyRequirement(current);
  const anchor = legacyRequirement(HERO_XP_EXPONENTIAL_START_LEVEL);
  const requirement = anchor * Math.pow(
    HERO_XP_EXPONENTIAL_GROWTH_RATE,
    current - HERO_XP_EXPONENTIAL_START_LEVEL
  );
  if (!Number.isFinite(requirement)) return Number.MAX_SAFE_INTEGER;
  return Math.min(
    Number.MAX_SAFE_INTEGER,
    Math.floor(requirement)
  );
}

function getLevelUpGoldUpgradeShare(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE
      + (LEVEL_UP_GOLD_MID_END_UPGRADE_SHARE - LEVEL_UP_GOLD_EARLY_UPGRADE_SHARE) * progress;
  }
  return LEVEL_UP_GOLD_END_UPGRADE_SHARE;
}

function getLevelUpGoldProductionHours(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS
      + (LEVEL_UP_GOLD_MID_END_PRODUCTION_HOURS - LEVEL_UP_GOLD_EARLY_PRODUCTION_HOURS) * progress;
  }
  return LEVEL_UP_GOLD_END_PRODUCTION_HOURS;
}

function getLevelUpGoldFloor(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  return LEVEL_UP_GOLD_FLOOR_BASE
    + current * LEVEL_UP_GOLD_FLOOR_PER_LEVEL
    + Math.pow(current, LEVEL_UP_GOLD_FLOOR_EXPONENT) * LEVEL_UP_GOLD_FLOOR_EXPONENT_SCALE;
}

function getLevelUpGoldReward(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  const goldFloor = getLevelUpGoldFloor(current);
  const referenceCityLevel = Math.max(1, current - 1);
  const referenceUpgradeCost = getCityUpgradeCostAtLevel(referenceCityLevel, 0);
  const upgradeRelief = Number.isFinite(referenceUpgradeCost)
    ? referenceUpgradeCost * getLevelUpGoldUpgradeShare(current)
    : 0;
  const productionRelief = getMillionLordsPassiveGoldPerHour(current)
    * getLevelUpGoldProductionHours(current);
  return Math.floor(Math.max(goldFloor, Math.min(upgradeRelief, productionRelief)));
}

function getLevelUpTroopRewardHours(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) {
    return LEVEL_UP_TROOP_REWARD_EARLY_BASE_HOURS
      + current * LEVEL_UP_TROOP_REWARD_EARLY_HOURS_PER_LEVEL;
  }
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    return LEVEL_UP_TROOP_REWARD_MID_BASE_HOURS
      + (current - HERO_XP_SOFT_CAP_LEVEL) * LEVEL_UP_TROOP_REWARD_MID_HOURS_PER_LEVEL;
  }
  return Math.min(
    LEVEL_UP_TROOP_REWARD_MAX_HOURS,
    LEVEL_UP_TROOP_REWARD_END_BASE_HOURS
      + (current - HERO_XP_HARD_CAP_LEVEL) * LEVEL_UP_TROOP_REWARD_END_HOURS_PER_LEVEL
  );
}

function getLevelUpTroopReward(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  const production = getCityStats({ level: current }, {
    includeSkillBoosts: false,
    includeTimedItemBoosts: false,
  });
  return Math.floor(Math.max(
    50,
    production.troopProductionPerHour * getLevelUpTroopRewardHours(current)
  ));
}

function getMainRewardCity(excludeCityId = null) {
  const main = state?.mainCityId ? cityById(state.mainCityId) : null;
  if (main?.owner === "player" && main.id !== excludeCityId && !isStronghold(main)) return main;
  return playerRegularCities().find(city => city.id !== excludeCityId) || null;
}

function normalizeLevelUpRewardReceipt(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const fromLevel = Math.max(1, Math.floor(Number(raw.fromLevel) || 1));
  const toLevel = Math.max(1, Math.floor(Number(raw.toLevel) || 1));
  if (toLevel <= fromLevel) return null;
  const levelsGained = toLevel - fromLevel;
  return {
    fromLevel,
    toLevel,
    levelsGained,
    skillPoints: Math.max(0, Math.floor(Number(raw.skillPointsAwarded ?? raw.skillPoints ?? levelsGained) || 0)),
    gold: Math.max(0, Math.floor(Number(raw.goldAwarded ?? raw.gold) || 0)),
    troops: Math.max(0, Math.floor(Number(raw.troopsAwarded ?? raw.troops) || 0)),
    cityId: String(raw.cityId || "").trim(),
    cityName: String(raw.cityName || "your main city").trim() || "your main city",
    regionId: raw.regionId ? normalizeRegionId(raw.regionId) : "",
  };
}

function getLevelUpRewardAnnouncement(patch = null, previousLevel = 1, options = {}) {
  if (!patch?.character || options.announceLevelUp === false) return null;
  const reward = normalizeLevelUpRewardReceipt(options.levelUpReward || patch.levelUpReward);
  if (!reward) return null;
  const prior = Math.max(1, Math.floor(Number(previousLevel) || 1));
  const next = Math.max(1, Math.floor(Number(patch.character.level) || 1));
  if (next <= prior || reward.toLevel !== next || reward.toLevel <= prior) return null;
  return reward;
}

function getLevelUpRewardBundle(fromLevel, toLevel, options = {}) {
  const startLevel = Math.max(1, Math.floor(Number(fromLevel) || 1));
  const endLevel = Math.max(startLevel, Math.floor(Number(toLevel) || startLevel));
  let calculatedGold = 0;
  let calculatedTroops = 0;
  for (let level = startLevel + 1; level <= endLevel; level += 1) {
    calculatedGold += getLevelUpGoldReward(level);
    calculatedTroops += getLevelUpTroopReward(level);
  }
  const hasGoldOverride = Number.isFinite(Number(options.gold));
  const hasTroopOverride = Number.isFinite(Number(options.troops));
  const hasSkillPointOverride = Number.isFinite(Number(options.skillPoints));
  const rewardCity = options.cityId ? cityById(options.cityId) : getMainRewardCity();
  return {
    fromLevel: startLevel,
    toLevel: endLevel,
    levelsGained: endLevel - startLevel,
    skillPoints: Math.max(0, Math.floor(hasSkillPointOverride ? Number(options.skillPoints) : endLevel - startLevel)),
    gold: Math.max(0, Math.floor(hasGoldOverride ? Number(options.gold) : calculatedGold)),
    troops: Math.max(0, Math.floor(hasTroopOverride ? Number(options.troops) : calculatedTroops)),
    cityId: String(options.cityId || rewardCity?.id || ""),
    cityName: String(options.cityName || rewardCity?.name || "your main city").trim() || "your main city",
    audioNotBeforeMs: Date.now() + Math.max(0, Number(options.audioDelayMs) || 0),
    audioPlayed: false,
  };
}

function mergeLevelUpRewardBundles(first, second) {
  const troopDestination = second.troops > 0 ? second : first;
  return {
    fromLevel: first.fromLevel,
    toLevel: second.toLevel,
    levelsGained: first.levelsGained + second.levelsGained,
    skillPoints: first.skillPoints + second.skillPoints,
    gold: first.gold + second.gold,
    troops: first.troops + second.troops,
    cityId: troopDestination.cityId || "",
    cityName: troopDestination.cityName || "your main city",
    audioNotBeforeMs: Math.max(
      Number(first.audioNotBeforeMs) || 0,
      Number(second.audioNotBeforeMs) || 0
    ),
    audioPlayed: Boolean(first.audioPlayed || second.audioPlayed),
  };
}

function formatLevelUpRewardAmount(value) {
  return Math.max(0, Math.floor(Number(value) || 0)).toLocaleString();
}

function renderLevelUpReward(reward) {
  if (!reward || !levelUpRewardTitle || !levelUpRewardSubtitle || !levelUpRewardBody) return;
  const multipleLevels = reward.levelsGained > 1;
  levelUpRewardTitle.textContent = multipleLevels
    ? `${formatLevelUpRewardAmount(reward.levelsGained)} Levels Gained`
    : `Level ${formatLevelUpRewardAmount(reward.toLevel)} Reached`;
  levelUpRewardSubtitle.textContent = multipleLevels
    ? `Your hero advanced from level ${formatLevelUpRewardAmount(reward.fromLevel)} to ${formatLevelUpRewardAmount(reward.toLevel)}.`
    : "Your hero grew stronger. These rewards are yours.";
  levelUpRewardBody.innerHTML = `
    <div class="level-up-step" aria-label="Level ${formatLevelUpRewardAmount(reward.fromLevel)} to level ${formatLevelUpRewardAmount(reward.toLevel)}">
      <span>Level ${formatLevelUpRewardAmount(reward.fromLevel)}</span>
      <strong aria-hidden="true">${renderCrownlandsIcon("forward")}</strong>
      <span class="current">Level ${formatLevelUpRewardAmount(reward.toLevel)}</span>
    </div>
    <section class="level-up-reward-grid" aria-label="Level-up rewards">
      <article class="level-up-reward-item skill">
        <span class="level-up-reward-icon" aria-hidden="true">${renderCrownlandsIcon("achievements")}</span>
        <div>
          <small>Skill ${reward.skillPoints === 1 ? "Point" : "Points"}</small>
          <strong>+${formatLevelUpRewardAmount(reward.skillPoints)}</strong>
          <p>Ready to spend in your hero profile.</p>
        </div>
      </article>
      <article class="level-up-reward-item gold">
        <span class="level-up-reward-icon" aria-hidden="true">
          <img src="${GOLD_PICKUP_ICON_SRC}" alt="" decoding="async" />
        </span>
        <div>
          <small>Gold</small>
          <strong>+${formatLevelUpRewardAmount(reward.gold)}</strong>
          <p>Added to your kingdom treasury.</p>
        </div>
      </article>
      <article class="level-up-reward-item troops">
        <span class="level-up-reward-icon" aria-hidden="true">
          <img src="${TROOP_PICKUP_ICON_SRC}" alt="" decoding="async" />
        </span>
        <div>
          <small>Troops</small>
          <strong>+${formatLevelUpRewardAmount(reward.troops)}</strong>
          <p>Rallied directly to ${escapeHtml(reward.cityName)}.</p>
        </div>
      </article>
    </section>
    <div class="level-up-troop-destination">
          <img src="${TROOP_PICKUP_ICON_SRC}" alt="" decoding="async" aria-hidden="true" />
      <span>
        <small>Troop destination</small>
        <strong>${escapeHtml(reward.cityName)}</strong>
      </span>
    </div>
  `;
}

function deferWhileScreenRewardAnimationRuns(callback) {
  const delayMs = Math.max(0, screenRewardAnimationBlockUntilMs - Date.now());
  if (!delayMs) return false;
  window.setTimeout(callback, delayMs);
  return true;
}

function showNextLevelUpReward() {
  if (!levelUpRewardModal || levelUpRewardModal.open || activeLevelUpReward || modal?.open) return;
  if (!levelUpRewardQueue.length || deferWhileScreenRewardAnimationRuns(showNextLevelUpReward)) return;
  const nextReward = levelUpRewardQueue.shift();
  if (!nextReward) return;
  activeLevelUpReward = nextReward;
  renderLevelUpReward(nextReward);
  levelUpRewardModal.showModal();
  scheduleLevelUpRewardAudio(nextReward);
  requestAnimationFrame(() => levelUpRewardModal.classList.add("revealed"));
}

function scheduleLevelUpRewardAudio(reward) {
  if (levelUpRewardAudioTimer) {
    window.clearTimeout(levelUpRewardAudioTimer);
    levelUpRewardAudioTimer = 0;
  }
  if (!reward || reward.audioPlayed) return;
  const play = () => {
    levelUpRewardAudioTimer = 0;
    if (
      activeLevelUpReward !== reward
      || !levelUpRewardModal?.open
      || reward.audioPlayed
    ) return;
    reward.audioPlayed = true;
    playGameSound("level_up", { cooldownMs: 180, allowCrossMap: true });
  };
  const remainingMs = Math.max(0, (Number(reward.audioNotBeforeMs) || 0) - Date.now());
  if (remainingMs > 0) levelUpRewardAudioTimer = window.setTimeout(play, remainingMs);
  else play();
}

function queueLevelUpReward(fromLevel, toLevel, options = {}) {
  const reward = getLevelUpRewardBundle(fromLevel, toLevel, options);
  if (reward.levelsGained <= 0) return;

  const activeDestinationMatches = activeLevelUpReward
    && (
      activeLevelUpReward.troops <= 0
      || reward.troops <= 0
      || activeLevelUpReward.cityId === reward.cityId
    );
  if (activeLevelUpReward && activeLevelUpReward.toLevel === reward.fromLevel && activeDestinationMatches) {
    activeLevelUpReward = mergeLevelUpRewardBundles(activeLevelUpReward, reward);
    renderLevelUpReward(activeLevelUpReward);
    scheduleLevelUpRewardAudio(activeLevelUpReward);
    return;
  }

  const pendingReward = levelUpRewardQueue[levelUpRewardQueue.length - 1];
  const pendingDestinationMatches = pendingReward
    && (pendingReward.troops <= 0 || reward.troops <= 0 || pendingReward.cityId === reward.cityId);
  if (pendingReward && pendingReward.toLevel === reward.fromLevel && pendingDestinationMatches) {
    levelUpRewardQueue[levelUpRewardQueue.length - 1] = mergeLevelUpRewardBundles(pendingReward, reward);
  } else {
    levelUpRewardQueue.push(reward);
  }
  setTimeout(showNextLevelUpReward, 0);
}

function getLoadedMainCity() {
  if (!state?.mainCityId) return null;
  const main = cityById(state.mainCityId);
  return main?.owner === "player" && !isStronghold(main) ? main : null;
}

function getMainCityReference() {
  if (!state?.mainCityId) return null;
  const loaded = cityById(state.mainCityId);
  if (loaded?.owner === "player" && !isStronghold(loaded)) return loaded;
  if (loaded && getCityRegionId(loaded) === getActiveMapRegionId()) return null;
  const cached = getOwnedCitySnapshotById(state.mainCityId);
  if (cached && !isStronghold(cached)) return { ...cached, owner: "player", isMainCity: true };
  const base = getPlayableBaseCityById(state.mainCityId);
  if (isStronghold(base)) return null;
  return base ? { ...base, owner: "player", isMainCity: true } : null;
}

function getMainCityRegionId() {
  return normalizeRegionId(
    state?.online?.mainRegionId
    || (state?.mainCityId ? getCityRegionId(state.mainCityId) : "")
    || getActiveOnlineRegionId()
  );
}

function getKnownOwnedRegularCities() {
  if (!state) return [];
  const merged = new Map();
  onlineOwnedCitiesCache.forEach(city => {
    const normalized = normalizeOwnedCitySnapshot(city);
    if (normalized && !isStronghold(normalized)) merged.set(normalized.id, normalized);
  });
  playerRegularCities().forEach(city => {
    const normalized = normalizeOwnedCitySnapshot({
      ...city,
      islandId: getOnlineIslandId(getCityRegionId(city)),
    });
    if (normalized && !isStronghold(normalized)) merged.set(normalized.id, normalized);
  });
  return Array.from(merged.values());
}

function resolveSingleMainCityId(preferredCityId = "") {
  if (!state) return "";
  const preferredId = getKnownCityId(preferredCityId);
  const currentId = getKnownCityId(state.mainCityId);
  const ownedCities = getKnownOwnedRegularCities();
  const ownedIds = new Set(ownedCities.map(city => city.id));
  if (preferredId && ownedIds.has(preferredId)) return preferredId;
  if (currentId && (!ownedIds.size || ownedIds.has(currentId))) return currentId;
  const flagged = ownedCities.find(city => city.isMainCity && !isStronghold(city));
  return flagged?.id || ownedCities[0]?.id || currentId || preferredId || "";
}

function normalizeSingleMainCityAssignment(preferredCityId = "", { markDirty = false } = {}) {
  if (!state) return { mainCityId: "", changed: false };
  const mainCityId = resolveSingleMainCityId(preferredCityId);
  let changed = false;
  if (mainCityId && state.mainCityId !== mainCityId) {
    state.mainCityId = mainCityId;
    changed = true;
  }

  if (mainCityId && state.online) {
    const mainRegionId = getCityRegionId(mainCityId);
    if (state.online.mainCityId !== mainCityId) {
      state.online.mainCityId = mainCityId;
      changed = true;
    }
    if (state.online.mainRegionId !== mainRegionId) {
      state.online.mainRegionId = mainRegionId;
      changed = true;
    }
    const mainIslandId = getOnlineIslandId(mainRegionId);
    if (state.online.mainIslandId !== mainIslandId) {
      state.online.mainIslandId = mainIslandId;
      changed = true;
    }
  }

  if (Array.isArray(state.cities)) {
    state.cities.forEach(city => {
      if (city.owner !== "player") return;
      if (isStronghold(city)) {
        if (city.isMainCity) {
          city.isMainCity = false;
          changed = true;
        }
        return;
      }
      const shouldBeMain = Boolean(mainCityId && city.id === mainCityId);
      if (city.isMainCity !== shouldBeMain) {
        city.isMainCity = shouldBeMain;
        changed = true;
        if (markDirty) markOwnedCityChanged(city, false);
      }
    });
  }

  if (onlineOwnedCitiesCache.length) {
    onlineOwnedCitiesCache = onlineOwnedCitiesCache.map(city => {
      const shouldBeMain = Boolean(mainCityId && city.id === mainCityId && !isStronghold(city));
      if (Boolean(city.isMainCity) === shouldBeMain) return city;
      changed = true;
      return { ...city, isMainCity: shouldBeMain };
    });
    updateIslandSummariesFromOwnedCityCache();
  }

  return { mainCityId, changed };
}

async function syncSingleMainCityAssignmentToOnline(mainCityId = state?.mainCityId || "", { refreshFirst = false } = {}) {
  if (!state || !mainCityId || !isOnlineWorldActive()) return false;
  const api = getOnlineApi();
  if (!api?.repairMainCityAssignment || !api?.isSignedIn?.()) return false;
  if (refreshFirst && api.loadOwnedCitiesAcrossIslands) {
    await refreshAllOwnedCities(true).catch(error => {
      console.warn("Could not refresh owned cities before main city repair", error);
      return false;
    });
  }

  const result = await api.repairMainCityAssignment({ mainCityId: getKnownCityId(mainCityId) });
  applyServerEconomyResult(result);
  const repairedMainCityId = getKnownCityId(result?.currentUser?.mainCityId) || getKnownCityId(mainCityId);
  if (repairedMainCityId) {
    state.mainCityId = repairedMainCityId;
    if (state.online) {
      state.online.mainCityId = repairedMainCityId;
      state.online.mainRegionId = normalizeRegionId(result?.currentUser?.mainRegionId || state.online.mainRegionId);
      state.online.mainIslandId = result?.currentUser?.mainIslandId || state.online.mainIslandId || getOnlineIslandId(state.online.mainRegionId);
    }
    normalizeSingleMainCityAssignment(repairedMainCityId, { markDirty: false });
  }
  return Boolean(result?.ok ?? true);
}

function getMainCityChangeCooldownDurationMs(ownedCount = getOwnedRegularCityCountForDisplay()) {
  return ownedCount < MAIN_CITY_CHANGE_CITY_LIMIT
    ? MAIN_CITY_CHANGE_SMALL_KINGDOM_COOLDOWN_MS
    : MAIN_CITY_CHANGE_LARGE_KINGDOM_COOLDOWN_MS;
}

function getMainCityChangeCooldownRemainingMs(now = Date.now(), ownedCount = getOwnedRegularCityCountForDisplay()) {
  if (!state) return 0;
  const lastChangedAt = normalizeTimestampMs(state.mainCityChangedAtMs);
  if (!lastChangedAt) return 0;
  const currentTime = Math.max(0, Number(now) || Date.now());
  const elapsed = Math.max(0, currentTime - Math.min(lastChangedAt, currentTime));
  return Math.max(0, getMainCityChangeCooldownDurationMs(ownedCount) - elapsed);
}

function getMainCityChangeStatus(city, now = Date.now()) {
  const ownedCount = state ? getOwnedRegularCityCountForDisplay() : 0;
  const cooldownDurationMs = getMainCityChangeCooldownDurationMs(ownedCount);
  const cooldownMs = getMainCityChangeCooldownRemainingMs(now, ownedCount);
  const cooldownText = cooldownMs > 0 ? formatDuration(Math.ceil(cooldownMs / 1000)) : "";
  const isMain = isMainCityForList(city);
  const hasAlliedReinforcements = getStationedReinforcementsForTarget(city).length > 0;
  let reason = "";

  if (!state) reason = "Game is not ready.";
  else if (!city) reason = "City is not available.";
  else if (city.owner !== "player") reason = "Only owned cities can become your main city.";
  else if (isStronghold(city)) reason = "Strongholds cannot become your main city.";
  else if (isMain) reason = "This city is already your main city.";
  else if (hasAlliedReinforcements) reason = "Send all clan reinforcements home before making this your main city.";
  else if (cooldownMs > 0) reason = `Main city can change again in ${cooldownText}.`;

  return {
    canChange: Boolean(state && city && city.owner === "player" && !isStronghold(city) && !isMain && !hasAlliedReinforcements && cooldownMs <= 0),
    cooldownDurationMs,
    cooldownMs,
    cooldownText,
    ownedCount,
    isMain,
    hasAlliedReinforcements,
    reason,
  };
}

async function changeMainCity(cityId) {
  if (!state) return false;
  const city = cityById(cityId);
  const status = getMainCityChangeStatus(city);
  if (!status.canChange) {
    if (status.reason) showToast(status.reason);
    if (city) showCityInfoModal(city.id);
    return false;
  }

  const previousMain = getLoadedMainCity() || (state.mainCityId ? cityById(state.mainCityId) : null);
  const api = getOnlineApi();
  if (isOnlineWorldActive() && api?.changeMainCity && api?.isSignedIn?.()) {
    try {
      showToast("Changing main city...");
      const result = await api.changeMainCity({
        cityId: city.id,
        regionId: getCityRegionId(city),
        playerName: state.playerName,
        flag: state.flag,
        ownerKingPower: getKingPower(),
      });
      applyServerEconomyResult(result);

      const newMain = result?.mainCity || {};
      const nextMainCityId = getKnownCityId(result?.currentUser?.mainCityId || newMain.id || city.id);
      const nextMainRegionId = normalizeRegionId(result?.currentUser?.mainRegionId || newMain.regionId || getCityRegionId(city));
      if (nextMainCityId) state.mainCityId = nextMainCityId;
      state.mainCityChangedAtMs = normalizeTimestampMs(result?.currentUser?.mainCityChangedAtMs)
        || state.mainCityChangedAtMs
        || Date.now();
      if (state.online) {
        state.online.mainCityId = nextMainCityId;
        state.online.mainRegionId = nextMainRegionId;
        state.online.mainIslandId = result?.currentUser?.mainIslandId || newMain.islandId || getOnlineIslandId(nextMainRegionId);
      }
      normalizeSingleMainCityAssignment(nextMainCityId, { markDirty: false });
      onlineOwnedCitiesCacheComplete = false;
      await refreshAllOwnedCities(true).catch(error => {
        console.warn("Could not refresh owned cities after main city change", error);
        return false;
      });
      addLog(`${city.name} is now your main city.`);
      publishOnlinePresence(true);
      saveGame();
      renderAll();
      showCityInfoModal(nextMainCityId || city.id);
      showToast(`${city.name} is now your main city.`);
      return true;
    } catch (error) {
      showToast(error?.message || "Could not change main city.");
      console.warn("Could not change main city on server", error);
      if (city) showCityInfoModal(city.id);
      return false;
    }
  }

  state.mainCityId = city.id;
  state.mainCityChangedAtMs = Date.now();
  normalizeSingleMainCityAssignment(city.id, { markDirty: true });

  const mainRegionId = getCityRegionId(city);
  if (state.online) {
    state.online.mainCityId = city.id;
    state.online.mainRegionId = mainRegionId;
    state.online.mainIslandId = getOnlineIslandId(mainRegionId);
  }

  if (previousMain && previousMain.id !== city.id) {
    markOwnedCityChanged(previousMain, false);
    syncCityStateToOnline(previousMain);
  }
  markOwnedCityChanged(city, false);
  syncCityStateToOnline(city);

  addLog(`${city.name} is now your main city.`);
  saveGame();
  if (isOnlineWorldActive()) {
    await syncSingleMainCityAssignmentToOnline(city.id, { refreshFirst: true }).catch(error => {
      console.warn("Could not repair remote main city flags", error);
      return false;
    });
    syncOwnedCitiesToOnline(true);
    publishOnlinePresence(true);
    flushOnlineSave(true);
  }
  renderAll();
  showCityInfoModal(city.id);
  showToast(`${city.name} is now your main city.`);
  return true;
}

function addCharacterXp(amount, reason = "progress", options = {}) {
  if (!state) return;
  state.character = normalizeCharacterProgress(state.character);
  state.upgrades = normalizeUpgrades(state.upgrades, state.version);
  reconcileSkillPoints(state.character, state.upgrades);
  const startingLevel = state.character.level;
  const gained = Math.max(0, Math.floor(Number(amount) || 0));
  if (!gained) return;

  state.character.xp += gained;
  addLog(`Hero gained ${formatNumber(gained)} XP from ${reason}.`);

  let levelsGained = 0;
  let totalGoldReward = 0;
  let totalTroopReward = 0;

  while (state.character.xp >= getXpRequiredForLevel(state.character.level)) {
    state.character.xp -= getXpRequiredForLevel(state.character.level);
    state.character.level += 1;
    state.character.skillPoints += 1;
    levelsGained += 1;

    const goldReward = getLevelUpGoldReward(state.character.level);
    const troopReward = getLevelUpTroopReward(state.character.level);
    totalGoldReward += goldReward;
    totalTroopReward += troopReward;
    state.gold += goldReward;
  }

  if (levelsGained > 0) {
    const mainCity = getMainRewardCity();
    if (mainCity && totalTroopReward > 0) {
      mainCity.troopFloat = Math.max(0, Number(mainCity.troopFloat) || mainCity.troops || 0) + totalTroopReward;
      mainCity.troops = Math.floor(mainCity.troopFloat);
      markOwnedCityChanged(mainCity, false);
    }

    addLog(`Hero leveled to ${state.character.level}. Reward: ${formatNumber(levelsGained)} skill point, ${formatNumber(totalGoldReward)} gold, and ${formatNumber(totalTroopReward)} troops to ${mainCity ? mainCity.name : "the main city"}.`);
    showToast(`Hero Lv ${state.character.level}: +${formatNumber(levelsGained)} skill point, +${formatNumber(totalGoldReward)} gold, +${formatNumber(totalTroopReward)} troops`);
    queueLevelUpReward(startingLevel, state.character.level, {
      gold: totalGoldReward,
      troops: totalTroopReward,
      cityId: mainCity?.id || "",
      cityName: mainCity?.name || "your main city",
      audioDelayMs: options.audioDelayMs,
    });
  }
  reconcileSkillPoints(state.character, state.upgrades);
}

function getCaptureXpAward(target, oldOwner, defenderLosses, attackerOwner = "player") {
  if (isGivenUpNeutralCity(target)) return 0;
  const level = clampCityLevel(target?.level);
  const troopXp = Math.floor(getBattleXpTroopCredit(target, defenderLosses) * CAPTURE_XP_PER_DEFENDER);
  const ownerBonus = oldOwner === "enemy" ? ENEMY_CAPTURE_XP_BONUS : 0;
  const cityXp = CAPTURE_XP_BASE + level * CAPTURE_XP_PER_CITY_LEVEL + ownerBonus;
  const efficiency = attackerOwner === "player" ? getCaptureXpEfficiency(target, oldOwner) : 1;
  return capBattleXpForCurrentLevel(Math.floor((cityXp + troopXp) * efficiency));
}

function getDefenseHeldXpAward(attackingTroops, target = null) {
  return Math.floor(DEFENSE_HELD_XP_BASE + getBattleXpTroopCredit(target, attackingTroops) * DEFENSE_HELD_XP_PER_ATTACKER);
}

function getPartialBattleXpAward(fullWinXp) {
  return Math.floor(Math.max(0, Number(fullWinXp) || 0) * FAILED_BATTLE_XP_RATE);
}

function getFailedAttackXpAward(target, oldOwner, defenderLosses, attackerOwner = "player") {
  return getPartialBattleXpAward(getCaptureXpAward(target, oldOwner, defenderLosses, attackerOwner));
}

function getCaptureXpEfficiency(target, oldOwner = target?.owner) {
  if (!target || !state) return 1;
  const pvpMultiplier = getPvpOpponentPowerXpMultiplier(target, oldOwner, "player");
  if (pvpMultiplier !== null) return Number(clamp(pvpMultiplier, 0, 2).toFixed(2));

  const heroLevel = Math.max(1, Math.floor(Number(state.character?.level) || 1));
  const empirePressure = 48 + heroLevel * 20 + getOwnedRegularCityCountForDisplay() * 2;
  const targetScore = getCityXpScore(target, oldOwner);
  const strengthEfficiency = clamp(0.35 + targetScore / Math.max(1, empirePressure), 0.25, 2);
  return Number(clamp(strengthEfficiency, 0.25, 2).toFixed(2));
}

function getCityXpScore(target, oldOwner = target?.owner) {
  const stats = getCityStats(target);
  const ownerBonus = oldOwner === "enemy" ? 45 : oldOwner === "neutral" ? 10 : 60;
  return stats.victoryPoints + getBattleXpTroopCredit(target, target?.troops) * 0.25 + ownerBonus;
}

function getBattleXpTroopCreditCap(target) {
  const stats = getCityStats(target || {});
  const cityCap = Math.max(
    25,
    Math.floor(
      stats.cityWalls * BATTLE_XP_TROOP_CREDIT_CITY_WALL_MULTIPLIER
      + stats.victoryPoints * BATTLE_XP_TROOP_CREDIT_VP_MULTIPLIER
    )
  );
  const levelCap = Math.min(
    Number.MAX_SAFE_INTEGER,
    getXpRequiredForLevel(stats.level) * BATTLE_XP_TROOP_CREDIT_LEVEL_CAP_MULTIPLIER
  );
  return Math.max(cityCap, levelCap);
}

function getBattleXpTroopCredit(target, troops) {
  return Math.min(Math.max(0, Math.floor(Number(troops) || 0)), getBattleXpTroopCreditCap(target));
}

function getPvpOpponentPowerXpMultiplier(target, oldOwner = target?.owner, attackerOwner = "player") {
  if (!target || attackerOwner !== "player") return null;
  if (isStronghold(target) || isRewardCampTarget(target)) return null;
  const targetOwnedByPlayer = oldOwner === "enemy"
    || oldOwner === "player"
    || target.ownerKind === "player"
    || Boolean(String(target.ownerUid || "").trim());
  if (!targetOwnedByPlayer) return null;

  const attackerPower = Math.max(1, normalizePowerValue(getKingPower()));
  const defenderPower = Math.max(1, normalizePowerValue(getCityOwnerKingPowerSnapshot(target)));
  const opponentRatio = defenderPower / attackerPower;
  return getOpponentPowerXpMultiplier(opponentRatio);
}

function getOpponentPowerXpMultiplier(opponentRatio) {
  const ratio = Number(opponentRatio) || 0;
  if (ratio >= 2) return 2;
  if (ratio >= 1.5) return 1.5;
  if (ratio >= 0.5) return 1;
  return 0;
}

function getBattleXpLevelCapRate(level) {
  const current = Math.max(1, Math.floor(Number(level) || 1));
  if (current <= HERO_XP_SOFT_CAP_LEVEL) return BATTLE_XP_EARLY_LEVEL_CAP_RATE;
  if (current <= HERO_XP_HARD_CAP_LEVEL) {
    const progress = (current - HERO_XP_SOFT_CAP_LEVEL)
      / (HERO_XP_HARD_CAP_LEVEL - HERO_XP_SOFT_CAP_LEVEL);
    return BATTLE_XP_MID_START_LEVEL_CAP_RATE
      + (BATTLE_XP_MID_END_LEVEL_CAP_RATE - BATTLE_XP_MID_START_LEVEL_CAP_RATE) * progress;
  }
  const progress = Math.min(1, (current - HERO_XP_HARD_CAP_LEVEL) / BATTLE_XP_END_CAP_RAMP_LEVELS);
  return Math.max(
    BATTLE_XP_END_FLOOR_LEVEL_CAP_RATE,
    BATTLE_XP_END_START_LEVEL_CAP_RATE
      + (BATTLE_XP_END_FLOOR_LEVEL_CAP_RATE - BATTLE_XP_END_START_LEVEL_CAP_RATE) * progress
  );
}

function capBattleXpForCurrentLevel(xp) {
  const base = Math.max(0, Math.floor(Number(xp) || 0));
  if (!state?.character) return base;
  const heroLevel = Math.max(1, Math.floor(Number(state.character.level) || 1));
  const cap = Math.max(250, Math.floor(getXpRequiredForLevel(heroLevel) * getBattleXpLevelCapRate(heroLevel)));
  return Math.min(base, cap);
}

function normalizePowerValue(value) {
  return Math.max(0, Math.floor(Number(value) || 0));
}

function normalizeGlobalStatsSnapshot(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const cityCountsByRegion = Object.entries(raw.cityCountsByRegion || {}).reduce((counts, [regionId, count]) => {
    const key = normalizeRegionId(regionId);
    if (key) counts[key] = Math.max(0, Math.floor(Number(count) || 0));
    return counts;
  }, {});
  return {
    uid: String(raw.uid || raw.playerId || getCurrentOnlineUid() || "").trim(),
    worldId: String(raw.worldId || ""),
    resetGeneration: String(raw.resetGeneration || ""),
    version: Math.max(0, Math.floor(Number(raw.version) || 0)),
    kingPower: normalizePowerValue(raw.kingPower),
    baseKingPower: normalizePowerValue(raw.baseKingPower ?? raw.kingPower),
    kingPowerBonus: normalizePowerValue(raw.kingPowerBonus),
    totalCities: Math.max(0, Math.floor(Number(raw.totalCities) || 0)),
    totalTroops: Math.max(0, Math.floor(Number(raw.totalTroops) || 0)),
    totalCityTroops: Math.max(0, Math.floor(Number(raw.totalCityTroops) || 0)),
    totalCampTroops: Math.max(0, Math.floor(Number(raw.totalCampTroops) || 0)),
    totalMarchingTroops: Math.max(0, Math.floor(Number(raw.totalMarchingTroops) || 0)),
    totalCityLevels: Math.max(0, Math.floor(Number(raw.totalCityLevels) || 0)),
    totalVictoryPoints: Math.max(0, Math.floor(Number(raw.totalVictoryPoints) || 0)),
    strongholdCount: Math.max(0, Math.floor(Number(raw.strongholdCount) || 0)),
    cityCountsByRegion,
    goldPerHour: Math.max(0, Math.floor(Number(raw.goldPerHour) || 0)),
    troopPerHour: Math.max(0, Math.floor(Number(raw.troopPerHour) || 0)),
    baseGoldPerHour: Math.max(0, Math.floor(Number(raw.baseGoldPerHour ?? raw.goldPerHour) || 0)),
    baseTroopPerHour: Math.max(0, Math.floor(Number(raw.baseTroopPerHour ?? raw.troopPerHour) || 0)),
    untimedGoldPerHour: Math.max(0, Math.floor(Number(raw.untimedGoldPerHour ?? raw.baseGoldPerHour ?? raw.goldPerHour) || 0)),
    untimedTroopPerHour: Math.max(0, Math.floor(Number(raw.untimedTroopPerHour ?? raw.baseTroopPerHour ?? raw.troopPerHour) || 0)),
    sustainableTroopPerHour: Math.max(0, Math.floor(Number(raw.sustainableTroopPerHour) || 0)),
    armyPower: normalizePowerValue(raw.armyPower),
    replacementPower: normalizePowerValue(raw.replacementPower),
    defensivePower: normalizePowerValue(raw.defensivePower),
    baseReplacementPower: normalizePowerValue(raw.baseReplacementPower ?? raw.replacementPower),
    baseDefensivePower: normalizePowerValue(raw.baseDefensivePower ?? raw.defensivePower),
    strongholdBonusesAuthoritative: raw.strongholdBonusesAuthoritative === true,
    strongholdBonusSource: String(raw.strongholdBonusSource || "").slice(0, 32),
    crownCitadelControlled: raw.crownCitadelControlled === true,
    strongholdGoldBonusPercent: Math.max(0, Math.floor(Number(raw.strongholdGoldBonusPercent) || 0)),
    strongholdTroopBonusPercent: Math.max(0, Math.floor(Number(raw.strongholdTroopBonusPercent) || 0)),
    strongholdMarchSpeedBonusPercent: Math.max(0, Math.floor(Number(raw.strongholdMarchSpeedBonusPercent) || 0)),
    objectiveTroopDefenseBonusPercent: Math.max(0, Number(
      raw.objectiveTroopDefenseBonusPercent ?? raw.strongholdDefenseBonusPercent
    ) || 0),
    strongholdDefenseBonusPercent: Math.max(0, Math.floor(Number(raw.strongholdDefenseBonusPercent) || 0)),
    strongholdUpgradeCostReductionPercent: Math.max(0, Math.floor(Number(raw.strongholdUpgradeCostReductionPercent) || 0)),
    personalStrongholdGoldBonusPercent: Math.max(0, Number(raw.personalStrongholdGoldBonusPercent) || 0),
    personalStrongholdTroopBonusPercent: Math.max(0, Number(raw.personalStrongholdTroopBonusPercent) || 0),
    personalStrongholdMarchSpeedBonusPercent: Math.max(0, Number(raw.personalStrongholdMarchSpeedBonusPercent) || 0),
    personalObjectiveTroopDefenseBonusPercent: Math.max(0, Number(
      raw.personalObjectiveTroopDefenseBonusPercent ?? raw.personalStrongholdDefenseBonusPercent
    ) || 0),
    personalStrongholdDefenseBonusPercent: Math.max(0, Number(raw.personalStrongholdDefenseBonusPercent) || 0),
    personalStrongholdUpgradeCostReductionPercent: Math.max(0, Number(raw.personalStrongholdUpgradeCostReductionPercent) || 0),
    sharedClanGoldBonusPercent: Math.max(0, Number(raw.sharedClanGoldBonusPercent) || 0),
    sharedClanTroopBonusPercent: Math.max(0, Number(raw.sharedClanTroopBonusPercent) || 0),
    sharedClanMarchSpeedBonusPercent: Math.max(0, Number(raw.sharedClanMarchSpeedBonusPercent) || 0),
    sharedClanObjectiveTroopDefenseBonusPercent: Math.max(0, Number(
      raw.sharedClanObjectiveTroopDefenseBonusPercent ?? raw.sharedClanDefenseBonusPercent
    ) || 0),
    sharedClanDefenseBonusPercent: Math.max(0, Number(raw.sharedClanDefenseBonusPercent) || 0),
    sharedClanUpgradeCostReductionPercent: Math.max(0, Number(raw.sharedClanUpgradeCostReductionPercent) || 0),
    clanCitadelBonusPercent: Math.max(0, Number(raw.clanCitadelBonusPercent) || 0),
    clanObjectiveBenefitRevision: Math.max(0, Math.floor(Number(raw.clanObjectiveBenefitRevision) || 0)),
    stationedTroopPower: normalizePowerValue(raw.stationedTroopPower),
    campTroopPower: normalizePowerValue(raw.campTroopPower),
    cityPower: normalizePowerValue(raw.cityPower),
    marchingPower: normalizePowerValue(raw.marchingPower),
    troopPower: normalizePowerValue(raw.troopPower),
    territoryPower: normalizePowerValue(raw.territoryPower),
    cityLevelPower: normalizePowerValue(raw.cityLevelPower),
    economicPower: normalizePowerValue(raw.economicPower),
    troopProductionPower: normalizePowerValue(raw.troopProductionPower),
    fortificationPower: normalizePowerValue(raw.fortificationPower),
    strongholdPower: normalizePowerValue(raw.strongholdPower),
    characterLevel: Math.max(1, Math.floor(Number(raw.characterLevel) || 1)),
    mainCityId: getKnownCityId(raw.mainCityId),
    mainIslandId: String(raw.mainIslandId || ""),
    mainRegionId: normalizeRegionId(raw.mainRegionId || getRegionIdFromOnlineIslandId(raw.mainIslandId)),
    updatedAtMs: normalizeTimestampMs(raw.updatedAtMs) || timestampToMs(raw.updatedAt),
  };
}

function hasUsableGlobalStats(stats = getGlobalStatsSnapshot()) {
  return Boolean(stats && (stats.version > 0 || stats.updatedAtMs > 0 || stats.worldId));
}

function getGlobalStatsSnapshot() {
  const stats = normalizeGlobalStatsSnapshot(state?.globalStats || onlineGlobalStats);
  const currentUid = getCurrentOnlineUid();
  if (stats?.uid && currentUid && stats.uid !== currentUid) return null;
  return stats;
}

function getGlobalOwnedCityCountByRegion(regionId) {
  const stats = getGlobalStatsSnapshot();
  if (!hasUsableGlobalStats(stats)) return null;
  if (regionId === null || regionId === undefined || !String(regionId || "").trim()) return stats.totalCities;
  const key = normalizeRegionId(regionId);
  return Math.max(0, Math.floor(Number(stats.cityCountsByRegion?.[key]) || 0));
}

function applyGlobalStatsSnapshot(raw = null, options = {}) {
  if (!state) return false;
  const stats = normalizeGlobalStatsSnapshot(raw);
  if (!stats) return false;
  const currentUid = getCurrentOnlineUid();
  if (stats.uid && currentUid && stats.uid !== currentUid) return false;
  const currentStats = getGlobalStatsSnapshot();
  if (stats.updatedAtMs > 0 && currentStats?.updatedAtMs > 0 && stats.updatedAtMs < currentStats.updatedAtMs) {
    return false;
  }
  const before = JSON.stringify(state.globalStats || onlineGlobalStats || null);
  onlineGlobalStats = stats;
  state.globalStats = stats;
  lastComputedKingPower = stats.kingPower;
  if (stats.mainCityId) {
    state.mainCityId = stats.mainCityId;
    if (state.online) {
      state.online.mainCityId = stats.mainCityId;
      state.online.mainRegionId = stats.mainRegionId || state.online.mainRegionId;
      state.online.mainIslandId = stats.mainIslandId || state.online.mainIslandId;
    }
  }
  rememberPlayerIdentity({
    uid: stats.uid || currentUid,
    playerName: state.playerName,
    flag: state.flag,
    kingPower: stats.kingPower,
    kingPowerVersion: stats.version,
    updatedAtMs: stats.updatedAtMs || Date.now(),
  }, { force: true });
  const changed = before !== JSON.stringify(stats);
  if (changed && options.render !== false) {
    renderHud();
    updateIslandSwitcherUi();
    renderCities();
    if (modal.open && modal.classList.contains("city-list-modal")) renderCityListModal();
    if (options.renderProfile !== false && profileScreen?.classList.contains("open")) renderProfileScreen();
  }
  return changed;
}

function getPresenceKingPowerByUid(uid) {
  const ownerUid = String(uid || "").trim();
  if (!ownerUid || !Array.isArray(onlinePresence)) return 0;
  const presence = onlinePresence.find(entry => entry?.uid === ownerUid);
  return normalizePowerValue(presence?.kingPower);
}

function getTroopKingPower(troops = 0) {
  const troopCount = Math.max(0, Math.floor(Number(troops) || 0));
  if (!troopCount) return 0;
  const power = troopCount * KING_POWER_ARMY_TROOP_VALUE;
  return Number.isFinite(power) ? Math.min(Number.MAX_SAFE_INTEGER, Math.floor(power)) : Number.MAX_SAFE_INTEGER;
}

function getCityInfrastructureKingPowerComponents(city, options = {}) {
  if (!city) return { replacementPower: 0, defensivePower: 0 };
  const troopCount = Math.max(0, Math.floor(Number(city.troops) || 0));
  const stats = getCityStats(city, {
    includeSkillBoosts: false,
    includeStrongholdBoosts: options.includeStrongholdBoosts !== false,
    includeTimedItemBoosts: false,
  });
  const replacementPower = Math.max(0, Math.floor(
    stats.troopProductionPerHour * KING_POWER_REPLACEMENT_HOURS
  ));
  const defensivePower = Math.max(0, Math.floor(
    Math.max(0, stats.totalDefense - troopCount) * KING_POWER_DEFENSIVE_ADVANTAGE_WEIGHT
  ));
  return { replacementPower, defensivePower };
}

function getCityInfrastructureKingPower(city) {
  const components = getCityInfrastructureKingPowerComponents(city);
  return Math.min(Number.MAX_SAFE_INTEGER, components.replacementPower + components.defensivePower);
}

function getCityPowerFloor(city) {
  if (!city) return 0;
  return getCityInfrastructureKingPower(city) + getTroopKingPower(city.troops);
}

function getCityOwnerKingPowerSnapshot(city) {
  if (!city) return 0;
  const currentUid = getCurrentOnlineUid();
  if (city.owner === "player" && (!city.ownerUid || city.ownerUid === currentUid)) return getKingPower();
  const cachedIdentity = playerIdentityCache.get(city.ownerUid);
  if (Math.max(0, Math.floor(Number(cachedIdentity?.kingPowerVersion) || 0)) >= KING_POWER_AUTHORITY_VERSION) {
    return normalizePowerValue(cachedIdentity.kingPower);
  }
  const presence = Array.isArray(onlinePresence)
    ? onlinePresence.find(entry => entry?.uid === city.ownerUid)
    : null;
  return Math.max(
    Math.max(0, Math.floor(Number(city.kingPowerVersion) || 0)) >= KING_POWER_AUTHORITY_VERSION
      ? normalizePowerValue(city.ownerKingPower)
      : 0,
    Math.max(0, Math.floor(Number(presence?.kingPowerVersion) || 0)) >= KING_POWER_AUTHORITY_VERSION
      ? normalizePowerValue(presence?.kingPower)
      : 0,
    getCityPowerFloor(city)
  );
}

function getAuthoritativeCityOwnerKingPowerSnapshot(city) {
  if (!city) return 0;
  const currentUid = getCurrentOnlineUid();
  if (city.owner === "player" && (!city.ownerUid || city.ownerUid === currentUid)) return getKingPower();
  const cachedIdentity = playerIdentityCache.get(city.ownerUid);
  const cachedPower = cachedIdentity?.authoritative
    && Math.max(0, Math.floor(Number(cachedIdentity.kingPowerVersion) || 0)) >= KING_POWER_AUTHORITY_VERSION
    ? normalizePowerValue(cachedIdentity.kingPower)
    : 0;
  if (cachedPower > 0) return cachedPower;
  return 0;
}

async function ensureAuthoritativeCityOwnerKingPower(city) {
  const existingPower = getAuthoritativeCityOwnerKingPowerSnapshot(city);
  if (existingPower > 0 || !city || city.owner !== "enemy") return existingPower;
  const ownerUid = String(city.ownerUid || "").trim();
  const api = getOnlineApi();
  if (!ownerUid || !api?.isSignedIn?.()) return 0;
  let changed = false;
  if (api?.loadPlayerIdentities) {
    try {
      const rows = await withTimeout(
        api.loadPlayerIdentities([ownerUid]),
        3500,
        "Kingdom strength check is taking too long."
      );
      rememberPlayerIdentities(Array.isArray(rows) ? rows : [], { force: true });
      changed = applyCanonicalPlayerIdentityToRecord(city) || changed;
      const leaderboardPower = getAuthoritativeCityOwnerKingPowerSnapshot(city);
      if (leaderboardPower > 0) {
        if (changed) renderCities(true);
        return leaderboardPower;
      }
    } catch (error) {
      console.warn("Could not load defender leaderboard power", error);
    }
  }
  if (!api?.getCombatPlayerIdentity) return 0;
  try {
    const identity = await withTimeout(
      api.getCombatPlayerIdentity({ uid: ownerUid }),
      15000,
      "Kingdom strength check is taking too long."
    );
    if (identity) rememberPlayerIdentity(identity, { force: true });
    changed = applyCanonicalPlayerIdentityToRecord(city) || changed;
    if (changed) renderCities(true);
    return getAuthoritativeCityOwnerKingPowerSnapshot(city);
  } catch (error) {
    console.warn("Could not load authoritative defender King Power", error);
    return 0;
  }
}

function getDemoAttackTier(powerRatio) {
  const ratio = Number(powerRatio) || 0;
  return DEMO_ATTACK_TIERS.find(tier => ratio >= tier.minRatio) || null;
}

function getEnemyCityPowerBand(
  city,
  playerKingPower = getKingPower(),
  defenderKingPower = getAuthoritativeCityOwnerKingPowerSnapshot(city)
) {
  if (!city || city.owner !== "enemy" || isStronghold(city)) return "";
  const attackerPower = Math.max(1, normalizePowerValue(playerKingPower));
  const defenderPower = normalizePowerValue(defenderKingPower);
  if (defenderPower <= 0) return "in-range";
  if (attackerPower / defenderPower >= ATTACK_PROTECTION_ASSAULT_MIN_RATIO) return "protected";
  if (defenderPower > attackerPower) return "overpowering";
  return "in-range";
}

function getAuthoritativePlayerPowerBandSnapshot() {
  const stats = getGlobalStatsSnapshot();
  const power = normalizePowerValue(stats?.kingPower);
  const version = Math.max(0, Math.floor(Number(stats?.version) || 0));
  const updatedAtMs = normalizeTimestampMs(stats?.updatedAtMs);
  if (power <= 0 || version < KING_POWER_AUTHORITY_VERSION || updatedAtMs <= 0) return null;
  return {
    power,
    updatedAtMs,
  };
}

function getAuthoritativeEnemyPowerBandSnapshot(city) {
  const ownerUid = String(city?.ownerUid || "").trim();
  const identity = ownerUid ? playerIdentityCache.get(ownerUid) : null;
  const power = normalizePowerValue(identity?.kingPower);
  const version = Math.max(0, Math.floor(Number(identity?.kingPowerVersion) || 0));
  const updatedAtMs = normalizeTimestampMs(identity?.updatedAtMs);
  if (!identity?.authoritative || power <= 0 || version < KING_POWER_AUTHORITY_VERSION || updatedAtMs <= 0) return null;
  return {
    power,
    updatedAtMs,
  };
}

function clearEnemyPowerBandPending(record) {
  if (!record) return;
  record.pendingBand = "";
  record.pendingSinceMs = 0;
  record.pendingAttackerPower = 0;
  record.pendingDefenderPower = 0;
  record.pendingAttackerUpdatedAtMs = 0;
  record.pendingDefenderUpdatedAtMs = 0;
}

function scheduleEnemyPowerBandCommit() {
  if (enemyPowerBandCommitTimer !== null) {
    window.clearTimeout(enemyPowerBandCommitTimer);
    enemyPowerBandCommitTimer = null;
  }
  let nextCommitAtMs = Infinity;
  enemyPowerBandCache.forEach(record => {
    if (!record?.pendingBand || !record.pendingSinceMs) return;
    nextCommitAtMs = Math.min(nextCommitAtMs, record.pendingSinceMs + ENEMY_POWER_BAND_STABILIZE_MS);
  });
  if (!Number.isFinite(nextCommitAtMs)) return;
  enemyPowerBandCommitTimer = window.setTimeout(() => {
    enemyPowerBandCommitTimer = null;
    if (!state) return;
    if (isCameraInteractionActive()) {
      queueDeferredMapRender();
      return;
    }
    renderCities(true);
    scheduleEnemyPowerBandCommit();
  }, Math.max(50, nextCommitAtMs - Date.now()));
}

function clearEnemyPowerBandCache() {
  enemyPowerBandCache.clear();
  if (enemyPowerBandCommitTimer !== null) {
    window.clearTimeout(enemyPowerBandCommitTimer);
    enemyPowerBandCommitTimer = null;
  }
}

function pruneEnemyPowerBandCache(cities = state?.cities) {
  const eligibleOwnerUids = new Set((Array.isArray(cities) ? cities : [])
    .filter(city => city?.owner === "enemy" && !isStronghold(city) && !isClanAllyCity(city))
    .map(city => String(city.ownerUid || "").trim())
    .filter(Boolean));
  let changed = false;
  enemyPowerBandCache.forEach((_, ownerUid) => {
    if (eligibleOwnerUids.has(ownerUid)) return;
    enemyPowerBandCache.delete(ownerUid);
    changed = true;
  });
  if (changed) scheduleEnemyPowerBandCommit();
}

function getStableEnemyCityPowerBand(city, nowMs = Date.now()) {
  if (!city || city.owner !== "enemy" || isStronghold(city)) return "";
  const ownerUid = String(city.ownerUid || "").trim();
  if (isClanAllyCity(city)) {
    if (ownerUid && enemyPowerBandCache.delete(ownerUid)) scheduleEnemyPowerBandCommit();
    return "";
  }
  if (!ownerUid) return "in-range";

  const record = enemyPowerBandCache.get(ownerUid) || null;
  const attackerSnapshot = getAuthoritativePlayerPowerBandSnapshot();
  const defenderSnapshot = getAuthoritativeEnemyPowerBandSnapshot(city);
  const snapshotsAreComplete = Boolean(
    normalizePowerValue(attackerSnapshot?.power) > 0
    && normalizeTimestampMs(attackerSnapshot?.updatedAtMs) > 0
    && normalizePowerValue(defenderSnapshot?.power) > 0
    && normalizeTimestampMs(defenderSnapshot?.updatedAtMs) > 0
  );
  if (!snapshotsAreComplete) {
    if (record?.pendingBand) {
      clearEnemyPowerBandPending(record);
      scheduleEnemyPowerBandCommit();
    }
    return record?.confirmedBand || "in-range";
  }

  const attackerUpdatedAtMs = attackerSnapshot.updatedAtMs;
  const defenderUpdatedAtMs = defenderSnapshot.updatedAtMs;
  const staleAttacker = Boolean(
    record?.lastAttackerUpdatedAtMs
    && attackerUpdatedAtMs
    && attackerUpdatedAtMs < record.lastAttackerUpdatedAtMs
  );
  const staleDefender = Boolean(
    record?.lastDefenderUpdatedAtMs
    && defenderUpdatedAtMs
    && defenderUpdatedAtMs < record.lastDefenderUpdatedAtMs
  );
  if (staleAttacker || staleDefender) {
    if (record?.pendingBand) {
      clearEnemyPowerBandPending(record);
      scheduleEnemyPowerBandCommit();
    }
    return record?.confirmedBand || "in-range";
  }

  const candidateBand = getEnemyCityPowerBand(city, attackerSnapshot.power, defenderSnapshot.power);
  if (!record) {
    enemyPowerBandCache.set(ownerUid, {
      confirmedBand: candidateBand,
      pendingBand: "",
      pendingSinceMs: 0,
      attackerPower: attackerSnapshot.power,
      defenderPower: defenderSnapshot.power,
      attackerUpdatedAtMs,
      defenderUpdatedAtMs,
      pendingAttackerPower: 0,
      pendingDefenderPower: 0,
      pendingAttackerUpdatedAtMs: 0,
      pendingDefenderUpdatedAtMs: 0,
      lastAttackerUpdatedAtMs: attackerUpdatedAtMs,
      lastDefenderUpdatedAtMs: defenderUpdatedAtMs,
    });
    return candidateBand;
  }

  record.lastAttackerUpdatedAtMs = Math.max(record.lastAttackerUpdatedAtMs || 0, attackerUpdatedAtMs);
  record.lastDefenderUpdatedAtMs = Math.max(record.lastDefenderUpdatedAtMs || 0, defenderUpdatedAtMs);
  if (candidateBand === record.confirmedBand) {
    record.attackerPower = attackerSnapshot.power;
    record.defenderPower = defenderSnapshot.power;
    record.attackerUpdatedAtMs = attackerUpdatedAtMs;
    record.defenderUpdatedAtMs = defenderUpdatedAtMs;
    if (record.pendingBand) {
      clearEnemyPowerBandPending(record);
      scheduleEnemyPowerBandCommit();
    }
    return record.confirmedBand;
  }

  if (record.pendingBand !== candidateBand) {
    record.pendingBand = candidateBand;
    record.pendingSinceMs = nowMs;
    record.pendingAttackerPower = attackerSnapshot.power;
    record.pendingDefenderPower = defenderSnapshot.power;
    record.pendingAttackerUpdatedAtMs = attackerUpdatedAtMs;
    record.pendingDefenderUpdatedAtMs = defenderUpdatedAtMs;
    scheduleEnemyPowerBandCommit();
    return record.confirmedBand;
  }

  record.pendingAttackerPower = attackerSnapshot.power;
  record.pendingDefenderPower = defenderSnapshot.power;
  record.pendingAttackerUpdatedAtMs = attackerUpdatedAtMs;
  record.pendingDefenderUpdatedAtMs = defenderUpdatedAtMs;
  if (nowMs - record.pendingSinceMs < ENEMY_POWER_BAND_STABILIZE_MS) return record.confirmedBand;

  record.confirmedBand = record.pendingBand;
  record.attackerPower = record.pendingAttackerPower;
  record.defenderPower = record.pendingDefenderPower;
  record.attackerUpdatedAtMs = record.pendingAttackerUpdatedAtMs;
  record.defenderUpdatedAtMs = record.pendingDefenderUpdatedAtMs;
  clearEnemyPowerBandPending(record);
  scheduleEnemyPowerBandCommit();
  return record.confirmedBand;
}

function getEnemyCityPowerBandLabel(powerBand, city = null) {
  if (powerBand === "protected") {
    const stableRecord = enemyPowerBandCache.get(String(city?.ownerUid || "").trim());
    const attackerPower = Math.max(1, normalizePowerValue(stableRecord?.attackerPower) || normalizePowerValue(getKingPower()));
    const defenderPower = normalizePowerValue(stableRecord?.defenderPower)
      || normalizePowerValue(getAuthoritativeCityOwnerKingPowerSnapshot(city));
    return defenderPower > 0 && attackerPower / defenderPower >= ATTACK_PROTECTION_RAID_MIN_RATIO
      ? "Weaker kingdom protection: raid only, no capture"
      : "Weaker kingdom protection: two-stage assault required";
  }
  if (powerBand === "overpowering") return "King Power above yours";
  if (powerBand === "in-range") return "Within your King Power range";
  return "";
}

function normalizeDemoAttackSnapshot(demo = null) {
  if (!demo || typeof demo !== "object" || !demo.active) return null;
  const attackerKingPower = normalizePowerValue(demo.attackerKingPower);
  const defenderKingPower = Math.max(1, normalizePowerValue(demo.defenderKingPower));
  const powerRatio = Number.isFinite(Number(demo.powerRatio))
    ? Number(demo.powerRatio)
    : attackerKingPower / Math.max(1, defenderKingPower);
  const tier = getDemoAttackTier(powerRatio);
  if (!tier) return null;
  const maxTroops = Math.max(1, Math.floor(Number(demo.maxTroops) || 1));
  const requestedTroops = Math.max(1, Math.floor(Number(demo.requestedTroops) || maxTroops));
  const effectiveTroops = Math.max(1, Math.min(maxTroops, Math.floor(Number(demo.effectiveTroops) || maxTroops)));
  const attackPowerPercent = clamp(Math.floor(Number(demo.attackPowerPercent) || tier.attackPowerPercent), 1, 100);
  const troopCapPercent = clamp(Math.floor(Number(demo.troopCapPercent) || tier.troopCapPercent), 1, 100);
  const travelMultiplier = Math.max(1, Number(demo.travelMultiplier) || tier.travelMultiplier);
  return {
    active: true,
    label: String(demo.label || tier.label || "Demo Attack"),
    attackerKingPower,
    defenderKingPower,
    powerRatio: Number(powerRatio.toFixed(2)),
    requestedTroops,
    effectiveTroops,
    maxTroops,
    troopCapPercent,
    attackPowerPercent,
    attackPowerMultiplier: attackPowerPercent / 100,
    travelMultiplier,
    attackerXpMultiplier: 0,
    defenderXpMultiplier: DEMO_ATTACK_DEFENDER_XP_MULTIPLIER,
  };
}

function roundDownToTwoSignificantDigits(value) {
  const integer = Math.max(0, Math.floor(Number(value) || 0));
  if (integer < 10) return integer;
  const magnitude = 10 ** Math.max(0, Math.floor(Math.log10(integer)) - 1);
  return Math.floor(integer / magnitude) * magnitude;
}

function roundUpToTwoSignificantDigits(value) {
  const integer = Math.max(0, Math.ceil(Number(value) || 0));
  if (integer < 10) return integer;
  const magnitude = 10 ** Math.max(0, Math.floor(Math.log10(integer)) - 1);
  return Math.ceil(integer / magnitude) * magnitude;
}

function getAttackProtectionMode(powerRatio) {
  const ratio = Math.max(0, Number(powerRatio) || 0);
  if (ratio >= ATTACK_PROTECTION_RAID_MIN_RATIO) return "raid";
  if (ratio >= ATTACK_PROTECTION_ASSAULT_MIN_RATIO) return "assault";
  return "normal";
}

function getAttackProtectionBreakEvenScale(mode, powerRatio) {
  const ratio = Math.max(0, Number(powerRatio) || 0);
  if (mode === "assault") {
    const progress = clamp(
      (ratio - ATTACK_PROTECTION_ASSAULT_MIN_RATIO)
        / (ATTACK_PROTECTION_RAID_MIN_RATIO - ATTACK_PROTECTION_ASSAULT_MIN_RATIO),
      0,
      1
    );
    return 1.25 - progress * 0.2;
  }
  if (mode === "raid") {
    const progress = clamp(
      (ratio - ATTACK_PROTECTION_RAID_MIN_RATIO)
        / (ATTACK_PROTECTION_RAID_MAX_SCALE_RATIO - ATTACK_PROTECTION_RAID_MIN_RATIO),
      0,
      1
    );
    return 0.5 - progress * 0.25;
  }
  return 1;
}

function normalizeAttackProtectionSnapshot(raw = null, legacyDemoAttack = null) {
  if (raw && typeof raw === "object" && Number(raw.version) === ATTACK_PROTECTION_VERSION) {
    const mode = raw.mode === "raid" ? "raid" : raw.mode === "assault" ? "assault" : "normal";
    const assaultStage = mode === "assault" && raw.assaultStage === "capture" ? "capture" : mode === "assault" ? "breach" : "";
    const maxTroops = Math.max(1, Math.floor(Number(raw.maxTroops) || 1));
    const requestedTroops = Math.max(1, Math.floor(Number(raw.requestedTroops) || maxTroops));
    return {
      version: ATTACK_PROTECTION_VERSION,
      mode,
      assaultStage,
      label: mode === "raid"
        ? "Protected Raid"
        : mode === "assault"
          ? assaultStage === "capture"
            ? "Protected Capture Assault"
            : "Protected Breach Assault"
          : "Normal Attack",
      powerRatio: Math.max(0, Number(raw.powerRatio) || 0),
      maxTroops,
      requestedTroops,
      effectiveTroops: Math.max(1, Math.min(maxTroops, Math.floor(Number(raw.effectiveTroops) || requestedTroops))),
      captureAllowed: mode === "normal" || (mode === "assault" && assaultStage === "capture"),
      breachRequired: mode === "assault" && assaultStage === "breach",
      maxDefenderLossPercent: mode === "raid" ? 10 : 100,
      attackerXpMultiplier: mode === "normal" ? 1 : 0,
      defenderXpPolicy: mode === "normal" ? "normal" : ATTACK_PROTECTION_DEFENDER_XP_POLICY,
      legacyDemoAttack: raw.legacyDemoAttack === true,
    };
  }
  const legacy = normalizeDemoAttackSnapshot(legacyDemoAttack);
  if (!legacy) return null;
  return {
    version: ATTACK_PROTECTION_VERSION,
    mode: "raid",
    assaultStage: "",
    label: "Protected Raid",
    powerRatio: Math.max(ATTACK_PROTECTION_RAID_MIN_RATIO, legacy.powerRatio),
    maxTroops: legacy.maxTroops,
    requestedTroops: legacy.requestedTroops,
    effectiveTroops: legacy.effectiveTroops,
    captureAllowed: false,
    breachRequired: false,
    maxDefenderLossPercent: 10,
    attackerXpMultiplier: 0,
    defenderXpPolicy: ATTACK_PROTECTION_DEFENDER_XP_POLICY,
    legacyDemoAttack: true,
  };
}

function normalizeCombatFortificationSnapshot(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  return {
    modelVersion: SIEGE_COMBAT_VERSION,
    baseCityWalls: Math.max(0, Math.floor(Number(raw.baseCityWalls) || 0)),
    reinforcedCityWalls: Math.max(0, Math.floor(Number(raw.reinforcedCityWalls) || 0)),
    stoneworksPercent: Math.max(0, Number(raw.stoneworksPercent) || 0),
    gearWallStrengthPercent: Math.max(0, Number(raw.gearWallStrengthPercent) || 0),
    cityLevelDefensePercent: Math.max(0, Number(raw.cityLevelDefensePercent) || 0),
    defenseCombatVersion: Math.max(0, Math.floor(Number(raw.defenseCombatVersion) || 0)),
    baseDefensePowerPerTroop: Math.max(1, Number(raw.baseDefensePowerPerTroop) || 1),
    shieldwallDisciplinePercent: Math.max(0, Number(raw.shieldwallDisciplinePercent) || 0),
    gearDefenderStrengthPercent: Math.max(0, Number(raw.gearDefenderStrengthPercent) || 0),
    troopObjectiveDefenseBonusPercent: Math.max(0, Number(raw.troopObjectiveDefenseBonusPercent) || 0),
    objectiveDefenseBonusPercent: Math.max(0, Number(raw.objectiveDefenseBonusPercent) || 0),
    fullWallPower: Math.max(0, Math.floor(Number(raw.fullWallPower) || 0)),
    wallDefenseIgnored: raw.wallDefenseIgnored === true,
    currentWallPower: Math.max(0, Math.floor(Number(raw.currentWallPower ?? raw.startingWallPower) || 0)),
    startingWallPower: Math.max(0, Math.floor(Number(raw.startingWallPower ?? raw.currentWallPower) || 0)),
    wallDamagePower: Math.max(0, Math.floor(Number(raw.wallDamagePower) || 0)),
    penetratingAttackPower: Math.max(0, Math.floor(Number(raw.penetratingAttackPower) || 0)),
    garrisonDefensePower: Math.max(0, Math.floor(Number(raw.garrisonDefensePower) || 0)),
    ownerGarrisonDefensePower: Math.max(0, Math.floor(Number(raw.ownerGarrisonDefensePower) || 0)),
    reinforcementGarrisonDefensePower: Math.max(0, Math.floor(Number(raw.reinforcementGarrisonDefensePower) || 0)),
    startingIntegrityBps: clamp(Math.floor(Number(raw.startingIntegrityBps ?? raw.integrityBps) || 0), 0, 10_000),
    endingIntegrityBps: clamp(Math.floor(Number(raw.endingIntegrityBps ?? raw.integrityBps) || 0), 0, 10_000),
    repairAtMs: normalizeTimestampMs(raw.repairAtMs),
    repairWindowMinutes: Math.max(0, Math.floor(Number(raw.repairWindowMinutes) || 0)),
    repairReductionPercent: clamp(Number(raw.repairReductionPercent) || 0, 0, 100),
    repairAddedMs: Math.max(0, Math.floor(Number(raw.repairAddedMs) || 0)),
    breached: raw.breached === true,
    meaningfulWallDamage: raw.meaningfulWallDamage === true,
    persistentDamageApplied: raw.persistentDamageApplied === true,
  };
}

function normalizeCombatForecast(raw = null) {
  if (!raw || typeof raw !== "object" || Number(raw.version) !== COMBAT_FORECAST_VERSION) return null;
  const status = ["scouted", "unavailable", "expired", "owner_changed"].includes(raw.status)
    ? raw.status
    : "unavailable";
  const normalized = {
    version: COMBAT_FORECAST_VERSION,
    status,
    attackPowerPerTroop: Math.max(0, Number(raw.attackPowerPerTroop) || BASE_TROOP_ATTACK_POWER),
    swordmasteryLevel: Math.max(0, Math.floor(Number(raw.swordmasteryLevel) || 0)),
    swordmasteryPercent: Math.max(0, Number(raw.swordmasteryPercent) || 0),
  };
  if (status !== "scouted") return normalized;
  return {
    ...normalized,
    scoutedAtMs: normalizeTimestampMs(raw.scoutedAtMs),
    expiresAtMs: normalizeTimestampMs(raw.expiresAtMs),
    targetOwnerUid: String(raw.targetOwnerUid || "").slice(0, 128),
    targetLevel: clampCityLevel(raw.targetLevel || 1),
    targetTroops: Math.max(0, Math.floor(Number(raw.targetTroops) || 0)),
    ownerTroops: Math.max(0, Math.floor(Number(raw.ownerTroops ?? raw.targetTroops) || 0)),
    reinforcementTroops: Math.max(0, Math.floor(Number(raw.reinforcementTroops) || 0)),
    baseDefensePower: Math.max(0, Math.floor(Number(raw.baseDefensePower ?? raw.defensePower) || 0)),
    defensePower: Math.max(0, Math.floor(Number(raw.defensePower) || 0)),
    effectiveTroops: Math.max(1, Math.floor(Number(raw.effectiveTroops) || 1)),
    attackPower: Math.max(0, Math.floor(Number(raw.attackPower) || 0)),
    powerRatio: Math.max(0, Number(raw.powerRatio) || 0),
    expectedOutcome: ["capture", "breach", "raid", "defeat", "wall_hold", "garrison_hold"].includes(raw.expectedOutcome)
      ? raw.expectedOutcome
      : "defeat",
    estimatedSurvivors: Math.max(0, Math.floor(Number(raw.estimatedSurvivors) || 0)),
    estimatedDefendersLeft: Math.max(0, Math.floor(Number(raw.estimatedDefendersLeft) || 0)),
    estimatedAttackerLosses: Math.max(0, Math.floor(Number(raw.estimatedAttackerLosses) || 0)),
    estimatedDefenderLosses: Math.max(0, Math.floor(Number(raw.estimatedDefenderLosses) || 0)),
    estimatedAttackerLossPercent: clamp(Number(raw.estimatedAttackerLossPercent) || 0, 0, 100),
    estimatedDefenderLossPercent: clamp(Number(raw.estimatedDefenderLossPercent) || 0, 0, 100),
    minimumCaptureTroops: Math.max(1, Math.floor(Number(raw.minimumCaptureTroops) || 1)),
    minimumMeaningfulWallDamageTroops: Math.max(
      0,
      Math.floor(Number(raw.minimumMeaningfulWallDamageTroops) || 0)
    ),
    advantageTier: [
      "defeat_expected",
      "costly_victory",
      "advantage",
      "strong_advantage",
      "overwhelming_advantage",
    ].includes(raw.advantageTier) ? raw.advantageTier : getCombatAdvantageTier(raw.powerRatio).key,
    siegeCombatVersion: Math.max(0, Math.floor(Number(raw.siegeCombatVersion) || 0)),
    defenseCombatVersion: Math.max(0, Math.floor(Number(raw.defenseCombatVersion) || 0)),
    fortification: normalizeCombatFortificationSnapshot(raw.fortification),
  };
}

function createAttackProtectionSnapshot(source, target, requestedTroops, owner = "player", overrides = {}) {
  if (!source || !target || owner !== "player" || target.owner === owner || isStronghold(target) || isRewardCampTarget(target)) {
    return null;
  }
  const targetOwnerUid = String(target.ownerUid || "").trim();
  const targetProtectionOwnerKey = targetOwnerUid || String(target.owner || "").trim();
  const currentUid = getCurrentOnlineUid();
  const targetOwnedByPlayer = target.ownerKind === "player" || target.owner === "enemy" || Boolean(targetOwnerUid);
  const targetOwnedByCurrentPlayer = target.owner === "player" || (targetOwnerUid && currentUid && targetOwnerUid === currentUid);
  if (!targetOwnedByPlayer || targetOwnedByCurrentPlayer) return null;
  const attackerKingPower = normalizePowerValue(overrides.attackerKingPower ?? getKingPower());
  const defenderKingPower = normalizePowerValue(
    overrides.defenderKingPower ?? getAuthoritativeCityOwnerKingPowerSnapshot(target)
  );
  if (defenderKingPower <= 0) return null;
  const powerRatio = attackerKingPower / defenderKingPower;
  const mode = getAttackProtectionMode(powerRatio);
  if (mode === "normal") return null;
  const sourceTroops = Math.max(1, Math.floor(Number(source.troops) || 1));
  const requested = clamp(Math.floor(Number(requestedTroops) || 1), 1, sourceTroops);
  const attackPerTroop = Math.max(1, getAttackPower(1, owner));
  const totalDefense = Math.max(1, getCityStats(target).totalDefense);
  const breakEvenTroops = Math.max(1, Math.floor(totalDefense / attackPerTroop) + 1);
  const assaultStage = mode === "assault" && (
    overrides.assaultStage === "capture"
    || target.protectedAssaultBreach?.attackerUid === (currentUid || "player")
      && target.protectedAssaultBreach?.defenderUid === targetProtectionOwnerKey
  )
    ? "capture"
    : "breach";
  const captureSafeCap = Math.max(1, roundUpToTwoSignificantDigits(breakEvenTroops));
  const scaledCap = Math.max(1, Math.floor(
    breakEvenTroops * getAttackProtectionBreakEvenScale(mode, powerRatio)
  ));
  const exposedCap = mode === "assault"
    ? assaultStage === "breach"
      ? captureSafeCap
      : Math.max(captureSafeCap, roundDownToTwoSignificantDigits(scaledCap))
    : Math.max(1, roundDownToTwoSignificantDigits(scaledCap));
  const maxTroops = Math.min(sourceTroops, exposedCap);
  return normalizeAttackProtectionSnapshot({
    version: ATTACK_PROTECTION_VERSION,
    mode,
    assaultStage,
    powerRatio,
    maxTroops,
    requestedTroops: requested,
    effectiveTroops: Math.min(requested, maxTroops),
  });
}

function getAttackProtectionNotice(snapshot) {
  const protection = normalizeAttackProtectionSnapshot(snapshot);
  if (!protection || protection.mode === "normal") return "";
  const captureText = protection.mode === "raid"
    ? `no capture; defender damage is capped at ${formatNumber(protection.maxDefenderLossPercent)}%`
    : protection.captureAllowed
      ? "follow-up assault; capture is possible"
      : "first assault; a victory breaches the walls but cannot capture";
  return `${protection.label}: maximum ${formatNumber(protection.maxTroops)} troops, ${captureText}, attacker earns 0 XP. Defender XP is 2× on their first protected battle against you this world; normal afterward.`;
}

function getAttackProtectionReportSuffix(snapshot) {
  const protection = normalizeAttackProtectionSnapshot(snapshot);
  return protection && protection.mode !== "normal"
    ? ` ${protection.label}: attacker XP blocked; defender first-battle XP policy applied.`
    : "";
}

function createDemoAttackSnapshot(source, target, requestedTroops, owner = "player", overrides = {}) {
  if (!source || !target || owner !== "player") return null;
  if (target.owner === owner) return null;
  if (isStronghold(target)) return null;
  const targetOwnerUid = String(target.ownerUid || "").trim();
  const currentUid = getCurrentOnlineUid();
  const targetOwnedByPlayer = target.ownerKind === "player" || target.owner === "enemy" || Boolean(targetOwnerUid);
  const targetOwnedByCurrentPlayer = target.owner === "player" || (targetOwnerUid && currentUid && targetOwnerUid === currentUid);
  if (!targetOwnedByPlayer || targetOwnedByCurrentPlayer) return null;

  const attackerKingPower = normalizePowerValue(overrides.attackerKingPower ?? getKingPower());
  const defenderSnapshot = overrides.defenderKingPower === undefined
    ? getAuthoritativeCityOwnerKingPowerSnapshot(target)
    : normalizePowerValue(overrides.defenderKingPower);
  if (defenderSnapshot <= 0) return null;
  const defenderKingPower = Math.max(1, defenderSnapshot);
  const powerRatio = attackerKingPower / Math.max(1, defenderKingPower);
  const tier = getDemoAttackTier(powerRatio);
  if (!tier) return null;

  const sourceTroops = Math.max(1, Math.floor(Number(source.troops) || 1));
  const requested = clamp(Math.floor(Number(requestedTroops) || 1), 1, sourceTroops);
  const targetWalls = Math.max(1, Math.floor(Number(getCityStats(target).cityWalls) || 1));
  const capByWalls = Math.max(1, Math.floor(targetWalls * tier.troopCapPercent / 100));
  const maxTroops = Math.max(1, Math.min(sourceTroops, capByWalls));
  return normalizeDemoAttackSnapshot({
    active: true,
    label: tier.label,
    attackerKingPower,
    defenderKingPower,
    powerRatio,
    requestedTroops: requested,
    effectiveTroops: Math.min(requested, maxTroops),
    maxTroops,
    troopCapPercent: tier.troopCapPercent,
    attackPowerPercent: tier.attackPowerPercent,
    travelMultiplier: tier.travelMultiplier,
  });
}

function applyDemoDefenderXpMultiplier(xp, demoAttack) {
  const base = Math.max(0, Math.floor(Number(xp) || 0));
  const demo = normalizeDemoAttackSnapshot(demoAttack);
  return demo ? capBattleXpForCurrentLevel(Math.floor(base * demo.defenderXpMultiplier)) : base;
}

function applyDefenseOpponentXpMultiplier(xp, attack, target, attackProtection = null) {
  const base = Math.max(0, Math.floor(Number(xp) || 0));
  if (isStronghold(target)) return capBattleXpForCurrentLevel(base);
  const protection = normalizeAttackProtectionSnapshot(attackProtection, attack?.demoAttack);
  if (protection?.mode !== "normal") {
    const attackerKey = String(attack?.ownerUid || attack?.ownerName || attack?.owner || "unknown");
    const claimKey = `${ONLINE_WORLD_ID}:${RESET_GENERATION}:${attackerKey}`;
    if (!state.protectedDefenseXpClaims || typeof state.protectedDefenseXpClaims !== "object") {
      state.protectedDefenseXpClaims = {};
    }
    const firstProtectedDefense = !state.protectedDefenseXpClaims[claimKey];
    state.protectedDefenseXpClaims[claimKey] = {
      armyId: String(attack?.onlineId || attack?.id || ""),
      claimedAtMs: Date.now(),
    };
    return Math.floor(capBattleXpForCurrentLevel(base) * (firstProtectedDefense ? 2 : 1));
  }

  const defenderPower = Math.max(1, normalizePowerValue(getKingPower()));
  const attackerPower = Math.max(
    1,
    normalizePowerValue(attack?.attackerKingPower)
      || normalizePowerValue(attack?.ownerKingPower)
      || normalizePowerValue(attack?.troops)
      || getCityPowerFloor(cityById(attack?.fromId))
  );
  const multiplier = getOpponentPowerXpMultiplier(attackerPower / defenderPower);
  return capBattleXpForCurrentLevel(Math.floor(base * multiplier));
}

function getDemoAttackNotice(demoAttack) {
  const demo = normalizeDemoAttackSnapshot(demoAttack);
  if (!demo) return "";
  const cappedText = demo.requestedTroops > demo.effectiveTroops
    ? `${formatNumber(demo.effectiveTroops)} of ${formatNumber(demo.requestedTroops)} selected troops will march`
    : `${formatNumber(demo.effectiveTroops)} troops will march`;
  return `${demo.label}: weaker kingdom protection is active. ${cappedText}, attack power is ${formatNumber(demo.attackPowerPercent)}%, march time is x${demo.travelMultiplier.toFixed(1)}, attacker earns 0 XP, defender XP is x${demo.defenderXpMultiplier}.`;
}

function getDemoAttackReportSuffix(demoAttack) {
  const demo = normalizeDemoAttackSnapshot(demoAttack);
  return demo ? ` ${demo.label}: attacker XP blocked and defender XP x${demo.defenderXpMultiplier}.` : "";
}

function getSkillLevel(skill) {
  return normalizeSkillUpgradeLevel(skill, state?.upgrades?.[skill]);
}

function getSkillPercent(skill) {
  const config = SKILL_CONFIG[skill];
  if (!config) return 0;
  const raw = getSkillRawPercent(skill);
  return Number.isFinite(config.maxPercent) ? Math.min(raw, config.maxPercent) : raw;
}

function getSkillRawPercent(skill) {
  const config = SKILL_CONFIG[skill];
  if (!config) return 0;
  return getSkillLevel(skill) * config.percentPerLevel;
}

function isSkillAtCap(skill) {
  const config = SKILL_CONFIG[skill];
  return Boolean(config && Number.isFinite(config.maxPercent) && getSkillRawPercent(skill) >= config.maxPercent);
}

function skillMultiplier(skill) {
  return Number((1 + getSkillPercent(skill) / 100).toFixed(3));
}

function getControlledCrownCitadel(owner = "player") {
  if (!state || !Array.isArray(state.cities)) return null;
  const loadedCitadel = state.cities.find(city => city.owner === owner && isCrownCitadel(city));
  if (loadedCitadel) return loadedCitadel;
  if (owner !== "player") return null;
  const citadel = getCrownCitadelControlSnapshot();
  const currentUid = getCurrentOnlineUid();
  return currentUid && getCrownCitadelHolderUid() === currentUid ? citadel : null;
}

function getAuthoritativePlayerStrongholdBonuses() {
  if (getControlledCrownCitadel("player")) {
    return {
      source: "crown_citadel",
      crownCitadelControlled: true,
      goldBonusPercent: CROWN_CITADEL_GOLD_BONUS_PERCENT,
      troopBonusPercent: CROWN_CITADEL_TROOP_BONUS_PERCENT,
      marchSpeedBonusPercent: CROWN_CITADEL_MARCH_SPEED_BONUS_PERCENT,
      objectiveTroopDefenseBonusPercent: CROWN_CITADEL_DEFENSE_BONUS_PERCENT,
      cityDefenseBonusPercent: CROWN_CITADEL_DEFENSE_BONUS_PERCENT,
      upgradeCostReductionPercent: CROWN_CITADEL_UPGRADE_COST_REDUCTION_PERCENT,
    };
  }
  const globalStats = getGlobalStatsSnapshot();
  if (!globalStats?.strongholdBonusesAuthoritative) return null;
  return {
    source: globalStats.strongholdBonusSource || "individual",
    crownCitadelControlled: globalStats.crownCitadelControlled === true,
    goldBonusPercent: globalStats.strongholdGoldBonusPercent,
    troopBonusPercent: globalStats.strongholdTroopBonusPercent,
    marchSpeedBonusPercent: globalStats.strongholdMarchSpeedBonusPercent,
    objectiveTroopDefenseBonusPercent: getObjectiveTroopDefenseBonusPercent(globalStats),
    cityDefenseBonusPercent: globalStats.strongholdDefenseBonusPercent,
    upgradeCostReductionPercent: globalStats.strongholdUpgradeCostReductionPercent,
  };
}

function getControlledStrongholdGoldBonusPercent(owner = "player") {
  if (owner === "player") {
    const authoritative = getAuthoritativePlayerStrongholdBonuses();
    if (authoritative) return authoritative.goldBonusPercent;
  }
  if (getControlledCrownCitadel(owner)) return CROWN_CITADEL_GOLD_BONUS_PERCENT;
  if (!state || !Array.isArray(state.cities)) return 0;
  return state.cities.reduce((total, city) => {
    if (city.owner !== owner || !isGoldStronghold(city)) return total;
    return total + getStrongholdBonusPercent(city);
  }, 0);
}

function getControlledStrongholdTroopBonusPercent(owner = "player") {
  if (owner === "player") {
    const authoritative = getAuthoritativePlayerStrongholdBonuses();
    if (authoritative) return authoritative.troopBonusPercent;
  }
  if (getControlledCrownCitadel(owner)) return CROWN_CITADEL_TROOP_BONUS_PERCENT;
  if (!state || !Array.isArray(state.cities)) return 0;
  return state.cities.reduce((total, city) => {
    if (city.owner !== owner || !isTrainingStronghold(city)) return total;
    return total + getStrongholdBonusPercent(city);
  }, 0);
}

function getControlledStrongholdMarchSpeedPercent(owner = "player") {
  if (owner === "player") {
    const authoritative = getAuthoritativePlayerStrongholdBonuses();
    if (authoritative) return authoritative.marchSpeedBonusPercent;
  }
  if (getControlledCrownCitadel(owner)) return CROWN_CITADEL_MARCH_SPEED_BONUS_PERCENT;
  if (!state || !Array.isArray(state.cities)) return 0;
  return state.cities.reduce((total, city) => {
    if (city.owner !== owner || !isSpeedStronghold(city)) return total;
    return total + getStrongholdBonusPercent(city);
  }, 0);
}

function getStrongholdMarchSpeedMultiplier(owner = "player") {
  return 1 + getControlledStrongholdMarchSpeedPercent(owner) / 100;
}

function getCityControllerKey(city) {
  if (!city || city.owner === "neutral" || city.ownerKind === "neutral") return "";
  if (city.ownerKind === "player") {
    if (city.ownerUid) return `player:${city.ownerUid}`;
    if (city.owner === "player") return "player:local";
    return "";
  }
  if (city.owner === "player") return "player:local";
  if (city.owner === "enemy") {
    if (city.ownerUid) return `player:${city.ownerUid}`;
    return "";
  }
  return city.owner || "";
}

function getControlledCrownCitadelForControllerKey(controllerKey) {
  if (!state || !Array.isArray(state.cities) || !controllerKey) return null;
  const loadedCitadel = state.cities.find(city => isCrownCitadel(city) && getCityControllerKey(city) === controllerKey);
  if (loadedCitadel) return loadedCitadel;
  const citadel = getCrownCitadelControlSnapshot();
  return citadel && getCityControllerKey(citadel) === controllerKey ? citadel : null;
}

function getControlledObjectiveTroopDefenseBonusPercentForCity(target) {
  if (!state || !Array.isArray(state.cities)) return 0;
  const targetControllerKey = getCityControllerKey(target);
  if (!targetControllerKey) return 0;
  const currentUid = getCurrentOnlineUid();
  if (targetControllerKey === "player:local" || (currentUid && targetControllerKey === `player:${currentUid}`)) {
    const authoritative = getAuthoritativePlayerStrongholdBonuses();
    if (authoritative) return getObjectiveTroopDefenseBonusPercent(authoritative);
  }
  if (getControlledCrownCitadelForControllerKey(targetControllerKey)) return CROWN_CITADEL_DEFENSE_BONUS_PERCENT;
  return state.cities.reduce((total, city) => {
    if (!isDefenseStronghold(city) || getCityControllerKey(city) !== targetControllerKey) return total;
    return total + getStrongholdBonusPercent(city);
  }, 0);
}

function getControlledStrongholdCityDefenseBonusPercentForCity(target) {
  return getControlledObjectiveTroopDefenseBonusPercentForCity(target);
}

function getControlledStrongholdUpgradeCostReductionPercent(owner = "player") {
  if (owner === "player") {
    const authoritative = getAuthoritativePlayerStrongholdBonuses();
    if (authoritative) return authoritative.upgradeCostReductionPercent;
  }
  return getControlledCrownCitadel(owner) ? CROWN_CITADEL_UPGRADE_COST_REDUCTION_PERCENT : 0;
}

function clampCityLevel(level) {
  const normalized = Math.floor(Number(level));
  if (!Number.isFinite(normalized)) return 1;
  return clamp(normalized, 1, Number.MAX_SAFE_INTEGER);
}

function getMillionLordsCityProductionVp(level) {
  const normalizedLevel = clampCityLevel(level);
  const rawValue = MILLION_LORDS_CITY_PRODUCTION_VP_BASE
    * Math.pow(MILLION_LORDS_CITY_PRODUCTION_VP_GROWTH, normalizedLevel - 1);
  if (!Number.isFinite(rawValue)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(rawValue + 0.000001)));
}

function getMillionLordsPassiveGoldPerHour(level) {
  const normalizedLevel = clampCityLevel(level);
  const curveLevel = Math.min(normalizedLevel, CITY_GOLD_ENDGAME_START_LEVEL);
  const level100Base = getMillionLordsCityProductionVp(curveLevel)
    * MILLION_LORDS_PASSIVE_GOLD_PER_CITY_VP;
  const endgameMultiplier = normalizedLevel > CITY_GOLD_ENDGAME_START_LEVEL
    ? Math.pow(CITY_GOLD_ENDGAME_GROWTH, normalizedLevel - CITY_GOLD_ENDGAME_START_LEVEL)
    : 1;
  const rawGold = level100Base * endgameMultiplier;
  if (!Number.isFinite(rawGold)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(rawGold)));
}

function dropCapturedCityLevel(city) {
  const previousLevel = clampCityLevel(city?.level);
  if (isStronghold(city)) return { previousLevel, nextLevel: previousLevel };
  const nextLevel = Math.max(1, previousLevel - 1);
  if (city) city.level = nextLevel;
  return { previousLevel, nextLevel };
}

function formatCapturedCityLevelDrop(levelDrop) {
  if (!levelDrop) return "";
  if (levelDrop.previousLevel === levelDrop.nextLevel) return `Level stayed ${formatNumber(levelDrop.nextLevel)}.`;
  return `Level ${formatNumber(levelDrop.previousLevel)} to ${formatNumber(levelDrop.nextLevel)}.`;
}

function getBaseCityWalls(level) {
  const normalizedLevel = clampCityLevel(level);
  const levelOffset = normalizedLevel - 1;
  const walls = CITY_LEVEL_STATS.cityWallsBase
    + CITY_LEVEL_STATS.cityWallsPerLevel * levelOffset;
  if (!Number.isFinite(walls)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(walls)));
}

function getObjectiveTroopDefenseBonusPercent(value = {}) {
  if (!value || typeof value !== "object") return 0;
  return Math.max(0, Number(
    value.objectiveTroopDefenseBonusPercent
    ?? value.troopDefenseBonusPercent
    ?? value.strongholdDefenseBonusPercent
    ?? value.cityDefenseBonusPercent
  ) || 0);
}

function getSiegeRepairWindowMinutes(level) {
  const normalizedLevel = clampCityLevel(level);
  const minutes = Math.round(
    SIEGE_REPAIR_BASE_MINUTES + normalizedLevel * SIEGE_REPAIR_MINUTES_PER_LEVEL
  );
  if (!Number.isFinite(minutes)) return Number.MAX_SAFE_INTEGER;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(1, minutes));
}

function getSiegeRepairTiming(
  level,
  wallDamagePower,
  fullWallPower,
  currentRepairAtMs = 0,
  nowMs = Date.now(),
  reductionPercent = 0
) {
  const repairWindowMinutes = getSiegeRepairWindowMinutes(level);
  const damagePower = Math.max(0, Number(wallDamagePower) || 0);
  const maximumPower = Math.max(0, Number(fullWallPower) || 0);
  const damageShare = maximumPower > 0 ? clamp(damagePower / maximumPower, 0, 1) : 0;
  const reduction = clamp(Number(reductionPercent) || 0, 0, 100);
  const fullRepairWindowMs = Math.min(
    Number.MAX_SAFE_INTEGER,
    repairWindowMinutes * 60_000
  );
  const repairAddedMs = Math.max(
    0,
    Math.round(fullRepairWindowMs * damageShare * (1 - reduction / 100))
  );
  const startedAtMs = Math.max(0, Math.floor(Number(nowMs) || Date.now()));
  const existingDeadlineMs = normalizeTimestampMs(currentRepairAtMs);
  const extensionBaseMs = existingDeadlineMs > startedAtMs ? existingDeadlineMs : startedAtMs;
  return {
    repairWindowMinutes,
    repairReductionPercent: reduction,
    repairAddedMs,
    repairAtMs: Math.min(Number.MAX_SAFE_INTEGER, extensionBaseMs + repairAddedMs),
  };
}

function getSiegeRepairLevel(target = {}) {
  return isStronghold(target) ? getStrongholdDefenseLevel(target) : clampCityLevel(target.level);
}

function calculateGoldProductionRates(
  baseGoldProductionPerHour = 0,
  taxStewardshipPercent = 0,
  strongholdGoldBonusPercent = 0,
  royalTaxDecreeGoldBonusPercent = 0
) {
  const base = Number.isFinite(Number(baseGoldProductionPerHour))
    ? Math.max(0, Number(baseGoldProductionPerHour))
    : 0;
  const taxPercent = Number.isFinite(Number(taxStewardshipPercent))
    ? Math.max(0, Number(taxStewardshipPercent))
    : 0;
  const strongholdPercent = Number.isFinite(Number(strongholdGoldBonusPercent))
    ? Math.max(0, Number(strongholdGoldBonusPercent))
    : 0;
  const royalTaxPercent = Number.isFinite(Number(royalTaxDecreeGoldBonusPercent))
    ? Math.max(0, Number(royalTaxDecreeGoldBonusPercent))
    : 0;
  const untimedGoldProductionPerHour = base * (1 + (taxPercent + strongholdPercent) / 100);
  const goldProductionPerHour = untimedGoldProductionPerHour + base * royalTaxPercent / 100;
  return {
    baseGoldProductionPerHour: base,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour: Math.max(0, goldProductionPerHour - base),
  };
}

function calculateTroopProductionRates(
  baseTroopProductionPerHour = 0,
  royalGranariesPercent = 0,
  strongholdTroopBonusPercent = 0,
  warDrumsTroopBonusPercent = 0
) {
  const base = Number.isFinite(Number(baseTroopProductionPerHour))
    ? Math.max(0, Number(baseTroopProductionPerHour))
    : 0;
  const granariesPercent = Number.isFinite(Number(royalGranariesPercent))
    ? Math.max(0, Number(royalGranariesPercent))
    : 0;
  const strongholdPercent = Number.isFinite(Number(strongholdTroopBonusPercent))
    ? Math.max(0, Number(strongholdTroopBonusPercent))
    : 0;
  const warDrumsPercent = Number.isFinite(Number(warDrumsTroopBonusPercent))
    ? Math.max(0, Number(warDrumsTroopBonusPercent))
    : 0;
  const untimedTroopProductionPerHour = base * (1 + (granariesPercent + strongholdPercent) / 100);
  const troopProductionPerHour = untimedTroopProductionPerHour + base * warDrumsPercent / 100;
  return {
    baseTroopProductionPerHour: base,
    untimedTroopProductionPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour: Math.max(0, troopProductionPerHour - base),
  };
}

function getCityStats(city, options = {}) {
  const stronghold = isStronghold(city);
  const rewardCamp = isRewardCampTarget(city);
  const level = rewardCamp ? 0 : stronghold ? getStrongholdDefenseLevel(city) : clampCityLevel(city?.level);
  const victoryPoints = rewardCamp ? 0 : Math.floor(
    CITY_LEVEL_STATS.victoryPointsBase
    + level * CITY_LEVEL_STATS.victoryPointsPerLevel
    + Math.pow(level, CITY_LEVEL_STATS.victoryPointsExponent) * CITY_LEVEL_STATS.victoryPointsExponentScale
  );
  const defenseCombatVersion = Math.max(0, Math.floor(Number(
    options.defenseCombatVersion ?? (supportsDefenseCombat() ? DEFENSE_COMBAT_VERSION : 0)
  ) || 0));
  const soldierDefenseEnabled = !rewardCamp
    && defenseCombatVersion >= DEFENSE_COMBAT_VERSION;
  const defensePercent = soldierDefenseEnabled || rewardCamp ? 0 : level * 2;
  const baseCityWalls = rewardCamp ? 0 : getBaseCityWalls(level);
  const includeSkillBoosts = options.includeSkillBoosts !== false;
  const gearBonuses = city?.owner === "player" ? getCommonGearBonuses() : {};
  const stoneworksPercent = !rewardCamp && includeSkillBoosts && city?.owner === "player" ? getSkillPercent("stoneworks") : 0;
  const shieldwallDisciplinePercent = soldierDefenseEnabled && includeSkillBoosts && city?.owner === "player"
    ? getSkillPercent("shieldwallDiscipline")
    : 0;
  const gearWallStrengthPercent = rewardCamp ? 0 : Math.max(0, Number(gearBonuses.wallStrength) || 0);
  const gearDefenderStrengthPercent = rewardCamp ? 0 : Math.max(0, Number(gearBonuses.defenderStrength) || 0);
  const gearTroopProductionPercent = stronghold || rewardCamp
    ? 0
    : Math.max(0, Number(gearBonuses.troopProductionAllCities) || 0);
  const gearGoldProductionPercent = stronghold || rewardCamp
    ? 0
    : Math.max(0, Number(gearBonuses.goldProductionAllCities) || 0)
      + (city?.id === state?.mainCityId ? Math.max(0, Number(gearBonuses.goldProductionMainCity) || 0) : 0);
  const cityWalls = Math.floor(
    baseCityWalls + baseCityWalls * (stoneworksPercent + gearWallStrengthPercent) / 100
  );
  const royalGranariesPercent = includeSkillBoosts && city?.owner === "player" ? getSkillPercent("royalGranaries") : 0;
  const taxStewardshipPercent = includeSkillBoosts && city?.owner === "player" ? getSkillPercent("taxStewardship") : 0;
  const includeStrongholdBoosts = options.includeStrongholdBoosts !== false;
  const strongholdGoldBonusPercent = includeStrongholdBoosts && !stronghold && !rewardCamp && city?.owner === "player"
    ? getControlledStrongholdGoldBonusPercent("player")
    : 0;
  const strongholdTroopBonusPercent = includeStrongholdBoosts && !stronghold && !rewardCamp && city?.owner === "player"
    ? getControlledStrongholdTroopBonusPercent("player")
    : 0;
  const objectiveTroopDefenseBonusPercent = !rewardCamp && includeStrongholdBoosts
    ? getControlledObjectiveTroopDefenseBonusPercentForCity(city)
    : 0;
  const includeTimedItemBoosts = options.includeTimedItemBoosts !== false;
  const warDrumsTroopBonusPercent = includeTimedItemBoosts && !stronghold && !rewardCamp && city?.owner === "player" ? getWarDrumsTroopProductionBonusPercent() : 0;
  const royalTaxDecreeGoldBonusPercent = includeTimedItemBoosts && !stronghold && !rewardCamp && city?.owner === "player" && getActiveRoyalTaxDecreeExpiresAtMs() > Date.now()
    ? ROYAL_TAX_DECREE_GOLD_PRODUCTION_BONUS_PERCENT
    : 0;
  const rawTroopProductionPerHour = stronghold || rewardCamp ? 0 : victoryPoints * CITY_LEVEL_STATS.troopProductionPerVictoryPoint;
  const {
    baseTroopProductionPerHour,
    untimedTroopProductionPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour,
  } = calculateTroopProductionRates(
    rawTroopProductionPerHour,
    royalGranariesPercent + gearTroopProductionPercent,
    strongholdTroopBonusPercent,
    warDrumsTroopBonusPercent
  );
  const royalGranariesBonusPerHour = baseTroopProductionPerHour * royalGranariesPercent / 100;
  const millionLordsProductionVp = rewardCamp ? 0 : getMillionLordsCityProductionVp(level);
  const rawGoldProductionPerHour = stronghold || rewardCamp ? 0 : getMillionLordsPassiveGoldPerHour(level);
  const {
    baseGoldProductionPerHour,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour,
  } = calculateGoldProductionRates(
    rawGoldProductionPerHour,
    taxStewardshipPercent + gearGoldProductionPercent,
    strongholdGoldBonusPercent,
    royalTaxDecreeGoldBonusPercent
  );
  const defendingTroops = Math.max(0, Number(city?.troops) || 0)
    + (city?.owner === "player" ? Math.max(0, Number(city?.alliedReinforcementTroops) || 0) : 0);
  const baseTroopDefense = rewardCamp
    ? Math.floor(defendingTroops * REWARD_CAMP_TROOP_POWER)
    : soldierDefenseEnabled
      ? Math.floor(defendingTroops * BASE_TROOP_DEFENSE_POWER)
      : Math.floor(defendingTroops);
  const troopDefenseBeforeObjective = rewardCamp
    ? baseTroopDefense
    : soldierDefenseEnabled
      ? Math.floor(defendingTroops * BASE_TROOP_DEFENSE_POWER * (1 + shieldwallDisciplinePercent / 100))
      : Math.floor(defendingTroops * (1 + defensePercent / 100));
  const troopDefenseBeforeGear = rewardCamp
    ? baseTroopDefense
    : soldierDefenseEnabled
      ? Math.floor(defendingTroops * BASE_TROOP_DEFENSE_POWER * (
        1 + (shieldwallDisciplinePercent + objectiveTroopDefenseBonusPercent) / 100
      ))
      : troopDefenseBeforeObjective;
  const gearDefenderStrengthBonusPower = soldierDefenseEnabled
    ? Math.floor(defendingTroops * BASE_TROOP_DEFENSE_POWER * gearDefenderStrengthPercent / 100)
    : 0;
  const troopDefense = troopDefenseBeforeGear + gearDefenderStrengthBonusPower;
  const cityWallsBonus = Math.max(0, cityWalls - baseCityWalls);
  const baseTotalDefense = Math.floor(baseCityWalls + baseTroopDefense);
  const preStrongholdTotalDefense = Math.floor(cityWalls + troopDefenseBeforeObjective);
  const strongholdDefenseBonus = soldierDefenseEnabled
    ? Math.max(0, troopDefense - troopDefenseBeforeObjective)
    : Math.floor(preStrongholdTotalDefense * objectiveTroopDefenseBonusPercent / 100);
  const totalDefense = soldierDefenseEnabled
    ? Math.floor(cityWalls + troopDefense)
    : preStrongholdTotalDefense + strongholdDefenseBonus;
  const totalDefenseBonus = Math.max(0, totalDefense - baseTotalDefense);
  return {
    level,
    victoryPoints,
    cityPower: victoryPoints,
    defenseCombatVersion: soldierDefenseEnabled ? DEFENSE_COMBAT_VERSION : 0,
    baseDefensePowerPerTroop: soldierDefenseEnabled ? BASE_TROOP_DEFENSE_POWER : 1,
    defensePercent,
    baseCityWalls,
    cityWalls,
    cityWallsBonus,
    stoneworksPercent,
    gearWallStrengthPercent,
    gearDefenderStrengthPercent,
    gearTroopProductionPercent,
    gearGoldProductionPercent,
    shieldwallDisciplineLevel: soldierDefenseEnabled && includeSkillBoosts && city?.owner === "player"
      ? getSkillLevel("shieldwallDiscipline")
      : 0,
    shieldwallDisciplinePercent,
    royalGranariesPercent,
    taxStewardshipPercent,
    strongholdGoldBonusPercent,
    strongholdTroopBonusPercent,
    objectiveTroopDefenseBonusPercent,
    strongholdDefenseBonusPercent: objectiveTroopDefenseBonusPercent,
    strongholdDefenseBonus,
    warDrumsTroopBonusPercent,
    royalTaxDecreeGoldBonusPercent,
    baseTroopProductionPerHour,
    untimedTroopProductionPerHour,
    royalGranariesBonusPerHour,
    troopProductionPerHour,
    troopProductionBonusPerHour,
    millionLordsProductionVp,
    rawGoldProductionPerHour,
    baseGoldProductionPerHour,
    untimedGoldProductionPerHour,
    goldProductionPerHour,
    goldProductionBonusPerHour,
    troopProductionPerSecond: troopProductionPerHour / 3600,
    goldProductionPerSecond: goldProductionPerHour / 3600,
    baseTroopDefense,
    troopDefenseBeforeObjective,
    troopDefenseBeforeGear,
    gearDefenderStrengthBonusPower,
    troopDefense,
    baseTotalDefense,
    totalDefenseBonus,
    totalDefense,
  };
}

function normalizeFortificationState(city = {}, nowMs = Date.now()) {
  const raw = city?.fortificationState && typeof city.fortificationState === "object"
    ? city.fortificationState
    : {};
  const repairAtMs = normalizeTimestampMs(raw.repairAtMs);
  const integrityBps = Math.floor(Number(raw.integrityBps));
  const lastDamagedAtMs = normalizeTimestampMs(raw.lastDamagedAtMs);
  const inferredRepairWindowMinutes = repairAtMs > lastDamagedAtMs
    ? Math.max(1, Math.round((repairAtMs - lastDamagedAtMs) / 60_000))
    : 0;
  const repairWindowMinutes = Math.max(
    0,
    Math.floor(Number(raw.repairWindowMinutes) || inferredRepairWindowMinutes)
  );
  const active = Math.floor(Number(raw.version) || 0) === FORTIFICATION_STATE_VERSION
    && repairAtMs > nowMs
    && Number.isFinite(integrityBps)
    && integrityBps < 10_000;
  return {
    version: FORTIFICATION_STATE_VERSION,
    integrityBps: active ? clamp(integrityBps, 0, 10_000) : 10_000,
    lastDamagedAtMs: active ? lastDamagedAtMs : 0,
    repairAtMs: active ? repairAtMs : 0,
    repairWindowMinutes: active ? repairWindowMinutes : 0,
    repairReductionPercent: active ? clamp(Number(raw.repairReductionPercent) || 0, 0, 100) : 0,
    lastArmyId: active ? String(raw.lastArmyId || "").slice(0, 96) : "",
  };
}

function getFortificationIntegrityBpsAt(state = {}, nowMs = Date.now()) {
  const integrityBps = clamp(Math.floor(Number(state.integrityBps) || 0), 0, 10_000);
  if (integrityBps >= 10_000) return 10_000;
  const repairAtMs = normalizeTimestampMs(state.repairAtMs);
  if (!repairAtMs) return integrityBps;
  const sampledAtMs = Math.max(
    0,
    Math.floor(Number.isFinite(Number(nowMs)) ? Number(nowMs) : Date.now())
  );
  if (sampledAtMs >= repairAtMs) return 10_000;
  const lastDamagedAtMs = normalizeTimestampMs(state.lastDamagedAtMs);
  if (!lastDamagedAtMs || repairAtMs <= lastDamagedAtMs || sampledAtMs <= lastDamagedAtMs) {
    return integrityBps;
  }
  const repairProgress = clamp(
    (sampledAtMs - lastDamagedAtMs) / (repairAtMs - lastDamagedAtMs),
    0,
    1
  );
  return clamp(
    integrityBps + Math.floor((10_000 - integrityBps) * repairProgress),
    integrityBps,
    10_000
  );
}

function getCityFortificationSnapshot(city = {}, statsOverride = null, nowMs = Date.now()) {
  const stats = statsOverride || getCityStats(city);
  const state = normalizeFortificationState(city, nowMs);
  const currentIntegrityBps = getFortificationIntegrityBpsAt(state, nowMs);
  const troopObjectiveDefenseBonusPercent = getObjectiveTroopDefenseBonusPercent(stats);
  const objectiveDefenseBonusPercent = Math.floor(Number(stats.defenseCombatVersion) || 0) >= DEFENSE_COMBAT_VERSION
    ? 0
    : troopObjectiveDefenseBonusPercent;
  const fullWallPower = Math.max(0, Math.floor(
    Math.max(0, Number(stats.cityWalls) || 0) * (1 + objectiveDefenseBonusPercent / 100)
  ));
  const ownerGarrisonDefensePower = Math.max(0, Math.floor(
    Math.max(0, Number(stats.troopDefense) || 0)
      * (Math.floor(Number(stats.defenseCombatVersion) || 0) >= DEFENSE_COMBAT_VERSION
        ? 1
        : 1 + objectiveDefenseBonusPercent / 100)
  ));
  return {
    modelVersion: SIEGE_COMBAT_VERSION,
    baseCityWalls: Math.max(0, Math.floor(Number(stats.baseCityWalls) || 0)),
    reinforcedCityWalls: Math.max(0, Math.floor(Number(stats.cityWalls) || 0)),
    stoneworksPercent: Math.max(0, Number(stats.stoneworksPercent) || 0),
    gearWallStrengthPercent: Math.max(0, Number(stats.gearWallStrengthPercent) || 0),
    cityLevelDefensePercent: Math.max(0, Number(stats.defensePercent) || 0),
    defenseCombatVersion: Math.max(0, Math.floor(Number(stats.defenseCombatVersion) || 0)),
    baseDefensePowerPerTroop: Math.max(1, Number(stats.baseDefensePowerPerTroop) || 1),
    shieldwallDisciplinePercent: Math.max(0, Number(stats.shieldwallDisciplinePercent) || 0),
    gearDefenderStrengthPercent: Math.max(0, Number(stats.gearDefenderStrengthPercent) || 0),
    objectiveDefenseBonusPercent,
    troopObjectiveDefenseBonusPercent,
    fullWallPower,
    currentWallPower: Math.max(0, Math.floor(fullWallPower * currentIntegrityBps / 10_000)),
    integrityBps: currentIntegrityBps,
    repairAtMs: state.repairAtMs,
    repairWindowMinutes: state.repairWindowMinutes,
    repairReductionPercent: state.repairReductionPercent,
    lastDamagedAtMs: state.lastDamagedAtMs,
    garrisonDefensePower: ownerGarrisonDefensePower,
    ownerGarrisonDefensePower,
    reinforcementGarrisonDefensePower: 0,
  };
}

function getBattleDefensePower(city) {
  const stats = getCityStats(city);
  return stats.totalDefense;
}

function getAttackPower(troops, owner) {
  const ownerBoost = owner === "player"
    ? skillMultiplier("swordmastery") + Math.max(0, Number(getCommonGearBonuses().attackStrength) || 0) / 100
    : 1.04;
  return troops * BASE_TROOP_ATTACK_POWER * ownerBoost;
}

function getCombatAdvantageTier(powerRatio = 0) {
  const ratio = Math.max(0, Number(powerRatio) || 0);
  if (ratio <= 1) return { key: "defeat_expected", label: "Defeat expected" };
  if (ratio < 1.5) return { key: "costly_victory", label: "Costly victory" };
  if (ratio < 2) return { key: "advantage", label: "Advantage" };
  if (ratio < 3) return { key: "strong_advantage", label: "Strong advantage" };
  return { key: "overwhelming_advantage", label: "Overwhelming advantage" };
}

function getMinimumTroopsForPower(requiredPower = 0, attackPowerPerTroop = BASE_TROOP_ATTACK_POWER) {
  const power = Math.max(0, Math.floor(Number(requiredPower) || 0));
  const perTroop = Math.max(Number.EPSILON, Number(attackPowerPerTroop) || BASE_TROOP_ATTACK_POWER);
  return Math.max(1, Math.floor(power / perTroop) + 1);
}

function calculateCombatResult(attackTroops, attackOwner, target, options = {}) {
  const troops = Math.max(0, Math.floor(Number(attackTroops) || 0));
  const defendersAtStart = Math.max(0, Math.floor(Number(target?.troops) || 0));
  const attackProtection = normalizeAttackProtectionSnapshot(options.attackProtection, options.demoAttack);
  const protectedAttack = attackProtection?.mode !== "normal" ? attackProtection : null;
  const hasAttackPowerOverride = Number.isFinite(Number(options.attackPower));
  const attackPower = hasAttackPowerOverride
    ? Math.max(0, Math.floor(Number(options.attackPower)))
    : getAttackPower(troops, attackOwner);
  const siegeEnabled = Math.floor(Number(options.siegeCombatVersion) || 0) >= SIEGE_COMBAT_VERSION
    && !isRewardCampTarget(target)
    && options.fortification && typeof options.fortification === "object";
  const fullWallPower = siegeEnabled
    ? Math.max(0, Math.floor(Number(options.fortification.fullWallPower) || 0))
    : 0;
  const startingIntegrityBps = siegeEnabled
    ? clamp(Math.floor(Number(options.fortification.integrityBps ?? options.fortification.startingIntegrityBps) || 0), 0, 10_000)
    : 10_000;
  const startingWallPower = siegeEnabled
    ? Math.max(0, Math.floor(Number(options.fortification.currentWallPower ?? options.fortification.startingWallPower) || 0))
    : 0;
  const garrisonDefensePower = siegeEnabled
    ? Math.max(0, Math.floor(Number(
      options.garrisonDefensePower
        ?? options.fortification.garrisonDefensePower
        ?? Math.max(0, (Number(options.defensePower) || 0) - startingWallPower)
    ) || 0))
    : 0;
  const defensePower = Number.isFinite(Number(options.defensePower))
    ? Math.max(0, Math.floor(Number(options.defensePower)))
    : siegeEnabled
      ? startingWallPower + garrisonDefensePower
      : getBattleDefensePower(target);
  const ratio = attackPower / Math.max(1, defensePower);
  const protectedRaid = protectedAttack?.mode === "raid";
  const convertedReinforcement = options.convertedReinforcement === true;
  const convertedReinforcementCanCapture = protectedRaid && convertedReinforcement;
  const breachOnly = protectedAttack?.mode === "assault"
    && protectedAttack.captureAllowed !== true
    && !convertedReinforcement;
  const wallDamagePower = siegeEnabled ? Math.min(attackPower, startingWallPower) : 0;
  const penetratingAttackPower = siegeEnabled ? Math.max(0, attackPower - startingWallPower) : attackPower;
  const wallBreached = siegeEnabled && startingWallPower <= attackPower;
  const rawEndingIntegrityBps = siegeEnabled && fullWallPower > 0
    ? Math.max(0, startingIntegrityBps - Math.ceil(wallDamagePower * 10_000 / fullWallPower))
    : startingIntegrityBps;
  const meaningfulWallDamage = siegeEnabled && startingWallPower > 0 && (
    wallDamagePower * 100 >= fullWallPower * SIEGE_MEANINGFUL_WALL_DAMAGE_PERCENT
    || rawEndingIntegrityBps <= 0
  );
  const siegePowerWon = siegeEnabled
    ? penetratingAttackPower > garrisonDefensePower
    : attackPower > defensePower;
  const battleWon = (!protectedRaid || convertedReinforcementCanCapture) && siegePowerWon;
  const success = battleWon && !breachOnly;
  const raid = protectedRaid && !success;
  const persistentDamageApplied = meaningfulWallDamage && !raid;
  const endingIntegrityBps = persistentDamageApplied ? rawEndingIntegrityBps : startingIntegrityBps;
  const repairTiming = persistentDamageApplied
    ? getSiegeRepairTiming(
      getSiegeRepairLevel(target),
      wallDamagePower,
      fullWallPower,
      options.fortification?.repairAtMs,
      Math.max(0, Math.floor(Number(options.nowMs) || Date.now())),
        Math.min(95, Math.max(0, Number(options.repairReductionPercent) || 0)
          + (target?.owner === "player" ? Math.max(0, Number(getCommonGearBonuses().wallRepairSpeed) || 0) : 0))
    )
    : null;
  const repairAtMs = repairTiming?.repairAtMs || normalizeTimestampMs(options.fortification?.repairAtMs);
  const repairWindowMinutes = repairTiming?.repairWindowMinutes
    || Math.max(0, Math.floor(Number(options.fortification?.repairWindowMinutes) || 0));
  const repairReductionPercent = repairTiming?.repairReductionPercent
    ?? clamp(Number(options.fortification?.repairReductionPercent) || 0, 0, 100);
  const repairAddedMs = repairTiming?.repairAddedMs || 0;
  const attackerBoost = attackOwner === "player"
    ? skillMultiplier("swordmastery") + Math.max(0, Number(getCommonGearBonuses().attackStrength) || 0) / 100
    : 1.04;
  let survivors = 0;
  let defendersLeft = defendersAtStart;
  let attackerLosses = troops;
  let defenderLosses = 0;

  if (raid) {
    const pressure = clamp(ratio, 0, 1);
    const damageRate = Math.min(0.1, pressure * 0.2);
    const damageCeiling = Math.floor(defendersAtStart * 0.1);
    defenderLosses = Math.min(damageCeiling, Math.floor(defendersAtStart * damageRate));
    if (defendersAtStart > 0) {
      defenderLosses = Math.min(defenderLosses, defendersAtStart - 1);
      defendersLeft = Math.max(1, defendersAtStart - defenderLosses);
    }
  } else if (battleWon) {
    const leftoverPower = Math.max(0, attackPower - defensePower * (siegeEnabled ? 1 : 0.68));
    survivors = hasAttackPowerOverride
      ? clamp(Math.floor(troops * leftoverPower / Math.max(attackPower, 1)), 1, troops)
      : clamp(Math.floor(leftoverPower / Math.max(BASE_TROOP_ATTACK_POWER * attackerBoost, 1)), 1, troops);
    attackerLosses = troops - survivors;
    defenderLosses = breachOnly ? Math.max(0, defendersAtStart - 1) : defendersAtStart;
    defendersLeft = breachOnly && defendersAtStart > 0 ? 1 : 0;
  } else if (siegeEnabled && !wallBreached) {
    const pressure = clamp(attackPower / Math.max(1, startingWallPower), 0, 1);
    const maximumRate = SIEGE_INTACT_WALL_DEFENDER_LOSS_CAP_PERCENT / 100;
    defenderLosses = Math.min(
      defendersAtStart,
      Math.floor(defendersAtStart * Math.min(maximumRate, pressure * maximumRate))
    );
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  } else if (siegeEnabled) {
    const pressure = clamp(penetratingAttackPower / Math.max(1, garrisonDefensePower), 0, 1);
    defenderLosses = Math.min(
      defendersAtStart,
      Math.floor(defendersAtStart * Math.min(0.82, pressure * 0.82))
    );
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  } else {
    const pressure = clamp(ratio, 0, 1);
    defenderLosses = Math.min(defendersAtStart, Math.floor(defendersAtStart * Math.min(0.82, pressure * 0.82)));
    defendersLeft = Math.max(defendersAtStart > 0 ? 1 : 0, defendersAtStart - defenderLosses);
  }

  return {
    attackPower,
    defensePower,
    ratio,
    battleWon,
    success,
    survivors,
    defendersLeft,
    attackerLosses,
    defenderLosses,
    killedAttackers: attackerLosses,
    killedDefenders: defenderLosses,
    attackProtection: protectedAttack,
    demoAttack: protectedAttack?.legacyDemoAttack ? normalizeDemoAttackSnapshot(options.demoAttack) : null,
    raidCompleted: raid,
    breachCompleted: breachOnly && battleWon,
    fortificationBreached: wallBreached,
    fortification: siegeEnabled ? {
      modelVersion: SIEGE_COMBAT_VERSION,
      baseCityWalls: Math.max(0, Math.floor(Number(options.fortification.baseCityWalls) || 0)),
      reinforcedCityWalls: Math.max(0, Math.floor(Number(options.fortification.reinforcedCityWalls) || 0)),
      stoneworksPercent: Math.max(0, Number(options.fortification.stoneworksPercent) || 0),
      cityLevelDefensePercent: Math.max(0, Number(options.fortification.cityLevelDefensePercent) || 0),
      objectiveDefenseBonusPercent: Math.max(0, Number(options.fortification.objectiveDefenseBonusPercent) || 0),
      fullWallPower,
      currentWallPower: startingWallPower,
      startingWallPower,
      wallDamagePower,
      penetratingAttackPower,
      garrisonDefensePower,
      ownerGarrisonDefensePower: Math.max(
        0,
        Math.floor(Number(options.fortification.ownerGarrisonDefensePower ?? garrisonDefensePower) || 0)
      ),
      reinforcementGarrisonDefensePower: Math.max(
        0,
        Math.floor(Number(options.fortification.reinforcementGarrisonDefensePower) || 0)
      ),
      startingIntegrityBps,
      endingIntegrityBps,
      meaningfulWallDamage,
      persistentDamageApplied,
      repairAtMs,
      repairWindowMinutes,
      repairReductionPercent,
      repairAddedMs,
      breached: wallBreached,
    } : null,
    convertedReinforcement,
    convertedReinforcementCapture: convertedReinforcementCanCapture && success,
  };
}

function returnSavedTroops(skill, losses, reason, excludeCityId = null) {
  const percent = skill === "fieldMedics"
    ? Math.min(COMMON_GEAR?.CASUALTY_RECOVERY_CAP_PERCENT || 75,
      getSkillPercent(skill) + Math.max(0, Number(getCommonGearBonuses().casualtyEfficiency) || 0))
    : getSkillPercent(skill);
  const lost = Math.max(0, Math.floor(Number(losses) || 0));
  if (percent <= 0 || lost <= 0) return 0;
  const saved = Math.floor(lost * percent / 100);
  if (saved <= 0) return 0;
  const city = getMainRewardCity(excludeCityId);
  if (!city) return 0;
  city.troopFloat = Math.max(0, Number(city.troopFloat) || city.troops || 0) + saved;
  city.troops = Math.floor(city.troopFloat);
  addLog(`${SKILL_CONFIG[skill].label}: ${formatNumber(saved)} troops returned to ${city.name} from ${reason}.`);
  return saved;
}

function returnSurvivingAttackersToSource(attack, troops, reason = "") {
  const returned = Math.max(0, Math.floor(Number(troops) || 0));
  if (returned <= 0) return 0;
  const source = cityById(attack?.fromId);
  const attackOwnerUid = String(attack?.ownerUid || "").trim();
  const sourceOwnerUid = String(source?.ownerUid || "").trim();
  const sourceBelongsToAttacker = Boolean(source && (
    source.owner === attack?.owner
    || (attackOwnerUid && sourceOwnerUid && attackOwnerUid === sourceOwnerUid)
  ));
  if (!sourceBelongsToAttacker) return 0;

  source.troopFloat = Math.max(0, Number(source.troopFloat) || Number(source.troops) || 0) + returned;
  source.troops = Math.floor(source.troopFloat);

  if (source.owner === "player") {
    markOwnedCityChanged(source, false);
    syncCityStateToOnline(source);
    syncOwnedCitiesToOnline(true);
  } else if (source.ownerKind === "player" && source.ownerUid) {
    syncSharedCityState(source);
  }

  const reasonText = reason ? ` from ${reason}` : "";
  addLog(`${formatNumber(returned)} surviving attackers returned to ${source.name}${reasonText}.`);
  return returned;
}

function currentDailyDateKey(now = new Date()) {
  const year = now.getUTCFullYear();
  const month = String(now.getUTCMonth() + 1).padStart(2, "0");
  const day = String(now.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function normalizeDailyCaptureTracker(daily) {
  const today = currentDailyDateKey();
  if (!daily || typeof daily !== "object" || daily.date !== today) {
    return { date: today, neutralCaptures: 0, harvestedBonuses: 0, harvestedGoldBonuses: 0, harvestedTroopBonuses: 0 };
  }
  const legacyHarvested = clamp(Math.floor(Number(daily.harvestedBonuses) || 0), 0, HARVEST_BONUS_DAILY_LIMIT);
  const hasTypedCounts = Number.isFinite(Number(daily.harvestedGoldBonuses)) || Number.isFinite(Number(daily.harvestedTroopBonuses));
  const harvestedGoldBonuses = hasTypedCounts
    ? clamp(Math.floor(Number(daily.harvestedGoldBonuses) || 0), 0, HARVEST_BONUS_DAILY_GOLD_LIMIT)
    : clamp(legacyHarvested, 0, HARVEST_BONUS_DAILY_GOLD_LIMIT);
  const harvestedTroopBonuses = hasTypedCounts
    ? clamp(Math.floor(Number(daily.harvestedTroopBonuses) || 0), 0, HARVEST_BONUS_DAILY_TROOP_LIMIT)
    : clamp(legacyHarvested - harvestedGoldBonuses, 0, HARVEST_BONUS_DAILY_TROOP_LIMIT);
  const harvestedBonuses = clamp(harvestedGoldBonuses + harvestedTroopBonuses, 0, HARVEST_BONUS_DAILY_LIMIT);
  return {
    date: today,
    neutralCaptures: clamp(Math.floor(Number(daily.neutralCaptures) || 0), 0, DAILY_NEUTRAL_CAPTURE_LIMIT),
    harvestedBonuses,
    harvestedGoldBonuses,
    harvestedTroopBonuses,
  };
}

function ensureDailyCaptureTracker() {
  if (!state) return { date: currentDailyDateKey(), neutralCaptures: 0, harvestedBonuses: 0, harvestedGoldBonuses: 0, harvestedTroopBonuses: 0 };
  state.daily = normalizeDailyCaptureTracker(state.daily);
  return state.daily;
}

function normalizeHarvestBonusType(type) {
  return HARVEST_BONUS_TYPES.includes(type) ? type : "gold";
}

function normalizeHarvestBonuses(bonuses) {
  if (!Array.isArray(bonuses)) return [];
  return bonuses
    .map(bonus => ({
      id: String(bonus?.id || ""),
      type: normalizeHarvestBonusType(bonus?.type),
      regionId: normalizeRegionId(bonus?.regionId),
      x: Number(bonus?.x),
      y: Number(bonus?.y),
      createdAt: Math.max(0, Number(bonus?.createdAt) || 0),
      createdAtMs: normalizeTimestampMs(bonus?.createdAtMs),
    }))
    .filter(bonus => bonus.id && Number.isFinite(bonus.x) && Number.isFinite(bonus.y));
}

function normalizeHarvestState(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return;
  snapshot.harvestBonuses = enforceHarvestBonusActiveLimit(snapshot.harvestBonuses);
  const timer = Number(snapshot.harvestSpawnTimer);
  snapshot.harvestSpawnTimer = Number.isFinite(timer)
    ? clamp(timer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS)
    : HARVEST_BONUS_INITIAL_SPAWN_SECONDS;
  snapshot.harvestNextSpawnAtMs = normalizeTimestampMs(snapshot.harvestNextSpawnAtMs)
    || (Date.now() + snapshot.harvestSpawnTimer * 1000);
  snapshot.harvestNextBonusType = normalizeHarvestBonusType(snapshot.harvestNextBonusType);
}

function currentUtcDateKey() {
  return new Date().toISOString().slice(0, 10);
}

function normalizeGameOverState(snapshot = state) {
  if (!snapshot || typeof snapshot !== "object") return;
  if (snapshot.gameOver === "defeat") snapshot.gameOver = null;
}

function isGamePausedByOutcome() {
  normalizeGameOverState();
  return state?.gameOver === "victory";
}

function normalizeScoutReports(reports) {
  if (!reports || typeof reports !== "object" || Array.isArray(reports)) return {};
  const normalized = {};
  const nowMs = Date.now();
  const currentGameSeconds = Math.max(0, Math.floor(Number(state?.gameSeconds) || 0));
  for (const [cityId, report] of Object.entries(reports)) {
    const troops = Math.max(0, Math.floor(Number(report?.troops) || 0));
    const reinforcements = normalizeScoutReportReinforcements(report?.reinforcements);
    const reinforcementTroops = reinforcements.reduce((total, row) => total + row.troops, 0);
    const totalDefense = Math.max(0, Math.floor(Number(report?.totalDefense) || 0));
    const baseTotalDefense = Math.min(
      totalDefense,
      Math.max(0, Math.floor(Number(report?.baseTotalDefense ?? totalDefense) || 0))
    );
    let scoutedAt = Math.max(0, Number(report?.scoutedAt) || 0);
    let expiresAt = Math.max(0, Number(report?.expiresAt) || 0);
    const scoutedAtMs = normalizeTimestampMs(report?.scoutedAtMs);
    const expiresAtMs = normalizeTimestampMs(report?.expiresAtMs);
    if (expiresAtMs) {
      const startMs = scoutedAtMs || Math.max(0, expiresAtMs - SCOUT_REPORT_SECONDS * 1000);
      const remainingSeconds = Math.max(0, Math.ceil((expiresAtMs - nowMs) / 1000));
      if (remainingSeconds <= 0) continue;
      if (!scoutedAt || !expiresAt || expiresAt <= scoutedAt || expiresAt <= currentGameSeconds) {
        const ageSeconds = Math.max(0, Math.floor((nowMs - startMs) / 1000));
        scoutedAt = Math.max(0, currentGameSeconds - ageSeconds);
        expiresAt = scoutedAt + remainingSeconds;
      }
    }
    if (expiresAt <= scoutedAt) continue;
    if (currentGameSeconds > 0 && expiresAt <= currentGameSeconds) continue;
    normalized[cityId] = {
      ...report,
      troops,
      ownerTroops: Math.max(0, Math.floor(Number(report?.ownerTroops ?? Math.max(0, troops - reinforcementTroops)) || 0)),
      reinforcementTroops,
      reinforcements,
      ownerFlag: report?.ownerFlag && typeof report.ownerFlag === "object"
        ? normalizeFlag(report.ownerFlag)
        : null,
      totalDefense,
      baseTotalDefense,
      totalDefenseBonus: Math.max(0, totalDefense - baseTotalDefense),
      siegeCombatVersion: Math.max(0, Math.floor(Number(report?.siegeCombatVersion) || 0)),
      defenseCombatVersion: Math.max(0, Math.floor(Number(report?.defenseCombatVersion) || 0)),
      baseDefensePowerPerTroop: Math.max(1, Number(report?.baseDefensePowerPerTroop) || 1),
      fortification: normalizeCombatFortificationSnapshot(report?.fortification),
      scoutedAt,
      expiresAt,
      scoutedAtMs,
      expiresAtMs,
    };
  }
  return normalized;
}

function normalizeScoutReportReinforcements(rows) {
  return (Array.isArray(rows) ? rows : [])
    .map(row => ({
      ownerUid: String(row?.ownerUid || "").slice(0, 128),
      ownerName: cleanName(row?.ownerName || "Ruler") || "Ruler",
      ownerFlag: row?.ownerFlag && typeof row.ownerFlag === "object" ? normalizeFlag(row.ownerFlag) : null,
      troops: Math.max(0, Math.floor(Number(row?.troops) || 0)),
      defenseCombatVersion: Math.max(0, Math.floor(Number(row?.defenseCombatVersion) || 0)),
      baseDefensePowerPerTroop: Math.max(1, Number(row?.baseDefensePowerPerTroop) || 1),
      basePower: Math.max(0, Math.floor(Number(row?.basePower) || 0)),
      shieldwallDisciplineLevel: Math.max(0, Math.floor(Number(row?.shieldwallDisciplineLevel) || 0)),
      shieldwallDisciplinePercent: Math.max(0, Number(row?.shieldwallDisciplinePercent) || 0),
      gearDefenderStrengthPercent: Math.max(0, Number(row?.gearDefenderStrengthPercent) || 0),
      personalDefenseBonusPercent: Math.max(0, Number(row?.personalDefenseBonusPercent) || 0),
      sharedDefenseBonusPercent: Math.max(0, Number(row?.sharedDefenseBonusPercent) || 0),
      effectivePower: Math.max(0, Math.floor(Number(row?.effectivePower) || 0)),
    }))
    .filter(row => row.ownerUid && row.troops > 0)
    .slice(0, 50);
}

function normalizeDefenderScoutDisclosure(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const count = value => Math.max(0, Math.floor(Number(value) || 0));
  const skills = {};
  for (const skill of SKILL_ORDER) {
    const value = raw.skills?.[skill];
    skills[skill] = { level: count(value?.level), percent: Math.max(0, Number(value?.percent) || 0) };
  }
  return {
    targetType: raw.targetType === "camp" ? "camp" : "city",
    troops: count(raw.troops),
    ownerTroops: count(raw.ownerTroops),
    reinforcementTroops: count(raw.reinforcementTroops),
    reinforcements: normalizeScoutReportReinforcements(raw.reinforcements),
    totalDefense: count(raw.totalDefense),
    cityLevel: raw.targetType === "camp" ? 0 : clampCityLevel(raw.cityLevel || 1),
    wallIntegrityBps: Math.min(10_000, count(raw.wallIntegrityBps)),
    skills,
  };
}

function isDefenderScoutReport(report = null) {
  return Boolean(report?.type === "scout" && report.scoutPerspective === "defender");
}

function isSuccessfulScoutIntelBattleReport(report = null) {
  if (report?.type !== "scout") return false;
  if (report.scoutReport && typeof report.scoutReport === "object") return true;
  return /^Scout revealed\b/i.test(String(report.summary || ""));
}

function getScoutBattleReportExpiresAtMs(report = null) {
  if (!isSuccessfulScoutIntelBattleReport(report)) return 0;
  const explicitExpiry = normalizeTimestampMs(report?.expiresAtMs)
    || normalizeTimestampMs(report?.scoutReport?.expiresAtMs);
  if (explicitExpiry) return explicitExpiry;
  const createdAtMs = getBattleReportOccurredAtMs(report);
  return createdAtMs ? createdAtMs + LEGACY_SCOUT_REPORT_SECONDS * 1000 : 0;
}

function getBattleReportRevisionMs(report = null) {
  return normalizeTimestampMs(report?.occurredAtMs)
    || normalizeTimestampMs(report?.createdAtMs)
    || Math.max(0, Math.floor(Number(report?.createdAt) || 0) * 1000);
}

function getBattleReportOccurredAtMs(report = null) {
  return normalizeTimestampMs(report?.occurredAtMs)
    || normalizeTimestampMs(report?.resolvedAtMs)
    || normalizeTimestampMs(report?.createdAtMs);
}

function getBattleReportHistoryExpiresAtMs(report = null) {
  if (isSuccessfulScoutIntelBattleReport(report)) {
    return getScoutBattleReportExpiresAtMs(report);
  }
  const occurredAtMs = getBattleReportOccurredAtMs(report);
  return occurredAtMs ? occurredAtMs + BATTLE_REPORT_RETENTION_MS : 0;
}

function getBattleReportAgeSeconds(report = null, nowMs = Date.now()) {
  const occurredAtMs = getBattleReportOccurredAtMs(report);
  if (occurredAtMs) return Math.max(0, Math.floor((nowMs - occurredAtMs) / 1000));
  return 0;
}

function getBattleReportExactTime(report = null) {
  const occurredAtMs = getBattleReportOccurredAtMs(report);
  return occurredAtMs ? new Date(occurredAtMs).toLocaleString() : "Time unavailable";
}

function renderBattleReportAge(report = null, className = "") {
  const occurredAtMs = getBattleReportOccurredAtMs(report);
  const classAttribute = className ? ` class="${escapeHtml(className)}"` : "";
  const timingAttribute = occurredAtMs ? ` data-report-occurred-at-ms="${occurredAtMs}"` : "";
  return `<span${classAttribute}${timingAttribute} title="${escapeHtml(getBattleReportExactTime(report))}">${formatDuration(getBattleReportAgeSeconds(report))} ago</span>`;
}

function normalizeRealmActivityEvent(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const eventType = ["STRONGHOLD_CAPTURED", "CITADEL_CAPTURED"].includes(raw.eventType)
    ? raw.eventType
    : "";
  const eventId = String(raw.eventId || raw.id || "").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 180);
  const objectiveId = String(raw.objectiveId || "").slice(0, 96);
  const attackerPlayerId = String(raw.attackerPlayerId || "").slice(0, 128);
  const occurredAtMs = normalizeTimestampMs(raw.occurredAtMs || raw.createdAtMs || raw.createdAt);
  if (!eventType || !eventId || !objectiveId || !attackerPlayerId || !occurredAtMs) return null;
  const x = Number(raw.x);
  const y = Number(raw.y);
  return {
    schemaVersion: Math.max(0, Math.floor(Number(raw.schemaVersion) || 0)),
    eventId,
    eventType,
    sourceResolutionId: String(raw.sourceResolutionId || "").slice(0, 160),
    occurredAtMs,
    createdAtMs: normalizeTimestampMs(raw.createdAtMs || raw.createdAt),
    objectiveId,
    objectiveType: eventType === "CITADEL_CAPTURED" ? "crown_citadel" : "stronghold",
    objectiveName: String(raw.objectiveName || (eventType === "CITADEL_CAPTURED" ? CROWN_CITADEL_NAME : "Stronghold")).slice(0, 80),
    strongholdType: String(raw.strongholdType || "").trim().toLowerCase().slice(0, 32),
    regionId: raw.regionId ? normalizeRegionId(raw.regionId) : "",
    x: Number.isFinite(x) ? x : null,
    y: Number.isFinite(y) ? y : null,
    attackerPlayerId,
    attackerPlayerName: cleanName(raw.attackerPlayerName || "Ruler") || "Ruler",
    attackerClanId: String(raw.attackerClanId || "").slice(0, 128),
    attackerClanName: String(raw.attackerClanName || "").slice(0, 24),
    attackerClanTag: String(raw.attackerClanTag || "").slice(0, 5),
    defenderPlayerId: String(raw.defenderPlayerId || "").slice(0, 128),
    defenderPlayerName: raw.defenderPlayerId
      ? cleanName(raw.defenderPlayerName || "Ruler") || "Ruler"
      : "",
    defenderClanId: String(raw.defenderClanId || "").slice(0, 128),
    defenderClanName: String(raw.defenderClanName || "").slice(0, 24),
    defenderClanTag: String(raw.defenderClanTag || "").slice(0, 5),
    newKingPlayerId: String(raw.newKingPlayerId || "").slice(0, 128),
    previousKingPlayerId: String(raw.previousKingPlayerId || "").slice(0, 128),
  };
}

function normalizeRealmActivityEvents(events = []) {
  const byId = new Map();
  (Array.isArray(events) ? events : []).forEach(raw => {
    const event = normalizeRealmActivityEvent(raw);
    if (!event) return;
    const existing = byId.get(event.eventId);
    if (!existing || event.occurredAtMs >= existing.occurredAtMs) byId.set(event.eventId, event);
  });
  return [...byId.values()]
    .sort((a, b) => b.occurredAtMs - a.occurredAtMs || b.eventId.localeCompare(a.eventId))
    .slice(0, REALM_ACTIVITY_HISTORY_LIMIT);
}

function getRealmActivityObjectiveLabel(event = {}) {
  if (event.eventType === "CITADEL_CAPTURED") return CROWN_CITADEL_NAME;
  const type = String(event.strongholdType || "").toLowerCase();
  if (type === "defense" || type === "defense_stronghold") return "Defense Stronghold";
  if (type === "gold" || type === "gold_stronghold") return "Gold Stronghold";
  if (type === "training" || type === "troop" || type === "troop_stronghold") return "Training Stronghold";
  if (type === "speed" || type === "march_speed" || type === "march_speed_stronghold") return "Speed Stronghold";
  if (type) {
    const label = type
      .replace(/_stronghold$/, "")
      .split(/[_-]+/)
      .filter(Boolean)
      .map(part => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
      .join(" ");
    if (label) return `${label} Stronghold`;
  }
  return String(event.objectiveName || "Stronghold");
}

function formatRealmActivityParticipant(event = {}, side = "attacker", options = {}) {
  const attacker = side === "attacker";
  const playerId = String(event[`${side}PlayerId`] || "");
  const playerName = String(event[`${side}PlayerName`] || "Ruler");
  const clanId = String(event[`${side}ClanId`] || "");
  const clanName = String(event[`${side}ClanName`] || "");
  const clanTag = String(event[`${side}ClanTag`] || "");
  const html = options.html === true;
  const includeClan = options.includeClan !== false && clanId && clanName;
  const player = html
    ? renderPlayerNameLink(playerId, playerName, `realm-activity-${attacker ? "attacker" : "defender"}`)
    : playerName;
  if (!includeClan) return player;
  const clan = html
    ? renderClanIdentityLink({
      clanId,
      clanName,
      clanTag,
      className: "realm-activity-clan",
      display: "name",
    })
    : clanName;
  return `${player} of ${clan}`;
}

function getRealmActivityCopy(event = {}, options = {}) {
  const html = options.html === true;
  const objectiveLabel = getRealmActivityObjectiveLabel(event);
  const attacker = formatRealmActivityParticipant(event, "attacker", { html });
  const attackerWithoutClan = formatRealmActivityParticipant(event, "attacker", { html, includeClan: false });
  const defender = event.defenderPlayerId
    ? formatRealmActivityParticipant(event, "defender", { html })
    : "";
  if (event.eventType === "CITADEL_CAPTURED") {
    return {
      tone: "citadel",
      title: "A NEW KING RISES",
      herald: "Hear ye! Hear ye! Let it be proclaimed throughout Crownlands!",
      body: defender
        ? `${attacker} has stormed the Crown Citadel, overthrown King ${defender}, and claimed the throne.`
        : `${attacker} has stormed the Crown Citadel and claimed the vacant throne.`,
      closing: `All hail King ${attackerWithoutClan}, ruler of Crownlands!`,
      liveTitle: "A NEW KING RISES",
      liveMessage: `All hail King ${event.attackerPlayerName}!`,
      objectiveLabel,
    };
  }
  return {
    tone: "stronghold",
    title: `THE ${objectiveLabel.toUpperCase()} HAS FALLEN`,
    herald: "Hear ye, Lords of the Realm!",
    body: defender
      ? `${attacker} has overthrown ${defender} and seized control of the ${html ? escapeHtml(objectiveLabel) : objectiveLabel}.`
      : `${attacker} has seized the unclaimed ${html ? escapeHtml(objectiveLabel) : objectiveLabel}.`,
    closing: "A new banner now flies above its walls.",
    liveTitle: "STRONGHOLD FALLEN",
    liveMessage: `${event.attackerPlayerName} seized the ${objectiveLabel}.`,
    objectiveLabel,
  };
}

function getRealmActivityArtSrc(event = {}) {
  if (event.eventType === "CITADEL_CAPTURED") return CROWN_CITADEL_ART_SRC;
  const loaded = getArmyTargetById(event.objectiveId);
  const artSrc = getStrongholdArtSrc(loaded || {
    id: event.objectiveId,
    kind: "stronghold",
    strongholdType: event.strongholdType,
  });
  return artSrc || "assets/optimized/hud-report-192x192-21644b7390fb.webp";
}

function renderRealmActivityCard(event = {}) {
  const copy = getRealmActivityCopy(event, { html: true });
  const properName = String(event.objectiveName || copy.objectiveLabel);
  const objectiveMeta = properName && properName !== copy.objectiveLabel
    ? `${properName} · ${copy.objectiveLabel}`
    : copy.objectiveLabel;
  return `
    <article class="realm-activity-card ${copy.tone}" data-realm-activity-id="${escapeHtml(event.eventId)}">
      <header class="realm-activity-card-head">
        <img src="${escapeHtml(getRealmActivityArtSrc(event))}" width="96" height="96" alt="" draggable="false" decoding="async" />
        <div>
          <strong>${escapeHtml(copy.title)}</strong>
          ${renderBattleReportAge(event, "realm-activity-age")}
        </div>
      </header>
      <div class="realm-activity-proclamation">
        <p class="realm-activity-herald">${escapeHtml(copy.herald)}</p>
        <p>${copy.body}</p>
        <p class="realm-activity-closing">${copy.closing}</p>
      </div>
      <footer class="realm-activity-card-foot">
        <span><b>Objective</b>${escapeHtml(objectiveMeta)}</span>
        <span><b>Location</b>${escapeHtml(getRegionLabel(event.regionId))}</span>
        <button class="realm-activity-location-btn" type="button" data-realm-activity-location="${escapeHtml(event.eventId)}">View Location</button>
      </footer>
    </article>
  `;
}

function normalizeCampReportReward(value = null) {
  if (!value || typeof value !== "object") return null;
  const rewardType = ["gold", "troops", "city", "item"].includes(value.rewardType)
    ? value.rewardType
    : "";
  if (!rewardType) return null;
  const amount = Math.max(0, Math.floor(Number(value.amount) || 0));
  if ((rewardType === "gold" || rewardType === "troops") && amount <= 0) return null;
  if (rewardType === "city") {
    const cityId = String(value.cityId || "").slice(0, 96);
    const cityName = String(value.cityName || "").slice(0, 80);
    if (!cityId || !cityName) return null;
    return {
      rewardType,
      amount: Math.max(1, amount),
      cityId,
      cityName,
      cityRegionId: value.cityRegionId ? normalizeRegionId(value.cityRegionId) : "",
      cityRegionName: String(value.cityRegionName || "").slice(0, 80),
    };
  }
  if (rewardType === "item") {
    const itemId = String(value.itemId || "").slice(0, 64);
    const itemName = String(value.itemName || "").slice(0, 80);
    const itemQuantity = Math.max(0, Math.floor(Number(value.itemQuantity ?? amount) || 0));
    if (!itemId || !itemName || itemQuantity <= 0) return null;
    return { rewardType, amount: itemQuantity, itemId, itemName, itemQuantity };
  }
  return { rewardType, amount };
}

function normalizeBattleReports(reports) {
  if (!Array.isArray(reports)) return [];
  const nowMs = Date.now();
  const normalized = reports
    .map(report => {
      if (!report || typeof report !== "object") return null;
      const type = ["attack", "defense", "scout"].includes(report.type) ? report.type : "";
      if (!type) return null;
      const cityId = getKnownCityId(report.cityId || report.targetCityId || report.city?.id) || String(report.cityId || report.targetCityId || report.city?.id || "");
      const targetType = report.targetType === "camp" || report.city?.targetType === "camp" || WORLD_CAMPS_BY_ID.has(cityId)
        ? "camp"
        : "city";
      const inferredRegionId = cityId ? getCityRegionId(cityId) : "";
      const rawRegionId = report.regionId || report.targetRegionId || report.city?.regionId || report.city?.startPool || inferredRegionId;
      const fallbackOutcome = type === "scout" ? "scout" : "defeat";
      const outcome = ["victory", "defeat", "held", "lost", "scout", "raid", "breach", "breached", "damaged"].includes(report.outcome)
        ? report.outcome
        : fallbackOutcome;
      return {
        id: String(report.id || `report_${Math.random().toString(36).slice(2)}`),
        type,
        outcome,
        createdAt: Math.max(0, Number(report.createdAt) || 0),
        occurredAtMs: normalizeTimestampMs(report.occurredAtMs || report.resolvedAtMs || report.createdAtMs),
        createdAtMs: normalizeTimestampMs(report.createdAtMs),
        cityId,
        targetType,
        regionId: rawRegionId ? normalizeRegionId(rawRegionId) : "",
        cityName: String(report.cityName || "Unknown city").slice(0, 40),
        cityLevel: targetType === "camp" ? 0 : clampCityLevel(report.cityLevel || 1),
        troopCount: Math.max(0, Math.floor(Number(report.troopCount) || 0)),
        sentTroops: Math.max(0, Math.floor(Number(report.sentTroops) || 0)),
        survivors: Math.max(0, Math.floor(Number(report.survivors) || 0)),
        defendersLeft: Math.max(0, Math.floor(Number(report.defendersLeft) || 0)),
        attackerLosses: Math.max(0, Math.floor(Number(report.attackerLosses) || 0)),
        defenderLosses: Math.max(0, Math.floor(Number(report.defenderLosses) || 0)),
        totalDefense: Math.max(0, Math.floor(Number(report.totalDefense) || 0)),
        baseTotalDefense: Math.min(
          Math.max(0, Math.floor(Number(report.totalDefense) || 0)),
          Math.max(0, Math.floor(Number(report.baseTotalDefense ?? report.totalDefense) || 0))
        ),
        totalDefenseBonus: Math.max(0, Math.floor(Number(report.totalDefenseBonus) || 0)),
        opponentUid: String(report.opponentUid || "").slice(0, 128),
        opponentName: String(report.opponentName || "").slice(0, 40),
        opponentFlag: report.opponentFlag && typeof report.opponentFlag === "object"
          ? normalizeFlag(report.opponentFlag)
          : null,
        scoutPerspective: report.scoutPerspective === "defender" ? "defender" : "",
        sourceCityId: String(report.sourceCityId || "").slice(0, 96),
        sourceCityName: String(report.sourceCityName || "").slice(0, 80),
        sourceRegionId: report.sourceRegionId ? normalizeRegionId(report.sourceRegionId) : "",
        scoutDisclosure: normalizeDefenderScoutDisclosure(report.scoutDisclosure),
        ownerName: String(report.ownerName || "").slice(0, 40),
        summary: String(report.summary || "").slice(0, 220),
        xpAwarded: Math.max(0, Math.floor(Number(report.xpAwarded) || 0)),
        goldAwarded: Math.max(0, Math.floor(Number(report.goldAwarded) || 0)),
        troopsAwarded: Math.max(0, Math.floor(Number(report.troopsAwarded) || 0)),
        levelUpReward: normalizeLevelUpRewardReceipt(report.levelUpReward),
        campReward: normalizeCampReportReward(report.campReward),
        eventKind: String(report.eventKind || "").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 48),
        rewardEventId: String(report.rewardEventId || "").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 160),
        rewardSourceId: String(report.rewardSourceId || "").slice(0, 96),
        rewardSourceRegionId: report.rewardSourceRegionId ? normalizeRegionId(report.rewardSourceRegionId) : "",
        fieldMedicsRecovered: Math.max(0, Math.floor(Number(report.fieldMedicsRecovered) || 0)),
        battleId: String(report.battleId || "").replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 160),
        battleSnapshotVersion: Math.max(0, Math.floor(Number(report.battleSnapshotVersion) || 0)),
        siegeCombatVersion: Math.max(0, Math.floor(Number(report.siegeCombatVersion) || 0)),
        defenseCombatVersion: Math.max(0, Math.floor(Number(report.defenseCombatVersion) || 0)),
        fortification: normalizeCombatFortificationSnapshot(report.fortification),
        attackProtection: normalizeAttackProtectionSnapshot(report.attackProtection, report.demoAttack),
        launchCombatForecast: normalizeCombatForecast(report.launchCombatForecast),
        scoutReport: report.scoutReport || null,
        expiresAtMs: normalizeTimestampMs(report.expiresAtMs || report.scoutReport?.expiresAtMs),
        bulkOrderKind: report.bulkOrderKind === "regroup" ? "regroup" : report.bulkRequestId && type === "scout" ? "nearby_scout" : "",
        bulkRequestId: String(report.bulkRequestId || "").slice(0, 96),
        bulkArrivalCue: ["first", "last", "first_last", "mute"].includes(report.bulkArrivalCue) ? report.bulkArrivalCue : "",
        bulkArrivalIndex: Math.max(0, Math.floor(Number(report.bulkArrivalIndex) || 0)),
        bulkOrderCount: Math.max(0, Math.floor(Number(report.bulkOrderCount) || 0)),
      };
    })
    .filter(Boolean);
  const active = [];
  const successfulScoutIndexByCity = new Map();
  normalized.forEach(report => {
    const historyExpiresAtMs = getBattleReportHistoryExpiresAtMs(report);
    if (historyExpiresAtMs && historyExpiresAtMs <= nowMs) return;
    if (!isSuccessfulScoutIntelBattleReport(report)) {
      active.push(report);
      return;
    }
    const expiresAtMs = getScoutBattleReportExpiresAtMs(report);
    if (!expiresAtMs) return;
    report.expiresAtMs = expiresAtMs;
    const cityId = String(report.cityId || "");
    const existingIndex = successfulScoutIndexByCity.get(cityId);
    if (existingIndex === undefined) {
      successfulScoutIndexByCity.set(cityId, active.length);
      active.push(report);
      return;
    }
    if (getBattleReportRevisionMs(report) > getBattleReportRevisionMs(active[existingIndex])) {
      active[existingIndex] = report;
    }
  });
  return active.slice(-120);
}

function compareBattleReportsNewestFirst(a = {}, b = {}) {
  const realTimeDifference = getBattleReportOccurredAtMs(b) - getBattleReportOccurredAtMs(a);
  if (realTimeDifference) return realTimeDifference;
  const gameTimeDifference = Math.max(0, Number(b.createdAt) || 0) - Math.max(0, Number(a.createdAt) || 0);
  if (gameTimeDifference) return gameTimeDifference;
  return String(b.id || "").localeCompare(String(a.id || ""));
}

function getLatestLoadedReportOccurredAtMs() {
  const battleLatest = normalizeBattleReports(state?.battleReports || []).reduce(
    (latest, report) => Math.max(latest, getBattleReportOccurredAtMs(report)),
    0
  );
  return normalizeRealmActivityEvents(onlineRealmActivityEvents).reduce(
    (latest, event) => Math.max(latest, event.occurredAtMs),
    battleLatest
  );
}

function getUnreadReportCount() {
  const viewedAtMs = Math.max(
    normalizeTimestampMs(state?.reportsViewedAtMs),
    normalizeTimestampMs(reportsViewedPendingAtMs)
  );
  const battleUnread = normalizeBattleReports(state?.battleReports || []).reduce((count, report) => (
    getBattleReportOccurredAtMs(report) > viewedAtMs ? count + 1 : count
  ), 0);
  return normalizeRealmActivityEvents(onlineRealmActivityEvents).reduce((count, event) => (
    event.occurredAtMs > viewedAtMs ? count + 1 : count
  ), battleUnread);
}

function updateReportUnreadBadge() {
  if (!reportUnreadBadge || !logBtn) return;
  const unreadCount = getUnreadReportCount();
  reportUnreadBadge.hidden = unreadCount <= 0;
  reportUnreadBadge.textContent = unreadCount > 99 ? "99+" : String(unreadCount);
  reportUnreadBadge.setAttribute("aria-label", `${unreadCount} unread ${unreadCount === 1 ? "report" : "reports"}`);
  logBtn.setAttribute("aria-label", unreadCount > 0
    ? `Reports, ${unreadCount > 99 ? "more than 99" : unreadCount} unread`
    : "Reports");
}

async function markLoadedReportsViewed() {
  if (!state) return false;
  const viewedThroughMs = getLatestLoadedReportOccurredAtMs();
  if (!viewedThroughMs) {
    updateReportUnreadBadge();
    return false;
  }
  reportsViewedPendingAtMs = Math.max(reportsViewedPendingAtMs, viewedThroughMs);
  updateReportUnreadBadge();
  const api = getOnlineApi();
  if (!api?.markReportsViewed || !api?.isSignedIn?.()) {
    state.reportsViewedAtMs = Math.max(
      normalizeTimestampMs(state.reportsViewedAtMs),
      reportsViewedPendingAtMs
    );
    reportsViewedPendingAtMs = 0;
    saveGame();
    return true;
  }
  if (reportsViewedRequestInFlight) return true;
  reportsViewedRequestInFlight = true;
  try {
    while (reportsViewedPendingAtMs > normalizeTimestampMs(state.reportsViewedAtMs)) {
      const requestedViewedAtMs = reportsViewedPendingAtMs;
      const result = await api.markReportsViewed({ viewedThroughMs: requestedViewedAtMs });
      const confirmedViewedAtMs = normalizeTimestampMs(result?.reportsViewedAtMs);
      if (!confirmedViewedAtMs) throw new Error("The server did not confirm the Reports read position.");
      state.reportsViewedAtMs = Math.max(
        normalizeTimestampMs(state.reportsViewedAtMs),
        confirmedViewedAtMs
      );
      if (confirmedViewedAtMs < requestedViewedAtMs) {
        reportsViewedPendingAtMs = 0;
        saveGame();
        break;
      }
      if (reportsViewedPendingAtMs <= normalizeTimestampMs(state.reportsViewedAtMs)) {
        reportsViewedPendingAtMs = 0;
      }
      saveGame();
    }
  } catch (error) {
    console.warn("Could not save the Reports read position", error);
  } finally {
    reportsViewedRequestInFlight = false;
    updateReportUnreadBadge();
  }
  return true;
}

function normalizeTimestampMs(value) {
  const timestamp = Number(value);
  return Number.isFinite(timestamp) && timestamp > 0 ? Math.floor(timestamp) : 0;
}

function getScoutReport(cityId) {
  if (!state || !cityId) return null;
  state.scoutReports = normalizeScoutReports(state.scoutReports);
  const report = state.scoutReports[cityId];
  if (!report) return null;
  if (report.expiresAt <= state.gameSeconds) {
    delete state.scoutReports[cityId];
    return null;
  }
  return report;
}

function getScoutReportForTarget(target = null) {
  if (!target?.id) return null;
  const report = getScoutReport(target.id);
  if (!report) return null;
  const currentUid = getCurrentOnlineUid();
  const targetOwnerUid = String(
    target.ownerUid || (target.owner === "player" ? currentUid : "") || ""
  ).trim();
  const reportOwnerUid = String(report.ownerUid || "").trim();
  return targetOwnerUid === reportOwnerUid ? report : null;
}

function getScoutReportRemainingSeconds(report = null, nowMs = Date.now()) {
  const expiresAtMs = normalizeTimestampMs(report?.expiresAtMs);
  if (expiresAtMs) return Math.max(0, Math.ceil((expiresAtMs - nowMs) / 1000));
  return Math.max(0, Math.ceil((Number(report?.expiresAt) || 0) - (Number(state?.gameSeconds) || 0)));
}

function getScoutReportAgeSeconds(report = null, nowMs = Date.now()) {
  const scoutedAtMs = normalizeTimestampMs(report?.scoutedAtMs);
  if (scoutedAtMs) return Math.max(0, Math.floor((nowMs - scoutedAtMs) / 1000));
  return Math.max(0, Math.floor((Number(state?.gameSeconds) || 0) - (Number(report?.scoutedAt) || 0)));
}

function updateVisibleFortificationRepairStatus(nowMs = Date.now()) {
  if (!modal?.open || !modalBody) return;
  const label = modalBody.querySelector("[data-fortification-repair-at-ms]");
  if (!label || label.dataset.fortificationRepairComplete === "true") return;
  const repairAtMs = normalizeTimestampMs(label.dataset.fortificationRepairAtMs);
  const remaining = Math.max(0, Math.ceil((repairAtMs - nowMs) / 1000));
  setTextIfChanged(
    label,
    remaining > 0
      ? `Full repair in ${formatDuration(remaining)}`
      : "Fully repaired — wall integrity restored"
  );
  const status = label.closest(".fortification-status");
  if (!status) {
    if (remaining <= 0) label.dataset.fortificationRepairComplete = "true";
    return;
  }
  const displayedAtMs = normalizeTimestampMs(status.dataset.fortificationDisplayedAtMs);
  if (!displayedAtMs && remaining > 0) return;
  const displayedIntegrityBps = clamp(
    Math.floor(Number(status.dataset.fortificationDisplayedIntegrityBps) || 0),
    0,
    10_000
  );
  const integrityBps = displayedAtMs
    ? getFortificationIntegrityBpsAt({
      integrityBps: displayedIntegrityBps,
      lastDamagedAtMs: displayedAtMs,
      repairAtMs,
    }, nowMs)
    : 10_000;
  const lastRenderedIntegrityBps = Math.floor(
    Number(status.dataset.fortificationRenderedIntegrityBps) || 0
  );
  if (integrityBps !== lastRenderedIntegrityBps) {
    status.dataset.fortificationRenderedIntegrityBps = String(integrityBps);
    const breached = integrityBps <= 0;
    const damaged = integrityBps < 10_000;
    const nextClass = breached ? "breached" : damaged ? "damaged" : "intact";
    if (!status.classList.contains(nextClass)) {
      status.classList.remove("intact", "damaged", "breached");
      status.classList.add(nextClass);
    }
    const integrity = status.querySelector("[data-fortification-integrity]");
    setTextIfChanged(
      integrity,
      `${formatWallIntegrity(integrityBps)} · ${breached ? "Breached" : damaged ? "Damaged" : "Intact"}`
    );
    const fullWallPower = Math.max(0, Math.floor(Number(status.dataset.fortificationFullWallPower) || 0));
    const power = status.querySelector("[data-fortification-power]");
    if (power && fullWallPower > 0) {
      const currentWallPower = Math.max(0, Math.floor(fullWallPower * integrityBps / 10_000));
      setTextIfChanged(
        power,
        `${formatNumber(currentWallPower)} / ${formatNumber(fullWallPower)} wall power. Walls absorb attack power before the garrison fights.`
      );
    }
  }
  if (remaining <= 0) label.dataset.fortificationRepairComplete = "true";
}

function updateScoutReportLifecycle(nowMs = Date.now()) {
  if (!state) return false;
  const beforeScoutIds = Object.keys(state.scoutReports || {}).sort().join("|");
  const beforeBattleIds = (state.battleReports || []).map(report => report?.id || "").join("|");
  state.scoutReports = normalizeScoutReports(state.scoutReports);
  state.battleReports = normalizeBattleReports(state.battleReports);
  const afterScoutIds = Object.keys(state.scoutReports).sort().join("|");
  const afterBattleIds = state.battleReports.map(report => report.id).join("|");
  const changed = beforeScoutIds !== afterScoutIds || beforeBattleIds !== afterBattleIds;

  modalBody?.querySelectorAll?.("[data-report-occurred-at-ms]").forEach(label => {
    const occurredAtMs = normalizeTimestampMs(label.dataset.reportOccurredAtMs);
    if (!occurredAtMs) return;
    label.textContent = `${formatDuration(Math.max(0, Math.floor((nowMs - occurredAtMs) / 1000)))} ago`;
    label.title = new Date(occurredAtMs).toLocaleString();
  });

  updateVisibleFortificationRepairStatus(nowMs);

  const activeScoutCityId = String(modal?.dataset?.scoutReportCityId || "");
  if (modal?.open && modal.classList.contains("scout-report-modal")) {
    const report = activeScoutCityId ? getScoutReport(activeScoutCityId) : null;
    if (!report) {
      delete modal.dataset.scoutReportCityId;
      showLogModal({ silentAudio: true });
      showToast("That scout report expired. Send a new scout for updated intelligence.");
    } else {
      const age = getScoutReportAgeSeconds(report, nowMs);
      const remaining = getScoutReportRemainingSeconds(report, nowMs);
      modalBody.querySelectorAll("[data-scout-report-age]").forEach(label => {
        label.textContent = formatDuration(age);
      });
      modalBody.querySelectorAll("[data-scout-report-expires]").forEach(label => {
        label.textContent = formatDuration(remaining);
      });
    }
  }

  if (modal?.open && modal.classList.contains("battle-report-modal")) {
    const activeIds = new Set(state.battleReports.map(report => report.id));
    const detailId = String(modal.dataset.battleReportDetailId || "");
    const renderedExpiredCard = [...modalBody.querySelectorAll("[data-report-card-id]")]
      .some(card => !activeIds.has(card.dataset.reportCardId));
    if ((detailId && !activeIds.has(detailId)) || renderedExpiredCard) {
      showLogModal({ silentAudio: true });
    } else {
      modalBody.querySelectorAll("[data-scout-report-expires-at-ms]").forEach(label => {
        const expiresAtMs = normalizeTimestampMs(label.dataset.scoutReportExpiresAtMs);
        label.textContent = `Expires in ${formatDuration(Math.max(0, Math.ceil((expiresAtMs - nowMs) / 1000)))}`;
      });
    }
  }

  if (
    modal?.open
    && modal.classList.contains("troop-slider-modal")
    && activeTroopOrderKind === "attack"
    && activeTroopSliderRoute?.route?.points?.length
  ) {
    const source = cityById(activeTroopSliderRoute.sourceId);
    const target = getArmyTargetById(activeTroopSliderRoute.targetId);
    if (source && target) updateTroopSliderModal(source, target, activeTroopSliderRoute.route);
  }

  if (changed) {
    saveGame();
    cityRenderSignature = "";
    renderCities(true);
    renderPanel();
  }
  updateReportUnreadBadge();
  return changed;
}

function scoutCity(cityId) {
  const target = cityById(cityId);
  if (!target || target.owner === "player") return;
  void scoutTarget(target);
}

function scoutRewardCamp(campId) {
  const target = getCampTargetById(campId);
  if (!target) return;
  if (target.owner === "player") {
    rejectGameAction(`You already control ${target.name}.`);
    return;
  }
  void scoutTarget(target);
}

async function scoutTarget(target) {
  const campTarget = isRewardCampTarget(target);
  const mainCityBlockReason = campTarget ? "" : getMainCityScoutBlockReason(target, "player");
  if (mainCityBlockReason) {
    rejectGameAction(mainCityBlockReason);
    return;
  }
  if (getPendingScoutMission(target.id)) {
    rejectGameAction(`A scout is already traveling to ${target.name}`);
    return;
  }
  if (pendingDirectScoutTargets.has(target.id)) {
    showToast(`A scout route to ${target.name} is already being calculated.`);
    return;
  }
  pendingDirectScoutTargets.add(target.id);
  try {
    const instantSource = findNearestOwnedSourceCandidate(target, 1);
    const sourceOption = usesServerArmyAuthority() && instantSource?.city
      ? { city: instantSource.city, route: createInstantOrderRoute(instantSource.city, target) }
      : await findNearestScoutSourceAsync(target);
    const freshTarget = getArmyTargetById(target.id);
    if (!freshTarget || getPendingScoutMission(target.id)) return;
    if (!sourceOption?.city || sourceOption.city.owner !== "player" || sourceOption.city.troops < 1) {
      rejectGameAction("No owned city with a troop can reach this target.");
      return;
    }

    const source = sourceOption.city;
    const mission = launchScoutMission(source, freshTarget, sourceOption.route);
    if (!mission || usesServerArmyAuthority()) return;
    if (isOnlineWorldActive() && !usesServerArmyAuthority()) syncOwnedCitiesToOnline(true);
    addLog(`One scout left ${source.name} for ${freshTarget.name}.`);
    saveGame();
    renderAll();
    showToast(`Scout moving from ${source.name} to ${freshTarget.name}`);
  } finally {
    pendingDirectScoutTargets.delete(target.id);
  }
}

function launchScoutMission(source, target, route, _options = {}) {
  const options = _options && typeof _options === "object" ? _options : {};
  if (!source || !target || source.owner !== "player" || source.troops < 1 || !route?.points?.length) return null;
  const campTarget = isRewardCampTarget(target);
  const mainCityBlockReason = campTarget ? "" : getMainCityScoutBlockReason(target, "player");
  if (mainCityBlockReason) {
    rejectGameAction(mainCityBlockReason);
    return null;
  }
  if (!canUseOnlineArmyOrders()) return null;
  const duration = travelTime(source, target, "player", route.length, 1, "scout");
  const mission = {
    id: attackIdCounter++,
    owner: "player",
    kind: "scout",
    targetType: campTarget ? "camp" : "city",
    fromId: source.id,
    toId: target.id,
    troops: 1,
    total: duration,
    remaining: duration,
    path: route.points,
    pathSegments: getRouteSegments(route, getCityRegionId(source)),
    pathLength: route.length,
    sourceRegionId: getCityRegionId(source),
    targetRegionId: getCityRegionId(target),
    targetOwnerAtLaunch: target.owner,
    bulkAudioVersion: Math.max(0, Math.floor(Number(options.bulkAudioVersion) || 0)),
    bulkOrderKind: options.bulkOrderKind || "",
    bulkRequestId: options.bulkRequestId || "",
    bulkArrivalCue: options.bulkArrivalCue || "",
    bulkArrivalIndex: Math.max(0, Math.floor(Number(options.bulkArrivalIndex) || 0)),
    bulkOrderCount: Math.max(0, Math.floor(Number(options.bulkOrderCount) || 0)),
  };
  prepareOnlineArmyMission(mission);
  if (usesServerArmyAuthority()) {
    const launchKey = getServerArmyLaunchKey(source.id, target.id, "scout");
    if (pendingServerArmyLaunchKeys.has(launchKey)) {
      rejectGameAction(`A scout order from ${source.name} to ${target.name} is already being sent.`);
      return null;
    }
    pendingServerArmyLaunchKeys.add(launchKey);
    publishOnlineArmyMovement(mission, { addLocalMissionOnAccept: true, optimistic: false })
      .then(accepted => {
        if (!accepted) return;
        addLog(`One scout left ${source.name} for ${target.name}.`);
        if (!options.silentAudio) {
          playGameSound("troop_dispatch", {
            cooldownMs: 80,
            regionId: getCityRegionId(source),
            allowCrossMap: true,
          });
        }
        showToast(`Scout moving from ${source.name} to ${target.name}`);
      })
      .finally(() => pendingServerArmyLaunchKeys.delete(launchKey));
    showToast("Sending scout order to the server...");
    return mission;
  }

  source.troopFloat = Math.max(0, (Number(source.troopFloat) || source.troops) - 1);
  source.troops = Math.floor(source.troopFloat);
  markOwnedCityChanged(source, false);
  syncCityStateToOnline(source);
  state.attacks.push(mission);
  publishOnlineArmyMovement(mission);
  if (!options.silentAudio) {
    playGameSound("troop_dispatch", { cooldownMs: 80, regionId: getCityRegionId(source) });
  }
  return mission;
}

function isNearbyScoutCandidate(source, city) {
  return Boolean(
    source &&
    city &&
    city.id !== source.id &&
    getCityRegionId(city) === getCityRegionId(source) &&
    city.owner !== "player" &&
    !getMainCityScoutBlockReason(city, "player") &&
    !getPendingScoutMission(city.id) &&
    Math.hypot(city.x - source.x, city.y - source.y) <= SCOUT_NEARBY_RADIUS
  );
}

function getNearbyScoutCandidates(source) {
  return state.cities.filter(city => isNearbyScoutCandidate(source, city));
}

function getBulkOrderKey(kind, cityId) {
  return `${String(kind || "bulk")}:${String(cityId || "")}`;
}

function getBulkOrderRequestId(kind, cityId) {
  const key = getBulkOrderKey(kind, cityId);
  let requestId = bulkOrderRequestIds.get(key);
  if (!requestId) {
    requestId = createOnlineArmyId(kind === "scout" ? "nearby_scout" : "regroup");
    bulkOrderRequestIds.set(key, requestId);
  }
  return requestId;
}

function beginBulkOrderAction(kind, cityId) {
  if (pendingBulkOrderAction?.kind === kind && pendingBulkOrderAction?.cityId === cityId) return null;
  const action = {
    id: ++bulkOrderActionRequestId,
    kind,
    cityId,
    requestId: getBulkOrderRequestId(kind, cityId),
    phase: "routing",
  };
  pendingBulkOrderAction = action;
  return action;
}

function isBulkOrderActionCurrent(action) {
  if (!action || pendingBulkOrderAction?.id !== action.id) return false;
  if (action.kind === "scout") return scoutNearbySourceId === action.cityId;
  return regroupSourceId === action.cityId;
}

function finishBulkOrderAction(action, { completed = false } = {}) {
  if (pendingBulkOrderAction?.id === action?.id) pendingBulkOrderAction = null;
  if (completed) bulkOrderRequestIds.delete(getBulkOrderKey(action?.kind, action?.cityId));
}

function cancelBulkOrderPreview(kind = "", cityId = "") {
  bulkOrderActionRequestId += 1;
  pendingBulkOrderAction = null;
  if (kind && cityId) bulkOrderRequestIds.delete(getBulkOrderKey(kind, cityId));
}

async function getNearbyScoutOptionsAsync(source) {
  const candidates = getNearbyScoutCandidates(source);
  const routes = await findRoutesAsync(candidates.map(city => ({ source, target: city })));
  return candidates
    .map((city, index) => ({ city, route: routes[index] }))
    .filter(option => option.route?.points?.length)
    .sort((a, b) => a.route.length - b.route.length);
}

function getBulkResultCityUpdates(result = {}) {
  const rows = [
    ...(Array.isArray(result.cities) ? result.cities : []),
    ...(Array.isArray(result.cityUpdates) ? result.cityUpdates : []),
    result.sourceCity,
    result.targetCity,
  ].filter(city => city?.id);
  return [...new Map(rows.map(city => [`${normalizeRegionId(city.regionId || city.islandId)}:${city.id}`, city])).values()];
}

function getBulkOrderAudioKind(entry = {}) {
  if (entry.bulkOrderKind === "nearby_scout" || entry.bulkOrderKind === "regroup") {
    return entry.bulkOrderKind;
  }
  if (!entry.bulkRequestId) return "";
  return entry.kind === "scout" || entry.type === "scout" ? "nearby_scout" : "regroup";
}

function annotateClientBulkArrivalAudio(armies = []) {
  const groups = new Map();
  (Array.isArray(armies) ? armies : []).forEach(army => {
    const bulkRequestId = String(army?.bulkRequestId || "").trim();
    const bulkOrderKind = getBulkOrderAudioKind(army);
    if (!army || !bulkRequestId || !bulkOrderKind) return;
    const key = `${bulkOrderKind}:${bulkRequestId}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(army);
  });
  groups.forEach(group => {
    const authoritative = group.every(army => (
      Math.max(0, Math.floor(Number(army.bulkAudioVersion) || 0)) >= 1
      && ["first", "last", "first_last", "mute"].includes(army.bulkArrivalCue)
    ));
    if (authoritative) return;
    const ordered = [...group].sort((left, right) => (
      normalizeTimestampMs(left.arrivesAtMs) - normalizeTimestampMs(right.arrivesAtMs)
      || String(left.id || left.onlineId || "").localeCompare(String(right.id || right.onlineId || ""))
    ));
    const count = ordered.length;
    ordered.forEach((army, arrivalIndex) => {
      const bulkOrderKind = getBulkOrderAudioKind(army);
      let bulkArrivalCue = "mute";
      if (bulkOrderKind === "nearby_scout" && arrivalIndex === 0) bulkArrivalCue = "first";
      if (bulkOrderKind === "regroup") {
        if (count === 1) bulkArrivalCue = "first_last";
        else if (arrivalIndex === 0) bulkArrivalCue = "first";
        else if (arrivalIndex === count - 1) bulkArrivalCue = "last";
      }
      Object.assign(army, {
        bulkOrderKind,
        bulkArrivalCue,
        bulkArrivalIndex: arrivalIndex,
        bulkOrderCount: count,
      });
    });
  });
  return armies;
}

function claimBulkArrivalAudio(entry = {}) {
  const bulkRequestId = String(entry?.bulkRequestId || "").trim();
  const bulkOrderKind = getBulkOrderAudioKind(entry);
  if (!bulkRequestId || !bulkOrderKind) return true;
  const cue = ["first", "last", "first_last", "mute"].includes(entry.bulkArrivalCue)
    ? entry.bulkArrivalCue
    : "mute";
  if (cue === "mute") return false;
  const nowMs = Date.now();
  claimedBulkArrivalAudio.forEach((expiresAtMs, key) => {
    if (expiresAtMs <= nowMs) claimedBulkArrivalAudio.delete(key);
  });
  const key = `${bulkOrderKind}:${bulkRequestId}:${cue}`;
  if (claimedBulkArrivalAudio.has(key)) return false;
  claimedBulkArrivalAudio.set(key, nowMs + BATTLE_REPORT_RETENTION_MS);
  return true;
}

function applyServerBulkOrderResult(result = {}) {
  const cityUpdates = getBulkResultCityUpdates(result);
  applyServerArmyResult({
    currentUser: result.currentUser,
    globalStats: result.globalStats,
    cityUpdates,
  });
  if (Number.isFinite(Number(result.gold))) state.gold = Math.max(0, Math.floor(Number(result.gold)));
  const armies = Array.isArray(result.armies)
    ? result.armies
    : Array.isArray(result.movements) ? result.movements : result.movement ? [result.movement] : [];
  annotateClientBulkArrivalAudio(armies);
  armies.forEach(adoptServerArmyMovement);
  onlineLastError = "";
  saveGame();
  renderAll();
  return armies;
}

async function toggleScoutNearby(cityId) {
  if (!canUseBulkArmyOrders()) {
    cancelBulkOrderPreview("scout", cityId);
    scoutNearbySourceId = null;
    regroupSourceId = null;
    renderAll();
    rejectGameAction("Scout Nearby needs the latest Crownlands server. Reconnect and try again.");
    return;
  }
  const source = cityById(cityId);
  if (!source || source.owner !== "player") {
    cancelBulkOrderPreview("scout", cityId);
    scoutNearbySourceId = null;
    regroupSourceId = null;
    renderAll();
    return;
  }
  if (source.troops < 1) {
    cancelBulkOrderPreview("scout", source.id);
    scoutNearbySourceId = null;
    renderAll();
    rejectGameAction(`${source.name} needs at least 1 soldier to send scouts.`);
    return;
  }

  if (scoutNearbySourceId !== source.id) {
    cancelBulkOrderPreview();
    scoutNearbySourceId = source.id;
    regroupSourceId = null;
    getBulkOrderRequestId("scout", source.id);
    const targets = getNearbyScoutCandidates(source);
    renderAll();
    showToast(targets.length
      ? `${targets.length} nearby cities. Press Send All to dispatch one scout to each for ${formatNumber(SCOUT_NEARBY_COST)} gold.`
      : "No non-owned cities are inside this scout radius.");
    return;
  }

  const action = beginBulkOrderAction("scout", source.id);
  if (!action) {
    showToast(pendingBulkOrderAction?.phase === "sending" ? "Scout orders are being sent..." : "Finding reachable scout targets...");
    return;
  }
  renderAll();
  const serverBulkOrder = supportsBulkArmyOrders();
  if (serverBulkOrder) action.phase = "sending";
  showToast(serverBulkOrder ? "Sending scout orders..." : "Finding reachable scout targets...");
  if (!serverBulkOrder) await waitForSetupLoadingPaint(0);
  const options = serverBulkOrder
    ? getNearbyScoutCandidates(source).map(city => ({ city, route: null }))
    : await getNearbyScoutOptionsAsync(source);
  if (!isBulkOrderActionCurrent(action)) return;
  if (!options.length) {
    finishBulkOrderAction(action, { completed: true });
    scoutNearbySourceId = null;
    renderAll();
    rejectGameAction("No reachable cities remain inside this scout radius.");
    return;
  }
  if (state.gold < SCOUT_NEARBY_COST) {
    finishBulkOrderAction(action);
    renderAll();
    rejectGameAction(`Scout Nearby costs ${formatNumber(SCOUT_NEARBY_COST)} gold.`);
    return;
  }
  if (source.troops < options.length) {
    finishBulkOrderAction(action);
    renderAll();
    rejectGameAction(`${source.name} needs ${formatNumber(options.length)} troops to scout every highlighted city.`);
    return;
  }

  if (serverBulkOrder) {
    const api = getOnlineApi();
    if (!api?.sendNearbyScouts) {
      finishBulkOrderAction(action);
      renderAll();
      rejectGameAction("Scout Nearby needs the latest Crownlands server. Reconnect and try again.");
      return;
    }
    action.phase = "sending";
    renderAll();
    try {
      const result = await api.sendNearbyScouts({
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        sourceCityId: source.id,
        sourceRegionId: getCityRegionId(source),
        targetCityIds: options.map(option => option.city.id),
        requestId: action.requestId,
      });
      const armies = applyServerBulkOrderResult(result);
      finishBulkOrderAction(action, { completed: true });
      scoutNearbySourceId = null;
      if (armies.length) {
        playGameSound("troop_dispatch", {
          cooldownMs: 80,
          regionId: getCityRegionId(source),
          allowCrossMap: true,
        });
      }
      addLog(`${source.name} dispatched ${formatNumber(armies.length || options.length)} nearby scouts for ${formatNumber(SCOUT_NEARBY_COST)} gold.`);
      renderAll();
      showToast(`${formatNumber(armies.length || options.length)} scouts dispatched from ${source.name}`);
    } catch (error) {
      onlineLastError = error?.message || String(error);
      finishBulkOrderAction(action);
      renderAll();
      rejectGameAction(onlineLastError || "Scout Nearby could not be sent.");
    }
    return;
  }

  if (isOnlineWorldActive()) {
    finishBulkOrderAction(action);
    scoutNearbySourceId = null;
    renderAll();
    rejectGameAction("Scout Nearby lost its server connection. Reconnect and try again.");
    return;
  }

  state.gold -= SCOUT_NEARBY_COST;
  let launched = 0;
  for (let index = 0; index < options.length; index += 1) {
    const option = options[index];
    if (launchScoutMission(source, option.city, option.route, {
      silentAudio: launched > 0,
      bulkOrderKind: "nearby_scout",
      bulkRequestId: action.requestId,
      bulkArrivalCue: index === 0 ? "first" : "mute",
      bulkArrivalIndex: index,
      bulkOrderCount: options.length,
    })) launched += 1;
  }
  if (!launched) state.gold += SCOUT_NEARBY_COST;
  finishBulkOrderAction(action, { completed: launched > 0 });
  scoutNearbySourceId = null;
  if (isOnlineWorldActive() && !usesServerArmyAuthority()) syncOwnedCitiesToOnline(true);
  if (launched) addLog(`${source.name} dispatched ${formatNumber(launched)} nearby scouts for ${formatNumber(SCOUT_NEARBY_COST)} gold.`);
  saveGame();
  renderAll();
  if (launched) showToast(`${formatNumber(launched)} scouts dispatched from ${source.name}`);
  else rejectGameAction("No nearby scouts could be sent right now.");
}

function isNearbyRegroupCandidate(target, city) {
  return Boolean(
    target &&
    city &&
    city.id !== target.id &&
    target.owner === "player" &&
    city.owner === "player" &&
    getCityRegionId(city) === getCityRegionId(target) &&
    Math.floor(Number(city.troops) || 0) > 0 &&
    Math.hypot(city.x - target.x, city.y - target.y) <= REGROUP_RADIUS
  );
}

function getNearbyRegroupCandidates(target) {
  return state.cities.filter(city => isNearbyRegroupCandidate(target, city));
}

async function getNearbyRegroupOptionsAsync(target) {
  const candidates = getNearbyRegroupCandidates(target);
  const routes = await findRoutesAsync(candidates.map(city => ({ source: city, target })));
  return candidates
    .map((city, index) => ({ city, route: routes[index] }))
    .filter(option => option.route?.points?.length)
    .sort((a, b) => a.route.length - b.route.length);
}

async function toggleRegroup(cityId) {
  if (!canUseBulkArmyOrders()) {
    cancelBulkOrderPreview("regroup", cityId);
    scoutNearbySourceId = null;
    regroupSourceId = null;
    renderAll();
    rejectGameAction("Regroup needs the latest Crownlands server. Reconnect and try again.");
    return;
  }
  const target = cityById(cityId);
  if (!target || target.owner !== "player") {
    cancelBulkOrderPreview("regroup", cityId);
    regroupSourceId = null;
    renderAll();
    return;
  }

  if (regroupSourceId !== target.id) {
    cancelBulkOrderPreview();
    regroupSourceId = target.id;
    scoutNearbySourceId = null;
    getBulkOrderRequestId("regroup", target.id);
    const targets = getNearbyRegroupCandidates(target);
    const troops = targets.reduce((total, city) => total + Math.floor(Number(city.troops) || 0), 0);
    renderAll();
    showToast(targets.length
      ? `${formatNumber(targets.length)} owned cities can regroup ${formatNumber(troops)} troops to ${target.name} for ${formatNumber(REGROUP_COST)} gold. Press Regroup again.`
      : `No owned cities with troops are inside ${target.name}'s regroup radius.`);
    return;
  }

  const action = beginBulkOrderAction("regroup", target.id);
  if (!action) {
    showToast(pendingBulkOrderAction?.phase === "sending" ? "Regroup orders are being sent..." : "Finding reachable regroup routes...");
    return;
  }
  renderAll();
  const serverBulkOrder = supportsBulkArmyOrders();
  if (serverBulkOrder) action.phase = "sending";
  showToast(serverBulkOrder ? "Sending regroup orders..." : "Finding reachable regroup routes...");
  if (!serverBulkOrder) await waitForSetupLoadingPaint(0);
  const options = serverBulkOrder
    ? getNearbyRegroupCandidates(target).map(city => ({ city, route: null }))
    : await getNearbyRegroupOptionsAsync(target);
  if (!isBulkOrderActionCurrent(action)) return;
  if (!options.length) {
    finishBulkOrderAction(action, { completed: true });
    regroupSourceId = null;
    renderAll();
    rejectGameAction("No nearby owned cities with troops can regroup here.");
    return;
  }
  if (state.gold < REGROUP_COST) {
    finishBulkOrderAction(action);
    renderAll();
    rejectGameAction(`Regroup costs ${formatNumber(REGROUP_COST)} gold.`);
    return;
  }

  if (serverBulkOrder) {
    const api = getOnlineApi();
    if (!api?.sendRegroupOrders) {
      finishBulkOrderAction(action);
      renderAll();
      rejectGameAction("Regroup needs the latest Crownlands server. Reconnect and try again.");
      return;
    }
    action.phase = "sending";
    renderAll();
    try {
      const result = await api.sendRegroupOrders({
        worldId: ONLINE_WORLD_ID,
        resetGeneration: RESET_GENERATION,
        targetCityId: target.id,
        targetRegionId: getCityRegionId(target),
        sourceCityIds: options.map(option => option.city.id),
        requestId: action.requestId,
      });
      const armies = applyServerBulkOrderResult(result);
      const troopsSent = armies.reduce((total, army) => total + Math.max(0, Math.floor(Number(army?.troops) || 0)), 0);
      finishBulkOrderAction(action, { completed: true });
      regroupSourceId = null;
      if (armies.length) {
        playGameSound("troop_dispatch", {
          cooldownMs: 80,
          regionId: getCityRegionId(target),
          allowCrossMap: true,
        });
      }
      addLog(`${target.name} called a regroup for ${formatNumber(REGROUP_COST)} gold: ${formatNumber(troopsSent)} troops moving in from ${formatNumber(armies.length || options.length)} cities.`);
      renderAll();
      showToast(`Regroup moving: ${formatNumber(troopsSent)} troops to ${target.name}`);
    } catch (error) {
      onlineLastError = error?.message || String(error);
      finishBulkOrderAction(action);
      renderAll();
      rejectGameAction(onlineLastError || "Regroup could not be sent.");
    }
    return;
  }

  if (isOnlineWorldActive()) {
    finishBulkOrderAction(action);
    regroupSourceId = null;
    renderAll();
    rejectGameAction("Regroup lost its server connection. Reconnect and try again.");
    return;
  }

  state.gold -= REGROUP_COST;
  let launched = 0;
  let troopsSent = 0;
  const regroupArrivalOrder = options
    .map(option => ({
      option,
      duration: travelTime(
        option.city,
        target,
        "player",
        option.route?.length,
        Math.max(1, Math.floor(Number(option.city?.troops) || 0)),
        "transfer"
      ),
    }))
    .sort((left, right) => left.duration - right.duration || String(left.option.city.id).localeCompare(String(right.option.city.id)));
  const regroupArrivalIndex = new Map(regroupArrivalOrder.map((entry, index) => [entry.option.city.id, index]));
  for (const option of options) {
    const troops = Math.floor(Number(option.city.troops) || 0);
    if (troops < 1) continue;
    const arrivalIndex = regroupArrivalIndex.get(option.city.id) ?? 0;
    const arrivalCount = regroupArrivalOrder.length;
    const bulkArrivalCue = arrivalCount === 1
      ? "first_last"
      : arrivalIndex === 0
        ? "first"
        : arrivalIndex === arrivalCount - 1 ? "last" : "mute";
    if (launchAttack(option.city.id, target.id, 1, "player", troops, {
      silent: true,
      silentAudio: launched > 0,
      syncOwnedCities: false,
      route: option.route,
      bulkOrderKind: "regroup",
      bulkRequestId: action.requestId,
      bulkArrivalCue,
      bulkArrivalIndex: arrivalIndex,
      bulkOrderCount: arrivalCount,
    })) {
      launched += 1;
      troopsSent += troops;
    }
  }

  finishBulkOrderAction(action, { completed: launched > 0 });
  regroupSourceId = null;
  if (!launched) {
    state.gold += REGROUP_COST;
    renderAll();
    rejectGameAction("No troops could regroup right now.");
    return;
  }

  if (isOnlineWorldActive() && !usesServerArmyAuthority()) syncOwnedCitiesToOnline(true);
  addLog(`${target.name} called a regroup for ${formatNumber(REGROUP_COST)} gold: ${formatNumber(troopsSent)} troops moving in from ${formatNumber(launched)} cities.`);
  saveGame();
  renderAll();
  showToast(`Regroup moving: ${formatNumber(troopsSent)} troops to ${target.name}`);
}

function getPendingScoutMission(cityId) {
  return state?.attacks?.find(attack => (
    attack.owner === "player"
    && attack.kind === "scout"
    && attack.toId === cityId
    && !isArrivedScoutMission(attack)
  )) || null;
}

function getRouteHeuristicDistance(source, target) {
  if (!source || !target) return Infinity;
  const sourceRegionId = getCityRegionId(source);
  const targetRegionId = getCityRegionId(target);
  if (sourceRegionId === targetRegionId) return Math.hypot(source.x - target.x, source.y - target.y);

  const chain = getPortalRouteRegionChain(sourceRegionId, targetRegionId);
  if (!chain?.length) return Infinity;

  let currentPoint = { x: source.x, y: source.y };
  let distance = 0;
  for (let index = 0; index < chain.length; index += 1) {
    const regionId = chain[index];
    const isLastRegion = index === chain.length - 1;
    const nextRegionId = isLastRegion ? "" : chain[index + 1];
    if (isLastRegion) {
      distance += Math.hypot(currentPoint.x - target.x, currentPoint.y - target.y);
      break;
    }
    const sourcePortal = getEditorPortalForRoute(regionId, nextRegionId);
    const exitPoint = getPortalWorldPoint(regionId, nextRegionId, sourcePortal ? { portal: sourcePortal } : {});
    if (!exitPoint) return Infinity;
    distance += Math.hypot(currentPoint.x - exitPoint.x, currentPoint.y - exitPoint.y);
    const arrivalPortal = sourcePortal ? getLinkedEditorArrivalPortal(regionId, nextRegionId, sourcePortal) : null;
    const arrivalPoint = getPortalWorldPoint(nextRegionId, regionId, arrivalPortal ? { portal: arrivalPortal } : {});
    if (!arrivalPoint) return Infinity;
    currentPoint = arrivalPoint;
  }
  return distance;
}

function findNearestOwnedSource(target, minimumTroops = 1, options = {}) {
  const maxRouteChecks = Math.max(1, Math.floor(Number(options.maxRouteChecks) || NEAREST_SOURCE_ROUTE_CHECK_LIMIT));
  const candidates = getOwnedSourceCandidates(target, minimumTroops);

  let checked = 0;
  for (const option of candidates) {
    if (checked >= maxRouteChecks) break;
    checked += 1;
    const route = findRoute(option.city, target);
    if (route?.points?.length) return { city: option.city, route };
  }
  return null;
}

function getOwnedSourceCandidates(target, minimumTroops = 1) {
  return playerCities()
    .filter(city => Math.floor(Number(city.troops) || 0) >= minimumTroops && city.id !== target.id)
    .map(city => ({ city, estimate: getRouteHeuristicDistance(city, target) }))
    .filter(option => Number.isFinite(option.estimate))
    .sort((a, b) => a.estimate - b.estimate);
}

function findNearestOwnedSourceCandidate(target, minimumTroops = 1) {
  return getOwnedSourceCandidates(target, minimumTroops)[0] || null;
}

async function findNearestScoutSourceAsync(target) {
  const candidates = getOwnedSourceCandidates(target, 1).slice(0, SCOUT_SOURCE_ROUTE_CHECK_LIMIT);
  const routes = await findRoutesAsync(candidates.map(option => ({ source: option.city, target })));
  const index = routes.findIndex(route => route?.points?.length);
  return index >= 0 ? { city: candidates[index].city, route: routes[index] } : null;
}

function rememberOwnedAttackSource(cityOrId) {
  const city = typeof cityOrId === "string" ? cityById(cityOrId) : cityOrId;
  if (city?.owner === "player") lastSelectedOwnedCityId = city.id;
}

function getLastSelectedOwnedAttackCity() {
  const source = lastSelectedOwnedCityId ? cityById(lastSelectedOwnedCityId) : null;
  return source?.owner === "player" ? source : null;
}

function completeScoutMission(attack, target) {
  if (target.owner === "player") {
    const joined = Math.max(0, Math.floor(Number(attack.troops) || 1));
    target.troopFloat = Math.max(0, Number(target.troopFloat) || target.troops || 0) + joined;
    target.troops = Math.floor(target.troopFloat);
    const stats = getCityStats(target);
    addBattleReport({
      type: "scout",
      outcome: "scout",
      cityId: target.id,
      regionId: getCityRegionId(target),
      cityName: target.name,
      cityLevel: clampCityLevel(target.level),
      sentTroops: joined,
      troopCount: target.troops,
      totalDefense: stats.totalDefense,
      baseTotalDefense: stats.baseTotalDefense,
      totalDefenseBonus: stats.totalDefenseBonus,
      ownerName: getCityOwnerDisplayName(target),
      opponentName: getCityOwnerDisplayName(target),
      opponentFlag: getCityOwnerFlag(target),
      summary: `Scout reached ${target.name}, now under your control. ${formatNumber(joined)} scout joined the garrison.`,
    });
    addLog(`The scout joined your garrison at ${target.name}.`);
    if (claimBulkArrivalAudio(attack)) {
      playGameSound("notification", {
        cooldownMs: 500,
        regionId: getCityRegionId(target),
        allowCrossMap: true,
      });
    }
    showToast(`Scout arrived at ${target.name}`);
    return;
  }
  state.scoutReports = normalizeScoutReports(state.scoutReports);
  const report = createScoutReportSnapshot(target);
  state.scoutReports[target.id] = report;
  addBattleReport({
    id: getLocalScoutReportId(target.id),
    type: "scout",
    outcome: "scout",
    cityId: target.id,
    regionId: getCityRegionId(target),
    cityName: target.name,
    cityLevel: report.cityLevel,
    troopCount: report.troops,
    totalDefense: report.totalDefense,
    baseTotalDefense: report.baseTotalDefense,
    totalDefenseBonus: report.totalDefenseBonus,
    ownerName: report.ownerName,
    opponentName: report.ownerName,
    opponentFlag: getCityOwnerFlag(target),
    scoutReport: report,
    expiresAtMs: report.expiresAtMs,
    summary: `Scout revealed ${formatNumber(report.troops)} troops at ${target.name}.`,
  });
  addLog(`Scouts reported ${formatNumber(target.troops)} troops stationed at ${target.name}.`);
  if (claimBulkArrivalAudio(attack)) {
    playGameSound("notification", {
      cooldownMs: 500,
      regionId: getCityRegionId(target),
      allowCrossMap: true,
    });
  }
  showToast(`Scout report received from ${target.name}`);
}

function createScoutReportSnapshot(target) {
  const stats = getCityStats(target);
  const targetType = isRewardCampTarget(target) ? "camp" : "city";
  const troopCount = Math.max(0, Math.floor(Number(target.troops) || 0));
  const troopDefense = Math.max(0, Math.floor(Number(stats.troopDefense) || troopCount));
  const ownerUsesPlayerSkills = target.owner === "player";
  const skillSnapshot = {};
  for (const skill of SKILL_ORDER) {
    const level = ownerUsesPlayerSkills ? getSkillLevel(skill) : 0;
    const config = SKILL_CONFIG[skill];
    const rawPercent = level * config.percentPerLevel;
    skillSnapshot[`${skill}Level`] = level;
    skillSnapshot[`${skill}Percent`] = Number.isFinite(config.maxPercent) ? Math.min(rawPercent, config.maxPercent) : rawPercent;
  }
  const scoutedAtMs = Date.now();
  return {
    targetType,
    troops: troopCount,
    totalDefense: Math.floor(stats.totalDefense),
    baseTotalDefense: Math.floor(stats.baseTotalDefense),
    totalDefenseBonus: Math.floor(stats.totalDefenseBonus),
    owner: target.owner,
    ownerUid: String(target.ownerUid || (target.owner === "player" ? getCurrentOnlineUid() : "")).slice(0, 128),
    ownerName: getCityOwnerDisplayName(target),
    ownerFlag: getCityOwnerFlag(target),
    cityLevel: targetType === "camp" ? 0 : stats.level,
    defenseCombatVersion: stats.defenseCombatVersion,
    baseDefensePowerPerTroop: stats.baseDefensePowerPerTroop,
    gearWallStrengthPercent: stats.gearWallStrengthPercent,
    gearDefenderStrengthPercent: stats.gearDefenderStrengthPercent,
    defensePercent: stats.defensePercent,
    baseCityWalls: stats.baseCityWalls,
    cityWalls: stats.cityWalls,
    troopDefense,
    cityDefenseBonus: Math.max(0, troopDefense - troopCount),
    stoneworksBonus: Math.max(0, stats.cityWalls - stats.baseCityWalls),
    baseAttackPercent: target.owner === "enemy" ? 4 : 0,
    ...skillSnapshot,
    siegeCombatVersion: SIEGE_COMBAT_VERSION,
    fortification: getCityFortificationSnapshot(target, stats),
    scoutedAt: state.gameSeconds,
    expiresAt: state.gameSeconds + SCOUT_REPORT_SECONDS,
    scoutedAtMs,
    expiresAtMs: scoutedAtMs + SCOUT_REPORT_SECONDS * 1000,
  };
}

function getBattleReportOwnerName(city, owner = city?.owner) {
  if (owner === "player") return state?.playerName || "You";
  if (city?.ownerKind === "player" && city.ownerUid) {
    const identity = resolvePlayerIdentityForUid(city.ownerUid, city);
    return identity.displayName || city.ownerName || "Rival ruler";
  }
  return OWNER[owner]?.label || "Unknown";
}

function addBattleReport(report) {
  if (!state) return;
  state.battleReports = normalizeBattleReports(state.battleReports);
  const occurredAtMs = Date.now();
  const entry = normalizeBattleReports([{
    id: `report_${occurredAtMs.toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
    createdAt: state.gameSeconds,
    occurredAtMs,
    createdAtMs: occurredAtMs,
    ...report,
  }])[0];
  if (!entry) return;
  const existingIndex = state.battleReports.findIndex(existing => existing.id === entry.id);
  if (existingIndex >= 0) state.battleReports[existingIndex] = entry;
  else state.battleReports.push(entry);
  if (state.battleReports.length > 120) state.battleReports = state.battleReports.slice(-120);
}

function getLocalScoutReportId(cityId = "") {
  const target = String(cityId || "").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 96);
  return `scout_current_local_${target}`;
}

function pendingNeutralCaptureCount(owner = "player", excludeAttackId = null) {
  if (!state || !Array.isArray(state.attacks)) return 0;
  return state.attacks.filter(attack => {
    if (attack.id === excludeAttackId) return false;
    if (attack.owner !== owner || attack.kind !== "attack") return false;
    if (attack.targetType === "camp" || isRewardCampTarget(getArmyTargetById(attack.toId))) return false;
    const target = cityById(attack.toId);
    if (isStronghold(target)) return false;
    return attack.targetOwnerAtLaunch === "neutral" || (!attack.targetOwnerAtLaunch && target?.owner === "neutral");
  }).length;
}

function neutralCaptureStatus(excludeAttackId = null) {
  const daily = ensureDailyCaptureTracker();
  const pending = pendingNeutralCaptureCount("player", excludeAttackId);
  const owned = getOwnedRegularCityCountForDisplay();
  const remainingByCityCount = Math.max(0, NEUTRAL_CITY_COUNT_LIMIT - owned - pending);
  const remainingToday = Math.max(0, DAILY_NEUTRAL_CAPTURE_LIMIT - daily.neutralCaptures - pending);
  return {
    capturesToday: daily.neutralCaptures,
    pending,
    cityCount: owned,
    remainingToday,
    remainingByCityCount,
    remaining: Math.min(remainingToday, remainingByCityCount),
  };
}

function getNeutralCaptureBlockReason(target, owner = "player", excludeAttackId = null) {
  if (owner !== "player" || target?.owner !== "neutral") return "";
  if (isStronghold(target)) return "";
  const status = neutralCaptureStatus(excludeAttackId);
  if (status.remainingByCityCount <= 0) {
    return `Neutral expansion is capped while you own ${NEUTRAL_CITY_COUNT_LIMIT} or more cities. Attack player-owned cities to keep expanding.`;
  }
  if (status.remainingToday <= 0) {
    return `You cannot conquer more neutral towns today. Daily neutral capture limit reached: ${DAILY_NEUTRAL_CAPTURE_LIMIT}/${DAILY_NEUTRAL_CAPTURE_LIMIT}.`;
  }
  return "";
}

function showNeutralCaptureLimitModal(message) {
  playGameSound("invalid_action", { cooldownMs: 140 });
  const status = neutralCaptureStatus();
  modalTitle.textContent = "Neutral expansion blocked";
  modalBody.innerHTML = `
    <div class="send-outcome lose">
      <strong>You cannot conquer that neutral town right now.</strong>
      <span>${escapeHtml(message)}</span>
      <small>${status.capturesToday}/${DAILY_NEUTRAL_CAPTURE_LIMIT} neutral captures used today. ${status.cityCount}/${NEUTRAL_CITY_COUNT_LIMIT} owned cities count toward the neutral-city cap. You can still attack player-owned cities and move troops between your owned cities.</small>
    </div>
    <div class="modal-actions">
      <button id="neutralLimitCloseBtn" class="safe-action" type="button">Close</button>
    </div>
  `;
  if (!modal.open) modal.showModal();
  const closeBtn = modalBody.querySelector("#neutralLimitCloseBtn");
  if (closeBtn) closeBtn.addEventListener("click", () => modal.close());
}

function recordNeutralCapture() {
  const daily = ensureDailyCaptureTracker();
  daily.neutralCaptures = clamp(daily.neutralCaptures + 1, 0, DAILY_NEUTRAL_CAPTURE_LIMIT);
}

function saveGame() {
  if (!state) return;
  state.lastRealTimeMs = Date.now();
  queueOnlineSave();
}

function getOnlineApi() {
  return window.CrownlandsOnline || null;
}

function usesServerArmyAuthority() {
  const api = getOnlineApi();
  const apiReady = typeof api?.usesServerArmyAuthority === "function"
    ? api.usesServerArmyAuthority()
    : true;
  return Boolean(isOnlineWorldActive() && api?.isSignedIn?.() && api?.sendArmyOrder && api?.resolveArmyOrder && apiReady);
}

function getRealmCapabilityVersion(name = "") {
  return Math.max(
    0,
    Math.floor(Number(verifiedRealmInfo?.[name] ?? verifiedRealmInfo?.features?.[name]) || 0)
  );
}

function supportsAuthoritativeArmyRoutes() {
  return usesServerArmyAuthority() && getRealmCapabilityVersion("authoritativeRoutesVersion") >= 1;
}

function supportsBulkArmyOrders() {
  return usesServerArmyAuthority() && getRealmCapabilityVersion("bulkOrdersVersion") >= 1;
}

function supportsSiegeCombat() {
  return !isOnlineWorldActive() || getRealmCapabilityVersion("siegeCombatVersion") >= SIEGE_COMBAT_VERSION;
}

function supportsDefenseCombat() {
  return !isOnlineWorldActive() || getRealmCapabilityVersion("defenseCombatVersion") >= DEFENSE_COMBAT_VERSION;
}

function supportsRealmActivity() {
  return isOnlineWorldActive() && getRealmCapabilityVersion("realmActivityVersion") >= REALM_ACTIVITY_VERSION;
}

function supportsDailyMissions() {
  const api = getOnlineApi();
  return Boolean(
    isOnlineWorldActive()
      && getRealmCapabilityVersion("dailyMissionVersion") >= DAILY_MISSION_VERSION
      && api?.getDailyMissionStatus
      && api?.rerollDailyMission
      && api?.claimDailyMissionReward
  );
}

function supportsSeasonalAchievements() {
  const api = getOnlineApi();
  return Boolean(
    isOnlineWorldActive()
      && getRealmCapabilityVersion("seasonalAchievementVersion") >= SEASONAL_ACHIEVEMENT_VERSION
      && api?.getSeasonalAchievementStatus
      && api?.claimSeasonalAchievementReward
  );
}

function canUseBulkArmyOrders() {
  return !isOnlineWorldActive() || supportsBulkArmyOrders();
}

function hasServerEconomyApi() {
  const api = getOnlineApi();
  const apiReady = typeof api?.usesServerEconomyAuthority === "function"
    ? api.usesServerEconomyAuthority()
    : true;
  return Boolean(
    api?.isSignedIn?.()
      && api?.collectEconomy
      && api?.reserveHarvestBonusSpawn
      && api?.collectHarvestBonus
      && api?.upgradeCity
      && api?.relinquishCity
      && api?.purchaseShopItem
      && api?.activateInventoryItem
      && apiReady
  );
}

function usesServerEconomyAuthority() {
  return Boolean(isOnlineWorldActive() && hasServerEconomyApi());
}

function getServerArmyLaunchKey(sourceId, targetId, kind = "attack") {
  return `${String(kind || "attack")}:${String(sourceId || "")}:${String(targetId || "")}`;
}

function canUseOnlineArmyOrders() {
  if (!isOnlineWorldActive()) return true;
  if (usesServerArmyAuthority()) return true;
  onlineLastError = "Online army orders require the Crownlands server.";
  rejectGameAction("Online army orders need the server connection. Try again after reconnecting.");
  return false;
}

function normalizeServerScoutReport(report = null) {
  if (!report || typeof report !== "object" || !state) return null;
  const nowMs = Date.now();
  const scoutedAtMs = normalizeTimestampMs(report.scoutedAtMs) || nowMs;
  const expiresAtMs = normalizeTimestampMs(report.expiresAtMs) || (scoutedAtMs + LEGACY_SCOUT_REPORT_SECONDS * 1000);
  const createdAgeSeconds = Math.max(0, Math.floor((nowMs - scoutedAtMs) / 1000));
  const remainingSeconds = Math.max(0, Math.ceil((expiresAtMs - nowMs) / 1000));
  if (remainingSeconds <= 0) return null;
  const scoutedAt = Math.max(0, Math.floor(Number(state.gameSeconds) || 0) - createdAgeSeconds);
  const troops = Math.max(0, Math.floor(Number(report.troops) || 0));
  const reinforcements = normalizeScoutReportReinforcements(report.reinforcements);
  const reinforcementTroops = reinforcements.reduce((total, row) => total + row.troops, 0);
  const targetType = report.targetType === "camp" || WORLD_CAMPS_BY_ID.has(String(report.cityId || ""))
    ? "camp"
    : "city";
  return {
    ...report,
    targetType,
    troops,
    ownerTroops: Math.max(0, Math.floor(Number(report.ownerTroops ?? Math.max(0, troops - reinforcementTroops)) || 0)),
    reinforcementTroops,
    reinforcements,
    ownerFlag: report.ownerFlag && typeof report.ownerFlag === "object"
      ? normalizeFlag(report.ownerFlag)
      : null,
    totalDefense: Math.max(0, Math.floor(Number(report.totalDefense) || 0)),
    baseTotalDefense: Math.min(
      Math.max(0, Math.floor(Number(report.totalDefense) || 0)),
      Math.max(0, Math.floor(Number(report.baseTotalDefense ?? report.totalDefense) || 0))
    ),
    cityLevel: targetType === "camp" ? 0 : clampCityLevel(report.cityLevel || 1),
    scoutedAt,
    expiresAt: scoutedAt + remainingSeconds,
  };
}

function normalizeServerBattleReport(report = null) {
  if (!report || typeof report !== "object") return null;
  const currentUid = getCurrentOnlineUid();
  if (report.uid && currentUid && report.uid !== currentUid) return null;
  return normalizeBattleReports([{
    ...report,
    id: report.id || `server_${report.cityId || "report"}_${report.occurredAtMs || report.createdAtMs || Date.now()}`,
  }])[0] || null;
}

function mergeServerScoutReport(rawReport = null) {
  if (!state || rawReport?.type !== "scout" || !rawReport.cityId || !rawReport.scoutReport) return false;
  state.scoutReports = normalizeScoutReports(state.scoutReports);
  const scoutReport = normalizeServerScoutReport({
    ...rawReport.scoutReport,
    cityId: rawReport.cityId,
    targetType: rawReport.targetType || rawReport.scoutReport.targetType,
    ownerUid: rawReport.scoutReport.ownerUid || rawReport.opponentUid,
    ownerName: rawReport.scoutReport.ownerName || rawReport.opponentName,
    ownerFlag: rawReport.scoutReport.ownerFlag || rawReport.opponentFlag,
  });
  if (!scoutReport) return false;
  const existing = state.scoutReports[rawReport.cityId];
  const existingTime = normalizeTimestampMs(existing?.scoutedAtMs) || Math.max(0, Number(existing?.scoutedAt) || 0);
  const nextTime = normalizeTimestampMs(scoutReport.scoutedAtMs) || Math.max(0, Number(scoutReport.scoutedAt) || 0);
  if (existing && existingTime >= nextTime) return false;
  state.scoutReports[rawReport.cityId] = scoutReport;
  return true;
}

function mergeServerReports(reports = [], options = {}) {
  if (!state || !Array.isArray(reports)) return false;
  const shouldNotify = options.notify === true;
  const authoritativeSnapshot = options.authoritative === true;
  const reportsPanelOpen = Boolean(modal?.open && modal.classList.contains("battle-report-modal"));
  const reportListOpen = reportsPanelOpen && !String(modal.dataset.battleReportDetailId || "");
  if (!reports.length) {
    if (authoritativeSnapshot) deedRewardReportsVfxHydrated = true;
    return false;
  }
  let changed = false;
  let addedReport = false;
  const newDeedCompletionReports = [];
  const newCityCombatReports = [];
  const notificationCandidates = [];
  const refreshedScoutCityIds = new Set();
  state.battleReports = normalizeBattleReports(state.battleReports);
  state.scoutReports = normalizeScoutReports(state.scoutReports);
  for (const rawReport of reports) {
    const scoutChanged = mergeServerScoutReport(rawReport);
    if (scoutChanged) refreshedScoutCityIds.add(String(rawReport.cityId || ""));
    changed = scoutChanged || changed;
    addedReport = scoutChanged || addedReport;
    const normalized = normalizeServerBattleReport(rawReport);
    if (!normalized) continue;
    const revisionMs = getBattleReportRevisionMs(normalized);
    const existingIndex = state.battleReports.findIndex(report => report.id === normalized.id);
    const existingRevisionMs = existingIndex >= 0
      ? getBattleReportRevisionMs(state.battleReports[existingIndex])
      : 0;
    const appliedRevisionMs = Math.max(0, Number(appliedServerReportRevisions.get(normalized.id)) || 0);
    if (revisionMs <= Math.max(existingRevisionMs, appliedRevisionMs)) continue;
    notificationCandidates.push(normalized);
    if (existingIndex >= 0) state.battleReports[existingIndex] = normalized;
    else {
      state.battleReports.push(normalized);
      if (normalized.eventKind === "deed_camp_completed" && normalized.rewardEventId) {
        newDeedCompletionReports.push(normalized);
      }
      if (
        normalized.battleId
        && (normalized.type === "attack" || normalized.type === "defense")
        && normalized.eventKind !== CITADEL_ASSAULT_EVENT_KIND
      ) {
        newCityCombatReports.push(normalized);
      }
    }
    appliedServerReportRevisions.set(normalized.id, revisionMs);
    if (shouldNotify && normalized.levelUpReward) {
      const reward = normalized.levelUpReward;
      queueLevelUpReward(reward.fromLevel, reward.toLevel, {
        skillPoints: reward.skillPoints,
        gold: reward.gold,
        troops: reward.troops,
        cityId: reward.cityId,
        cityName: reward.cityName,
        audioDelayMs: REWARD_FOLLOWUP_AUDIO_DELAY_MS,
      });
    }
    changed = true;
    addedReport = true;
  }
  if (changed) {
    state.battleReports = normalizeBattleReports(state.battleReports);
    if (state.battleReports.length > 120) state.battleReports = state.battleReports.slice(-120);
    saveGame();
    cityRenderSignature = "";
    renderCities(true);
    if (reportListOpen) {
      const scrollTop = modalBody.scrollTop;
      showLogModal({ silentAudio: true, preserveScrollTop: scrollTop });
    } else if (reportsPanelOpen) {
      void markLoadedReportsViewed();
    }
    const openScoutCityId = String(modal.dataset.scoutReportCityId || "");
    if (modal.open && openScoutCityId && refreshedScoutCityIds.has(openScoutCityId)) {
      showScoutReportModal(openScoutCityId);
    }
    renderHud();
  }
  if (
    shouldNotify
    && addedReport
    && !reportsPanelOpen
    && notificationCandidates.some(report => claimBulkArrivalAudio(report))
  ) {
    playGameSound("notification", { cooldownMs: 500, allowCrossMap: true });
  }
  if (deedRewardReportsVfxHydrated) {
    newCityCombatReports.forEach(report => {
      const target = cityById(report.cityId);
      if (target) playCityAttackAnimation(target, { eventId: `city-attack:${report.battleId}` });
    });
    newDeedCompletionReports.forEach(report => {
      const sourceCamp = getCampTargetById(report.rewardSourceId);
      const sourceNode = report.rewardSourceId
        ? cityLayer?.querySelector(`[data-render-camp-id="${CSS.escape(report.rewardSourceId)}"]`)
        : null;
      playCompletedDeedRewardAnimation({
        status: "paid",
        rewardEventId: report.rewardEventId,
        rewardSourceId: report.rewardSourceId,
        rewardSourceRegionId: report.rewardSourceRegionId,
        awardedCity: {
          id: report.cityId,
          name: report.cityName,
          regionId: report.regionId,
        },
      }, sourceCamp, captureAnimationAnchor(sourceNode));
    });
  }
  if (authoritativeSnapshot) deedRewardReportsVfxHydrated = true;
  return changed;
}

function getAuthoritativeProfileRevisionMs(profile = null) {
  if (!profile || typeof profile !== "object") return 0;
  return normalizeTimestampMs(profile.economyUpdatedAtMs)
    || normalizeTimestampMs(profile.accountUpdatedAtMs)
    || normalizeTimestampMs(profile.updatedAtMs)
    || timestampToMs(profile.updatedAt);
}

function applyServerProfilePatch(patch = null, options = {}) {
  if (!state || !patch || typeof patch !== "object") return false;
  let changed = false;
  const reportsViewedAtMs = normalizeTimestampMs(patch.reportsViewedAtMs);
  if (reportsViewedAtMs > normalizeTimestampMs(state.reportsViewedAtMs)) {
    state.reportsViewedAtMs = reportsViewedAtMs;
    changed = true;
    updateReportUnreadBadge();
  }
  const realmAnnouncementSeenThroughMs = normalizeTimestampMs(patch.realmAnnouncementSeenThroughMs);
  if (realmAnnouncementSeenThroughMs > normalizeTimestampMs(state.realmAnnouncementSeenThroughMs)) {
    state.realmAnnouncementSeenThroughMs = realmAnnouncementSeenThroughMs;
    state.lastRealmAnnouncementEventId = String(patch.lastRealmAnnouncementEventId || state.lastRealmAnnouncementEventId || "").slice(0, 180);
    changed = true;
  }
  const previousLevel = Math.max(1, Math.floor(Number(state.character?.level) || 1));
  if (patch.globalStats) {
    changed = applyGlobalStatsSnapshot(patch.globalStats, { render: false }) || changed;
  }
  const revisionMs = getAuthoritativeProfileRevisionMs(patch);
  if (revisionMs > 0 && lastAuthoritativeProfileRevisionMs > 0 && revisionMs < lastAuthoritativeProfileRevisionMs) {
    return changed;
  }
  if (revisionMs > 0) lastAuthoritativeProfileRevisionMs = Math.max(lastAuthoritativeProfileRevisionMs, revisionMs);
  if (patch.character) {
    state.character = normalizeCharacterProgress(patch.character);
    syncCharacterSkillPoints(state.character, state.upgrades, patch.character?.skillPoints);
    changed = true;
  }
  if (patch.upgrades && typeof patch.upgrades === "object") {
    state.upgrades = normalizeUpgrades(patch.upgrades, state.version);
    syncCharacterSkillPoints(state.character, state.upgrades, state.character?.skillPoints);
    changed = true;
  }
  if (patch.skillPresets && typeof patch.skillPresets === "object") {
    state.skillPresets = normalizeSkillPresets(patch.skillPresets);
    changed = true;
  }
  if (Number.isFinite(Number(patch.freeSkillResetGrantVersion))) {
    state.freeSkillResetGrantVersion = Math.max(0, Math.floor(Number(patch.freeSkillResetGrantVersion) || 0));
    changed = true;
  }
  if (Number.isFinite(Number(patch.freeSkillResetCredits))) {
    state.freeSkillResetCredits = Math.max(0, Math.floor(Number(patch.freeSkillResetCredits) || 0));
    changed = true;
  }
  if (Number.isFinite(Number(patch.gold))) {
    state.gold = Math.max(0, Math.floor(Number(patch.gold) || 0));
    changed = true;
  }
  if (patch.daily && typeof patch.daily === "object") {
    state.daily = normalizeDailyCaptureTracker(patch.daily);
    changed = true;
  }
  if (patch.dailyLoginReward && typeof patch.dailyLoginReward === "object") {
    applyDailyLoginRewardProfileState(patch.dailyLoginReward, { autoOpen: false });
    changed = true;
  }
  if (Array.isArray(patch.harvestBonuses)) {
    state.harvestBonuses = enforceHarvestBonusActiveLimit(normalizeHarvestBonuses(patch.harvestBonuses));
    changed = true;
  }
  if (Number.isFinite(Number(patch.harvestSpawnTimer))) {
    state.harvestSpawnTimer = clamp(
      Math.floor(Number(patch.harvestSpawnTimer) || 0),
      0,
      HARVEST_BONUS_SPAWN_INTERVAL_SECONDS
    );
    changed = true;
  }
  if (Number.isFinite(Number(patch.harvestNextSpawnAtMs))) {
    state.harvestNextSpawnAtMs = normalizeTimestampMs(patch.harvestNextSpawnAtMs);
    const remainingSeconds = Math.ceil(Math.max(0, state.harvestNextSpawnAtMs - Date.now()) / 1000);
    state.harvestSpawnTimer = clamp(remainingSeconds, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS);
    changed = true;
  }
  if (patch.harvestNextBonusType) {
    state.harvestNextBonusType = normalizeHarvestBonusType(patch.harvestNextBonusType);
    changed = true;
  }
  if (patch.shopItems && typeof patch.shopItems === "object") {
    state.shopItems = normalizeShopItems(patch.shopItems);
    changed = true;
  }
  if (patch.itemEffects && typeof patch.itemEffects === "object") {
    state.itemEffects = normalizeItemEffects(patch.itemEffects);
    changed = true;
  }
  if (patch.itemPurchaseCooldowns && typeof patch.itemPurchaseCooldowns === "object") {
    state.itemPurchaseCooldowns = normalizeItemPurchaseCooldowns(patch.itemPurchaseCooldowns);
    changed = true;
  }
  if (patch.gear && typeof patch.gear === "object") {
    state.gear = normalizeCommonGearState(patch.gear);
    changed = true;
  }
  const nextMainCityId = getKnownCityId(patch.mainCityId);
  if (nextMainCityId) {
    state.mainCityId = nextMainCityId;
    if (state.online) {
      state.online.mainCityId = nextMainCityId;
      state.online.mainRegionId = normalizeRegionId(patch.mainRegionId || getCityRegionId(nextMainCityId));
      state.online.mainIslandId = patch.mainIslandId || getOnlineIslandId(state.online.mainRegionId);
    }
    changed = true;
  }
  if (Number.isFinite(Number(patch.mainCityChangedAtMs))) {
    state.mainCityChangedAtMs = normalizeTimestampMs(patch.mainCityChangedAtMs);
    changed = true;
  }
  if (Number.isFinite(Number(patch.lastCityRelinquishedAtMs))) {
    state.lastCityRelinquishedAtMs = normalizeTimestampMs(patch.lastCityRelinquishedAtMs);
    changed = true;
  }
  const mainCityRepair = normalizeSingleMainCityAssignment(nextMainCityId || state.mainCityId);
  changed = mainCityRepair.changed || changed;
  if (changed) {
    saveGame();
    renderHud();
    if (profileScreen?.classList.contains("open")) renderProfileScreen();
  }
  const levelUpReward = getLevelUpRewardAnnouncement(patch, previousLevel, options);
  if (levelUpReward) {
    queueLevelUpReward(levelUpReward.fromLevel, levelUpReward.toLevel, {
      skillPoints: levelUpReward.skillPoints,
      gold: levelUpReward.gold,
      troops: levelUpReward.troops,
      cityId: levelUpReward.cityId || getMainRewardCity()?.id || "",
      cityName: levelUpReward.cityName || getMainRewardCity()?.name || "your main city",
      audioDelayMs: options.levelUpAudioDelayMs,
    });
  }
  return changed;
}

function applyServerCityUpdateToOwnedCache(update = {}) {
  if (!state || !update || typeof update !== "object") return false;
  const cityId = getKnownCityId(update.id);
  if (!cityId) return false;
  const currentUid = getCurrentOnlineUid();
  const existingIndex = onlineOwnedCitiesCache.findIndex(city => city.id === cityId);
  const existing = existingIndex >= 0 ? onlineOwnedCitiesCache[existingIndex] : null;
  const ownerUidProvided = Object.prototype.hasOwnProperty.call(update, "ownerUid");
  const nextOwnerUid = ownerUidProvided ? String(update.ownerUid || "").trim() : String(existing?.ownerUid || currentUid || "").trim();

  if (ownerUidProvided && (!nextOwnerUid || (currentUid && nextOwnerUid !== currentUid))) {
    if (existingIndex < 0) return false;
    onlineOwnedCitiesCache.splice(existingIndex, 1);
    localDirtyCityIds.delete(cityId);
    return true;
  }

  if (!existing && !(ownerUidProvided && nextOwnerUid && (!currentUid || nextOwnerUid === currentUid))) return false;
  const next = normalizeOwnedCitySnapshot({
    ...(existing || {}),
    ...update,
    id: cityId,
    regionId: normalizeRegionId(update.regionId || existing?.regionId || getCityRegionId(cityId)),
    ownerKind: "player",
    ownerUid: nextOwnerUid || currentUid || null,
    ownerName: update.ownerName || existing?.ownerName || state.playerName,
    ownerFlag: update.ownerFlag || existing?.ownerFlag || state.flag,
  });
  if (!next) return false;
  if (existingIndex >= 0) onlineOwnedCitiesCache[existingIndex] = next;
  else onlineOwnedCitiesCache.push(next);
  return true;
}

function applyServerCityUpdates(cityUpdates = []) {
  if (!state || !Array.isArray(cityUpdates)) return false;
  let changed = false;
  let cacheChanged = false;
  for (const update of cityUpdates) {
    if (update?.ownerUid) rememberOwnerIdentitiesFromRecords([update]);
    cacheChanged = applyServerCityUpdateToOwnedCache(update) || cacheChanged;
    const cityId = getKnownCityId(update?.id);
    const city = cityId ? cityById(cityId) : null;
    if (!city) continue;
    const currentRegionId = getCityRegionId(city);
    const updateRegionId = normalizeRegionId(update.regionId || currentRegionId);
    if (currentRegionId !== updateRegionId) continue;
    if (Number.isFinite(Number(update.troops))) {
      city.troops = Math.max(0, Math.floor(Number(update.troops) || 0));
      city.troopFloat = Math.max(0, Number(update.troopFloat) || city.troops);
      changed = true;
    }
    if (Number.isFinite(Number(update.level))) {
      city.level = isStronghold(city) ? getStrongholdDefenseLevel(city) : clampCityLevel(update.level);
      changed = true;
    }
    if (Number.isFinite(Number(update.investedGold))) {
      city.investedGold = isStronghold(city) ? 0 : Math.max(0, Math.floor(Number(update.investedGold) || 0));
      changed = true;
    }
    if (Number.isFinite(Number(update.ownerShieldExpiresAtMs))) {
      city.ownerShieldExpiresAtMs = isStronghold(city) ? 0 : normalizeTimestampMs(update.ownerShieldExpiresAtMs);
      changed = true;
    }
    if (Number.isFinite(Number(update.productionUpdatedAtMs))) {
      city.productionUpdatedAtMs = normalizeTimestampMs(update.productionUpdatedAtMs);
      changed = true;
    }
    if (update.relinquishedAtMs !== undefined) {
      city.relinquishedAtMs = timestampToMs(update.relinquishedAtMs);
      changed = true;
    }
    if (update.relocatedAtMs !== undefined) {
      city.relocatedAtMs = timestampToMs(update.relocatedAtMs);
      changed = true;
    }
    if (update.deedAwardedAtMs !== undefined) {
      city.deedAwardedAtMs = normalizeTimestampMs(update.deedAwardedAtMs);
      changed = true;
    }
    if (update.deedCampId !== undefined) {
      city.deedCampId = String(update.deedCampId || "");
      changed = true;
    }
    if (update.neutralClaimSource !== undefined) {
      city.neutralClaimSource = String(update.neutralClaimSource || "");
      changed = true;
    }
    if (Object.prototype.hasOwnProperty.call(update, "fortificationState")) {
      city.fortificationState = update.fortificationState && typeof update.fortificationState === "object"
        ? { ...update.fortificationState }
        : null;
      changed = true;
    }
    if (update.ownerUid !== undefined) {
      const currentUid = getCurrentOnlineUid();
      const ownerUid = String(update.ownerUid || "").trim();
      const ownerIdentity = ownerUid ? resolvePlayerIdentityForUid(ownerUid, update) : null;
      city.ownerKind = ownerUid ? "player" : "neutral";
      city.ownerUid = ownerUid || null;
      city.owner = ownerUid && currentUid && ownerUid === currentUid ? "player" : ownerUid ? "enemy" : "neutral";
      city.ownerName = ownerIdentity?.displayName || update.ownerName || "";
      city.ownerFlag = ownerIdentity?.flag || update.ownerFlag || null;
      city.ownerKingPower = normalizePowerValue(ownerIdentity?.kingPower) || normalizePowerValue(update.ownerKingPower);
      city.ownerShieldExpiresAtMs = normalizeTimestampMs(update.ownerShieldExpiresAtMs);
      city.isMainCity = Boolean(update.isMainCity) && !isStronghold(city);
      if (ownerUid) {
        city.relinquishedAtMs = 0;
        city.relocatedAtMs = 0;
      }
      if (!ownerUid) localDirtyCityIds.delete(city.id);
      changed = true;
    } else if (update.isMainCity !== undefined) {
      city.isMainCity = Boolean(update.isMainCity) && !isStronghold(city);
      changed = true;
    }
  }
  if (cacheChanged) updateIslandSummariesFromOwnedCityCache();
  const mainCityRepair = normalizeSingleMainCityAssignment(state.mainCityId);
  changed = mainCityRepair.changed || changed;
  if (changed) {
    renderHud();
    renderCities();
    renderPanel();
  }
  return changed || cacheChanged;
}

function applyServerArmyResult(result = null, options = {}) {
  if (!result || typeof result !== "object") return false;
  const preResultReport = Array.isArray(result.reports)
    ? [...result.reports].reverse().find(report => report?.type === "attack" || report?.type === "defense")
    : null;
  const preResultTargetId = String(result.targetId || preResultReport?.cityId || result.campUpdate?.id || "");
  const preResultCitySnapshot = getCityVfxSnapshot(cityById(preResultTargetId));
  const preResultCampSnapshot = getCampVfxSnapshot(getCampTargetById(preResultTargetId));
  let changed = false;
  if (result.antiFarmPolicy?.blocked && result.message) {
    addLog(result.message);
    rejectGameAction(result.message);
  }
  if (result.globalStats) changed = applyGlobalStatsSnapshot(result.globalStats, { render: false }) || changed;
  if (Array.isArray(result.reports)) changed = mergeServerReports(result.reports, { notify: false }) || changed;
  if (Array.isArray(result.cityUpdates)) changed = applyServerCityUpdates(result.cityUpdates) || changed;
  const newestPlayerReport = Array.isArray(result.reports)
    ? [...result.reports].reverse().find(report => report?.type === "attack" || report?.type === "defense")
    : null;
  const audioTarget = getArmyTargetById(
    result.targetId
    || newestPlayerReport?.cityId
    || result.campUpdate?.id
  );
  const audioRegionId = result.regionId
    || newestPlayerReport?.regionId
    || result.campUpdate?.regionId
    || audioTarget?.regionId
    || audioTarget?.startPool
    || "";
  const audioOnActiveMap = !audioRegionId || normalizeRegionId(audioRegionId) === getActiveMapRegionId();
  const normalizedCampUpdate = result.campUpdate?.id
    ? normalizeOnlineCampState({
        ...(onlineCampStates.get(result.campUpdate.id) || {}),
        ...result.campUpdate,
      })
    : null;
  if (normalizedCampUpdate) {
    onlineCampStates.set(normalizedCampUpdate.id, normalizedCampUpdate);
    if (normalizedCampUpdate.holderUid === getCurrentOnlineUid()) {
      onlineHeldCampStates.set(normalizedCampUpdate.id, normalizedCampUpdate);
    } else {
      onlineHeldCampStates.delete(normalizedCampUpdate.id);
    }
    cityRenderSignature = "";
    changed = true;
  }
  const scoutAudioContext = result.reports?.find(report => report?.type === "scout") || options.movement || result;
  const armyArrivalAudioContext = options.movement || result;
  if (
    result.kind === "scout"
    && result.reports?.some(report => report?.type === "scout")
    && claimBulkArrivalAudio(scoutAudioContext)
  ) {
    playGameSound("notification", { cooldownMs: 500, regionId: audioRegionId, allowCrossMap: true });
  }
  if (result.kind && result.kind !== "scout" && claimBulkArrivalAudio(armyArrivalAudioContext)) {
    playGameSound("army_arrival", { cooldownMs: 80, regionId: audioRegionId });
    if (result.kind === "attack" && audioOnActiveMap) {
      crownlandsAudio?.pulseMusic("battle", 3500, getAmbientMusicState());
      playBattleImpactAfter(audioTarget, audioRegionId);
    }
  }
  const resultTargetIsCamp = result.targetType === "camp"
    || Boolean(normalizedCampUpdate)
    || isRewardCampTarget(audioTarget);
  const cityBattleId = String(preResultReport?.battleId || newestPlayerReport?.battleId || "");
  if (result.kind === "attack" && !resultTargetIsCamp && audioTarget && cityBattleId) {
    const attackEventId = cityBattleId;
    playCityAttackAnimation(audioTarget, { eventId: `city-attack:${attackEventId}` });
    const afterSnapshot = getCityVfxSnapshot(cityById(preResultTargetId) || audioTarget);
    if (
      preResultCitySnapshot
      && afterSnapshot
      && preResultCitySnapshot.ownerUid !== afterSnapshot.ownerUid
      && afterSnapshot.ownerUid
    ) {
      playCityCaptureAnimation(preResultCitySnapshot, afterSnapshot);
    }
  }
  if (
    normalizedCampUpdate
    && result.kind === "attack"
    && result.outcome === "victory"
    && normalizedCampUpdate.holderUid
    && preResultCampSnapshot?.holderUid !== normalizedCampUpdate.holderUid
  ) {
    playCampCaptureAnimation(preResultCampSnapshot, getCampVfxSnapshot(getCampTargetById(normalizedCampUpdate.id) || normalizedCampUpdate));
  }
  if (
    newestPlayerReport?.type === "attack"
    && newestPlayerReport.outcome === "victory"
    && !resultTargetIsCamp
  ) {
    const capturedCity = cityById(newestPlayerReport.cityId);
    if (isStronghold(capturedCity)) {
      if (audioOnActiveMap) {
        playGameSoundAfter("stronghold_captured", BATTLE_OUTCOME_AUDIO_DELAY_MS, { regionId: audioRegionId });
        playVictoryMusicAfter(audioRegionId);
      }
    } else if (audioOnActiveMap) {
      playGameSoundAfter("city_captured", BATTLE_OUTCOME_AUDIO_DELAY_MS, { regionId: audioRegionId });
    }
  } else if (
    (newestPlayerReport?.type === "attack" && newestPlayerReport.outcome === "defeat")
    || (newestPlayerReport?.type === "defense" && newestPlayerReport.outcome === "lost")
  ) {
    if (audioOnActiveMap) {
      playGameSoundAfter("battle_defeat", BATTLE_OUTCOME_AUDIO_DELAY_MS, { regionId: audioRegionId });
    }
  }
  if (
    normalizedCampUpdate
    && result.targetType === "camp"
    && result.kind === "attack"
    && result.outcome === "victory"
    && normalizedCampUpdate.holderUid === getCurrentOnlineUid()
  ) {
    const config = getRewardCampConfig(normalizedCampUpdate);
    if (audioOnActiveMap) {
      playGameSoundAfter("camp_captured", BATTLE_OUTCOME_AUDIO_DELAY_MS, {
        regionId: normalizedCampUpdate.regionId || audioRegionId,
      });
    }
    showToast(`${config?.name || normalizedCampUpdate.name} captured. Hold for ${Math.floor((config?.holdSeconds || 0) / 60)} minutes to claim ${formatNumber(config?.baseReward || 0)} ${config?.rewardLabel || "reward"}.`);
  }
  if (result.currentUser) {
    changed = applyServerProfilePatch(result.currentUser, {
      levelUpReward: result.currentUser.levelUpReward,
      levelUpAudioDelayMs: newestPlayerReport || (result.kind && result.kind !== "scout")
        ? REWARD_FOLLOWUP_AUDIO_DELAY_MS
        : 0,
    }) || changed;
  }
  return changed;
}

function applyServerEconomyResult(result = null, options = {}) {
  if (!result || typeof result !== "object") return false;
  let changed = false;
  if (result.globalStats) changed = applyGlobalStatsSnapshot(result.globalStats, { render: false }) || changed;
  if (result.currentUser) {
    changed = applyServerProfilePatch(result.currentUser, {
      levelUpReward: result.currentUser.levelUpReward || result.levelUpReward,
    }) || changed;
  }
  if (Array.isArray(result.cityUpdates)) changed = applyServerCityUpdates(result.cityUpdates) || changed;
  const awaySummary = options.requestWelcomeBack === true
    && result.awaySummary
    && typeof result.awaySummary === "object"
    ? result.awaySummary
    : null;
  const resumeProduction = options.resumeCatchUp && result.production && typeof result.production === "object"
    ? result.production
    : null;
  const summary = awaySummary || resumeProduction;
  const awayGoldGained = Math.max(0, Math.floor(Number(summary?.goldGained) || 0));
  const awayTroopsGained = Math.max(0, Math.floor(Number(summary?.troopsGained) || 0));
  const awayElapsed = Math.max(0, Math.floor(Number(summary?.elapsedSeconds) || 0));
  const awayLostCities = Array.isArray(awaySummary?.lostCities) ? awaySummary.lostCities : [];
  const awayLostCityCount = Math.max(awayLostCities.length, Math.floor(Number(awaySummary?.lostCityCount) || 0));
  if (
    options.showOfflineRewards
    && summary
    && awayElapsed >= 60
    && (awayGoldGained > 0 || awayTroopsGained > 0 || awayLostCityCount > 0)
  ) {
    addLog(`Server production: +${formatNumber(awayGoldGained)} gold and +${formatNumber(awayTroopsGained)} troops while away.`);
    queueOfflineRewardsSummary({
      goldGained: awayGoldGained,
      troopsGained: awayTroopsGained,
      elapsed: awayElapsed,
      lostCities: awayLostCities,
      lostCityCount: awayLostCityCount,
    });
  }
  if (changed) {
    renderHud();
    if (options.renderCities === false) updateVisibleCityDynamicText();
    else renderCities();
    renderHarvestBonuses();
    if (modal.open && modal.classList.contains("shop-modal")) renderShopModal();
    if (modal.open && modal.classList.contains("inventory-modal")) showInventoryModal();
    if (modal.open && modal.classList.contains("city-list-modal")) renderCityListModal();
    if (options.renderProfile !== false && profileScreen?.classList.contains("open")) renderProfileScreen();
  }
  return changed;
}

function mergeServerEconomyRefreshOptions(current = null, next = null) {
  const currentOptions = current && typeof current === "object" ? current : {};
  const nextOptions = next && typeof next === "object" ? next : {};
  const optionRequests = [current, next].filter(value => value && typeof value === "object");
  const merged = {
    ...currentOptions,
    ...nextOptions,
    showOfflineRewards: Boolean(currentOptions.showOfflineRewards || nextOptions.showOfflineRewards),
    requestWelcomeBack: Boolean(currentOptions.requestWelcomeBack || nextOptions.requestWelcomeBack),
    resumeCatchUp: Boolean(currentOptions.resumeCatchUp || nextOptions.resumeCatchUp),
  };
  if (optionRequests.length && optionRequests.every(value => value.renderCities === false)) merged.renderCities = false;
  else delete merged.renderCities;
  return merged;
}

async function performServerEconomyRefresh(options = {}) {
  const api = getOnlineApi();
  if (!api?.collectEconomy) return false;
  try {
    const result = await api.collectEconomy({
      worldId: ONLINE_WORLD_ID,
      resetGeneration: RESET_GENERATION,
      includeWelcomeBack: options.requestWelcomeBack === true,
    });
    applyServerEconomyResult(result, mergeServerEconomyRefreshOptions(options, serverEconomyRefreshActiveOptions));
    if (options.requestWelcomeBack === true) {
      pendingWelcomeBackSession = null;
      if (serverEconomyRefreshQueuedOptions?.requestWelcomeBack) {
        serverEconomyRefreshQueuedOptions = {
          ...serverEconomyRefreshQueuedOptions,
          requestWelcomeBack: false,
        };
      }
      resolveLoginPresentationWelcomePhase(options.presentationGeneration);
    }
    serverEconomyLastSyncAt = Date.now();
    onlineLastError = "";
    updateOnlineUi();
    return true;
  } catch (error) {
    if (options.requestWelcomeBack === true) {
      resolveLoginPresentationWelcomePhase(options.presentationGeneration);
    }
    onlineLastError = error?.message || String(error);
    const nowMs = Date.now();
    if (nowMs - serverEconomyLastToastAt > 30000) {
      serverEconomyLastToastAt = nowMs;
      showToast("Server economy sync failed. Reconnecting to Crownlands...");
    }
    updateOnlineUi();
    console.warn("Could not refresh server economy", error);
    return false;
  }
}

function refreshServerEconomy(force = false, options = {}) {
  if (!state || !usesServerEconomyAuthority()) return false;
  const api = getOnlineApi();
  if (!api?.collectEconomy) return false;
  if (serverEconomyRefreshInFlight) {
    if (force) {
      serverEconomyRefreshQueued = true;
      serverEconomyRefreshActiveOptions = mergeServerEconomyRefreshOptions(
        serverEconomyRefreshActiveOptions,
        options
      );
      serverEconomyRefreshQueuedOptions = mergeServerEconomyRefreshOptions(
        serverEconomyRefreshQueuedOptions,
        options
      );
    }
    return serverEconomyRefreshPromise || Promise.resolve(false);
  }
  serverEconomyRefreshInFlight = true;
  serverEconomyRefreshActiveOptions = mergeServerEconomyRefreshOptions(null, options);
  serverEconomyRefreshPromise = (async () => {
    let nextOptions = serverEconomyRefreshActiveOptions;
    let refreshed = false;
    do {
      refreshed = await performServerEconomyRefresh(nextOptions) || refreshed;
      nextOptions = serverEconomyRefreshQueuedOptions;
      serverEconomyRefreshQueuedOptions = null;
      serverEconomyRefreshQueued = false;
      serverEconomyRefreshActiveOptions = nextOptions;
    } while (nextOptions);
    return refreshed;
  })().finally(() => {
    serverEconomyRefreshInFlight = false;
    serverEconomyRefreshPromise = null;
    serverEconomyRefreshActiveOptions = null;
    if (serverEconomyRefreshQueuedOptions) {
      const queuedOptions = serverEconomyRefreshQueuedOptions;
      serverEconomyRefreshQueuedOptions = null;
      serverEconomyRefreshQueued = false;
      refreshServerEconomy(true, queuedOptions);
    }
  });
  return serverEconomyRefreshPromise;
}

function getSerializableGameState() {
  if (!state) return null;
  normalizeGameOverState(state);
  return JSON.parse(JSON.stringify(state));
}

function getPlayerCloudStateSnapshot() {
  const profile = getPlayerProfileSnapshot();
  return {
    ...profile,
    snapshotKind: "player-profile",
    version: WORLD_SCHEMA_VERSION,
    gameSeconds: state ? Math.max(0, Number(state.gameSeconds) || 0) : 0,
  };
}

function stripServerEconomyProfileFields(profile = {}) {
  if (!usesServerEconomyAuthority()) return profile;
  const clientWritableFields = [
    "version",
    "snapshotKind",
    "activeIslandId",
    "activeRegionId",
    "playerName",
    "flag",
    "daily",
    "scoutReports",
    "battleReports",
    "marchPercent",
    "lastSelectedOwnedCityId",
    "gameSeconds",
    "localGameSeconds",
    "lastRealTimeMs",
    "lastSeenAtMs",
  ];
  return clientWritableFields.reduce((clean, field) => {
    if (profile[field] !== undefined) clean[field] = profile[field];
    return clean;
  }, {});
}

function getPlayerProfileSnapshot() {
  const profileName = state?.playerName || cleanName(playerNameInput?.value) || "Ricky";
  const activeRegionId = state ? getActiveOnlineRegionId() : DEFAULT_ONLINE_REGION_ID;
  const mainRegionId = state?.online?.mainRegionId || (state?.mainCityId ? getCityRegionId(state.mainCityId) : activeRegionId);
  const activeIslandId = state?.online?.islandId || getOnlineIslandId(activeRegionId);
  const harvestTimer = Number(state?.harvestSpawnTimer);
  return {
    resetGeneration: RESET_GENERATION,
    cloudSaveSlot: ONLINE_SAVE_SLOT,
    worldId: ONLINE_WORLD_ID,
    version: WORLD_SCHEMA_VERSION,
    mainCityId: state?.mainCityId || "",
    mainCityChangedAtMs: state ? normalizeTimestampMs(state.mainCityChangedAtMs) : 0,
    lastCityRelinquishedAtMs: state ? normalizeTimestampMs(state.lastCityRelinquishedAtMs) : 0,
    mainIslandId: state?.online?.mainIslandId || getOnlineIslandId(mainRegionId),
    activeIslandId,
    mainRegionId,
    activeRegionId,
    playerName: profileName,
    flag: PLAYER_FLAG_CONFIG.toStoredFlag(state?.flag || createDefaultFlag(), getCurrentOnlineUid() || profileName),
    character: state?.character ? normalizeCharacterProgress(state.character) : createCharacterProgress(),
    upgrades: state?.upgrades ? normalizeUpgrades(state.upgrades, state.version || 20) : createDefaultSkills(),
    skillPresets: state ? normalizeSkillPresets(state.skillPresets) : createDefaultSkillPresets(),
    freeSkillResetGrantVersion: Math.max(0, Math.floor(Number(state?.freeSkillResetGrantVersion) || 0)),
    freeSkillResetCredits: Math.max(0, Math.floor(Number(state?.freeSkillResetCredits) || 0)),
    shopItems: state ? normalizeShopItems(state.shopItems) : createDefaultShopItems(),
    gear: state ? normalizeCommonGearState(state.gear) : normalizeCommonGearState(),
    itemEffects: state ? normalizeItemEffects(state.itemEffects) : createDefaultItemEffects(),
    itemPurchaseCooldowns: state ? normalizeItemPurchaseCooldowns(state.itemPurchaseCooldowns) : createDefaultItemPurchaseCooldowns(),
    cityCount: state ? getOwnedRegularCityCountForDisplay() : 0,
    kingPower: state ? getKingPower() : 0,
    gold: state ? Math.floor(Number(state.gold) || 0) : 0,
    daily: state ? normalizeDailyCaptureTracker(state.daily) : normalizeDailyCaptureTracker(null),
    harvestBonuses: state ? normalizeHarvestBonuses(state.harvestBonuses) : [],
    harvestSpawnTimer: Number.isFinite(harvestTimer)
      ? clamp(harvestTimer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS)
      : HARVEST_BONUS_INITIAL_SPAWN_SECONDS,
    harvestNextSpawnAtMs: normalizeTimestampMs(state?.harvestNextSpawnAtMs)
      || Date.now() + (Number.isFinite(harvestTimer) ? clamp(harvestTimer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS) : HARVEST_BONUS_INITIAL_SPAWN_SECONDS) * 1000,
    harvestNextBonusType: normalizeHarvestBonusType(state?.harvestNextBonusType),
    scoutReports: state ? normalizeScoutReports(state.scoutReports) : {},
    battleReports: state ? normalizeBattleReports(state.battleReports) : [],
    reportsViewedAtMs: normalizeTimestampMs(state?.reportsViewedAtMs),
    realmAnnouncementSeenThroughMs: normalizeTimestampMs(state?.realmAnnouncementSeenThroughMs),
    lastRealmAnnouncementEventId: String(state?.lastRealmAnnouncementEventId || "").slice(0, 180),
    marchPercent: normalizeMarchPercent(state?.marchPercent ?? selectedMarchPercent),
    lastSelectedOwnedCityId: getKnownCityId(lastSelectedOwnedCityId),
    gameSeconds: state ? Math.max(0, Number(state.gameSeconds) || 0) : 0,
    localGameSeconds: state ? Number(state.gameSeconds) || 0 : 0,
    lastRealTimeMs: state ? normalizeTimestampMs(state.lastRealTimeMs) || Date.now() : Date.now(),
    lastSeenAtMs: Date.now(),
    offlineProductionCities: state ? createOfflineProductionSnapshot(state) : [],
  };
}

function mergeOnlineProfileSources(profile = null, cloudSnapshot = null) {
  const currentProfile = profile && isCurrentResetProfile(profile) ? profile : null;
  const currentCloudSnapshot = cloudSnapshot && isCurrentResetProfile(cloudSnapshot) ? cloudSnapshot : null;
  if (!currentProfile) return currentCloudSnapshot;
  if (!currentCloudSnapshot) return currentProfile;
  const profileSavedAtMs = getProfileGameSaveMs(currentProfile);
  const cloudSavedAtMs = getProfileGameSaveMs(currentCloudSnapshot);
  const merged = cloudSavedAtMs > profileSavedAtMs
    ? { ...currentProfile, ...currentCloudSnapshot }
    : { ...currentCloudSnapshot, ...currentProfile };
  if (hasServerEconomyApi()) {
    [
      "gold",
      "goldFloat",
      "character",
      "upgrades",
      "skillPresets",
      "shopItems",
      "gear",
      "itemEffects",
      "itemPurchaseCooldowns",
      "economyUpdatedAtMs",
      "mainCityId",
      "mainIslandId",
      "mainRegionId",
      "mainCityChangedAtMs",
      "lastCityRelinquishedAtMs",
      "globalStats",
      "kingPower",
      "cityCount",
      "reportsViewedAtMs",
      "realmAnnouncementSeenThroughMs",
      "lastRealmAnnouncementEventId",
    ].forEach(key => {
      if (currentProfile[key] !== undefined) merged[key] = currentProfile[key];
    });
  }
  return merged;
}

function applyOnlineProfileSnapshot(profile = null, fallbackPlayerName = "Ricky") {
  if (!state || !profile || typeof profile !== "object") return;
  state.playerName = cleanName(profile.playerName || profile.displayName) || fallbackPlayerName;
  state.clanId = String(profile.clanId || "");
  state.clanName = String(profile.clanName || "");
  state.clanTag = String(profile.clanTag || "");
  state.clanRole = String(profile.clanRole || "");
  state.clanJoinCooldownUntilMs = normalizeTimestampMs(profile.clanJoinCooldownUntilMs);
  state.pendingClanApplicationId = String(profile.pendingClanApplicationId || "");
  state.flag = normalizeFlag(profile.flag, getCurrentOnlineUid() || profile.uid || profile.playerName);
  state.character = normalizeCharacterProgress(profile.character);
  state.upgrades = normalizeUpgrades(profile.upgrades, state.version || WORLD_SCHEMA_VERSION);
  state.skillPresets = normalizeSkillPresets(profile.skillPresets);
  state.freeSkillResetGrantVersion = Math.max(0, Math.floor(Number(profile.freeSkillResetGrantVersion) || 0));
  state.freeSkillResetCredits = Math.max(0, Math.floor(Number(profile.freeSkillResetCredits) || 0));
  state.shopItems = normalizeShopItems(profile.shopItems);
  state.gear = normalizeCommonGearState(profile.gear);
  state.itemEffects = normalizeItemEffects(profile.itemEffects);
  state.itemPurchaseCooldowns = normalizeItemPurchaseCooldowns(profile.itemPurchaseCooldowns);
  if (profile.dailyLoginReward && typeof profile.dailyLoginReward === "object") {
    applyDailyLoginRewardProfileState(profile.dailyLoginReward, { autoOpen: false });
  }
  syncCharacterSkillPoints(state.character, state.upgrades, profile.character?.skillPoints);
  const profileGold = Number(profile.gold);
  state.gold = Math.max(0, Math.floor(Number.isFinite(profileGold) ? profileGold : TEST_STARTING_GOLD));
  state.daily = normalizeDailyCaptureTracker(profile.daily);
  state.harvestBonuses = enforceHarvestBonusActiveLimit(normalizeHarvestBonuses(profile.harvestBonuses));
  const harvestTimer = Number(profile.harvestSpawnTimer);
  state.harvestSpawnTimer = Number.isFinite(harvestTimer)
    ? clamp(harvestTimer, 0, HARVEST_BONUS_SPAWN_INTERVAL_SECONDS)
    : HARVEST_BONUS_INITIAL_SPAWN_SECONDS;
  state.harvestNextSpawnAtMs = normalizeTimestampMs(profile.harvestNextSpawnAtMs)
    || Date.now() + state.harvestSpawnTimer * 1000;
  state.harvestNextBonusType = normalizeHarvestBonusType(profile.harvestNextBonusType);
  state.scoutReports = normalizeScoutReports(profile.scoutReports);
  state.battleReports = normalizeBattleReports(profile.battleReports);
  state.reportsViewedAtMs = normalizeTimestampMs(profile.reportsViewedAtMs);
  state.realmAnnouncementSeenThroughMs = normalizeTimestampMs(profile.realmAnnouncementSeenThroughMs);
  state.lastRealmAnnouncementEventId = String(profile.lastRealmAnnouncementEventId || "").slice(0, 180);
  state.marchPercent = normalizeMarchPercent(profile.marchPercent);
  selectedMarchPercent = state.marchPercent;
  lastSelectedOwnedCityId = getKnownCityId(profile.lastSelectedOwnedCityId) || lastSelectedOwnedCityId;
  state.mainCityChangedAtMs = normalizeTimestampMs(profile.mainCityChangedAtMs);
  state.lastCityRelinquishedAtMs = normalizeTimestampMs(profile.lastCityRelinquishedAtMs);
  state.gameSeconds = Math.max(0, Number(profile.localGameSeconds) || Number(profile.gameSeconds) || Number(state.gameSeconds) || 0);
  state.lastRealTimeMs = normalizeTimestampMs(profile.lastRealTimeMs) || state.lastRealTimeMs;
  lastAuthoritativeProfileRevisionMs = Math.max(
    lastAuthoritativeProfileRevisionMs,
    getAuthoritativeProfileRevisionMs(profile)
  );
  if (profile.globalStats) applyGlobalStatsSnapshot(profile.globalStats, { render: false });
}

function timestampToMs(value) {
  if (!value) return 0;
  if (typeof value.toMillis === "function") return normalizeTimestampMs(value.toMillis());
  if (Number.isFinite(Number(value))) return normalizeTimestampMs(value);
  if (Number.isFinite(Number(value.seconds))) {
    return normalizeTimestampMs(Number(value.seconds) * 1000 + Math.floor((Number(value.nanoseconds) || 0) / 1_000_000));
  }
  return 0;
}

function getProfileGameSaveMs(profile = null) {
  if (!profile || typeof profile !== "object") return 0;
  return normalizeTimestampMs(profile.lastSeenAtMs)
    || normalizeTimestampMs(profile.lastRealTimeMs);
}

function getProfileLastSeenMs(profile = null) {
  if (!profile || typeof profile !== "object") return 0;
  return normalizeTimestampMs(profile.lastSeenAtMs)
    || normalizeTimestampMs(profile.lastRealTimeMs)
    || timestampToMs(profile.updatedAt);
}

function normalizeOfflineProductionCities(cities = []) {
  if (!Array.isArray(cities)) return [];
  const seen = new Set();
  return cities
    .map(city => {
      const id = getKnownCityId(city?.id);
      if (!id || seen.has(id)) return null;
      seen.add(id);
      const base = getPlayableBaseCityById(id) || {};
      return {
        id,
        name: getCanonicalCityName(base, city),
        owner: "player",
        ownerKind: "player",
        ownerUid: city.ownerUid || getCurrentOnlineUid() || null,
        ownerName: city.ownerName || state?.playerName || "",
        ownerFlag: city.ownerFlag || state?.flag || null,
        ownerKingPower: normalizePowerValue(city.ownerKingPower) || getKingPower(),
        level: isStronghold(city) ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level ?? base.level),
        troops: Math.max(0, Math.floor(Number(city.troops) || 0)),
        troopFloat: Math.max(0, Number(city.troopFloat) || Number(city.troops) || 0),
        kind: city.kind || base.kind || "",
        strongholdType: city.strongholdType || base.strongholdType || "",
        bonus: city.bonus || base.bonus || "",
        bonusPercent: Number(city.bonusPercent ?? base.bonusPercent) || 0,
        size: isStronghold(city) || isStronghold(base) ? getStrongholdVisualSize(isStronghold(base) ? base : city) : undefined,
        regionId: city.regionId || base.regionId || getCityRegionId(id),
      };
    })
    .filter(Boolean);
}

function restoreOfflineProductionCitiesToLocalState(cities = []) {
  if (!state || !Array.isArray(state.cities)) return;
  const currentUid = getCurrentOnlineUid();
  const byId = new Map(normalizeOfflineProductionCities(cities).map(city => [city.id, city]));
  if (!byId.size) return;
  state.cities = state.cities.map(city => {
    const snapshot = byId.get(city.id);
    if (!snapshot || city.owner === "enemy") return city;
    return {
      ...city,
      owner: "player",
      ownerKind: "player",
      ownerUid: currentUid || snapshot.ownerUid || city.ownerUid || null,
      ownerName: state.playerName,
      ownerFlag: state.flag,
      ownerKingPower: getKingPower(),
      level: snapshot.level,
      troops: snapshot.troops,
      troopFloat: snapshot.troopFloat,
      investedGold: Math.max(0, Math.floor(Number(city.investedGold) || 0)),
      lastCapturedAt: city.lastCapturedAt ?? null,
      isMainCity: !isStronghold(city) && city.id === state.mainCityId,
      relinquishedAtMs: 0,
      relocatedAtMs: 0,
    };
  });
}

async function prepareOfflineProgressFromProfile(profile = null) {
  pendingOfflineProgressSeconds = 0;
  pendingOfflineProductionCities = [];
  pendingOfflineOwnedCityIds = null;
  if (hasServerEconomyApi()) return false;
  if (!state || !profile || !isCurrentResetProfile(profile)) return false;

  const productionCities = normalizeOfflineProductionCities(profile.offlineProductionCities);
  if (!productionCities.length) return false;
  const lastSeenAtMs = getProfileLastSeenMs(profile);
  const elapsed = getOfflineProgressSeconds({ lastRealTimeMs: lastSeenAtMs });
  if (elapsed <= 0) return false;

  pendingOfflineProgressSeconds = elapsed;
  pendingOfflineProductionCities = productionCities;
  restoreOfflineProductionCitiesToLocalState(productionCities);

  const api = getOnlineApi();
  if (api?.loadOwnedCitiesAcrossIslands && api?.isSignedIn?.()) {
    try {
      const islandIds = getRegionIds().map(getOnlineIslandId);
      const ownedCities = await withTimeout(
        api.loadOwnedCitiesAcrossIslands(islandIds),
        4500,
        "Owned city check is taking too long."
      );
      pendingOfflineOwnedCityIds = new Set((Array.isArray(ownedCities) ? ownedCities : []).map(city => getKnownCityId(city.id)).filter(Boolean));
    } catch (error) {
      console.warn("Could not check owned cities for offline summary", error);
    }
  }
  return true;
}

function queueOnlineSave() {
  const api = getOnlineApi();
  if (!api?.isConfigured?.() || !api?.isSignedIn?.()) return;
  Object.values(onlineSaveTargets).forEach(target => {
    if (!target.blocked) target.queued = true;
  });
  onlineSaveQueued = Object.values(onlineSaveTargets).some(target => target.queued && !target.blocked);
}

function getOnlineSaveErrorCode(error = null) {
  return String(error?.code || "").toLowerCase().replace(/^firestore\//, "");
}

function isPermanentOnlineSaveError(error = null) {
  return getOnlineSaveErrorCode(error) === "permission-denied";
}

function clearOnlineSaveRetry() {
  onlineSaveRetryIndex = 0;
  onlineSaveRetryAtMs = 0;
  if (onlineSaveRetryTimer) window.clearTimeout(onlineSaveRetryTimer);
  onlineSaveRetryTimer = 0;
}

function scheduleOnlineSaveRetry() {
  if (onlineSaveRetryTimer || !onlineSaveQueued) return;
  const baseDelay = ONLINE_SAVE_RETRY_DELAYS_MS[Math.min(onlineSaveRetryIndex, ONLINE_SAVE_RETRY_DELAYS_MS.length - 1)];
  const delayMs = Math.round(baseDelay * (0.9 + Math.random() * 0.2));
  onlineSaveRetryIndex += 1;
  onlineSaveRetryAtMs = Date.now() + delayMs;
  onlineSaveRetryTimer = window.setTimeout(() => {
    onlineSaveRetryTimer = 0;
    onlineSaveRetryAtMs = 0;
    flushOnlineSave();
  }, delayMs);
}

function resetOnlineSaveCircuitForAuth(uid = "") {
  const nextUid = String(uid || "");
  if (nextUid === onlineSaveAuthUid) return;
  clearInstantEconomyActions();
  onlineSaveAuthUid = nextUid;
  onlineSaveGeneration += 1;
  clearOnlineSaveRetry();
  onlineSavePromise = null;
  onlineSaveInFlight = false;
  onlineSaveQueued = false;
  Object.values(onlineSaveTargets).forEach(target => {
    target.queued = false;
    target.blocked = false;
  });
}

async function flushOnlineSave(force = false) {
  if (!state) return false;
  if (onlineSaveInFlight) return onlineSavePromise || false;
  const api = getOnlineApi();
  if (!api?.isConfigured?.() || !api?.isSignedIn?.()) return false;
  if (!force && !onlineSaveQueued) return false;
  if (onlineSaveRetryAtMs > Date.now()) return false;

  const requestedTargets = Object.entries(onlineSaveTargets)
    .filter(([, target]) => !target.blocked && (force || target.queued))
    .filter(([name]) => name === "profile" ? typeof api.savePlayerProfile === "function" : typeof api.saveGameSnapshot === "function")
    .map(([name]) => name);
  if (!requestedTargets.length) return false;

  onlineSaveInFlight = true;
  const saveGeneration = onlineSaveGeneration;
  requestedTargets.forEach(name => {
    onlineSaveTargets[name].queued = false;
  });
  onlineSaveQueued = Object.values(onlineSaveTargets).some(target => target.queued && !target.blocked);
  const operationPromise = (async () => {
    const cloudState = getPlayerCloudStateSnapshot();
    const writes = requestedTargets.map(name => ({
      name,
      promise: name === "profile"
        ? api.savePlayerProfile(stripServerEconomyProfileFields(cloudState))
        : api.saveGameSnapshot(cloudState, ONLINE_SAVE_SLOT),
    }));
    const results = await Promise.allSettled(writes.map(write => write.promise));
    if (saveGeneration !== onlineSaveGeneration) return false;
    let successCount = 0;
    let failureCount = 0;
    let transientFailure = false;
    let lastFailure = null;
    results.forEach((result, index) => {
      const targetName = writes[index].name;
      const target = onlineSaveTargets[targetName];
      if (result.status === "fulfilled") {
        successCount += 1;
        return;
      }
      failureCount += 1;
      lastFailure = result.reason;
      if (isPermanentOnlineSaveError(result.reason)) {
        target.blocked = true;
        target.queued = false;
        console.warn(`Cloud ${targetName} save paused after a permission failure`, result.reason);
        showToast(`Cloud ${targetName} sync paused for this session.`);
      } else {
        transientFailure = true;
        target.queued = true;
        console.warn(`Cloud ${targetName} save failed`, result.reason);
      }
    });
    onlineSaveQueued = Object.values(onlineSaveTargets).some(target => target.queued && !target.blocked);
    if (transientFailure) scheduleOnlineSaveRetry();
    else clearOnlineSaveRetry();
    if (successCount > 0) {
      await syncOwnedCitiesToOnline();
      publishKingPowerLeaderboard();
      onlineLastSaveAt = Date.now();
    }
    onlineLastError = transientFailure ? lastFailure?.message || String(lastFailure || "Cloud save failed") : "";
    updateOnlineUi();
    return failureCount === 0;
  })();
  onlineSavePromise = operationPromise;
  try {
    return await operationPromise;
  } finally {
    if (saveGeneration === onlineSaveGeneration && onlineSavePromise === operationPromise) {
      onlineSaveInFlight = false;
      onlineSavePromise = null;
    }
  }
}

function getOnlinePresenceSnapshot() {
  const mainRegionId = state?.online?.mainRegionId || (state?.mainCityId ? getCityRegionId(state.mainCityId) : getActiveOnlineRegionId());
  const stats = getGlobalStatsSnapshot();
  const cityCount = hasUsableGlobalStats(stats) ? stats.totalCities : state ? getOwnedRegularCityCountForDisplay() : 0;
  return {
    displayName: state?.playerName || getOnlineApi()?.getUser?.()?.displayName || "Ruler",
    playerName: state?.playerName || "Ruler",
    flag: PLAYER_FLAG_CONFIG.toStoredFlag(state?.flag || createDefaultFlag(), getCurrentOnlineUid() || state?.playerName),
    mainCityId: stats?.mainCityId || state?.mainCityId || "",
    mainRegionId: stats?.mainRegionId || mainRegionId,
    mainIslandId: stats?.mainIslandId || state?.online?.mainIslandId || getOnlineIslandId(mainRegionId),
    cityCount,
    kingPower: state ? getKingPower() : 0,
    kingPowerVersion: Math.max(KING_POWER_AUTHORITY_VERSION, Math.floor(Number(stats?.version) || 0)),
    updatedAtMs: Date.now(),
  };
}

function getKingPowerLeaderboardSnapshot() {
  const mainRegionId = state?.online?.mainRegionId || (state?.mainCityId ? getCityRegionId(state.mainCityId) : getActiveOnlineRegionId());
  const stats = getGlobalStatsSnapshot();
  const cityCount = hasUsableGlobalStats(stats) ? stats.totalCities : state ? getOwnedRegularCityCountForDisplay() : 0;
  return {
    displayName: state?.playerName || getOnlineApi()?.getUser?.()?.displayName || "Ruler",
    playerName: state?.playerName || "Ruler",
    flag: PLAYER_FLAG_CONFIG.toStoredFlag(state?.flag || createDefaultFlag(), getCurrentOnlineUid() || state?.playerName),
    kingPower: getKingPower(),
    kingPowerVersion: Math.max(KING_POWER_AUTHORITY_VERSION, Math.floor(Number(stats?.version) || 0)),
    cityCount,
    mainCityId: stats?.mainCityId || state?.mainCityId || "",
    mainRegionId: stats?.mainRegionId || mainRegionId,
    mainIslandId: stats?.mainIslandId || state?.online?.mainIslandId || getOnlineIslandId(mainRegionId),
    clanId: String(state?.clanId || ""),
    clanName: String(state?.clanName || ""),
    clanTag: String(state?.clanTag || ""),
    updatedAtMs: Date.now(),
  };
}

function getLeaderboardEntrySignature(entry) {
  return [
    entry.playerName,
    entry.kingPower,
    entry.cityCount,
    entry.mainCityId,
    entry.mainRegionId,
    entry.clanId,
    entry.clanName,
    entry.clanTag,
    JSON.stringify(normalizeFlag(entry.flag)),
  ].join("|");
}

async function publishKingPowerLeaderboard({ force = false } = {}) {
  if (!state || leaderboardSaveInFlight) return false;
  if (!isOnlineWorldActive()) return false;
  if (usesServerEconomyAuthority()) {
    rememberCurrentPlayerIdentity();
    return false;
  }
  const api = getOnlineApi();
  if (!api?.saveKingPowerLeaderboardEntry || !api?.isSignedIn?.()) return false;
  const entry = getKingPowerLeaderboardSnapshot();
  const signature = getLeaderboardEntrySignature(entry);
  const needsStaleRefresh = Date.now() - leaderboardLastSaveAt >= LEADERBOARD_STALE_REFRESH_MS;
  if (!force && signature === leaderboardLastSignature && !needsStaleRefresh) return false;

  leaderboardSaveInFlight = true;
  try {
    await api.saveKingPowerLeaderboardEntry(entry);
    rememberCurrentPlayerIdentity();
    leaderboardLastSignature = signature;
    leaderboardLastSaveAt = Date.now();
    return true;
  } catch (error) {
    console.warn("Could not publish King Power leaderboard entry", error);
    return false;
  } finally {
    leaderboardSaveInFlight = false;
  }
}

function normalizePresence(raw) {
  if (!raw || typeof raw !== "object") return null;
  const uid = String(raw.uid || raw.id || "").trim();
  if (!uid) return null;
  return {
    uid,
    displayName: cleanName(raw.playerName || raw.displayName || "Ruler") || "Ruler",
    flag: normalizeFlag(raw.flag, uid),
    mainCityId: String(raw.mainCityId || ""),
    mainRegionId: normalizeRegionId(raw.mainRegionId || getRegionIdFromOnlineIslandId(raw.mainIslandId)),
    mainIslandId: String(raw.mainIslandId || ""),
    cityCount: Math.max(0, Math.floor(Number(raw.cityCount) || 0)),
    kingPower: Math.max(0, Math.floor(Number(raw.kingPower) || 0)),
    kingPowerVersion: Math.max(0, Math.floor(Number(raw.kingPowerVersion) || 0)),
    updatedAtMs: Math.max(0, Number(raw.updatedAtMs) || 0),
  };
}

function normalizePlayerIdentity(raw = {}, fallbackUid = "") {
  if (!raw || typeof raw !== "object") return null;
  const uid = String(raw.uid || raw.ownerUid || raw.id || fallbackUid || "").trim();
  if (!uid) return null;
  return {
    uid,
    displayName: cleanName(raw.playerName || raw.displayName || raw.ownerName || raw.name || "") || "",
    flag: normalizeFlag(raw.flag || raw.ownerFlag, uid),
    kingPower: normalizePowerValue(raw.kingPower ?? raw.ownerKingPower ?? raw.attackerKingPower),
    kingPowerVersion: Math.max(0, Math.floor(Number(raw.kingPowerVersion) || 0)),
    mainCityId: getKnownCityId(raw.mainCityId),
    mainRegionId: String(raw.mainRegionId || "").trim(),
    mainIslandId: String(raw.mainIslandId || "").trim(),
    updatedAtMs: normalizeTimestampMs(raw.updatedAtMs) || timestampToMs(raw.updatedAt),
    clanId: String(raw.clanId || raw.ownerClanId || ""),
    clanName: String(raw.clanName || raw.ownerClanName || ""),
    clanTag: String(raw.clanTag || raw.ownerClanTag || ""),
    cityCount: Math.max(0, Math.floor(Number(raw.cityCount) || 0)),
    strongholdCount: Math.max(0, Math.floor(Number(raw.strongholdCount) || 0)),
    strongholds: (Array.isArray(raw.strongholds) ? raw.strongholds : []).map(stronghold => ({
      id: String(stronghold?.id || "").slice(0, 96),
      name: String(stronghold?.name || "Stronghold").slice(0, 80),
      strongholdType: String(stronghold?.strongholdType || "").slice(0, 32),
      regionId: normalizeRegionId(stronghold?.regionId || ""),
    })).filter(stronghold => stronghold.id),
  };
}

function renderPlayerNameLink(uid = "", name = "Ruler", className = "") {
  const playerUid = String(uid || "").trim();
  const safeName = escapeHtml(cleanName(name) || "Ruler");
  if (!playerUid) return `<strong class="${escapeHtml(className)}">${safeName}</strong>`;
  return `<strong class="player-name-link ${escapeHtml(className)}" role="button" tabindex="0" data-player-profile-uid="${escapeHtml(playerUid)}" aria-label="View ${safeName}'s profile">${safeName}</strong>`;
}

function renderClanIdentityLink({
  clanId = "",
  clanName = "Clan",
  clanTag = "",
  className = "",
  display = "full",
} = {}) {
  const id = String(clanId || "").trim();
  const name = String(clanName || "Clan").trim() || "Clan";
  const tag = String(clanTag || "").trim();
  const label = display === "tag"
    ? tag ? `[${tag}]` : name
    : display === "name"
      ? name
      : `${tag ? `[${tag}] ` : ""}${name}`;
  const safeLabel = escapeHtml(label);
  if (!id) return `<strong class="${escapeHtml(className)}">${safeLabel}</strong>`;
  return `<button class="clan-name-link clan-identity-link ${escapeHtml(className)}" type="button" data-public-clan-id="${escapeHtml(id)}" aria-label="View ${escapeHtml(name)} public clan profile">${safeLabel}</button>`;
}

function renderPlayerLinkedText(text = "", uid = "", playerName = "") {
  const value = String(text || "");
  const name = cleanName(playerName);
  const playerUid = String(uid || "").trim();
  if (!value || !name || !playerUid || !value.includes(name)) return escapeHtml(value);
  const segments = [];
  const identityCharacter = character => Boolean(character && /[\p{L}\p{N}_]/u.test(character));
  let cursor = 0;
  while (cursor < value.length) {
    const matchIndex = value.indexOf(name, cursor);
    if (matchIndex < 0) break;
    const before = value[matchIndex - 1] || "";
    const after = value[matchIndex + name.length] || "";
    if (identityCharacter(before) || identityCharacter(after)) {
      segments.push(escapeHtml(value.slice(cursor, matchIndex + name.length)));
      cursor = matchIndex + name.length;
      continue;
    }
    segments.push(escapeHtml(value.slice(cursor, matchIndex)));
    segments.push(renderPlayerNameLink(playerUid, name, "player-name-link-inline"));
    cursor = matchIndex + name.length;
  }
  segments.push(escapeHtml(value.slice(cursor)));
  return segments.join("");
}

function normalizePublicPlayerProfile(raw = {}, uid = "") {
  const identity = normalizePlayerIdentity(raw, uid);
  if (!identity) return null;
  const clan = raw.clan && typeof raw.clan === "object" ? raw.clan : null;
  const rawTroopEstimate = raw.troopEstimate && typeof raw.troopEstimate === "object"
    ? raw.troopEstimate
    : null;
  const troopEstimateMin = Math.max(0, Math.floor(Number(rawTroopEstimate?.min) || 0));
  const troopEstimateMax = Math.max(0, Math.floor(Number(rawTroopEstimate?.max) || 0));
  const troopEstimate = troopEstimateMin > 0 && troopEstimateMax >= troopEstimateMin
    ? {
        min: troopEstimateMin,
        max: troopEstimateMax,
        label: `${formatTroopEstimateBound(troopEstimateMin)}\u2013${formatTroopEstimateBound(troopEstimateMax)}`,
        updatedAtMs: normalizeTimestampMs(rawTroopEstimate.updatedAtMs),
      }
    : null;
  return {
    ...identity,
    displayName: identity.displayName || "Ruler",
    flag: identity.flag || createDefaultFlag(),
    cityCount: Math.max(1, identity.cityCount),
    strongholdCount: identity.strongholds.length || identity.strongholdCount,
    clan,
    clanShield: clan?.shield || clan?.banner || raw.clanShield || null,
    troopEstimate,
  };
}

function renderPublicPlayerProfile(profile) {
  if (!profile || !modalBody) return;
  const strongholds = profile.strongholds || [];
  const clan = profile.clan || {};
  const clanName = clan.name || profile.clanName || "Clan";
  const clanTag = clan.tag || profile.clanTag || "";
  modalTitle.textContent = `${profile.displayName}'s Profile`;
  modalBody.innerHTML = `
    <div class="public-player-profile">
      <section class="public-profile-section public-profile-player">
        <div class="public-profile-heading"><span>Player Info</span></div>
        <div class="public-profile-identity">
          <span id="publicPlayerFlag" class="kingdom-flag public-profile-flag" aria-hidden="true"><span class="flag-symbol"></span></span>
          <strong>${escapeHtml(profile.displayName)}</strong>
        </div>
        <button class="public-profile-location" type="button" data-public-main-city="${escapeHtml(profile.mainCityId)}" data-public-main-region="${escapeHtml(profile.mainRegionId)}" ${profile.mainCityId ? "" : "disabled"}>
          <span aria-hidden="true">⌖</span>
          <span><strong>Main City</strong><small>${profile.mainCityId ? `${escapeHtml(getRegionLabel(profile.mainRegionId))} · View on map` : "Location unavailable"}</small></span>
        </button>
      </section>
      <section class="public-profile-section">
        <div class="public-profile-heading"><span>Kingdom</span></div>
        <div class="public-profile-stat"><strong>${formatNumber(profile.cityCount)}</strong><span>${profile.cityCount === 1 ? "City" : "Cities"} owned</span></div>
        <div class="public-profile-stat public-profile-troop-estimate"><strong>${profile.troopEstimate ? escapeHtml(profile.troopEstimate.label) : "Unavailable"}</strong><span>Estimated troops</span></div>
        <div class="public-profile-strongholds">
          <div><strong>${formatNumber(profile.strongholdCount)}</strong><span>${profile.strongholdCount === 1 ? "Stronghold" : "Strongholds"} held</span></div>
          ${strongholds.length ? `<ul>${strongholds.map(stronghold => `<li>${escapeHtml(stronghold.name)}</li>`).join("")}</ul>` : `<p>No strongholds held.</p>`}
        </div>
      </section>
      <section class="public-profile-section">
        <div class="public-profile-heading"><span>Clan</span></div>
        ${profile.clanId
          ? `<button class="public-profile-clan" type="button" data-public-clan-id="${escapeHtml(profile.clanId)}" aria-label="View ${escapeHtml(clanName)} clan profile">
              ${renderClanShield(clan.shield || clan.banner || profile.clanShield, { size: "small", instance: `public-${profile.uid}`, label: `${clanName} shield` })}
              <span class="public-profile-clan-copy"><strong>${clanTag ? `[${escapeHtml(clanTag)}] ` : ""}${escapeHtml(clanName)}</strong><small>View clan public profile</small></span>
            </button>`
          : `<p class="public-profile-empty">Not in a clan.</p>`}
      </section>
    </div>`;
  FlagRenderer.render(modalBody.querySelector("#publicPlayerFlag"), profile.flag, { stableKey: profile.uid, context: "public-profile" });
}

async function showPublicPlayerProfile(uid = "") {
  const playerUid = String(uid || "").trim();
  const api = getOnlineApi();
  if (!playerUid || !api?.isSignedIn?.()) {
    showToast("Sign in to view player profiles.");
    return;
  }
  publicClanProfileRequestId += 1;
  const requestId = ++publicPlayerProfileRequestId;
  modal.classList.remove("battle-report-modal", "city-list-modal", "island-switcher-modal", "leaderboard-modal", "inventory-modal", "shop-modal", "incoming-attack-modal", "outgoing-attack-modal");
  modal.classList.add("public-player-profile-modal");
  modalTitle.textContent = "Player Profile";
  modalBody.innerHTML = `<div class="public-profile-loading" role="status">Loading player profile…</div>`;
  if (!modal.open) modal.showModal();
  try {
    const raw = await withTimeout(
      api.loadPublicPlayerProfile?.(playerUid) || api.getCombatPlayerIdentity?.({ uid: playerUid, includePublicProfile: true }),
      15000,
      "Player profile is taking too long to load."
    );
    if (requestId !== publicPlayerProfileRequestId || !modal.open) return;
    const profile = normalizePublicPlayerProfile(raw, playerUid);
    if (!profile) throw new Error("That player profile is unavailable.");
    rememberPlayerIdentity(profile, { force: true });
    renderPublicPlayerProfile(profile);
    if (profile.clanId && !profile.clanShield && api.loadClan) {
      try {
        const clan = await withTimeout(
          api.loadClan(profile.clanId),
          5000,
          "Clan profile is taking too long to load."
        );
        if (requestId === publicPlayerProfileRequestId && modal.open && clan?.status === "active") {
          profile.clan = clan;
          profile.clanName = clan.name || profile.clanName;
          profile.clanTag = clan.tag || profile.clanTag;
          profile.clanShield = clan.shield || clan.banner || profile.clanShield;
          renderPublicPlayerProfile(profile);
        }
      } catch (clanError) {
        console.warn("Could not load player clan shield", clanError);
      }
    }
  } catch (error) {
    if (requestId !== publicPlayerProfileRequestId || !modal.open) return;
    modalBody.innerHTML = `<div class="public-profile-error"><p>${escapeHtml(error?.message || "Could not load that player profile.")}</p><button type="button" data-public-profile-retry="${escapeHtml(playerUid)}">Try again</button></div>`;
  }
}

async function focusPublicPlayerMainCity(cityId = "", regionId = "") {
  const targetId = String(cityId || "").trim();
  const knownCity = cityById(targetId) || getOwnedCitySnapshotById(targetId);
  const targetRegion = normalizeRegionId(regionId || (knownCity ? getCityRegionId(knownCity) : ""));
  if (!targetId) {
    showToast("That main city is unavailable.");
    return;
  }
  if (modal.open) modal.close();
  if (targetRegion && targetRegion !== getActiveMapRegionId()) {
    const switched = await switchOnlineIsland(targetRegion);
    if (!switched || targetRegion !== getActiveMapRegionId()) return;
  }
  const city = cityById(targetId);
  if (!city) {
    showToast("That main city is no longer available.");
    return;
  }
  scoutNearbySourceId = null;
  regroupSourceId = null;
  sendMode = false;
  selectedSourceId = null;
  selectedTargetId = city.id;
  renderSelectionChangeNow();
  requestAnimationFrame(() => centerOnCity(city.id));
  showToast(`Viewing ${city.name}`);
}

async function showPublicClanDetails(clanId = "") {
  const api = getOnlineApi();
  const id = String(clanId || "").trim();
  if (!id || !api?.isSignedIn?.() || !api?.loadClan || !api?.loadClanMembers) {
    showToast("Sign in to view clan profiles.");
    return;
  }
  publicPlayerProfileRequestId += 1;
  const requestId = ++publicClanProfileRequestId;
  modal.classList.remove("battle-report-modal", "city-list-modal", "island-switcher-modal", "leaderboard-modal", "inventory-modal", "shop-modal", "incoming-attack-modal", "outgoing-attack-modal");
  modal.classList.add("public-player-profile-modal");
  modalTitle.textContent = "Clan Profile";
  modalBody.innerHTML = `<div class="public-profile-loading" role="status">Loading clan profile…</div>`;
  if (!modal.open) modal.showModal();
  try {
    const [clan, loadedMembers] = await withTimeout(
      Promise.all([api.loadClan(id), api.loadClanMembers(id)]),
      10000,
      "Clan profile is taking too long to load."
    );
    if (requestId !== publicClanProfileRequestId || !modal.open) return;
    if (!clan || clan.status !== "active") throw new Error("That clan is unavailable.");
    clanPublicSnapshotCache.set(id, clan);
    const members = sortClanMembersByRole(loadedMembers, (first, second) => (
      normalizePowerValue(second?.kingPower) - normalizePowerValue(first?.kingPower)
      || String(first?.displayName || "").localeCompare(String(second?.displayName || ""))
    ));
    modalTitle.textContent = `${clan.name || "Clan"} Clan`;
    modalBody.innerHTML = `
      <section class="public-clan-details">
        <div class="public-clan-identity">
          ${renderClanShield(clan.shield || clan.banner, { size: "large", instance: `public-clan-${id}`, label: `${clan.name || "Clan"} shield` })}
          <div><span>Public Clan Profile</span><h3>[${escapeHtml(clan.tag || "")}] ${escapeHtml(clan.name || "Clan")}</h3><p>${escapeHtml(clan.description || "No description yet.")}</p></div>
        </div>
        <dl>
          <div><dt>Members</dt><dd>${formatNumber(clan.memberCount || members.length)}/30</dd></div>
          <div><dt>Clan Power</dt><dd>${formatNumber(clan.totalKingPower || 0)}</dd></div>
          <div><dt>Admission</dt><dd>${clan.admissionMode === "open" ? "Open" : "Approval"}</dd></div>
        </dl>
        <div class="public-clan-roster-heading"><span>Roster</span><strong>${formatNumber(members.length)} members</strong></div>
        <div class="public-clan-roster">${members.length ? members.map(member => `
          <article class="public-clan-member">
            <div>
              ${renderPlayerNameLink(member.uid || member.id, member.displayName || "Ruler")}
              <small>${escapeHtml(clanRoleLabel(member.role))}</small>
            </div>
            <div class="public-clan-member-power">
              <strong>${formatNumber(member.kingPower || 0)}</strong>
              <small>King Power</small>
            </div>
          </article>`).join("") : `<p class="public-profile-empty">No active members found.</p>`}</div>
      </section>`;
  } catch (error) {
    if (requestId === publicClanProfileRequestId && modal.open) {
      modalBody.innerHTML = `<div class="public-profile-error"><p>${escapeHtml(error?.message || "Could not load clan profile.")}</p><button type="button" data-public-clan-id="${escapeHtml(id)}">Try again</button></div>`;
    }
  }
}

function getPlayerIdentitySignature(identity) {
  if (!identity) return "";
  return [
    identity.uid || "",
    identity.displayName || "",
    getFlagSignature(identity.flag),
    normalizePowerValue(identity.kingPower),
    Math.max(0, Math.floor(Number(identity.kingPowerVersion) || 0)),
    identity.mainCityId || "",
    identity.mainRegionId || "",
    identity.clanId || "",
    identity.clanName || "",
    identity.clanTag || "",
    normalizeTimestampMs(identity.updatedAtMs),
    identity.authoritative ? 1 : 0,
  ].join("|");
}

function shouldReplacePlayerIdentity(existing, incoming, force = false) {
  if (!existing) return true;
  const existingVersion = Math.max(0, Math.floor(Number(existing.kingPowerVersion) || 0));
  const incomingVersion = Math.max(0, Math.floor(Number(incoming?.kingPowerVersion) || 0));
  if (incomingVersion < existingVersion) return false;
  if (incomingVersion > existingVersion) return true;
  if (force && !existing.authoritative) return true;
  const existingUpdatedAtMs = normalizeTimestampMs(existing.updatedAtMs);
  const incomingUpdatedAtMs = normalizeTimestampMs(incoming?.updatedAtMs);
  if (existingUpdatedAtMs && !incomingUpdatedAtMs) return false;
  if (existingUpdatedAtMs && incomingUpdatedAtMs && incomingUpdatedAtMs < existingUpdatedAtMs) return false;
  if (force) return true;
  if (existing.authoritative) return false;
  return !existingUpdatedAtMs || !incomingUpdatedAtMs || incomingUpdatedAtMs >= existingUpdatedAtMs;
}

function rememberPlayerIdentity(raw = {}, options = {}) {
  const identity = normalizePlayerIdentity(raw);
  if (!identity) return false;
  const currentUid = getCurrentOnlineUid();
  if (currentUid && state && identity.uid === currentUid) {
    identity.displayName = state.playerName || identity.displayName || "Ruler";
    identity.flag = state.flag || identity.flag || createDefaultFlag();
    identity.kingPower = getKingPower();
    identity.kingPowerVersion = Math.max(identity.kingPowerVersion, KING_POWER_AUTHORITY_VERSION);
    identity.updatedAtMs = Math.max(identity.updatedAtMs || 0, Date.now());
  }

  const existing = playerIdentityCache.get(identity.uid) || null;
  const before = getPlayerIdentitySignature(existing);
  const force = Boolean(options.force);
  const existingIsAuthoritative = Boolean(existing?.authoritative);
  const identityIsNewer = shouldReplacePlayerIdentity(existing, identity, force);
  const next = {
    uid: identity.uid,
    displayName: identityIsNewer
      ? identity.displayName || existing?.displayName || ""
      : existing?.displayName || identity.displayName || "",
    flag: identityIsNewer
      ? identity.flag || existing?.flag || null
      : existing?.flag || identity.flag || null,
    kingPower: identityIsNewer
      ? identity.kingPower
      : existing?.kingPower || 0,
    kingPowerVersion: identityIsNewer
      ? identity.kingPowerVersion
      : Math.max(0, Math.floor(Number(existing?.kingPowerVersion) || 0)),
    mainCityId: identityIsNewer
      ? identity.mainCityId || existing?.mainCityId || ""
      : existing?.mainCityId || identity.mainCityId || "",
    mainRegionId: identityIsNewer
      ? identity.mainRegionId || existing?.mainRegionId || ""
      : existing?.mainRegionId || identity.mainRegionId || "",
    mainIslandId: identityIsNewer
      ? identity.mainIslandId || existing?.mainIslandId || ""
      : existing?.mainIslandId || identity.mainIslandId || "",
    updatedAtMs: identityIsNewer
      ? Math.max(existing?.updatedAtMs || 0, identity.updatedAtMs || 0)
      : existing?.updatedAtMs || identity.updatedAtMs || 0,
    fetchedAtMs: force ? Date.now() : existing?.fetchedAtMs || 0,
    authoritative: existingIsAuthoritative || (force && identityIsNewer),
    clanId: identityIsNewer ? identity.clanId || existing?.clanId || "" : existing?.clanId || identity.clanId || "",
    clanName: identityIsNewer ? identity.clanName || existing?.clanName || "" : existing?.clanName || identity.clanName || "",
    clanTag: identityIsNewer ? identity.clanTag || existing?.clanTag || "" : existing?.clanTag || identity.clanTag || "",
  };
  playerIdentityCache.set(identity.uid, next);
  playerIdentityLookupMisses.delete(identity.uid);
  return before !== getPlayerIdentitySignature(next);
}

function rememberPlayerIdentities(rows = [], options = {}) {
  let changed = false;
  (Array.isArray(rows) ? rows : []).forEach(row => {
    if (rememberPlayerIdentity(row, options)) changed = true;
  });
  return changed;
}

function rememberOwnerIdentitiesFromRecords(records = []) {
  let changed = false;
  (Array.isArray(records) ? records : []).forEach(record => {
    if (!record || typeof record !== "object") return;
    const ownerUid = String(record.ownerUid || record.uid || "").trim();
    if (!ownerUid) return;
    if (rememberPlayerIdentity({
      uid: ownerUid,
      ownerName: record.ownerName,
      ownerFlag: record.ownerFlag,
      ownerKingPower: record.ownerKingPower ?? record.kingPower ?? record.attackerKingPower,
      kingPowerVersion: record.kingPowerVersion,
      updatedAtMs: normalizeTimestampMs(record.updatedAtMs) || timestampToMs(record.updatedAt),
    })) {
      changed = true;
    }
  });
  return changed;
}

function rememberCurrentPlayerIdentity() {
  const uid = getCurrentOnlineUid();
  if (!uid || !state) return false;
  return rememberPlayerIdentity({
    uid,
    playerName: state.playerName,
    flag: state.flag,
    kingPower: getKingPower(),
    kingPowerVersion: KING_POWER_AUTHORITY_VERSION,
    mainCityId: state.mainCityId || "",
    mainRegionId: state.online?.mainRegionId || getCityRegionId(state.mainCityId),
    mainIslandId: state.online?.mainIslandId || getOnlineIslandId(getCityRegionId(state.mainCityId)),
    updatedAtMs: Date.now(),
  }, { force: true });
}

function resolvePlayerIdentityForUid(uid, fallback = {}) {
  const ownerUid = String(uid || "").trim();
  const fallbackIdentity = normalizePlayerIdentity(fallback, ownerUid) || {};
  const currentUid = getCurrentOnlineUid();
  if (ownerUid && currentUid && ownerUid === currentUid && state) {
    return {
      uid: ownerUid,
      displayName: state.playerName || fallbackIdentity.displayName || "Ruler",
      flag: state.flag || fallbackIdentity.flag || createDefaultFlag(),
      kingPower: getCurrentPlayerIdentityKingPower(fallbackIdentity.kingPower),
      kingPowerVersion: KING_POWER_AUTHORITY_VERSION,
      mainCityId: state.mainCityId || fallbackIdentity.mainCityId || "",
      mainRegionId: state.online?.mainRegionId || fallbackIdentity.mainRegionId || "",
      mainIslandId: state.online?.mainIslandId || fallbackIdentity.mainIslandId || "",
      updatedAtMs: Date.now(),
      clanId: state.clanId || "",
      clanName: state.clanName || "",
      clanTag: state.clanTag || "",
    };
  }
  const cached = ownerUid ? playerIdentityCache.get(ownerUid) : null;
  const cachedPowerVersion = Math.max(0, Math.floor(Number(cached?.kingPowerVersion) || 0));
  const fallbackPowerVersion = Math.max(0, Math.floor(Number(fallbackIdentity.kingPowerVersion) || 0));
  const cachedPowerIsPreferred = Boolean(cached) && (
    cachedPowerVersion > fallbackPowerVersion
    || (
      cachedPowerVersion === fallbackPowerVersion
      && normalizeTimestampMs(cached?.updatedAtMs) >= normalizeTimestampMs(fallbackIdentity.updatedAtMs)
    )
  );
  return {
    uid: ownerUid,
    displayName: cached?.displayName || fallbackIdentity.displayName || "",
    flag: cached?.flag || fallbackIdentity.flag || null,
    kingPower: cachedPowerIsPreferred
      ? normalizePowerValue(cached.kingPower)
      : normalizePowerValue(fallbackIdentity.kingPower),
    kingPowerVersion: Math.max(cachedPowerVersion, fallbackPowerVersion),
    mainCityId: cached?.mainCityId || fallbackIdentity.mainCityId || "",
    mainRegionId: cached?.mainRegionId || fallbackIdentity.mainRegionId || "",
    mainIslandId: cached?.mainIslandId || fallbackIdentity.mainIslandId || "",
    updatedAtMs: Math.max(cached?.updatedAtMs || 0, fallbackIdentity.updatedAtMs || 0),
    clanId: cached?.clanId || fallbackIdentity.clanId || "",
    clanName: cached?.clanName || fallbackIdentity.clanName || "",
    clanTag: cached?.clanTag || fallbackIdentity.clanTag || "",
  };
}

function applyCanonicalPlayerIdentityToRecord(record) {
  if (!record || typeof record !== "object") return false;
  const ownerUid = String(record.ownerUid || "").trim();
  if (!ownerUid) return false;
  const rawOwnerKind = record.ownerKind || record.owner || "player";
  if (rawOwnerKind !== "player" && record.owner !== "player" && record.owner !== "enemy") return false;
  const identity = resolvePlayerIdentityForUid(ownerUid, record);
  const nextName = identity.displayName || record.ownerName || "";
  const nextFlag = identity.flag || record.ownerFlag || null;
  const nextPower = identity.kingPowerVersion >= KING_POWER_AUTHORITY_VERSION
    ? normalizePowerValue(identity.kingPower)
    : normalizePowerValue(identity.kingPower) || normalizePowerValue(record.ownerKingPower);
  const nextPowerVersion = Math.max(
    Math.max(0, Math.floor(Number(record.kingPowerVersion) || 0)),
    Math.max(0, Math.floor(Number(identity.kingPowerVersion) || 0))
  );
  const nextClanId = identity.clanId || "";
  const nextClanName = identity.clanName || "";
  const nextClanTag = identity.clanTag || "";
  let changed = false;
  if ((record.ownerName || "") !== nextName) {
    record.ownerName = nextName;
    changed = true;
  }
  if (getFlagSignature(record.ownerFlag) !== getFlagSignature(nextFlag)) {
    record.ownerFlag = nextFlag;
    changed = true;
  }
  if (normalizePowerValue(record.ownerKingPower) !== nextPower) {
    record.ownerKingPower = nextPower;
    changed = true;
  }
  if (Math.max(0, Math.floor(Number(record.kingPowerVersion) || 0)) !== nextPowerVersion) {
    record.kingPowerVersion = nextPowerVersion;
    changed = true;
  }
  if (record.attackerKingPower !== undefined && normalizePowerValue(record.attackerKingPower) !== nextPower) {
    record.attackerKingPower = nextPower;
    changed = true;
  }
  if ((record.ownerClanId || "") !== nextClanId) {
    record.ownerClanId = nextClanId;
    changed = true;
  }
  if ((record.ownerClanName || "") !== nextClanName) {
    record.ownerClanName = nextClanName;
    changed = true;
  }
  if ((record.ownerClanTag || "") !== nextClanTag) {
    record.ownerClanTag = nextClanTag;
    changed = true;
  }
  return changed;
}

function queuePlayerIdentityLookupForUids(uids = [], options = {}) {
  const api = getOnlineApi();
  if (!api?.loadPlayerIdentities || !api?.isSignedIn?.()) return;
  const currentUid = getCurrentOnlineUid();
  const now = Date.now();
  const refreshUids = options.refreshUids instanceof Set
    ? options.refreshUids
    : new Set(Array.isArray(options.refreshUids) ? options.refreshUids : []);
  const uniqueUids = [...new Set((Array.isArray(uids) ? uids : [])
    .map(uid => String(uid || "").trim())
    .filter(uid => uid && uid !== currentUid))];
  uniqueUids.forEach(uid => {
    const cached = playerIdentityCache.get(uid);
    const missedAt = playerIdentityLookupMisses.get(uid) || 0;
    const fetchedAt = cached?.authoritative ? cached.fetchedAtMs || 0 : 0;
    if (!refreshUids.has(uid) && fetchedAt && now - fetchedAt < PLAYER_IDENTITY_CACHE_STALE_MS) return;
    if (!refreshUids.has(uid) && missedAt && now - missedAt < PLAYER_IDENTITY_CACHE_STALE_MS) return;
    playerIdentityLookupQueue.add(uid);
  });
  if (!playerIdentityLookupQueue.size || playerIdentityLookupInFlight) return;
  window.setTimeout(refreshQueuedPlayerIdentities, 0);
}

function queuePlayerIdentityLookupForRecords(records = []) {
  if (!Array.isArray(records) || !records.length) return;
  const refreshUids = new Set();
  records.forEach(record => {
    const ownerUid = String(record?.ownerUid || record?.uid || "").trim();
    if (!ownerUid) return;
    const cached = playerIdentityCache.get(ownerUid);
    const recordKingPowerVersion = Math.max(0, Math.floor(Number(record?.kingPowerVersion) || 0));
    const recordKingPower = normalizePowerValue(
      record?.ownerKingPower ?? record?.kingPower ?? record?.attackerKingPower
    );
    const recordUpdatedAtMs = normalizeTimestampMs(record?.kingPowerUpdatedAtMs)
      || normalizeTimestampMs(record?.updatedAtMs)
      || timestampToMs(record?.updatedAt);
    if (recordKingPowerVersion >= KING_POWER_AUTHORITY_VERSION && recordKingPower > 0 && (
      !cached?.authoritative
      || (
        recordKingPower !== normalizePowerValue(cached.kingPower)
        || recordUpdatedAtMs > normalizeTimestampMs(cached.updatedAtMs)
      )
    )) {
      refreshUids.add(ownerUid);
    }
  });
  rememberOwnerIdentitiesFromRecords(records);
  queuePlayerIdentityLookupForUids(
    records.map(record => record?.ownerUid || record?.uid).filter(Boolean),
    { refreshUids }
  );
}

async function refreshQueuedPlayerIdentities() {
  if (playerIdentityLookupInFlight) return;
  const api = getOnlineApi();
  if (!api?.loadPlayerIdentities || !api?.isSignedIn?.()) return;
  playerIdentityLookupInFlight = true;
  let changed = false;
  try {
    while (playerIdentityLookupQueue.size) {
      const batch = Array.from(playerIdentityLookupQueue).slice(0, PLAYER_IDENTITY_LOOKUP_BATCH_SIZE);
      batch.forEach(uid => playerIdentityLookupQueue.delete(uid));
      const rows = await api.loadPlayerIdentities(batch);
      const normalizedRows = (Array.isArray(rows) ? rows : []).map(normalizePlayerIdentity).filter(Boolean);
      const found = new Set(normalizedRows.map(row => row.uid));
      if (rememberPlayerIdentities(normalizedRows, { force: true })) changed = true;
      batch.forEach(uid => {
        if (!found.has(uid)) playerIdentityLookupMisses.set(uid, Date.now());
      });
    }
  } catch (error) {
    console.warn("Could not refresh player identities", error);
  } finally {
    playerIdentityLookupInFlight = false;
  }
  const recordsChanged = canonicalizeVisiblePlayerIdentities();
  if (changed || recordsChanged) {
    renderCities(true);
    renderPaths();
    renderArmies();
    updateIncomingAttackUi();
    updateOutgoingAttackUi();
  }
  if (playerIdentityLookupQueue.size) window.setTimeout(refreshQueuedPlayerIdentities, 0);
}

function canonicalizeVisiblePlayerIdentities() {
  let changed = false;
  if (state?.cities?.length) {
    state.cities.forEach(city => {
      if (applyCanonicalPlayerIdentityToRecord(city)) changed = true;
    });
  }
  if (onlineOwnedCitiesCache.length) {
    onlineOwnedCitiesCache.forEach(city => {
      if (applyCanonicalPlayerIdentityToRecord(city)) changed = true;
    });
  }
  if (onlineArmies.length) {
    onlineArmies.forEach(army => {
      if (applyCanonicalPlayerIdentityToRecord(army)) changed = true;
    });
  }
  onlineArmiesByIsland.forEach(armies => {
    (Array.isArray(armies) ? armies : []).forEach(army => {
      if (applyCanonicalPlayerIdentityToRecord(army)) changed = true;
    });
  });
  if (state?.attacks?.length) {
    state.attacks.forEach(attack => {
      if (applyCanonicalPlayerIdentityToRecord(attack)) changed = true;
    });
  }
  return changed;
}

function getActiveOnlinePlayers() {
  const now = Date.now();
  const activeByUid = new Map();
  for (const presence of onlinePresence) {
    if (!presence?.uid) continue;
    if (presence.updatedAtMs && now - presence.updatedAtMs > ONLINE_PRESENCE_STALE_SECONDS * 1000) continue;
    activeByUid.set(presence.uid, presence);
  }
  const currentUid = getCurrentOnlineUid();
  if (currentUid && (onlineWorldConnected || isOnlineWorldActive()) && !activeByUid.has(currentUid)) {
    activeByUid.set(currentUid, {
      ...getOnlinePresenceSnapshot(),
      uid: currentUid,
      updatedAtMs: now,
    });
  }
  return Array.from(activeByUid.values()).sort((a, b) => a.displayName.localeCompare(b.displayName));
}

function updateOnlinePlayersUi() {
}

function updateIslandSwitcherUi() {
  if (!islandSwitchBtn) return;
  const show = Boolean(state);
  islandSwitchBtn.hidden = !show;
  if (!show) return;
  const regionId = getActiveOnlineRegionId();
  const label = getRegionLabel(regionId);
  if (islandSwitchLabel) islandSwitchLabel.textContent = "Map";
  islandSwitchBtn.title = `Map - viewing ${label}`;
  updateIslandMapTileSummariesInPlace();
}

function centerOnRegion(regionId) {
  const targetRegionId = normalizeRegionId(regionId);
  if (state) {
    state.activeRegionId = targetRegionId;
    if (state.online) {
      state.online.activeRegionId = targetRegionId;
      state.online.islandId = getOnlineIslandId(targetRegionId);
    }
  }
  onlineActiveRegionId = targetRegionId;
  syncMapSurfaceToActiveIsland(true);
  centerOnMap();
}

function getOwnedRegularCityCountsByRegionForDisplay() {
  const countsByRegion = new Map();
  const seenIds = new Set();
  const addCity = city => {
    const id = getKnownCityId(city?.id);
    if (!id || seenIds.has(id) || isStronghold(city)) return;
    seenIds.add(id);
    const regionId = getCityRegionId(city);
    countsByRegion.set(regionId, (countsByRegion.get(regionId) || 0) + 1);
  };
  onlineOwnedCitiesCache.forEach(addCity);
  if (state?.cities) playerRegularCities().forEach(addCity);
  return countsByRegion;
}

function getOwnedRegularCityCountForDisplay(regionId = null) {
  const hasRegionFilter = regionId !== null && regionId !== undefined && String(regionId || "").trim();
  const statsCount = getGlobalOwnedCityCountByRegion(hasRegionFilter ? regionId : null);
  if (statsCount !== null) return statsCount;
  const countsByRegion = getOwnedRegularCityCountsByRegionForDisplay();
  if (hasRegionFilter) {
    const targetRegionId = normalizeRegionId(regionId);
    return countsByRegion.get(targetRegionId) || 0;
  }
  let total = 0;
  countsByRegion.forEach(count => { total += count; });
  return total;
}

function getIslandOwnedCityCount(regionId) {
  const targetRegionId = normalizeRegionId(regionId);
  const cachedCount = getOwnedRegularCityCountForDisplay(targetRegionId);
  if (cachedCount > 0 || onlineOwnedCitiesCache.length) return cachedCount;
  return state ? playerRegularCities().filter(city => getCityRegionId(city) === targetRegionId).length : 0;
}

function getIslandSwitcherSummary(regionId) {
  const targetRegionId = normalizeRegionId(regionId);
  const statsOwnedCount = getGlobalOwnedCityCountByRegion(targetRegionId);
  const summary = getIslandOccupancySummary(targetRegionId);
  const ownedCount = statsOwnedCount !== null
    ? statsOwnedCount
    : summary
    ? Math.max(0, Math.floor(Number(summary.ownCityCount) || 0))
    : getIslandOwnedCityCount(targetRegionId);
  return `Your cities: ${formatNumber(ownedCount)}`;
}

function summarizeIslandOccupancy(regionId, cities = state?.cities || []) {
  const activeRegionId = normalizeRegionId(regionId);
  const currentUid = getCurrentOnlineUid();
  const owners = new Set();
  const rivalOwners = new Set();
  const regularCityCount = getRegularCityCapacity(activeRegionId);
  let playerHeldCityCount = 0;
  let ownCityCount = 0;
  let rivalCityCount = 0;

  cities.forEach(city => {
    if (!city || isStronghold(city) || getCityRegionId(city) !== activeRegionId) return;
    const ownership = getCityRecordOwnership(city, currentUid, { allowLocalPlayerFallback: true });
    const ownerUid = String(ownership.ownerUid || "");
    const isLocalPlayerCity = ownership.owner === "player";
    if (ownership.ownerKind !== "player" && !isLocalPlayerCity) return;

    playerHeldCityCount += 1;
    if (ownerUid) owners.add(ownerUid);
    if (isLocalPlayerCity || (currentUid && ownerUid === currentUid)) {
      ownCityCount += 1;
    } else {
      rivalCityCount += 1;
      if (ownerUid) rivalOwners.add(ownerUid);
    }
  });

  return {
    regionId: activeRegionId,
    islandId: getOnlineIslandId(activeRegionId),
    cityCount: regularCityCount,
    regularCityCount,
    playerHeldCityCount,
    neutralCityCount: Math.max(0, regularCityCount - playerHeldCityCount),
    ownCityCount,
    rivalCityCount,
    rulerCount: owners.size || (playerHeldCityCount > 0 ? 1 : 0),
    rivalRulerCount: rivalOwners.size || (rivalCityCount > 0 ? 1 : 0),
    updatedAtMs: Date.now(),
  };
}

function cacheIslandOccupancySummary(regionId, summary = null) {
  const activeRegionId = normalizeRegionId(regionId);
  const regularCityCount = Math.max(
    0,
    getRegularCityCapacity(activeRegionId),
    Math.floor(Number(summary?.regularCityCount) || 0),
    Math.floor(Number(summary?.cityCount) || 0)
  );
  const playerHeldCityCount = Math.max(0, Math.floor(Number(summary?.playerHeldCityCount) || 0));
  const neutralCityCount = getNeutralCityCountFromSummary(activeRegionId, {
    ...(summary || {}),
    regularCityCount,
    playerHeldCityCount,
  });
  const normalized = summary
    ? {
        regionId: activeRegionId,
        islandId: summary.islandId || getOnlineIslandId(activeRegionId),
        cityCount: Math.max(regularCityCount, Math.floor(Number(summary.cityCount) || 0)),
        regularCityCount,
        neutralCityCount,
        playerHeldCityCount,
        ownCityCount: Math.max(0, Math.floor(Number(summary.ownCityCount) || 0)),
        rivalCityCount: Math.max(0, Math.floor(Number(summary.rivalCityCount) || 0)),
        rulerCount: Math.max(0, Math.floor(Number(summary.rulerCount) || 0)),
        rivalRulerCount: Math.max(0, Math.floor(Number(summary.rivalRulerCount) || 0)),
        updatedAtMs: Math.max(0, Number(summary.updatedAtMs) || Date.now()),
      }
    : summarizeIslandOccupancy(activeRegionId);
  onlineIslandSummaries.set(activeRegionId, normalized);
  return normalized;
}

function updateIslandSummariesFromOwnedCityCache() {
  if (!onlineOwnedCitiesCache.length) return;
  const countsByRegion = new Map();
  for (const city of onlineOwnedCitiesCache) {
    if (!city || isStronghold(city)) continue;
    const regionId = getCityRegionId(city);
    countsByRegion.set(regionId, (countsByRegion.get(regionId) || 0) + 1);
  }
  getRegionIds().forEach(regionId => {
    const existing = onlineIslandSummaries.get(regionId) || {};
    onlineIslandSummaries.set(regionId, {
      regionId,
      islandId: getOnlineIslandId(regionId),
      cityCount: Math.max(0, Math.floor(Number(existing.cityCount) || 0)),
      regularCityCount: Math.max(0, getRegularCityCapacity(regionId), Math.floor(Number(existing.regularCityCount) || 0)),
      playerHeldCityCount: Math.max(
        Math.max(0, Math.floor(Number(existing.playerHeldCityCount) || 0)),
        Math.max(0, Math.floor(Number(existing.rivalCityCount) || 0)) + (countsByRegion.get(regionId) || 0)
      ),
      ownCityCount: countsByRegion.get(regionId) || 0,
      rivalCityCount: Math.max(0, Math.floor(Number(existing.rivalCityCount) || 0)),
      rulerCount: Math.max(0, Math.floor(Number(existing.rulerCount) || 0)),
      rivalRulerCount: Math.max(0, Math.floor(Number(existing.rivalRulerCount) || 0)),
      updatedAtMs: Date.now(),
    });
    const next = onlineIslandSummaries.get(regionId);
    next.neutralCityCount = getNeutralCityCountFromSummary(regionId, next);
  });
  rerenderIslandSwitcherModalIfOpen();
}

function getIslandOccupancySummary(regionId) {
  const activeRegionId = normalizeRegionId(regionId);
  if (state && activeRegionId === getActiveOnlineRegionId() && onlineCitiesLoaded) {
    return cacheIslandOccupancySummary(activeRegionId);
  }
  return onlineIslandSummaries.get(activeRegionId) || null;
}

function getIslandTileSummaryText(regionId) {
  return getIslandSwitcherSummary(regionId);
}

function getIslandTileAriaSummary(regionId) {
  return getIslandSwitcherSummary(regionId);
}

function rerenderIslandSwitcherModalIfOpen() {
  if (!modal.open || !modal.classList.contains("island-switcher-modal")) return;
  rememberIslandMapPickerView();
  updateIslandMapTileSummariesInPlace();
}

function updateIslandMapTileSummariesInPlace() {
  const picker = getIslandMapPickerElement();
  if (!picker) return false;
  const activeRegionId = getActiveOnlineRegionId();
  const homeRegionId = getMainCityRegionId();
  picker.querySelectorAll("[data-island-region]").forEach(button => {
    const regionId = normalizeRegionId(button.dataset.islandRegion);
    const summaryText = getIslandTileSummaryText(regionId);
    const summary = button.querySelector(".island-map-owned");
    if (summary && summary.textContent !== summaryText) summary.textContent = summaryText;

    const ariaParts = [getRegionLabel(regionId), getIslandTileAriaSummary(regionId)];
    if (regionId === activeRegionId) ariaParts.push("current map");
    if (regionId === homeRegionId) ariaParts.push("home island");
    button.setAttribute("aria-label", ariaParts.join(", "));
  });
  return true;
}

async function refreshOnlineIslandSummaries(force = false) {
  const api = getOnlineApi();
  if (onlineIslandSummaryRefreshInFlight || !api?.loadIslandCitySummary || !api?.isSignedIn?.()) return false;
  onlineIslandSummaryRefreshInFlight = true;
  try {
    const now = Date.now();
    const regions = getRegionIds();
    const staleRegions = regions
      .filter(regionId => force || !onlineIslandSummaries.get(regionId) || now - onlineIslandSummaries.get(regionId).updatedAtMs > 30000);
    if (!staleRegions.length) return true;
    for (const regionId of staleRegions) {
      if (mapSwitchLoading || onlineWorldLoading) break;
      try {
        const summary = await api.loadIslandCitySummary(getOnlineIslandId(regionId));
        if (summary) cacheIslandOccupancySummary(regionId, summary);
      } catch (error) {
        console.warn(`Could not load ${getRegionLabel(regionId)} ownership summary`, error);
      }
    }
    rerenderIslandSwitcherModalIfOpen();
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    console.warn("Could not load island ownership summaries", error);
    return false;
  } finally {
    onlineIslandSummaryRefreshInFlight = false;
  }
}

async function refreshAllOwnedCities(force = false) {
  if (!state || onlineOwnedCitiesRefreshInFlight) return false;
  const api = getOnlineApi();
  if (!api?.loadOwnedCitiesAcrossIslands || !api?.isSignedIn?.()) {
    mergeOwnedCitySnapshots(playerCities().map(city => ({
      ...city,
      islandId: getOnlineIslandId(getCityRegionId(city)),
    })), { complete: false });
    return false;
  }
  const now = Date.now();
  if (!force && onlineOwnedCitiesCacheComplete && onlineOwnedCitiesCache.length && now - onlineOwnedCitiesCacheAt < ONLINE_OWNED_CITIES_REFRESH_MS) return true;

  onlineOwnedCitiesRefreshInFlight = true;
  onlineOwnedCitiesRefreshError = "";
  try {
    const islandIds = getRegionIds().map(getOnlineIslandId);
    const owned = await withTimeout(
      api.loadOwnedCitiesAcrossIslands(islandIds),
      6500,
      "Owned city lookup is taking too long."
    );
    mergeOwnedCitySnapshots((Array.isArray(owned) ? owned : []).map(city => ({
      ...city,
      islandId: city.islandId || getOnlineIslandId(getCityRegionId(city)),
    })), { complete: true });
    onlineOwnedCitiesRefreshError = "";
    renderHud();
    if (profileScreen?.classList.contains("open")) renderProfileScreen();
    if (modal.open && modal.classList.contains("city-list-modal")) renderCityListModal();
    if (modal.open && modal.classList.contains("island-switcher-modal")) rerenderIslandSwitcherModalIfOpen();
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    onlineOwnedCitiesRefreshError = onlineLastError;
    console.warn("Could not load owned cities across islands", error);
    return false;
  } finally {
    onlineOwnedCitiesRefreshInFlight = false;
    if (modal.open && modal.classList.contains("city-list-modal")) renderCityListModal();
  }
}

const ISLAND_PICKER_TILE_WIDTH = 238;
const ISLAND_PICKER_TILE_HEIGHT = 179;
const ISLAND_PICKER_TILE_GAP = 34;
const ISLAND_PICKER_STAGE_PADDING = 260;
const ISLAND_PICKER_GRID_CELL_WORLD_SIZE = 2300;
const ISLAND_PICKER_MIN_ZOOM = 0.18;
const ISLAND_PICKER_MAX_ZOOM = 1;
const ISLAND_PICKER_CAMERA_EASE_MS = 120;
const ISLAND_PICKER_ZOOM_EPSILON = 0.00035;
const ISLAND_PICKER_CAMERA_EPSILON = 0.12;

function getIslandMapGridCoordinate(region) {
  const regionId = normalizeRegionId(region?.id);
  const map = getEditorMap(regionId);
  const explicitGridX = [map?.gridX, map?.region?.gridX, region?.gridX].find(value => Number.isFinite(Number(value)));
  const explicitGridY = [map?.gridY, map?.region?.gridY, region?.gridY].find(value => Number.isFinite(Number(value)));
  if (explicitGridX !== undefined && explicitGridY !== undefined) {
    return { gridX: Math.round(Number(explicitGridX)), gridY: Math.round(Number(explicitGridY)) };
  }

  const starterDefaults = {
    center: { gridX: 0, gridY: 0 },
    west: { gridX: -1, gridY: 0 },
    east: { gridX: 1, gridY: 0 },
    north: { gridX: 0, gridY: -1 },
    south: { gridX: 0, gridY: 1 },
  };
  if (starterDefaults[regionId]) return starterDefaults[regionId];

  const explicitWorldX = [map?.region?.x, region?.x].find(value => Number.isFinite(Number(value)));
  const explicitWorldY = [map?.region?.y, region?.y].find(value => Number.isFinite(Number(value)));
  if (explicitWorldX !== undefined && explicitWorldY !== undefined) {
    const cellSize = Math.max(500, Number(MAP_EDITOR_DATA?.globalSettings?.gridCellWorldSize) || ISLAND_PICKER_GRID_CELL_WORLD_SIZE);
    const worldWidth = Math.max(1000, Number(MAP_EDITOR_DATA?.globalSettings?.worldWidth) || WORLD_WIDTH);
    const worldHeight = Math.max(1000, Number(MAP_EDITOR_DATA?.globalSettings?.worldHeight) || WORLD_HEIGHT);
    return {
      gridX: Math.round((Number(explicitWorldX) - worldWidth / 2) / cellSize),
      gridY: Math.round((Number(explicitWorldY) - worldHeight / 2) / cellSize),
    };
  }

  const cellSize = Math.max(500, Number(MAP_EDITOR_DATA?.globalSettings?.gridCellWorldSize) || ISLAND_PICKER_GRID_CELL_WORLD_SIZE);
  return {
    gridX: Math.round(((Number(region?.x) || WORLD_WIDTH / 2) - WORLD_WIDTH / 2) / cellSize),
    gridY: Math.round(((Number(region?.y) || WORLD_HEIGHT / 2) - WORLD_HEIGHT / 2) / cellSize),
  };
}

function getIslandMapGridLayout() {
  const entries = WORLD_REGIONS.map(region => ({
    region,
    ...getIslandMapGridCoordinate(region),
  }));
  const xs = entries.map(entry => entry.gridX);
  const ys = entries.map(entry => entry.gridY);
  const minX = Math.min(...xs, 0);
  const maxX = Math.max(...xs, 0);
  const minY = Math.min(...ys, 0);
  const maxY = Math.max(...ys, 0);
  const stepX = ISLAND_PICKER_TILE_WIDTH + ISLAND_PICKER_TILE_GAP;
  const stepY = ISLAND_PICKER_TILE_HEIGHT + ISLAND_PICKER_TILE_GAP;
  const stageWidth = ISLAND_PICKER_STAGE_PADDING * 2 + (maxX - minX + 1) * ISLAND_PICKER_TILE_WIDTH + (maxX - minX) * ISLAND_PICKER_TILE_GAP;
  const stageHeight = ISLAND_PICKER_STAGE_PADDING * 2 + (maxY - minY + 1) * ISLAND_PICKER_TILE_HEIGHT + (maxY - minY) * ISLAND_PICKER_TILE_GAP;
  return { entries, minX, minY, stepX, stepY, stageWidth, stageHeight };
}

function getIslandMapPosition(region) {
  const layout = getIslandMapGridLayout();
  const { gridX, gridY } = getIslandMapGridCoordinate(region);
  return {
    x: ISLAND_PICKER_STAGE_PADDING + (gridX - layout.minX) * layout.stepX + ISLAND_PICKER_TILE_WIDTH / 2,
    y: ISLAND_PICKER_STAGE_PADDING + (gridY - layout.minY) * layout.stepY + ISLAND_PICKER_TILE_HEIGHT / 2,
  };
}

function getIslandMapIconStyle(region) {
  const position = getIslandMapPosition(region);
  return [
    `--island-x:${formatPathNumber(position.x)}px`,
    `--island-y:${formatPathNumber(position.y)}px`,
    `--island-w:${ISLAND_PICKER_TILE_WIDTH}px`,
    `--island-h:${ISLAND_PICKER_TILE_HEIGHT}px`,
  ].join(";");
}

function getIslandMapPickerStyle() {
  const layout = getIslandMapGridLayout();
  const zoom = clampIslandMapPickerZoom(islandMapPickerViewState.zoom);
  return [
    `--island-grid-base-w:${Math.round(layout.stageWidth)}px`,
    `--island-grid-base-h:${Math.round(layout.stageHeight)}px`,
    `--island-grid-cell-w:${ISLAND_PICKER_TILE_WIDTH + ISLAND_PICKER_TILE_GAP}px`,
    `--island-grid-cell-h:${ISLAND_PICKER_TILE_HEIGHT + ISLAND_PICKER_TILE_GAP}px`,
    `--island-camera-x:${formatPathNumber(islandMapPickerViewState.x)}px`,
    `--island-camera-y:${formatPathNumber(islandMapPickerViewState.y)}px`,
    `--island-map-zoom:${formatPathNumber(zoom)}`,
  ].join(";");
}

function getIslandMapConnectionEdges() {
  const regionIds = new Set(getRegionIds());
  const edges = new Map();
  for (const map of getEditorMapEntries()) {
    const source = normalizeRegionId(map.id);
    if (!regionIds.has(source)) continue;
    for (const transition of getEditorPortalDefinitions(source)) {
      const target = getEdgeConnectionTargetRegionId(transition);
      if (!target || target === source || !regionIds.has(target)) continue;
      const key = [source, target].sort().join("::");
      if (!edges.has(key)) edges.set(key, { source, target });
    }
  }
  return Array.from(edges.values());
}

function renderIslandMapConnections() {
  const layout = getIslandMapGridLayout();
  const regionById = new Map(WORLD_REGIONS.map(region => [normalizeRegionId(region.id), region]));
  const lines = getIslandMapConnectionEdges().map(edge => {
    const source = regionById.get(edge.source);
    const target = regionById.get(edge.target);
    if (!source || !target) return "";
    const start = getIslandMapPosition(source);
    const end = getIslandMapPosition(target);
    return `<line class="island-map-connection" x1="${formatPathNumber(start.x)}" y1="${formatPathNumber(start.y)}" x2="${formatPathNumber(end.x)}" y2="${formatPathNumber(end.y)}"></line>`;
  }).filter(Boolean).join("");
  return `<svg class="island-map-connections" viewBox="0 0 ${Math.round(layout.stageWidth)} ${Math.round(layout.stageHeight)}" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>`;
}

function renderIslandMapTile(region, activeRegionId, homeRegionId) {
  const regionId = normalizeRegionId(region.id);
  const label = region.label || regionId;
  const summaryText = getIslandTileSummaryText(regionId);
  const isActive = regionId === activeRegionId;
  const isHome = regionId === homeRegionId;
  const previewSrc = getIslandPreviewArtSrc(regionId) || getIslandMapArtSrc(regionId);
  const ariaParts = [label, getIslandTileAriaSummary(regionId)];
  if (isActive) ariaParts.push("current map");
  if (isHome) ariaParts.push("home island");
  return `
    <button
      class="island-map-icon ${isActive ? "active" : ""} ${isHome ? "home" : ""} ${escapeHtml(region.palette || "heartland")}"
      data-island-region="${escapeHtml(regionId)}"
      style="${getIslandMapIconStyle(region)}"
      type="button"
      aria-label="${escapeHtml(ariaParts.join(", "))}"
    >
      <span class="island-map-thumb" aria-hidden="true">
        <img src="${escapeHtml(previewSrc)}" alt="" draggable="false" loading="lazy" decoding="async" fetchpriority="low" />
      </span>
      <span class="island-map-name">${escapeHtml(label)}</span>
      <span class="island-map-owned">${escapeHtml(summaryText)}</span>
      ${isActive ? `<span class="island-map-active-label">Current map</span>` : ""}
      ${isHome ? `<span class="island-map-home-label">Home map</span>` : ""}
    </button>
  `;
}

function renderIslandSwitcherModalContent() {
  const activeRegionId = getActiveOnlineRegionId();
  const homeRegionId = getMainCityRegionId();
  const zoom = clampIslandMapPickerZoom(islandMapPickerViewState.zoom);
  modalBody.innerHTML = `
    <div class="island-map-shell">
      <div class="island-map-picker" style="${getIslandMapPickerStyle()}" data-island-map-zoom="${zoom}" aria-label="Island map picker">
        <div class="island-map-stage">
          <div class="island-map-canvas-frame">
            <div class="island-map-canvas">
              ${renderIslandMapConnections()}
              ${WORLD_REGIONS.map(region => renderIslandMapTile(region, activeRegionId, homeRegionId)).join("")}
            </div>
          </div>
        </div>
      </div>
    </div>
  `;
  if (!modal.open) modal.showModal();
  const picker = modalBody.querySelector(".island-map-picker");
  attachIslandMapPickerPan(picker);
  attachIslandMapPickerZoom(picker);
  setIslandMapPickerOpeningView(picker, activeRegionId || homeRegionId);
  modalBody.querySelectorAll("[data-island-region]").forEach(button => {
    button.addEventListener("click", () => {
      if (picker?.dataset.justDragged === "true" || picker?.dataset.justActivated === "true") return;
      rememberIslandMapPickerView(picker);
      switchOnlineIsland(button.dataset.islandRegion, { fromMapPicker: true });
    });
  });
}

function getIslandMapPickerElement() {
  return modalBody?.querySelector?.(".island-map-picker") || null;
}

function clampIslandMapPickerZoom(value, minimumZoom = ISLAND_PICKER_MIN_ZOOM) {
  const parsed = Number(value);
  const minimum = Math.min(
    ISLAND_PICKER_MAX_ZOOM,
    Math.max(ISLAND_PICKER_MIN_ZOOM, Number(minimumZoom) || ISLAND_PICKER_MIN_ZOOM)
  );
  return Math.min(
    ISLAND_PICKER_MAX_ZOOM,
    Math.max(minimum, Number.isFinite(parsed) ? parsed : 1)
  );
}

function getIslandMapPickerFitZoom(picker) {
  if (!picker?.clientWidth || !picker?.clientHeight) return ISLAND_PICKER_MIN_ZOOM;
  const bounds = getIslandMapContentBounds();
  const margin = getIslandMapPickerViewportMargin(picker);
  return clampIslandMapPickerZoom(Math.min(
    ISLAND_PICKER_MAX_ZOOM,
    Math.max(1, picker.clientWidth - margin * 2) / Math.max(1, bounds.width),
    Math.max(1, picker.clientHeight - margin * 2) / Math.max(1, bounds.height)
  ));
}

function getIslandMapContentBounds(regions = WORLD_REGIONS) {
  const positions = (Array.isArray(regions) ? regions : [])
    .map(region => getIslandMapPosition(region))
    .filter(position => Number.isFinite(position?.x) && Number.isFinite(position?.y));
  if (!positions.length) {
    const layout = getIslandMapGridLayout();
    return { left: 0, top: 0, right: layout.stageWidth, bottom: layout.stageHeight, width: layout.stageWidth, height: layout.stageHeight };
  }
  const left = Math.min(...positions.map(position => position.x - ISLAND_PICKER_TILE_WIDTH / 2));
  const right = Math.max(...positions.map(position => position.x + ISLAND_PICKER_TILE_WIDTH / 2));
  const top = Math.min(...positions.map(position => position.y - ISLAND_PICKER_TILE_HEIGHT / 2));
  const bottom = Math.max(...positions.map(position => position.y + ISLAND_PICKER_TILE_HEIGHT / 2));
  return { left, top, right, bottom, width: right - left, height: bottom - top };
}

function getIslandMapPickerViewportMargin(picker) {
  const shortestSide = Math.max(0, Math.min(picker?.clientWidth || 0, picker?.clientHeight || 0));
  return clamp(shortestSide * 0.045, 12, 28);
}

function getIslandMapPickerOpeningZoom(picker) {
  if (!picker?.clientWidth || !picker?.clientHeight) return getIslandMapPickerMinimumZoom(picker);
  const layout = getIslandMapGridLayout();
  const margin = getIslandMapPickerViewportMargin(picker);
  const neighborhoodWidth = ISLAND_PICKER_TILE_WIDTH + layout.stepX * 2;
  const neighborhoodHeight = ISLAND_PICKER_TILE_HEIGHT + layout.stepY * 2;
  return clampIslandMapPickerZoom(Math.min(
    ISLAND_PICKER_MAX_ZOOM,
    Math.max(1, picker.clientWidth - margin * 2) / neighborhoodWidth,
    Math.max(1, picker.clientHeight - margin * 2) / neighborhoodHeight
  ), getIslandMapPickerMinimumZoom(picker));
}

function getIslandMapPickerMinimumZoom(picker) {
  return getIslandMapPickerFitZoom(picker);
}

function getIslandMapPickerZoom(picker = getIslandMapPickerElement()) {
  return clampIslandMapPickerZoom(
    picker?.dataset?.islandMapZoom || islandMapPickerViewState.zoom,
    getIslandMapPickerMinimumZoom(picker)
  );
}

function clampIslandMapPickerCamera(camera, viewport, bounds, margin = 0) {
  const zoom = Math.max(0.001, Number(camera?.zoom) || 1);
  const viewportWidth = Math.max(0, Number(viewport?.width) || 0);
  const viewportHeight = Math.max(0, Number(viewport?.height) || 0);
  const horizontalMargin = Math.min(Math.max(0, Number(margin) || 0), viewportWidth / 2);
  const verticalMargin = Math.min(Math.max(0, Number(margin) || 0), viewportHeight / 2);
  const scaledWidth = Math.max(0, Number(bounds?.width) || 0) * zoom;
  const scaledHeight = Math.max(0, Number(bounds?.height) || 0) * zoom;
  const left = Number(bounds?.left) || 0;
  const right = Number(bounds?.right) || left;
  const top = Number(bounds?.top) || 0;
  const bottom = Number(bounds?.bottom) || top;
  const centerX = viewportWidth / 2 - (left + right) / 2 * zoom;
  const centerY = viewportHeight / 2 - (top + bottom) / 2 * zoom;
  const minimumX = horizontalMargin - right * zoom;
  const maximumX = viewportWidth - horizontalMargin - left * zoom;
  const minimumY = verticalMargin - bottom * zoom;
  const maximumY = viewportHeight - verticalMargin - top * zoom;
  return {
    x: scaledWidth <= viewportWidth - horizontalMargin * 2
      ? centerX
      : clamp(Number(camera?.x) || 0, minimumX, maximumX),
    y: scaledHeight <= viewportHeight - verticalMargin * 2
      ? centerY
      : clamp(Number(camera?.y) || 0, minimumY, maximumY),
    zoom,
  };
}

function getIslandMapPickerZoomedCamera(camera, nextZoom, anchorViewportX, anchorViewportY, targetViewportX = anchorViewportX, targetViewportY = anchorViewportY) {
  const anchor = getIslandMapPickerZoomAnchor(camera, anchorViewportX, anchorViewportY);
  return getIslandMapPickerAnchoredCamera(anchor, nextZoom, targetViewportX, targetViewportY);
}

function getIslandMapPickerZoomAnchor(camera, viewportX, viewportY) {
  const zoom = Math.max(0.001, Number(camera?.zoom) || 1);
  return {
    viewportX: Number(viewportX) || 0,
    viewportY: Number(viewportY) || 0,
    worldX: ((Number(viewportX) || 0) - (Number(camera?.x) || 0)) / zoom,
    worldY: ((Number(viewportY) || 0) - (Number(camera?.y) || 0)) / zoom,
  };
}

function getIslandMapPickerAnchoredCamera(anchor, nextZoom, targetViewportX = anchor?.viewportX, targetViewportY = anchor?.viewportY) {
  const zoom = Math.max(0.001, Number(nextZoom) || 1);
  return {
    x: (Number(targetViewportX) || 0) - (Number(anchor?.worldX) || 0) * zoom,
    y: (Number(targetViewportY) || 0) - (Number(anchor?.worldY) || 0) * zoom,
    zoom,
  };
}

function createIslandMapPickerCameraController(picker) {
  const frame = picker?.querySelector?.(".island-map-canvas-frame");
  const bounds = getIslandMapContentBounds();
  let current = { x: islandMapPickerViewState.x, y: islandMapPickerViewState.y, zoom: getIslandMapPickerZoom(picker) };
  let target = { ...current };
  let animationFrame = 0;
  let lastFrameAt = 0;
  let immediate = true;
  let zoomAnchor = null;

  const clampCamera = camera => clampIslandMapPickerCamera(
    camera,
    { width: picker?.clientWidth, height: picker?.clientHeight },
    bounds,
    getIslandMapPickerViewportMargin(picker)
  );

  const render = camera => {
    current = clampCamera(camera);
    islandMapPickerViewState.x = current.x;
    islandMapPickerViewState.y = current.y;
    islandMapPickerViewState.zoom = current.zoom;
    islandMapPickerViewState.hasView = true;
    picker.dataset.islandMapZoom = String(current.zoom);
    if (frame) frame.style.transform = `translate3d(${formatIslandCameraNumber(current.x)}px, ${formatIslandCameraNumber(current.y)}px, 0) scale(${formatIslandCameraNumber(current.zoom)})`;
  };

  const tick = timestamp => {
    animationFrame = 0;
    if (!picker?.isConnected) return;
    const elapsed = lastFrameAt ? Math.min(40, Math.max(8, timestamp - lastFrameAt)) : 16;
    lastFrameAt = timestamp;
    const easing = immediate ? 1 : 1 - Math.exp(-elapsed / ISLAND_PICKER_CAMERA_EASE_MS);
    const nextZoom = current.zoom + (target.zoom - current.zoom) * easing;
    const next = zoomAnchor
      ? getIslandMapPickerAnchoredCamera(zoomAnchor, nextZoom)
      : {
          x: current.x + (target.x - current.x) * easing,
          y: current.y + (target.y - current.y) * easing,
          zoom: nextZoom,
        };
    const finished = immediate || (zoomAnchor
      ? Math.abs(target.zoom - nextZoom) < ISLAND_PICKER_ZOOM_EPSILON
      : (Math.abs(target.x - next.x) < ISLAND_PICKER_CAMERA_EPSILON
        && Math.abs(target.y - next.y) < ISLAND_PICKER_CAMERA_EPSILON
        && Math.abs(target.zoom - next.zoom) < ISLAND_PICKER_ZOOM_EPSILON));
    render(finished ? target : next);
    if (!finished) {
      animationFrame = requestAnimationFrame(tick);
    } else {
      lastFrameAt = 0;
      zoomAnchor = null;
      picker.classList.remove("zooming");
    }
  };

  const schedule = () => {
    if (!animationFrame) animationFrame = requestAnimationFrame(tick);
  };

  const moveTo = (camera, options = {}) => {
    zoomAnchor = null;
    target = clampCamera({ ...target, ...camera });
    immediate = options.immediate === true;
    schedule();
    return { ...target };
  };

  const zoomTo = (value, focalX, focalY, options = {}) => {
    const zoom = clampIslandMapPickerZoom(value, getIslandMapPickerMinimumZoom(picker));
    zoomAnchor = getIslandMapPickerZoomAnchor(current, focalX, focalY);
    target = clampCamera(getIslandMapPickerAnchoredCamera(zoomAnchor, zoom));
    immediate = options.immediate === true;
    picker.classList.add("zooming");
    schedule();
    return { ...target };
  };

  const flush = () => {
    if (animationFrame) cancelAnimationFrame(animationFrame);
    animationFrame = 0;
    lastFrameAt = 0;
    render(target);
    zoomAnchor = null;
    picker.classList.remove("zooming");
  };

  const cancel = () => {
    if (animationFrame) cancelAnimationFrame(animationFrame);
    animationFrame = 0;
    lastFrameAt = 0;
    target = { ...current };
    zoomAnchor = null;
    picker.classList.remove("zooming");
  };

  const renderNow = camera => {
    if (animationFrame) cancelAnimationFrame(animationFrame);
    animationFrame = 0;
    lastFrameAt = 0;
    zoomAnchor = null;
    target = clampCamera({ ...current, ...camera });
    render(target);
    picker.classList.remove("zooming");
    return { ...current };
  };

  render(current);
  return {
    moveTo,
    zoomTo,
    flush,
    cancel,
    renderNow,
    getCamera: () => ({ ...current }),
    getTargetCamera: () => ({ ...target }),
  };
}

function getIslandMapPickerCameraController(picker) {
  if (!picker) return null;
  if (!picker._islandMapCameraController) picker._islandMapCameraController = createIslandMapPickerCameraController(picker);
  return picker._islandMapCameraController;
}

function attachIslandMapPickerZoom(picker) {
  if (!picker || picker.dataset.zoomReady === "true") return;
  picker.dataset.zoomReady = "true";
  const controller = getIslandMapPickerCameraController(picker);
  picker.addEventListener("wheel", event => {
    event.preventDefault();
    const target = controller.getTargetCamera();
    const boundedDelta = clamp(Number(event.deltaY) || 0, -120, 120);
    const nextZoom = target.zoom * Math.exp(-boundedDelta * 0.0016);
    const pickerBounds = picker.getBoundingClientRect();
    controller.zoomTo(
      nextZoom,
      event.clientX - pickerBounds.left - picker.clientLeft,
      event.clientY - pickerBounds.top - picker.clientTop,
      { immediate: false }
    );
  }, { passive: false });
}

function rememberIslandMapPickerView(picker = getIslandMapPickerElement()) {
  if (!picker) return false;
  const camera = getIslandMapPickerCameraController(picker)?.getCamera();
  if (camera) Object.assign(islandMapPickerViewState, camera);
  islandMapPickerViewState.hasView = true;
  return true;
}

function updateIslandMapHomeMarkerInPlace(homeRegionId = getMainCityRegionId()) {
  const picker = getIslandMapPickerElement();
  if (!picker) return false;
  const activeRegionId = getActiveOnlineRegionId();
  const nextHomeRegionId = normalizeRegionId(homeRegionId);
  picker.querySelectorAll("[data-island-region]").forEach(button => {
    const regionId = normalizeRegionId(button.dataset.islandRegion);
    const isHome = regionId === nextHomeRegionId;
    const isActive = regionId === activeRegionId;
    button.classList.toggle("home", isHome);

    let homeLabel = button.querySelector(".island-map-home-label");
    if (isHome && !homeLabel) {
      homeLabel = document.createElement("span");
      homeLabel.className = "island-map-home-label";
      homeLabel.textContent = "Home map";
      button.appendChild(homeLabel);
    } else if (!isHome && homeLabel) {
      homeLabel.remove();
    }

    const ariaParts = [getRegionLabel(regionId), getIslandTileAriaSummary(regionId)];
    if (isActive) ariaParts.push("current map");
    if (isHome) ariaParts.push("home island");
    button.setAttribute("aria-label", ariaParts.join(", "));
  });
  return true;
}

async function refreshIslandMapHomeRegionOnceForOpen() {
  if (!state || islandMapHomeRefreshInFlight) return false;
  const api = getOnlineApi();
  if (!api?.loadPlayerProfile || !api?.isSignedIn?.()) return false;
  islandMapHomeRefreshInFlight = true;
  try {
    const profile = await withTimeout(api.loadPlayerProfile(), 3500, "Player profile lookup is taking too long.");
    if (!profile || !isCurrentResetProfile(profile)) return false;
    const homeRegionId = getStoredHomeRegionId(profile, { trustLocalState: false });
    if (!homeRegionId) return false;
    const mainCityId = getKnownCityId(profile.mainCityId);
    if (!state.online) state.online = {};
    state.online.mainRegionId = homeRegionId;
    state.online.mainIslandId = getOnlineIslandId(homeRegionId);
    if (mainCityId) {
      state.online.mainCityId = mainCityId;
      state.mainCityId = mainCityId;
    }
    updateIslandMapHomeMarkerInPlace(homeRegionId);
    updateIslandSwitcherUi();
    updateMainCityReturnButton();
    return true;
  } catch (error) {
    console.warn("Could not refresh home map marker", error);
    return false;
  } finally {
    islandMapHomeRefreshInFlight = false;
  }
}

function setIslandMapPickerOpeningView(picker, regionId) {
  if (!picker) return false;
  const region = WORLD_REGIONS.find(entry => normalizeRegionId(entry.id) === normalizeRegionId(regionId)) || WORLD_REGIONS[0];
  const bounds = getIslandMapContentBounds();
  const position = region
    ? getIslandMapPosition(region)
    : { x: (bounds.left + bounds.right) / 2, y: (bounds.top + bounds.bottom) / 2 };
  const apply = () => {
    if (!picker.clientWidth || !picker.clientHeight) return false;
    const zoom = getIslandMapPickerOpeningZoom(picker);
    const controller = getIslandMapPickerCameraController(picker);
    controller.moveTo({
      x: picker.clientWidth / 2 - position.x * zoom,
      y: picker.clientHeight / 2 - position.y * zoom,
      zoom,
    }, { immediate: true });
    controller.flush();
    rememberIslandMapPickerView(picker);
    return true;
  };
  if (!apply()) requestAnimationFrame(apply);
  return true;
}

function getIslandMapPinchGeometry(pointers) {
  const points = Array.from(pointers?.values?.() || []).slice(0, 2);
  if (points.length < 2) return null;
  const [first, second] = points;
  return {
    centerX: (first.x + second.x) / 2,
    centerY: (first.y + second.y) / 2,
    distance: Math.max(1, Math.hypot(second.x - first.x, second.y - first.y)),
  };
}

function attachIslandMapPickerPan(picker) {
  if (!picker || picker.dataset.panReady === "true") return;
  picker.dataset.panReady = "true";
  const controller = getIslandMapPickerCameraController(picker);
  const touchPointers = new Map();
  let pointerId = null;
  let startX = 0;
  let startY = 0;
  let startCamera = controller.getCamera();
  let moved = false;
  let tapRegionId = "";
  let pinchGeometry = null;
  let pinchAnimationFrame = 0;
  let pickerViewportOriginX = 0;
  let pickerViewportOriginY = 0;

  const applyPendingPinch = () => {
    pinchAnimationFrame = 0;
    const nextGeometry = getIslandMapPinchGeometry(touchPointers);
    if (!pinchGeometry || !nextGeometry) return false;
    const camera = controller.getCamera();
    const nextZoom = clampIslandMapPickerZoom(
      camera.zoom * (nextGeometry.distance / pinchGeometry.distance),
      getIslandMapPickerMinimumZoom(picker)
    );
    controller.renderNow(getIslandMapPickerZoomedCamera(
      camera,
      nextZoom,
      pinchGeometry.centerX - pickerViewportOriginX,
      pinchGeometry.centerY - pickerViewportOriginY,
      nextGeometry.centerX - pickerViewportOriginX,
      nextGeometry.centerY - pickerViewportOriginY
    ));
    pinchGeometry = nextGeometry;
    return true;
  };

  const schedulePinch = () => {
    if (!pinchAnimationFrame) pinchAnimationFrame = requestAnimationFrame(applyPendingPinch);
  };

  const flushPendingPinch = () => {
    if (!pinchAnimationFrame) return false;
    cancelAnimationFrame(pinchAnimationFrame);
    pinchAnimationFrame = 0;
    return applyPendingPinch();
  };

  const beginPan = (id, x, y, regionId = "") => {
    controller.cancel();
    pointerId = id;
    startX = x;
    startY = y;
    startCamera = controller.getCamera();
    moved = false;
    tapRegionId = regionId;
    picker.classList.add("panning");
  };

  const suppressTileActivation = () => {
    picker.dataset.justDragged = "true";
    window.setTimeout(() => {
      if (picker) delete picker.dataset.justDragged;
    }, 180);
  };

  picker.addEventListener("pointerdown", event => {
    if (event.button !== undefined && event.button !== 0) return;
    const tile = event.target?.closest?.("[data-island-region]");
    picker.setPointerCapture?.(event.pointerId);
    if (event.pointerType === "touch") {
      if (touchPointers.size === 0) {
        const pickerBounds = picker.getBoundingClientRect();
        pickerViewportOriginX = pickerBounds.left + picker.clientLeft;
        pickerViewportOriginY = pickerBounds.top + picker.clientTop;
      }
      touchPointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
      if (touchPointers.size >= 2) {
        controller.flush();
        pointerId = null;
        moved = true;
        tapRegionId = "";
        pinchGeometry = getIslandMapPinchGeometry(touchPointers);
        picker.classList.add("panning", "pinching");
        event.preventDefault();
        return;
      }
    }
    if (pointerId !== null) return;
    beginPan(event.pointerId, event.clientX, event.clientY, tile?.dataset?.islandRegion || "");
  });

  picker.addEventListener("pointermove", event => {
    if (event.pointerType === "touch" && touchPointers.has(event.pointerId)) {
      touchPointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
      if (touchPointers.size >= 2) {
        schedulePinch();
        moved = true;
        tapRegionId = "";
        event.preventDefault();
        return;
      }
    }
    if (pointerId !== event.pointerId) return;
    const dx = event.clientX - startX;
    const dy = event.clientY - startY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) moved = true;
    if (moved) event.preventDefault();
    controller.moveTo({
      x: startCamera.x + dx,
      y: startCamera.y + dy,
      zoom: startCamera.zoom,
    }, { immediate: true });
  });

  const stopPan = event => {
    if (event.pointerType === "touch") flushPendingPinch();
    controller.flush();
    const wasPinching = picker.classList.contains("pinching");
    if (event.pointerType === "touch") touchPointers.delete(event.pointerId);
    picker.releasePointerCapture?.(event.pointerId);
    if (wasPinching) {
      pinchGeometry = getIslandMapPinchGeometry(touchPointers);
      if (pinchGeometry) return;
      picker.classList.remove("pinching");
      rememberIslandMapPickerView(picker);
      suppressTileActivation();
      const remaining = touchPointers.entries().next().value;
      if (remaining) {
        const [remainingPointerId, point] = remaining;
        beginPan(remainingPointerId, point.x, point.y);
        moved = true;
        return;
      }
      pointerId = null;
      picker.classList.remove("panning");
      return;
    }
    if (pointerId !== event.pointerId) return;
    pointerId = null;
    picker.classList.remove("panning");
    if (moved) {
      rememberIslandMapPickerView(picker);
      suppressTileActivation();
    } else if (tapRegionId) {
      const releasedTile = document.elementFromPoint(event.clientX, event.clientY)?.closest?.("[data-island-region]");
      if (releasedTile?.dataset?.islandRegion === tapRegionId) {
        picker.dataset.justActivated = "true";
        rememberIslandMapPickerView(picker);
        switchOnlineIsland(tapRegionId, { fromMapPicker: true });
        window.setTimeout(() => {
          if (picker) delete picker.dataset.justActivated;
        }, 180);
      }
    }
    tapRegionId = "";
  };

  picker.addEventListener("pointerup", stopPan);
  picker.addEventListener("pointercancel", stopPan);
}

function showIslandSwitcherModal() {
  if (!state) return;
  if (isMapInteractionBlocked()) {
    showToast("Finish loading the current island first.");
    return;
  }
  modal.classList.remove("battle-report-modal", "city-list-modal", "leaderboard-modal", "inventory-modal", "shop-modal", "incoming-attack-modal", "outgoing-attack-modal", "scout-report-modal", "offline-reward-modal");
  modal.classList.add("island-switcher-modal");
  modalTitle.textContent = "Map";
  renderIslandSwitcherModalContent();
  if (!modal.open) modal.showModal();
  refreshIslandMapHomeRegionOnceForOpen();
}

function prepareSelectionForIslandSwitch() {
  const source = selectedSourceId ? cityById(selectedSourceId) : null;
  if (sendMode && source?.owner === "player") {
    selectedTargetId = null;
    scoutNearbySourceId = null;
    regroupSourceId = null;
    return;
  }
  clearSelection(false);
}

function getMapTransitionDirection(fromRegionId, toRegionId, requestedSide = "", fromMapPicker = false) {
  const explicit = String(requestedSide || "").toLowerCase();
  if (["north", "south", "east", "west"].includes(explicit)) return explicit;
  const routeSide = String(getEditorPortalForRoute(fromRegionId, toRegionId)?.side || "").toLowerCase();
  if (["north", "south", "east", "west"].includes(routeSide)) return routeSide;
  if (!fromMapPicker) return "none";

  const sourceRegion = WORLD_REGIONS.find(region => normalizeRegionId(region?.id) === normalizeRegionId(fromRegionId));
  const targetRegion = WORLD_REGIONS.find(region => normalizeRegionId(region?.id) === normalizeRegionId(toRegionId));
  if (!sourceRegion || !targetRegion) return "east";
  const source = getIslandMapGridCoordinate(sourceRegion);
  const target = getIslandMapGridCoordinate(targetRegion);
  const deltaX = Number(target.gridX) - Number(source.gridX);
  const deltaY = Number(target.gridY) - Number(source.gridY);
  if (!Number.isFinite(deltaX) || !Number.isFinite(deltaY) || (deltaX === 0 && deltaY === 0)) return "east";
  if (Math.abs(deltaX) >= Math.abs(deltaY)) return deltaX >= 0 ? "east" : "west";
  return deltaY >= 0 ? "south" : "north";
}

function beginMapVisualTransition(fromRegionId, toRegionId, options = {}) {
  if (!crownlandsAnimations?.beginMapTransition || getEffectiveAnimationMode() === "off") return null;
  try {
    return crownlandsAnimations.beginMapTransition({
      id: `map-transition:${fromRegionId}:${toRegionId}:${Date.now()}`,
      root: mapFrame,
      stage: mapTransitionStage,
      scope: "map-transition",
      direction: getMapTransitionDirection(fromRegionId, toRegionId, options.transitionSide, options.fromMapPicker),
      watchdogMs: 45000,
    });
  } catch (error) {
    console.warn("Map transition effect skipped", error);
    return null;
  }
}

function finishMapVisualTransition(transition) {
  if (!transition) return false;
  try {
    return crownlandsAnimations?.finishMapTransition?.(transition.token || "") || false;
  } catch (error) {
    console.warn("Map transition settle effect skipped", error);
    return false;
  }
}

function cancelMapVisualTransition(transition, reason = "map-switch-cancelled") {
  if (!transition) return false;
  try {
    return crownlandsAnimations?.cancelMapTransition?.(reason, transition.token || "") || false;
  } catch (_error) {
    return false;
  }
}

async function switchOnlineIsland(regionId, { fromMapPicker = false, transitionSide = "" } = {}) {
  const targetRegionId = normalizeRegionId(regionId);
  if (isMapInteractionBlocked()) {
    if (fromMapPicker) showToast("Finish loading the current island first.");
    return false;
  }
  const sourceRegionId = normalizeRegionId(getActiveMapRegionId());
  if (!state) {
    const transition = sourceRegionId === targetRegionId
      ? null
      : beginMapVisualTransition(sourceRegionId, targetRegionId, { fromMapPicker, transitionSide });
    try {
      const ready = await preloadIslandMap(targetRegionId);
      if (!ready) {
        showToast(`Could not load ${getRegionLabel(targetRegionId)} map art.`);
        cancelMapVisualTransition(transition);
        return false;
      }
      centerOnRegion(targetRegionId);
      if (modal.open) modal.close();
      finishMapVisualTransition(transition);
      return true;
    } catch (error) {
      cancelMapVisualTransition(transition);
      throw error;
    }
  }
  if (targetRegionId === getActiveOnlineRegionId() && onlineWorldConnected) {
    if (modal.open) modal.close();
    syncMapSurfaceToActiveIsland();
    updateCameraTransform();
    return true;
  }

  if (!getOnlineApi()?.isSignedIn?.()) {
    const transition = beginMapVisualTransition(sourceRegionId, targetRegionId, { fromMapPicker, transitionSide });
    let transitionSettled = false;
    setMapSwitchLoading(`Loading ${getRegionLabel(targetRegionId)}...`);
    prepareSelectionForIslandSwitch();
    if (fromMapPicker && modal.open) modal.close();
    try {
      const ready = await preloadIslandMap(targetRegionId);
      if (!ready) {
        showToast(`Could not load ${getRegionLabel(targetRegionId)} map art.`);
        return false;
      }
      state.activeRegionId = targetRegionId;
      onlineActiveRegionId = targetRegionId;
      updateIslandSwitcherUi();
      if (modal.open) modal.close();
      centerOnRegion(targetRegionId);
      renderAll();
      transitionSettled = finishMapVisualTransition(transition);
      showMapLocationAnnouncement(targetRegionId);
      return true;
    } finally {
      if (!transitionSettled) cancelMapVisualTransition(transition);
      clearMapSwitchLoading();
    }
  }

  const previousRegionId = getActiveOnlineRegionId();
  const previousLabel = getRegionLabel(previousRegionId);
  const targetLabel = getRegionLabel(targetRegionId);
  const homeRegionId = state.online?.mainRegionId || previousRegionId;
  let leftPreviousIsland = false;
  const transition = beginMapVisualTransition(previousRegionId, targetRegionId, { fromMapPicker, transitionSide });
  let transitionSettled = false;
  setMapSwitchLoading(`Loading ${targetLabel}...`);
  prepareSelectionForIslandSwitch();
  if (fromMapPicker && modal.open) modal.close();
  try {
    onlineStatusDetail.textContent = `Preparing ${targetLabel}...`;
    const mapReady = await preloadIslandMap(targetRegionId);
    if (!mapReady) {
      showToast(`Could not load ${targetLabel} map art.`);
      onlineStatusDetail.textContent = `${previousLabel} connected.`;
      return false;
    }

    onlineStatusDetail.textContent = `Leaving ${previousLabel}...`;
    try {
      await withTimeout(syncOwnedCitiesToOnline(true), 4500, `${previousLabel} city save is taking too long.`);
    } catch (error) {
      onlineLastError = error?.message || String(error);
      console.warn("Continuing island switch before city sync finished", error);
    }
    queueOnlineSave();
    saveGame();
    retireActiveOnlineIslandSubscription();
    clearOnlineIslandArmySnapshots();
    leftPreviousIsland = true;
    onlinePresence = [];
    onlineCitiesLoaded = false;
    onlineWorldConnected = false;
    if (modal.open) modal.close();
    const connected = await connectOnlineIsland(targetRegionId, {
      claimHome: false,
      homeRegionId,
      activateOnFirstSnapshot: true,
      announceLocation: true,
    });
    if (connected) {
      centerOnRegion(targetRegionId);
      renderAll();
      transitionSettled = finishMapVisualTransition(transition);
      return true;
    } else {
      if (leftPreviousIsland) {
        await connectOnlineIsland(previousRegionId, {
          claimHome: false,
          homeRegionId,
        });
      }
      centerOnRegion(previousRegionId);
      renderAll();
      showToast(`Could not load ${targetLabel}.`);
      return false;
    }
  } finally {
    if (!transitionSettled) cancelMapVisualTransition(transition);
    clearMapSwitchLoading();
  }
}

function applyOnlinePresence(rawPresence) {
  if (!Array.isArray(rawPresence)) {
    onlinePresence = [];
    updateOnlinePlayersUi();
    return;
  }
  onlinePresence = rawPresence.map(normalizePresence).filter(Boolean);
  if (rememberPlayerIdentities(onlinePresence) && canonicalizeVisiblePlayerIdentities()) {
    renderCities();
    renderArmies();
    updateIncomingAttackUi();
    updateOutgoingAttackUi();
  }
  updateOnlinePlayersUi();
}

async function publishOnlinePresence(_force = false) {
  if (!isOnlineWorldActive()) return false;
  const api = getOnlineApi();
  if (!api?.savePresence) return false;
  const islandId = getActiveOnlineIslandId();
  const requestGeneration = ++onlinePresenceRequestGeneration;
  onlinePresenceInFlight = true;
  try {
    const saved = await api.savePresence(islandId, getOnlinePresenceSnapshot());
    if (requestGeneration !== onlinePresenceRequestGeneration) return Boolean(saved);
    rememberCurrentPlayerIdentity();
    onlineLastError = "";
    updateOnlinePlayersUi();
    return Boolean(saved);
  } catch (error) {
    if (requestGeneration !== onlinePresenceRequestGeneration) return false;
    onlineLastError = error?.message || String(error);
    updateOnlineUi();
    console.warn("Could not sync online presence", error);
    return false;
  } finally {
    if (requestGeneration === onlinePresenceRequestGeneration) onlinePresenceInFlight = false;
  }
}

function handleOnlineSnapshotError(error, rejectInitialCities = null) {
  onlineLastError = error?.message || String(error);
  updateOnlineUi();
  updateOnlinePlayersUi();
  if (typeof rejectInitialCities === "function") rejectInitialCities(error);
  showToast(`${getRegionLabel(getActiveOnlineRegionId())} sync error.`);
  console.warn("Active island snapshot failed", error);
}

function normalizeGameServerMembership(raw = null) {
  if (!raw || typeof raw !== "object") return null;
  const serverId = String(raw.serverId || "").trim();
  const status = String(raw.status || "").trim().toLowerCase();
  if (serverId !== GAME_SERVER_ID || !["active", "waiting", "left", "expired", "session-replaced"].includes(status)) return null;
  const rawNotice = raw.inactivityNotice && typeof raw.inactivityNotice === "object"
    ? raw.inactivityNotice
    : null;
  const noticeType = String(rawNotice?.type || "").trim();
  const inactivityNotice = ["territory-surrendered", "world-slot-reset"].includes(noticeType)
    ? {
        policyVersion: Math.max(0, Math.floor(Number(rawNotice.policyVersion) || 0)),
        type: noticeType,
        occurredAtMs: Math.max(0, Number(rawNotice.occurredAtMs) || 0),
        releasedCities: Math.max(0, Math.floor(Number(rawNotice.releasedCities) || 0)),
        releasedCamps: Math.max(0, Math.floor(Number(rawNotice.releasedCamps) || 0)),
        consolidatedTroops: Math.max(0, Math.floor(Number(rawNotice.consolidatedTroops) || 0)),
      }
    : null;
  const rawWelcomeBack = raw.welcomeBack && typeof raw.welcomeBack === "object"
    ? raw.welcomeBack
    : null;
  const welcomeBackSessionId = String(rawWelcomeBack?.sessionId || "").trim();
  const welcomeBack = welcomeBackSessionId
    ? {
        version: Math.max(0, Math.floor(Number(rawWelcomeBack.version) || 0)),
        sessionId: welcomeBackSessionId,
        sessionStartedAtMs: Math.max(0, Number(rawWelcomeBack.sessionStartedAtMs) || 0),
        awayStartedAtMs: Math.max(0, Number(rawWelcomeBack.awayStartedAtMs) || 0),
        eligible: Boolean(rawWelcomeBack.eligible && !Number(rawWelcomeBack.claimedAtMs)),
        claimedAtMs: Math.max(0, Number(rawWelcomeBack.claimedAtMs) || 0),
      }
    : null;
  return {
    serverId,
    serverName: String(raw.serverName || GAME_SERVER_NAME).trim() || GAME_SERVER_NAME,
    status,
    queuedAtMs: Math.max(0, Number(raw.queuedAtMs) || 0),
    admittedAtMs: Math.max(0, Number(raw.admittedAtMs) || 0),
    lastSeenAtMs: Math.max(0, Number(raw.lastSeenAtMs) || 0),
    updatedAtMs: Math.max(0, Number(raw.updatedAtMs) || 0),
    inactivityNotice,
    welcomeBack,
  };
}

function showGameServerInactivityNotice(notice = null) {
  if (!notice || !modal || !modalBody || !modalTitle) return false;
  modal.className = "modal offline-reward-modal";
  modalTitle.textContent = notice.type === "world-slot-reset"
    ? "Realm slot reset"
    : "Inactive holdings surrendered";
  modalBody.innerHTML = `
    <div class="offline-reward-panel">
      ${getGameServerInactivityNoticeMarkup(notice)}
      <button id="inactivityNoticeCloseBtn" class="offline-collect-btn" type="button">Continue</button>
    </div>
  `;
  modalBody.querySelector("#inactivityNoticeCloseBtn")?.addEventListener("click", () => modal.close());
  if (!modal.open) modal.showModal();
  if (pendingGameServerInactivityNotice === notice) pendingGameServerInactivityNotice = null;
  return true;
}

function getGameServerInactivityNoticeMarkup(notice = null) {
  if (!notice) return "";
  if (notice.type === "world-slot-reset") {
    return `
      <section class="offline-lost-cities">
        <span>20-day inactivity limit reached</span>
        <strong>World slot reset</strong>
        <p>Your previous home base and current-world progress were released. Your sign-in account and ruler identity remain, and this visit begins a fresh kingdom.</p>
      </section>
    `;
  }
  const holdings = notice.releasedCities + notice.releasedCamps;
  return `
    <section class="offline-lost-cities">
      <span>15-day inactivity limit reached</span>
      <strong>${formatNumber(holdings)} holdings surrendered</strong>
      <p>${formatNumber(notice.consolidatedTroops)} owned troops were secured at your protected main city. Surrendered territory is not restored.</p>
    </section>
  `;
}

function hasActiveGameServerSlot() {
  return gameServerMembership?.serverId === GAME_SERVER_ID && gameServerMembership.status === "active";
}

function isWaitingForGameServerSlot() {
  return gameServerMembership?.serverId === GAME_SERVER_ID && gameServerMembership.status === "waiting";
}

function stopGameServerHeartbeat() {
  if (gameServerHeartbeatIntervalId) window.clearInterval(gameServerHeartbeatIntervalId);
  gameServerHeartbeatIntervalId = 0;
  gameServerHeartbeatInFlight = false;
}

async function heartbeatGameServerMembership() {
  if (gameServerHeartbeatInFlight || (!hasActiveGameServerSlot() && !isWaitingForGameServerSlot())) return false;
  const api = getOnlineApi();
  if (!api?.heartbeatGameServer || !api?.isSignedIn?.()) return false;
  gameServerHeartbeatInFlight = true;
  try {
    const result = await api.heartbeatGameServer(GAME_SERVER_ID);
    applyGameServerMembership(result);
    return true;
  } catch (error) {
    console.warn("Could not refresh Crownlands realm membership", error);
    return false;
  } finally {
    gameServerHeartbeatInFlight = false;
  }
}

function startGameServerHeartbeat() {
  if (gameServerHeartbeatIntervalId) return;
  gameServerHeartbeatIntervalId = window.setInterval(
    heartbeatGameServerMembership,
    GAME_SERVER_HEARTBEAT_SECONDS * 1000
  );
  heartbeatGameServerMembership();
}

function stopGameServerMembershipWatcher({ clear = true } = {}) {
  if (typeof gameServerMembershipUnsubscribe === "function") gameServerMembershipUnsubscribe();
  gameServerMembershipUnsubscribe = null;
  stopGameServerHeartbeat();
  if (clear) gameServerMembership = null;
}

function applyGameServerMembership(raw = null) {
  const membership = normalizeGameServerMembership(raw);
  gameServerMembership = membership;
  if (membership?.status === "active" || membership?.status === "waiting") startGameServerHeartbeat();
  else stopGameServerHeartbeat();
  updateOnlineUi();

  if (
    membership?.status === "active"
    && gameServerAutoEnter
    && !gameServerLaunchInFlight
    && setupScreen?.classList.contains("visible")
  ) {
    gameServerAutoEnter = false;
    window.setTimeout(() => startFromInput(false), 0);
  }
}

function watchGameServerMembership({ preserve = false } = {}) {
  stopGameServerMembershipWatcher({ clear: !preserve });
  const api = getOnlineApi();
  if (!api?.isSignedIn?.() || !api?.subscribeGameServerMembership) {
    updateOnlineUi();
    return;
  }
  gameServerMembershipUnsubscribe = api.subscribeGameServerMembership({
    onMembership: membership => applyGameServerMembership(membership),
    onError: error => {
      console.warn("Could not watch Crownlands realm membership", error);
      markOnlineRealtimeRecoveryNeeded(error);
      onlineLastError = error?.message || String(error);
      updateOnlineUi();
    },
  });
}

async function joinSelectedGameServer() {
  if (gameServerJoinInFlight) return false;
  const api = getOnlineApi();
  if (!api?.joinGameServer || !api?.isSignedIn?.()) throw new Error("Sign in before entering a Crownlands realm.");
  gameServerJoinInFlight = true;
  try {
    const result = await api.joinGameServer(GAME_SERVER_ID);
    applyGameServerMembership(result);
    pendingGameServerInactivityNotice = gameServerMembership?.inactivityNotice || null;
    pendingWelcomeBackSession = gameServerMembership?.welcomeBack?.eligible
      ? { ...gameServerMembership.welcomeBack }
      : null;
    if (result?.status === "waiting") {
      gameServerAutoEnter = true;
      return false;
    }
    return result?.status === "active";
  } finally {
    gameServerJoinInFlight = false;
  }
}

async function leaveSelectedGameServer() {
  const api = getOnlineApi();
  const shouldLeave = hasActiveGameServerSlot() || isWaitingForGameServerSlot();
  gameServerAutoEnter = false;
  if (!shouldLeave || !api?.leaveGameServer || !api?.isSignedIn?.()) {
    stopGameServerMembershipWatcher({ clear: true });
    return false;
  }
  try {
    await api.leaveGameServer(GAME_SERVER_ID);
    return true;
  } catch (error) {
    console.warn("Could not release Crownlands realm slot", error);
    return false;
  } finally {
    stopGameServerMembershipWatcher({ clear: true });
  }
}

function updateOnlineUi() {
  const api = getOnlineApi();
  updateOnlinePlayersUi();
  updateIslandSwitcherUi();
  if (!onlineStatusText || !onlineStatusDetail) return;

  const setRealmMenuState = (visible, waiting = false) => {
    if (serverRealmList) serverRealmList.hidden = !visible;
    if (serverQueueStatus) serverQueueStatus.hidden = !visible || !waiting;
    if (serverRealmBtn) {
      serverRealmBtn.disabled = !visible || waiting || gameServerJoinInFlight || gameServerLaunchInFlight;
      serverRealmBtn.classList.toggle("selected", visible);
      serverRealmBtn.setAttribute("aria-pressed", visible ? "true" : "false");
    }
  };

  if (!api) {
    setRealmMenuState(false);
    onlineStatusText.textContent = "Online unavailable";
    onlineStatusDetail.textContent = "Firebase client did not load.";
    if (googleSignInBtn) googleSignInBtn.disabled = true;
    if (enterKingdomBtn) enterKingdomBtn.hidden = true;
    if (googleSignOutBtn) googleSignOutBtn.hidden = true;
    return;
  }

  const configured = Boolean(api.isConfigured?.());
  const signedIn = Boolean(api.isSignedIn?.());
  const user = api.getUser?.();

  if (!configured) {
    setRealmMenuState(false);
    onlineStatusText.textContent = "Firebase needed";
    onlineStatusDetail.textContent = "Paste your Firebase web config into firebase-config.js to enable Google login.";
    if (googleSignInBtn) {
      googleSignInBtn.hidden = false;
      googleSignInBtn.disabled = true;
    }
    if (enterKingdomBtn) enterKingdomBtn.hidden = true;
    if (googleSignOutBtn) googleSignOutBtn.hidden = true;
    return;
  }

  if (onlineSessionReplaced) {
    setRealmMenuState(false);
    onlineStatusText.textContent = "Signed out";
    onlineStatusDetail.textContent = "This account opened on another device.";
    if (googleSignInBtn) {
      googleSignInBtn.hidden = false;
      googleSignInBtn.disabled = signedIn;
    }
    if (enterKingdomBtn) enterKingdomBtn.hidden = true;
    if (googleSignOutBtn) googleSignOutBtn.hidden = true;
    return;
  }

  if (signedIn) {
    if (googleSignInFallbackTimer) window.clearTimeout(googleSignInFallbackTimer);
    googleSignInFallbackTimer = 0;
    googleSignInRedirectReady = false;
    const waitingForRealm = isWaitingForGameServerSlot();
    const realmIsActive = hasActiveGameServerSlot();
    setRealmMenuState(true, waitingForRealm);
    onlineStatusText.textContent = user?.displayName ? `Signed in: ${user.displayName}` : "Signed in";
    if (waitingForRealm) {
      onlineStatusDetail.textContent = `Waiting for an opening in ${GAME_SERVER_NAME}.`;
    } else if (onlineLastError) {
      onlineStatusDetail.textContent = `Online waiting: ${onlineLastError}`;
    } else if (realmIsActive) {
      onlineStatusDetail.textContent = `${GAME_SERVER_NAME} is ready. Press Enter Kingdom.`;
    } else if (usesServerEconomyAuthority() && serverEconomyLastSyncAt) {
      onlineStatusDetail.textContent = `${GAME_SERVER_NAME} is selected. Press Enter Kingdom.`;
    } else if (onlineLastSaveAt) {
      onlineStatusDetail.textContent = `${GAME_SERVER_NAME} is selected. Press Enter Kingdom.`;
    } else {
      onlineStatusDetail.textContent = `${GAME_SERVER_NAME} is selected. Press Enter Kingdom.`;
    }
    if (googleSignInBtn) {
      googleSignInBtn.hidden = true;
      googleSignInBtn.textContent = "Sign in with Google";
    }
    if (enterKingdomBtn) {
      enterKingdomBtn.hidden = waitingForRealm;
      enterKingdomBtn.disabled = waitingForRealm || gameServerJoinInFlight || gameServerLaunchInFlight;
    }
    if (googleSignOutBtn) {
      googleSignOutBtn.hidden = false;
      googleSignOutBtn.disabled = false;
    }
    return;
  }

  setRealmMenuState(false);
  onlineStatusText.textContent = "Sign in to play";
  onlineStatusDetail.textContent = "Use Google to load your kingdom.";
  if (googleSignInBtn) {
    googleSignInBtn.hidden = false;
    googleSignInBtn.disabled = false;
    googleSignInBtn.textContent = googleSignInRedirectReady
      ? "Continue sign-in in this tab"
      : "Sign in with Google";
  }
  if (enterKingdomBtn) enterKingdomBtn.hidden = true;
  if (googleSignOutBtn) googleSignOutBtn.hidden = true;
}

function clearGoogleSignInFallbackTimer() {
  if (googleSignInFallbackTimer) window.clearTimeout(googleSignInFallbackTimer);
  googleSignInFallbackTimer = 0;
}

function getGoogleSignInErrorDetail(error) {
  const code = String(error?.code || "");
  if (code === "auth/popup-closed-by-user") {
    return "The Google window was closed before sign-in finished. Try again or continue in this tab.";
  }
  if (code === "auth/popup-blocked" || code === "auth/operation-not-supported-in-this-environment") {
    return "This browser blocked the Google window. Continue sign-in in this tab.";
  }
  if (code === "auth/unauthorized-domain") {
    return "Google sign-in is not approved for this game address. Open the official Crownlands site.";
  }
  if (code === "auth/network-request-failed") {
    return "Google sign-in could not reach the network. Check your connection and try again.";
  }
  if (code === "auth/web-storage-unsupported") {
    return "This browser is blocking the storage Google needs to sign in. Allow site storage and try again.";
  }
  return "Google sign-in did not finish. Try again or continue in this tab.";
}

function armGoogleSignInRedirectFallback(api) {
  clearGoogleSignInFallbackTimer();
  googleSignInFallbackTimer = window.setTimeout(() => {
    googleSignInFallbackTimer = 0;
    if (api?.isSignedIn?.() || !googleSignInBtn || !api?.signInWithGoogleRedirect) return;
    googleSignInRedirectReady = true;
    googleSignInBtn.disabled = false;
    googleSignInBtn.textContent = "Continue sign-in in this tab";
    if (onlineStatusDetail) {
      onlineStatusDetail.textContent = "No Google window? Continue sign-in in this tab.";
    }
  }, GOOGLE_SIGN_IN_POPUP_GRACE_MS);
}

async function handleGoogleSignIn() {
  const api = getOnlineApi();
  if (!api?.signInWithGoogle) {
    showToast("Firebase login is not ready yet.");
    return;
  }

  const useRedirect = googleSignInRedirectReady && Boolean(api.signInWithGoogleRedirect);
  try {
    onlineSessionReplaced = false;
    googleSignInRedirectReady = false;
    if (googleSignInBtn) {
      googleSignInBtn.disabled = true;
      googleSignInBtn.textContent = useRedirect ? "Opening Google sign-in..." : "Waiting for Google...";
    }
    if (onlineStatusDetail) {
      onlineStatusDetail.textContent = useRedirect
        ? "Opening Google sign-in in this tab..."
        : "Complete sign-in in the Google window.";
    }
    if (useRedirect) {
      clearGoogleSignInFallbackTimer();
      await api.signInWithGoogleRedirect();
    } else {
      armGoogleSignInRedirectFallback(api);
      await api.signInWithGoogle();
    }
    clearGoogleSignInFallbackTimer();
    onlineLastError = "";
    updateOnlineUi();
    if (state) {
      queueOnlineSave();
      await flushOnlineSave(true);
    }
    showToast(`Google connected. ${GAME_SERVER_NAME} is ready to join.`);
  } catch (error) {
    clearGoogleSignInFallbackTimer();
    onlineLastError = getGoogleSignInErrorDetail(error);
    const errorCode = String(error?.code || "");
    googleSignInRedirectReady = Boolean(api.signInWithGoogleRedirect)
      && errorCode !== "auth/unauthorized-domain"
      && errorCode !== "auth/network-request-failed";
    updateOnlineUi();
    if (onlineStatusDetail) onlineStatusDetail.textContent = onlineLastError;
    showToast(onlineLastError);
    console.warn("Google sign-in failed", error);
  } finally {
    if (googleSignInBtn && !api.isSignedIn?.()) {
      googleSignInBtn.disabled = false;
      googleSignInBtn.textContent = googleSignInRedirectReady
        ? "Continue sign-in in this tab"
        : "Sign in with Google";
    }
  }
}

async function handleGoogleSignOut() {
  const api = getOnlineApi();
  if (!api?.signOut) return;
  try {
    onlineSessionReplaced = false;
    if (onlineArmySavePromises.size || onlineCityStateSavePromises.size) {
      showToast("Finishing army orders...");
      try {
        await waitForPendingOnlineWrites(5000);
      } catch (error) {
        onlineLastError = error?.message || String(error);
        console.warn("Continuing sign-out while some online writes are still pending", error);
      }
    }
    clearInstantEconomyActions();
    await flushOnlineSave(true);
    disconnectOnlineWorld();
    await leaveSelectedGameServer();
    await api.signOut();
    onlineLastSaveAt = 0;
    onlineLastError = "";
    updateOnlineUi();
    showToast("Signed out.");
  } catch (error) {
    onlineLastError = error?.message || String(error);
    updateOnlineUi();
    showToast("Could not sign out.");
  }
}

function handleOnlineSessionReplaced() {
  leaveSelectedGameServer();
  onlineSessionReplaced = true;
  clearInstantEconomyActions();
  onlineLastError = "";
  disconnectOnlineWorld();
  clearSelection(false);
  if (modal?.open) modal.close();
  closeProfileScreen();
  setSetupLoading(false);
  state = null;
  if (setupScreen) setupScreen.classList.add("visible");
  crownlandsAudio?.setMusicState("main_menu");
  updateOnlineUi();
  showToast("Signed out. This account opened on another device.");
}

function getCurrentOnlineUid() {
  return getOnlineApi()?.getUser?.()?.uid || "";
}

function isOnlineWorldActive() {
  return Boolean(state?.online?.islandId && getOnlineApi()?.isSignedIn?.());
}

function getChatController() {
  return window.CrownlandsChat?.init?.({
    onToast: message => showToast(message),
    onRealtimeError: error => markOnlineRealtimeRecoveryNeeded(error),
  }) || null;
}

function startOnlineChat() {
  const api = getOnlineApi();
  const uid = getCurrentOnlineUid();
  if (!state || !uid || !api?.isSignedIn?.() || !isOnlineWorldActive()) return false;
  getChatController()?.start({ api, uid, clanId: state.clanId || "" });
  return true;
}

function updateOnlineChatClan(clanId = "") {
  window.CrownlandsChat?.updateClan?.(String(clanId || ""));
}

function disposeOnlineChat(options = {}) {
  window.CrownlandsChat?.dispose?.(options);
}

function queueOnlineIdentityRepair() {
  const api = getOnlineApi();
  if (
    onlineIdentityRepairCompleted
    || onlineIdentityRepairInFlight
    || !state
    || !isOnlineWorldActive()
    || !api?.syncPlayerIdentity
  ) {
    return;
  }

  onlineIdentityRepairInFlight = true;
  window.setTimeout(async () => {
    try {
      const repaired = await syncPlayerIdentityToAllOwnedCities({ forceLeaderboard: true });
      onlineIdentityRepairCompleted = Boolean(repaired);
      if (!repaired) console.warn("Player identity repair did not complete; it will retry next kingdom load.");
    } catch (error) {
      onlineIdentityRepairCompleted = false;
      console.warn("Could not repair player identity across owned cities", error);
    } finally {
      onlineIdentityRepairInFlight = false;
    }
  }, 0);
}

function retireActiveOnlineIslandSubscription() {
  const unsubscribe = onlineIslandUnsubscribe;
  onlineIslandUnsubscribe = null;
  onlineIslandSubscriptionGeneration += 1;
  if (typeof unsubscribe === "function") unsubscribe();
  onlineCityVfxHydrated = false;
  onlineCampVfxHydrated = false;
  crownlandsAnimations?.cancelScope?.(`map:${getActiveMapRegionId()}`);
  return onlineIslandSubscriptionGeneration;
}

function disconnectOnlineWorld() {
  cancelLoginPresentationSequence();
  disposeOnlineChat();
  stopDailyMissionLifecycle({ clear: true });
  stopSeasonalAchievementLifecycle({ clear: true });
  retireActiveOnlineIslandSubscription();
  stopClanRealtimeSubscriptions({ clear: true });
  clearOnlineArmyWatchers();
  clearOnlineReinforcementWatcher();
  clearOnlineHeldCampWatcher();
  clearOnlineServerReportWatcher();
  clearOnlineRealmActivityWatcher();
  clearOnlineGlobalStatsWatcher();
  clearOnlineCrownCitadelWatcher();
  appliedServerReportRevisions = new Map();
  audioServerReportsHydrated = false;
  claimedBulkArrivalAudio = new Map();
  deedRewardReportsVfxHydrated = false;
  reportsViewedPendingAtMs = 0;
  lastAuthoritativeProfileRevisionMs = 0;
  lastReportDrivenEconomyRefreshAtMs = 0;
  onlinePresence = [];
  clearEnemyPowerBandCache();
  onlineCampStates = new Map();
  onlineHeldCampStates = new Map();
  resolvingRewardCampPayoutIds = new Set();
  pendingDeedCityHighlights.clear();
  crownlandsAnimations?.clearAll?.();
  deedCampHistoryCache.clear();
  deedCampHistoryRequests.clear();
  crownCitadelReignCache = [];
  crownCitadelReignRequest = null;
  strongholdLegacyCache.clear();
  strongholdLegacyRequests.clear();
  onlineGlobalStats = null;
  onlineIslandSummaries = new Map();
  onlineIslandSummaryRefreshInFlight = false;
  onlineOwnedCitiesCache = [];
  onlineOwnedCitiesCacheAt = 0;
  onlineOwnedCitiesCacheComplete = false;
  onlineOwnedCitiesRefreshInFlight = false;
  onlinePresenceTimer = 0;
  onlinePresenceRequestGeneration += 1;
  onlinePresenceInFlight = false;
  harvestRelocationRetryAtMs = 0;
  overdueArmyResolveTimer = 0;
  pendingArmyRecoveryInFlight = false;
  onlineWorldConnected = false;
  onlineCitiesLoaded = false;
  onlineFreshClaimCityId = "";
  onlineWorldLoading = false;
  updateOnlinePlayersUi();
  updateIslandSwitcherUi();
}

function withTimeout(promise, timeoutMs, message) {
  let timer = null;
  const timeout = new Promise((_, reject) => {
    timer = window.setTimeout(() => reject(new Error(message)), timeoutMs);
  });
  return Promise.race([promise, timeout]).finally(() => {
    if (timer) window.clearTimeout(timer);
  });
}

function getScriptVersionFromDocument(doc) {
  const scripts = Array.from(doc?.querySelectorAll?.("script[src]") || []);
  const gameScript = scripts.find(script => String(script.getAttribute("src") || "").includes("game.js"));
  if (!gameScript) return "";
  try {
    const url = new URL(gameScript.getAttribute("src"), window.location.href);
    return url.searchParams.get("v") || "";
  } catch (_) {
    return "";
  }
}

function getBuildIdFromDocument(doc) {
  const metaBuild = String(doc?.querySelector?.('meta[name="crownlands-build"]')?.getAttribute("content") || "").trim();
  return metaBuild || getScriptVersionFromDocument(doc);
}

function getCurrentDocumentBuildId() {
  return getBuildIdFromDocument(document) || "dev";
}

function getUpdateCheckUrl() {
  const url = new URL("/play/", window.location.origin);
  url.searchParams.set("updateCheck", Date.now().toString());
  return url;
}

function getBuildIdFromHtml(html) {
  try {
    const doc = new DOMParser().parseFromString(String(html || ""), "text/html");
    return getBuildIdFromDocument(doc);
  } catch (_) {
    return "";
  }
}

async function fetchDeployedBuildId() {
  const response = await fetch(getUpdateCheckUrl(), {
    cache: "no-store",
    credentials: "same-origin",
  });
  if (!response.ok) return "";
  return getBuildIdFromHtml(await response.text());
}

async function checkForDeployedUpdate(force = false) {
  const api = getOnlineApi();
  if (updateCheckInFlight || !api?.isSignedIn?.()) return false;
  if (!force && document.visibilityState === "hidden") return false;
  updateCheckInFlight = true;
  try {
    const deployedBuildId = await fetchDeployedBuildId();
    if (!deployedBuildId || deployedBuildId === APP_BUILD_ID) return false;
    if (deployedBuildId === deployedUpdateAvailableBuildId && deployedUpdateNoticeShown) return false;
    await handleDeployedUpdate(deployedBuildId);
    return true;
  } catch (error) {
    console.warn("Could not check for Crownlands updates", error);
    return false;
  } finally {
    updateCheckInFlight = false;
  }
}

function updateDeploymentCheck(dt) {
  updateCheckTimer += dt;
  if (updateCheckTimer < UPDATE_CHECK_INTERVAL_SECONDS) return;
  updateCheckTimer = 0;
  checkForDeployedUpdate();
}

async function handleDeployedUpdate(deployedBuildId) {
  const nextBuildId = String(deployedBuildId || "").trim();
  if (!nextBuildId || nextBuildId === APP_BUILD_ID || deployedUpdateReloadInProgress) return;
  deployedUpdateReloadInProgress = true;
  deployedUpdateAvailableBuildId = String(deployedBuildId || "");
  deployedUpdateNoticeShown = true;
  showToast("Crownlands updated. Restarting the game...");
  if (onlineStatusDetail) onlineStatusDetail.textContent = "Installing the latest Crownlands update...";
  setSetupLoading(true, "Installing the latest Crownlands update...");
  setMapSwitchLoading("Installing update...");
  console.info("[Crownlands] New deployed build available.", {
    currentBuildId: APP_BUILD_ID,
    deployedBuildId: deployedUpdateAvailableBuildId,
  });

  if (state) {
    saveGame();
    try {
      await withTimeout(
        Promise.resolve(flushOnlineSave(true)),
        UPDATE_RELOAD_SAVE_TIMEOUT_MS,
        "Timed out while saving before the update reload.",
      );
    } catch (error) {
      console.warn("[Crownlands] Continuing update reload after save timeout.", error);
    }
  }

  if ("serviceWorker" in navigator) {
    try {
      const registration = await navigator.serviceWorker.getRegistration("/");
      await registration?.update?.();
      registration?.waiting?.postMessage?.({ type: "SKIP_WAITING" });
    } catch (error) {
      console.warn("[Crownlands] Service worker update check failed before reload.", error);
    }
  }

  await new Promise(resolve => window.setTimeout(resolve, UPDATE_RELOAD_PAUSE_MS));
  const reloadUrl = new URL(window.location.href);
  reloadUrl.searchParams.set("build", nextBuildId);
  window.location.replace(reloadUrl.href);
}

function handleServiceWorkerUpdateMessage(event) {
  if (event?.data?.type === "CROWNLANDS_NOTIFICATION_CLICK") {
    const notification = event.data.notification || {};
    if (notification.type === "incoming_army" && notification.cityId) {
      if (!state) return;
      void focusIncomingAttackCity(notification.cityId, notification.targetRegionId || "");
    }
    return;
  }
  if (event?.data?.type !== "CROWNLANDS_UPDATE_READY") return;
  const buildId = String(event.data.buildId || "").trim();
  if (!buildId || buildId === APP_BUILD_ID) return;
  handleDeployedUpdate(buildId);
}

function readPendingOnlineArmyMovements() {
  try {
    const raw = localStorage.getItem(PENDING_ARMY_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter(entry => entry?.movement?.id) : [];
  } catch (error) {
    console.warn("Could not read pending army queue", error);
    return [];
  }
}

function writePendingOnlineArmyMovements(entries) {
  try {
    const cutoff = Date.now() - PENDING_ARMY_MAX_AGE_MS;
    const cleaned = (Array.isArray(entries) ? entries : [])
      .filter(entry => entry?.movement?.id && Math.max(0, Number(entry.updatedAtMs) || 0) >= cutoff)
      .slice(-40);
    if (cleaned.length) localStorage.setItem(PENDING_ARMY_STORAGE_KEY, JSON.stringify(cleaned));
    else localStorage.removeItem(PENDING_ARMY_STORAGE_KEY);
  } catch (error) {
    console.warn("Could not save pending army queue", error);
  }
}

function rememberPendingOnlineArmyMovement(movement, regionIds = []) {
  const uid = getCurrentOnlineUid();
  if (!uid || !movement?.id) return;
  const entries = readPendingOnlineArmyMovements();
  const key = `${uid}:${movement.id}`;
  const nextEntry = {
    key,
    uid,
    movement,
    regionIds: [...new Set((regionIds.length ? regionIds : movement.routeRegionIds || []).map(normalizeRegionId).filter(Boolean))],
    updatedAtMs: Date.now(),
  };
  const nextEntries = entries.filter(entry => entry.key !== key);
  nextEntries.push(nextEntry);
  writePendingOnlineArmyMovements(nextEntries);
}

function forgetPendingOnlineArmyMovement(onlineId) {
  const uid = getCurrentOnlineUid();
  if (!uid || !onlineId) return;
  const key = `${uid}:${onlineId}`;
  writePendingOnlineArmyMovements(readPendingOnlineArmyMovements().filter(entry => entry.key !== key));
}

async function saveOnlineArmyMovementToRegions(movement, regionIds = []) {
  onlineLastError = "Direct army writes are disabled. Online military movement must go through the server.";
  console.warn("Blocked direct army movement write", { movementId: movement?.id, regionIds });
  return false;
}

async function waitForPendingOnlineWrites(timeoutMs = 4500) {
  const pending = [...onlineArmySavePromises, ...onlineCityStateSavePromises];
  if (!pending.length) return true;
  await withTimeout(Promise.allSettled(pending), timeoutMs, "Online orders are still syncing.");
  return true;
}

async function recoverPendingOnlineArmyMovements() {
  if (pendingArmyRecoveryInFlight) return false;
  if (!isOnlineWorldActive()) return false;
  const uid = getCurrentOnlineUid();
  if (!uid) return false;
  writePendingOnlineArmyMovements(readPendingOnlineArmyMovements().filter(entry => entry.uid !== uid));
  return false;
}

async function subscribeOnlineIslandWithInitialCities(api, islandId, handlers = {}, timeoutMs = ONLINE_INITIAL_CITY_LIST_TIMEOUT_MS, timeoutMessage = "City list is taking too long.") {
  let unsubscribe = null;
  let settled = false;
  const initialSnapshot = new Promise((resolve, reject) => {
    unsubscribe = api.subscribeIsland(islandId, {
      ...handlers,
      onCities: cities => {
        if (typeof handlers.onCities === "function") handlers.onCities(cities);
        if (!settled) {
          settled = true;
          resolve(cities);
        }
      },
      onError: (error, source) => {
        if (typeof handlers.onError === "function") handlers.onError(error, source);
        if (source === "cities" && !settled) {
          settled = true;
          reject(error);
        }
      },
    });
    if (typeof unsubscribe !== "function" && !settled) {
      settled = true;
      reject(new Error("Island subscription could not start."));
    }
  });

  try {
    const cities = await withTimeout(initialSnapshot, timeoutMs, timeoutMessage);
    if (!Array.isArray(cities)) throw new Error("City list did not load.");
    return unsubscribe;
  } catch (error) {
    const timedOut = String(error?.message || error) === timeoutMessage;
    if (timedOut && api?.loadIslandCities) {
      console.warn("Initial live city list timed out; using one-time city load while the listener catches up.", {
        islandId,
        timeoutMs,
      });
      try {
        const fallbackMessage = timeoutMessage.replace(" is taking too long.", " backup load is taking too long.");
        const cities = await withTimeout(
          api.loadIslandCities(islandId),
          Math.max(ONLINE_INITIAL_CITY_LIST_FALLBACK_TIMEOUT_MS, timeoutMs + 12000),
          fallbackMessage
        );
        if (!Array.isArray(cities)) throw new Error("City list did not load.");
        if (!settled) {
          settled = true;
          if (typeof handlers.onCities === "function") handlers.onCities(cities);
        }
        return unsubscribe;
      } catch (fallbackError) {
        if (typeof unsubscribe === "function") unsubscribe();
        throw fallbackError;
      }
    }
    if (typeof unsubscribe === "function") unsubscribe();
    throw error;
  }
}

function markOnlineRealtimeRecoveryNeeded(error = null) {
  onlineRealtimeRecoveryNeeded = true;
  if (error) onlineLastError = error?.message || String(error);
}

function updateOnlineArmySyncBadge() {
  if (!mapFrame) return;
  let badge = mapFrame.querySelector(".army-sync-status");
  if (!badge) {
    badge = document.createElement("div");
    badge.className = "army-sync-status";
    badge.setAttribute("role", "status");
    badge.setAttribute("aria-live", "polite");
    badge.hidden = true;
    mapFrame.appendChild(badge);
  }
  const degraded = [...onlineArmySyncFailures.entries()]
    .filter(([, failures]) => Math.max(0, Number(failures) || 0) >= 2)
    .map(([source]) => source);
  badge.hidden = degraded.length === 0;
  badge.textContent = degraded.length
    ? `March sync reconnecting${degraded.length === 1 ? ` (${degraded[0]})` : ""}...`
    : "";
}

function handleOnlineArmySyncStatus(status, explicitSource = "") {
  const detail = status && typeof status === "object" ? status : { state: status };
  const source = String(explicitSource || detail.source || "armies");
  const stateLabel = String(detail.state || detail.status || "").toLowerCase();
  if (["ready", "connected", "listening", "recovered"].includes(stateLabel)) {
    onlineArmySyncFailures.delete(source);
  } else if (["retrying", "reconnecting", "error", "failed"].includes(stateLabel)) {
    const attempts = Math.max(1, Math.floor(Number(detail.attempt || detail.failures) || 1));
    onlineArmySyncFailures.set(source, Math.max(attempts, onlineArmySyncFailures.get(source) || 0));
  }
  updateOnlineArmySyncBadge();
}

function applyActiveOnlineCityPayload(onlineCities, {
  targetRegionId = getActiveOnlineRegionId(),
  activateOnFirstSnapshot = false,
  nextOnlineState = null,
  allowWelcomeBack = false,
  render = true,
} = {}) {
  const firstCitiesSnapshot = !onlineCitiesLoaded;
  if (activateOnFirstSnapshot && firstCitiesSnapshot && nextOnlineState) {
    onlineActiveRegionId = targetRegionId;
    state.activeRegionId = targetRegionId;
    state.online = { ...(state.online || {}), ...nextOnlineState };
    delete state.online.pendingIslandId;
    delete state.online.pendingRegionId;
  }
  applyOnlineCities(onlineCities, targetRegionId);
  onlineCitiesLoaded = true;
  if (firstCitiesSnapshot && getActivePeaceShieldExpiresAtMs()) refreshOwnedCityItemEffectMetadata(true);
  const economyIsStale = !serverEconomyLastSyncAt
    || Date.now() - serverEconomyLastSyncAt >= SERVER_ECONOMY_SYNC_SECONDS * 1000;
  const shouldRequestWelcomeBack = Boolean(
    firstCitiesSnapshot
    && allowWelcomeBack
    && pendingWelcomeBackSession?.eligible
  );
  if (firstCitiesSnapshot && usesServerEconomyAuthority() && (economyIsStale || shouldRequestWelcomeBack)) {
    serverEconomySyncTimer = 0;
    refreshServerEconomy(true, {
      requestWelcomeBack: shouldRequestWelcomeBack,
      showOfflineRewards: shouldRequestWelcomeBack,
      presentationGeneration: loginPresentationSequence?.generation || 0,
    });
  } else if (pendingOfflineProgressSeconds > 0) {
    applyPendingOfflineProgress();
  }
  if (state?.mainCityId && getCityRegionId(state.mainCityId) === targetRegionId && cityById(state.mainCityId)?.owner !== "player") {
    const nextOwned = playerCities()[0];
    state.mainCityId = nextOwned?.id || state.mainCityId;
  }
  if (firstCitiesSnapshot) {
    onlineCitySyncTimer = 0;
    onlinePresenceTimer = 0;
  }
  if (render) {
    if (firstCitiesSnapshot) {
      renderAll();
    } else {
      renderHud();
      renderCities();
      renderPanel();
    }
  }
  onlineFreshClaimCityId = "";
}

async function startActiveOnlineIslandSubscription(api, islandId, targetRegionId, options = {}) {
  const force = options.force === true;
  if (!force && typeof onlineIslandUnsubscribe === "function") return true;
  const subscriptionGeneration = retireActiveOnlineIslandSubscription();
  const isCurrentSubscription = () => subscriptionGeneration === onlineIslandSubscriptionGeneration;
  let unsubscribe = null;
  try {
    unsubscribe = await subscribeOnlineIslandWithInitialCities(api, islandId, {
      onCities: onlineCities => {
        if (!isCurrentSubscription()) return;
        applyActiveOnlineCityPayload(onlineCities, {
          targetRegionId,
          activateOnFirstSnapshot: options.activateOnFirstSnapshot === true,
          nextOnlineState: options.nextOnlineState || null,
          allowWelcomeBack: options.allowWelcomeBack === true,
        });
      },
      onCamps: camps => {
        if (!isCurrentSubscription()) return;
        applyOnlineCamps(camps, targetRegionId);
      },
      onArmies: armies => {
        if (!isCurrentSubscription()) return;
        applyOnlineArmies(armies, islandId);
        renderArmies();
        updateIncomingAttackUi();
        updateOutgoingAttackUi();
      },
      onPresence: presence => {
        if (!isCurrentSubscription()) return;
        applyOnlinePresence(presence);
      },
      onError: error => {
        if (!isCurrentSubscription()) return;
        markOnlineRealtimeRecoveryNeeded(error);
        handleOnlineSnapshotError(error, null);
      },
    }, options.timeoutMs || ONLINE_INITIAL_CITY_LIST_TIMEOUT_MS, options.timeoutMessage || `${getRegionLabel(targetRegionId)} city list is taking too long.`);
  } catch (error) {
    if (!isCurrentSubscription()) return false;
    throw error;
  }
  if (!isCurrentSubscription()) {
    if (typeof unsubscribe === "function") unsubscribe();
    return false;
  }
  onlineIslandUnsubscribe = unsubscribe;
  return true;
}

async function verifyRealmCompatibility(api, { force = false } = {}) {
  if (!api?.getRealmInfo) {
    throw new Error("The Crownlands server is still updating. Refresh in a moment.");
  }
  if (!force
    && verifiedRealmInfo?.releaseId === APP_RELEASE_ID
    && verifiedRealmInfo?.resetGeneration === RESET_GENERATION
    && verifiedRealmInfo?.worldId === ONLINE_WORLD_ID) {
    return verifiedRealmInfo;
  }
  const requestStartedAtMs = Date.now();
  const realm = await withTimeout(
    api.getRealmInfo(),
    10000,
    "The Crownlands server version check is taking too long."
  );
  const releaseMatches = String(realm?.releaseId || "") === APP_RELEASE_ID;
  const generationMatches = String(realm?.resetGeneration || "") === RESET_GENERATION;
  const worldMatches = String(realm?.worldId || "") === ONLINE_WORLD_ID;
  const clientManifest = window.CROWNLANDS_RELEASE_MANIFEST || {};
  const expectedContractHash = String(clientManifest.contractHash || "");
  const serverContractHash = String(realm?.contractHash || "");
  const contractMatches = Boolean(expectedContractHash)
    && Boolean(serverContractHash)
    && serverContractHash === expectedContractHash;
  if (!releaseMatches || !generationMatches || !worldMatches || !contractMatches) {
    if (!generationMatches || !worldMatches) clearInstantEconomyActions();
    throw new Error("A Crownlands update is still deploying. Refresh before entering the kingdom.");
  }
  const clientBuildId = String(clientManifest.buildId || "");
  const serverBuildId = String(realm?.serverBuildId || "");
  if (clientBuildId && serverBuildId && clientBuildId !== serverBuildId) {
    console.info("Crownlands client/server builds differ but share the same gameplay contract.", {
      clientBuildId,
      serverBuildId,
    });
  }
  const responseReceivedAtMs = Date.now();
  const serverTimeMs = Number(realm?.serverTimeMs);
  if (Number.isFinite(serverTimeMs) && serverTimeMs > 0) {
    clanQuestServerClockOffsetMs = serverTimeMs - Math.round((requestStartedAtMs + responseReceivedAtMs) / 2);
  }
  activeClanQuestPeriod = getCurrentClanQuestPeriod();
  verifiedRealmInfo = realm;
  return realm;
}

async function setupOnlineWorld({ requireOnlineProfile = false } = {}) {
  const api = getOnlineApi();
  if (!state || !api?.isConfigured?.() || !api?.isSignedIn?.()) return false;

  if (onlineWorldConnected && isOnlineWorldActive()) return true;

  onlineLastError = "";
  updateOnlineUi();
  onlineStatusDetail.textContent = "Checking the Crownlands realm...";
  await verifyRealmCompatibility(api);
  onlineStatusDetail.textContent = "Finding your home island...";
  let profile = null;
  let cloudSnapshot = null;
  const [profileResult, snapshotResult, statsResult] = await Promise.allSettled([
    api.loadPlayerProfile
      ? withTimeout(api.loadPlayerProfile(), 5000, "Player profile lookup is taking too long.")
      : Promise.resolve(null),
    api.loadGameSnapshot
      ? withTimeout(api.loadGameSnapshot(ONLINE_SAVE_SLOT), 5000, "Cloud player state lookup is taking too long.")
      : Promise.resolve(null),
    api.loadPlayerGlobalStats
      ? withTimeout(api.loadPlayerGlobalStats(), 5000, "Global stats lookup is taking too long.")
      : Promise.resolve(null),
  ]);
  const profileLoadFailed = profileResult.status === "rejected";
  if (profileResult.status === "fulfilled") profile = profileResult.value;
  else console.warn("Could not load online profile before island setup", profileResult.reason);
  const archivedProfileIdentity = profile && !isCurrentResetProfile(profile)
    ? {
        playerName: cleanName(profile.playerName || profile.displayName),
        flag: profile.flag && typeof profile.flag === "object"
          ? normalizeFlag(profile.flag)
          : null,
      }
    : null;
  if (snapshotResult.status === "fulfilled") cloudSnapshot = snapshotResult.value;
  else console.warn("Could not load cloud player state before island setup", snapshotResult.reason);
  if (profileLoadFailed && requireOnlineProfile) {
    console.warn("Continuing online setup without the player profile.");
  }
  profile = mergeOnlineProfileSources(profile, cloudSnapshot);

  const hasCurrentProfile = Boolean(profile && isCurrentResetProfile(profile));
  if (hasCurrentProfile) applyOnlineProfileSnapshot(profile, state.playerName);
  else if (archivedProfileIdentity) {
    state.playerName = archivedProfileIdentity.playerName || state.playerName;
    if (archivedProfileIdentity.flag) state.flag = archivedProfileIdentity.flag;
  }
  if (statsResult.status === "fulfilled" && statsResult.value) {
    applyGlobalStatsSnapshot(statsResult.value, { render: false });
  } else if (statsResult.status === "rejected") {
    console.warn("Could not load global kingdom stats before island setup", statsResult.reason);
  }
  if (hasCurrentProfile) await prepareOfflineProgressFromProfile(profile);
  let homeRegionId = await resolveHomeRegionIdForSetup(profile, { trustLocalState: hasCurrentProfile });
  let activeRegionId = homeRegionId;
  const mainIslandId = getOnlineIslandId(homeRegionId);
  const storedMainCityId = String(profile?.mainCityId
    || (hasCurrentProfile ? state.online?.mainCityId : "")
    || (hasCurrentProfile ? state.mainCityId : "")
    || "").trim();
  const mainCityId = getKnownCityId(storedMainCityId)
    || "";

  state.activeRegionId = activeRegionId;
  state.online = {
    worldId: ONLINE_WORLD_ID,
    islandId: getOnlineIslandId(activeRegionId),
    activeRegionId,
    mainIslandId,
    mainRegionId: homeRegionId,
    mainCityId,
    playerUid: getCurrentOnlineUid(),
  };
  state.mainCityId = mainCityId || "";
  normalizeSingleMainCityAssignment(state.mainCityId);
  let needsMainCityClaim = !storedMainCityId;

  const needsMainCityRepair = Number(profile?.mainCityAssignmentVersion || 0) < MAIN_CITY_ASSIGNMENT_VERSION;
  if (api.repairMainCityAssignment && needsMainCityRepair && (mainCityId || hasCurrentProfile)) {
    onlineStatusDetail.textContent = "Verifying your main city...";
    try {
      const repair = await withTimeout(
        api.repairMainCityAssignment({ mainCityId }),
        12000,
        "Main city repair is taking too long."
      );
      applyServerEconomyResult(repair);
      serverEconomyLastSyncAt = Date.now();
      const repairedMainCityId = getKnownCityId(repair?.currentUser?.mainCityId) || mainCityId;
      const repairedMainRegionId = normalizeRegionId(repair?.currentUser?.mainRegionId || homeRegionId);
      if (repairedMainCityId) {
        needsMainCityClaim = false;
        homeRegionId = repairedMainRegionId;
        activeRegionId = repairedMainRegionId;
        state.activeRegionId = activeRegionId;
        state.mainCityId = repairedMainCityId;
        state.online.islandId = getOnlineIslandId(activeRegionId);
        state.online.activeRegionId = activeRegionId;
        state.online.mainCityId = repairedMainCityId;
        state.online.mainRegionId = repairedMainRegionId;
        state.online.mainIslandId = repair?.currentUser?.mainIslandId || getOnlineIslandId(repairedMainRegionId);
        normalizeSingleMainCityAssignment(repairedMainCityId, { markDirty: false });
      }
    } catch (error) {
      console.warn("Could not verify main city during online setup", error);
    }
  }

  const connected = await connectOnlineIsland(activeRegionId, {
    claimHome: activeRegionId === homeRegionId && needsMainCityClaim,
    homeRegionId,
    profile,
    allowWelcomeBack: true,
  });
  if (connected) startOnlineChat();
  return connected;
}

function startOnlineSetupInBackground() {
  const api = getOnlineApi();
  if (!state || !api?.isConfigured?.() || !api?.isSignedIn?.()) return;
  if (onlineSetupBackgroundInFlight || onlineWorldConnected) return;

  onlineSetupBackgroundInFlight = true;
  onlineLastError = "";
  updateOnlineUi();
  if (onlineStatusDetail) onlineStatusDetail.textContent = "Kingdom loaded. Connecting online in the background...";
  showToast("Kingdom loaded. Connecting online...");

  setupOnlineWorld()
    .then(async connected => {
      if (!state) return;
      if (!connected) {
        state.online = null;
        onlineWorldConnected = false;
        onlineCitiesLoaded = false;
        updateOnlineUi();
        showToast("Playing locally. Online setup will retry next time.");
        return;
      }

      rememberOwnedAttackSource(state.mainCityId || playerCities()[0]?.id);
      saveGame();
      await flushOnlineSave(true);
      renderAll();
      requestAnimationFrame(() => centerOnCity(selectedSourceId || state.mainCityId || playerCities()[0]?.id));
      showToast("Online world connected.");
    })
    .catch(error => {
      onlineLastError = error?.message || String(error);
      state.online = null;
      onlineWorldConnected = false;
      onlineCitiesLoaded = false;
      updateOnlineUi();
      showToast("Playing locally. Online setup is still having trouble.");
      console.warn("Background online setup failed", error);
    })
    .finally(() => {
      onlineSetupBackgroundInFlight = false;
    });
}

async function connectOnlineIsland(regionId, {
  claimHome = false,
  homeRegionId = null,
  profile = null,
  activateOnFirstSnapshot = false,
  allowWelcomeBack = false,
  announceLocation = false,
} = {}) {
  const api = getOnlineApi();
  if (!state || !api?.isConfigured?.() || !api?.isSignedIn?.()) return false;
  if (onlineWorldLoading) return false;

  onlineLastError = "";
  updateOnlineUi();
  const targetRegionId = normalizeRegionId(regionId);
  const islandId = getOnlineIslandId(targetRegionId);
  const homeRegion = normalizeRegionId(homeRegionId || state.online?.mainRegionId || targetRegionId);
  const mainIslandId = getOnlineIslandId(homeRegion);

  onlineWorldLoading = true;
  onlineCitiesLoaded = false;
  onlineWorldConnected = false;
  const nextOnlineState = {
    ...(state.online || {}),
    worldId: ONLINE_WORLD_ID,
    islandId,
    activeRegionId: targetRegionId,
    mainIslandId,
    mainRegionId: homeRegion,
    mainCityId: getKnownCityId(state.online?.mainCityId)
      || getKnownCityId(profile?.mainCityId)
      || getKnownCityId(state.mainCityId)
      || "",
    playerUid: getCurrentOnlineUid(),
  };
  if (!activateOnFirstSnapshot) {
    onlineActiveRegionId = targetRegionId;
    state.activeRegionId = targetRegionId;
  }
  state.online = activateOnFirstSnapshot
    ? {
        ...(state.online || {}),
        worldId: ONLINE_WORLD_ID,
        islandId: state.online?.islandId || getOnlineIslandId(getActiveOnlineRegionId()),
        activeRegionId: state.online?.activeRegionId || getActiveOnlineRegionId(),
        mainIslandId,
        mainRegionId: homeRegion,
        mainCityId: nextOnlineState.mainCityId,
        playerUid: getCurrentOnlineUid(),
        pendingIslandId: islandId,
        pendingRegionId: targetRegionId,
      }
    : nextOnlineState;

  onlineStatusDetail.textContent = `Loading ${getRegionLabel(targetRegionId)}...`;
  try {
    const mapArtReadyPromise = preloadIslandMap(targetRegionId, { fetchPriority: "high" });
    const seed = createOnlineIslandSeed(targetRegionId);
    onlineStatusDetail.textContent = `Preparing ${getRegionLabel(targetRegionId)} (${seed.cities.length} city slots)...`;
    const islandSetupPromise = api.ensureMainIsland && !verifiedOnlineIslandSeeds.has(targetRegionId)
      ? withTimeout(api.ensureMainIsland({
        islandId,
        regionId: targetRegionId,
      }), claimHome ? 20000 : 10000, `${getRegionLabel(targetRegionId)} setup is taking too long.`)
        .then(result => {
          verifiedOnlineIslandSeeds.add(targetRegionId);
          return result;
        })
      : Promise.resolve(true);

    const [, mapArtReady] = await Promise.all([islandSetupPromise, mapArtReadyPromise]);
    if (!mapArtReady) {
      throw new Error(`${getRegionLabel(targetRegionId)} map art could not be verified. Retry opening the map.`);
    }

    if (claimHome) {
      onlineStatusDetail.textContent = "Claiming your starting city...";
      const isNewHomeClaim = !getKnownCityId(nextOnlineState.mainCityId);
      const claim = await withTimeout(api.claimStartingCity({
        playerName: state.playerName,
        flag: state.flag,
      }), isNewHomeClaim ? 45000 : 20000, "Starting city claim is taking too long.");

      if (!claim?.cityId) throw new Error("No starting city was claimed.");
      if (claim.currentUser) applyOnlineProfileSnapshot(claim.currentUser, state.playerName);
      const claimedRegionId = claim?.islandId ? getRegionIdFromOnlineIslandId(claim.islandId) : "";
      const redirectedRegionId = claimedRegionId && claimedRegionId !== targetRegionId ? claimedRegionId : "";
      if (redirectedRegionId && redirectedRegionId !== targetRegionId) {
        onlineStatusDetail.textContent = `Opening your ${getRegionLabel(redirectedRegionId)} main island...`;
        state.online.mainIslandId = claim.islandId;
        state.online.mainRegionId = redirectedRegionId;
        state.online.mainCityId = claim.cityId;
        state.mainCityId = claim.cityId;
        onlineWorldLoading = false;
        return connectOnlineIsland(redirectedRegionId, {
          claimHome: true,
          homeRegionId: redirectedRegionId,
          allowWelcomeBack,
          announceLocation,
          profile: {
            ...(profile || {}),
            mainIslandId: claim.islandId,
            mainRegionId: redirectedRegionId,
            mainCityId: claim.cityId,
          },
        });
      }
      state.online.mainIslandId = islandId;
      state.online.mainRegionId = targetRegionId;
      state.online.mainCityId = claim?.cityId || state.online.mainCityId || state.mainCityId;
      if (claim?.cityId) state.mainCityId = claim.cityId;
      onlineFreshClaimCityId = !claim?.alreadyClaimed && claim?.cityId ? claim.cityId : "";
      const claimedCity = claim?.cityId ? cityById(claim.cityId) : null;
      if (claimedCity) claimedCity.isMainCity = true;
      normalizeSingleMainCityAssignment(claim?.cityId || state.mainCityId, { markDirty: true });
      if (Math.max(0, Number(claim?.repairedMainCities) || 0) > 0) addLog(`${cityById(claim.cityId)?.name || "Your main city"} was restored. Main cities cannot be attacked.`);
      else if (claim?.alreadyClaimed) addLog(`Online ${getRegionLabel(targetRegionId)} connected. Your claimed city was restored.`);
      else if (claim?.cityId) addLog(`Online ${getRegionLabel(targetRegionId)} connected. ${cityById(claim.cityId)?.name || "A city"} joined your kingdom.`);
    }

    retireActiveOnlineIslandSubscription();
    clearOnlineIslandArmySnapshots();
    onlinePresence = [];
    state.attacks = state.attacks.filter(attack => String(attack?.fromId || "") && String(attack?.toId || ""));

    onlineStatusDetail.textContent = `Opening ${getRegionLabel(targetRegionId)}...`;
    const subscriptionStarted = await startActiveOnlineIslandSubscription(api, islandId, targetRegionId, {
      activateOnFirstSnapshot,
      nextOnlineState,
      allowWelcomeBack,
      timeoutMs: ONLINE_INITIAL_CITY_LIST_TIMEOUT_MS,
      timeoutMessage: `${getRegionLabel(targetRegionId)} city list is taking too long.`,
    });
    if (!subscriptionStarted) return false;

    onlineWorldConnected = true;
    onlineLastError = "";
    subscribeOnlineArmyWatchers(islandId);
    subscribeOnlineReinforcements();
    subscribeOnlineHeldCamps();
    subscribeOnlineServerReports();
    subscribeOnlineRealmActivity();
    subscribeOnlineGlobalStats();
    subscribeOnlineCrownCitadel();
    await recoverPendingOnlineArmyMovements();
    await publishOnlinePresence(true);
    queueOnlineIdentityRepair();
    refreshClanState({ silent: true, skipProfileLoad: true });
    updateOnlinePlayersUi();
    updateIslandSwitcherUi();
    const activeCount = Math.max(1, getActiveOnlinePlayers().length);
    onlineStatusDetail.textContent = `${getRegionLabel(targetRegionId)} connected. ${formatNumber(activeCount)} ruler${activeCount === 1 ? "" : "s"} online here.`;
    if (announceLocation) showMapLocationAnnouncement(targetRegionId);
    else showToast(`${getRegionLabel(targetRegionId)} connected.`);
    saveGame();
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    if (state?.online?.pendingIslandId === islandId) {
      delete state.online.pendingIslandId;
      delete state.online.pendingRegionId;
    }
    if (!activateOnFirstSnapshot && state?.online?.islandId === islandId) state.online = null;
    disconnectOnlineWorld();
    updateOnlineUi();
    showToast(`Could not connect ${getRegionLabel(targetRegionId)}.`);
    console.warn("Online island setup failed", error);
    return false;
  } finally {
    onlineWorldLoading = false;
  }
}

function getCityVfxSnapshot(city = null) {
  if (!city) return null;
  return {
    id: String(city.id || ""),
    regionId: getCityRegionId(city),
    x: Number(city.x),
    y: Number(city.y),
    level: clampCityLevel(city.level || 1),
    stage: isStronghold(city) ? 0 : getCastleStage(city.level),
    owner: city.owner || "neutral",
    ownerUid: String(city.ownerUid || ""),
    ownerFlag: city.ownerFlag ? normalizeFlag(city.ownerFlag) : null,
    lastCapturedAtMs: normalizeTimestampMs(city.lastCapturedAtMs ?? city.lastCapturedAt),
    deedAwardedAtMs: normalizeTimestampMs(city.deedAwardedAtMs),
    deedCampId: String(city.deedCampId || ""),
    neutralClaimSource: String(city.neutralClaimSource || ""),
    stronghold: isStronghold(city),
    crownCitadel: isCrownCitadel(city),
    artSrc: isStronghold(city) ? getStrongholdArtSrc(city) : getCastleAsset(getCastleStage(city.level)),
  };
}

function scheduleCityWorldAnimation(type, snapshot, options = {}) {
  if (!snapshot?.id || snapshot.regionId !== getActiveMapRegionId()) return null;
  return requestAnimationFrame(() => {
    const city = cityById(snapshot.id) || snapshot;
    const anchor = getWorldAnimationAnchor(city);
    const targetNode = cityLayer?.querySelector(`[data-city-id="${CSS.escape(snapshot.id)}"]`);
    if (!anchor || !targetNode?.isConnected) return;
    const eventId = options.id || `${type}:${snapshot.regionId}:${snapshot.id}:${Date.now()}`;
    const nowMs = Date.now();
    seenWorldAnimationEventIds.forEach((expiresAtMs, seenEventId) => {
      if (expiresAtMs <= nowMs) seenWorldAnimationEventIds.delete(seenEventId);
    });
    if (seenWorldAnimationEventIds.has(eventId)) return;
    seenWorldAnimationEventIds.set(eventId, nowMs + 30 * 60 * 1000);
    while (seenWorldAnimationEventIds.size > 512) {
      seenWorldAnimationEventIds.delete(seenWorldAnimationEventIds.keys().next().value);
    }
    emitCrownlandsAnimation(type, {
      id: eventId,
      intensity: options.intensity || "standard",
      regionId: snapshot.regionId,
      worldSpace: true,
      anchor,
      target: targetNode,
      payload: {
        cityId: snapshot.id,
        stronghold: snapshot.stronghold,
        crownCitadel: snapshot.crownCitadel,
        ...(options.payload || {}),
      },
    });
  });
}

function playCityAttackAnimation(cityOrId, { eventId = "", intensity = "standard" } = {}) {
  const city = typeof cityOrId === "string" ? cityById(cityOrId) : cityOrId;
  const snapshot = getCityVfxSnapshot(city);
  if (!snapshot) return null;
  return scheduleCityWorldAnimation("city-attack", snapshot, {
    id: eventId || `city-attack:${snapshot.regionId}:${snapshot.id}:${Date.now()}`,
    intensity,
  });
}

function playCityCaptureAnimation(before, after, { eventId = "" } = {}) {
  if (!before || !after || after.crownCitadel) return null;
  if (after.neutralClaimSource === "deed_camp") return null;
  const oldColors = getAnimationFlagColors(before.ownerFlag, before.owner);
  const newColors = getAnimationFlagColors(after.ownerFlag, after.owner);
  return window.setTimeout(() => {
    scheduleCityWorldAnimation("city-capture", after, {
      id: eventId || `city-capture:${after.regionId}:${after.id}:${after.lastCapturedAtMs}:${after.ownerUid}`,
      intensity: "major",
      payload: {
        previousOwnerUid: before.ownerUid,
        nextOwnerUid: after.ownerUid,
        oldPrimary: oldColors.primary,
        oldSecondary: oldColors.secondary,
        newPrimary: newColors.primary,
        newSecondary: newColors.secondary,
      },
    });
  }, 220);
}

function playCityUpgradeAnimation(before, after, { eventId = "" } = {}) {
  if (!before || !after || before.stronghold || after.stronghold || after.stage <= before.stage) return null;
  return scheduleCityWorldAnimation("city-upgrade", after, {
    id: eventId || `city-upgrade:${after.regionId}:${after.id}:${after.level}:${after.stage}`,
    payload: {
      previousStage: before.stage,
      nextStage: after.stage,
      previousAsset: before.artSrc,
      nextAsset: after.artSrc,
    },
  });
}

function emitOnlineCityStateAnimations(previousById, nextCities, hydrated) {
  if (!hydrated) return;
  nextCities.forEach(city => {
    const before = previousById.get(city.id);
    const after = getCityVfxSnapshot(city);
    if (!before || !after) return;
    const ownerChanged = before.ownerUid !== after.ownerUid;
    const captureAgeMs = Date.now() - after.lastCapturedAtMs;
    const freshCombatCapture = after.lastCapturedAtMs > before.lastCapturedAtMs
      && captureAgeMs >= -10000
      && captureAgeMs <= 60000
      && after.neutralClaimSource !== "deed_camp";
    if (ownerChanged && after.ownerUid && freshCombatCapture) {
      playCityCaptureAnimation(before, after);
      return;
    }
    if (after.stage > before.stage && !serverCityUpgradeInFlightIds.has(city.id)) {
      playCityUpgradeAnimation(before, after);
    }
  });
}

function applyOnlineCities(onlineCities, regionId = getActiveOnlineRegionId(), { activateRegion = true } = {}) {
  if (!state || !Array.isArray(onlineCities)) return;
  const byId = new Map(onlineCities.map(city => [city.id, city]));
  const currentUid = getCurrentOnlineUid();
  const localById = new Map(state.cities.map(city => [city.id, city]));
  const openStrongholdId = modal?.open ? String(modal.dataset.cityInfoId || "") : "";
  const previousOpenStronghold = localById.get(openStrongholdId);
  const previousStrongholdLegacySignature = previousOpenStronghold
    && isStronghold(previousOpenStronghold)
    && !isCrownCitadel(previousOpenStronghold)
      ? `${String(previousOpenStronghold.ownerUid || "")}:${normalizeTimestampMs(previousOpenStronghold.lastCapturedAtMs ?? previousOpenStronghold.lastCapturedAt)}`
      : "";
  const wasStrongholdLegacyTabOpen = Boolean(
    openStrongholdId
    && modalBody?.querySelector('[data-stronghold-info-panel="legacy"]:not([hidden])')
  );
  const previousVfxById = new Map(state.cities.map(city => [city.id, getCityVfxSnapshot(city)]));
  const activeRegionId = normalizeRegionId(regionId);
  const inactiveCities = state.cities.filter(city => getCityRegionId(city) !== activeRegionId);
  const previousKingPowerOverride = currentPlayerIdentityKingPowerOverride;
  const currentPlayerKingPower = getKingPower();
  queuePlayerIdentityLookupForRecords(onlineCities);

  currentPlayerIdentityKingPowerOverride = currentPlayerKingPower;
  try {
    const activeCities = getPlayableBaseCitiesByRegion(activeRegionId).map(base => {
    const current = localById.get(base.id) || {};
    const online = byId.get(base.id) || {};
    const onlineOwnership = getCityRecordOwnership(online, currentUid);
    const ownerUid = onlineOwnership.ownerUid;
    const ownerName = onlineOwnership.ownerName;
    const ownerFlag = onlineOwnership.ownerFlag;
    const ownerKingPower = onlineOwnership.ownerKingPower;
    const ownerShieldExpiresAtMs = onlineOwnership.ownerShieldExpiresAtMs;
    const foreignMainCityFlag = Object.prototype.hasOwnProperty.call(online, "isMainCity")
      ? Boolean(online.isMainCity)
      : Boolean(current.isMainCity);
    const localOwner = onlineOwnership.owner;
    const normalizedOwnerKind = onlineOwnership.ownerKind;
    const currentIsLocalPlayerCity = current.owner === "player" && (!current.ownerUid || current.ownerUid === currentUid);
    const onlineBelongsToAnotherPlayer = normalizedOwnerKind === "player" && ownerUid && ownerUid !== currentUid;
    const onlineBelongsToCurrentPlayer = normalizedOwnerKind === "player" && ownerUid === currentUid;
    const isFreshClaimCity = onlineFreshClaimCityId === base.id;
    const keepLocalPlayerCity = currentIsLocalPlayerCity
      && !onlineBelongsToAnotherPlayer
      && !isFreshClaimCity
      && (onlineBelongsToCurrentPlayer || localDirtyCityIds.has(base.id));
    const troopFallback = getCityTroopFallback(base, keepLocalPlayerCity
      ? { owner: "player", ownerKind: "player", ownerUid: currentUid || current.ownerUid || ownerUid || null }
      : onlineOwnership);

    return {
      ...base,
      name: getCanonicalCityName(base, keepLocalPlayerCity ? current : online),
      owner: keepLocalPlayerCity ? "player" : OWNER[localOwner] ? localOwner : "neutral",
      ownerKind: keepLocalPlayerCity ? "player" : normalizedOwnerKind,
      ownerUid: keepLocalPlayerCity ? currentUid || current.ownerUid || ownerUid || null : ownerUid,
      ownerName: keepLocalPlayerCity ? state.playerName : ownerName,
      ownerFlag: keepLocalPlayerCity ? state.flag : ownerFlag,
      ownerKingPower: keepLocalPlayerCity ? currentPlayerKingPower : ownerKingPower,
      ownerShieldExpiresAtMs: isStronghold(base) ? 0 : (keepLocalPlayerCity || localOwner === "player") ? getActivePeaceShieldExpiresAtMs() : ownerShieldExpiresAtMs,
      level: isStronghold(base) ? getStrongholdDefenseLevel(base) : clampCityLevel(keepLocalPlayerCity ? current.level ?? online.level ?? base.level : online.level ?? current.level ?? base.level),
      troops: readCityTroops(keepLocalPlayerCity ? current.troops ?? online.troops : online.troops ?? current.troops, troopFallback),
      troopFloat: readCityTroopFloat(keepLocalPlayerCity ? current.troopFloat ?? current.troops ?? online.troopFloat ?? online.troops : online.troopFloat ?? current.troopFloat ?? online.troops ?? current.troops, troopFallback),
      defense: 1,
      investedGold: isStronghold(base) ? 0 : Math.max(0, Math.floor(Number(keepLocalPlayerCity ? current.investedGold ?? online.investedGold : online.investedGold ?? current.investedGold) || 0)),
      lastCapturedAt: keepLocalPlayerCity ? current.lastCapturedAt ?? online.lastCapturedAt ?? null : online.lastCapturedAt ?? current.lastCapturedAt ?? null,
      lastCapturedAtMs: normalizeTimestampMs(keepLocalPlayerCity
        ? current.lastCapturedAtMs ?? online.lastCapturedAtMs ?? current.lastCapturedAt ?? online.lastCapturedAt
        : online.lastCapturedAtMs ?? current.lastCapturedAtMs ?? online.lastCapturedAt ?? current.lastCapturedAt),
      deedAwardedAtMs: normalizeTimestampMs(online.deedAwardedAtMs ?? current.deedAwardedAtMs),
      deedCampId: String(online.deedCampId ?? current.deedCampId ?? ""),
      neutralClaimSource: String(online.neutralClaimSource ?? current.neutralClaimSource ?? ""),
      isMainCity: !isStronghold(base) && (localOwner === "player" ? base.id === state.mainCityId : foreignMainCityFlag),
      relinquishedAtMs: keepLocalPlayerCity || normalizedOwnerKind === "player" ? 0 : timestampToMs(online.relinquishedAtMs ?? current.relinquishedAtMs),
      relocatedAtMs: keepLocalPlayerCity || normalizedOwnerKind === "player" ? 0 : timestampToMs(online.relocatedAtMs ?? current.relocatedAtMs),
      fortificationState: Object.prototype.hasOwnProperty.call(online, "fortificationState")
        ? online.fortificationState
        : current.fortificationState ?? null,
      startPool: base.startPool,
      regionId: base.regionId,
    };
    });
    state.cities = [...inactiveCities, ...activeCities];
  } finally {
    currentPlayerIdentityKingPowerOverride = previousKingPowerOverride;
  }
  if (activateRegion) {
    onlineActiveRegionId = activeRegionId;
    state.activeRegionId = activeRegionId;
    if (state.online) {
      state.online.activeRegionId = activeRegionId;
      state.online.islandId = getOnlineIslandId(activeRegionId);
    }
  }
  cacheIslandOccupancySummary(activeRegionId);
  canonicalizeVisiblePlayerIdentities();
  onlineOwnedCitiesCache = onlineOwnedCitiesCache.filter(city => getCityRegionId(city) !== activeRegionId);
  mergeOwnedCitySnapshots(playerCities()
    .filter(city => getCityRegionId(city) === activeRegionId)
    .map(city => ({
      ...city,
      islandId: getOnlineIslandId(activeRegionId),
    })));
  if (onlineCrownCitadelLoaded) {
    if (reconcileOnlineCrownCitadelSnapshot(onlineCrownCitadelSnapshot)) {
      updateOutgoingAttackUi();
    }
  }
  normalizeSingleMainCityAssignment(state.mainCityId);
  ensureLoadedMainCityForRegion(activateRegion ? activeRegionId : getActiveOnlineRegionId());
  const nextActiveCities = state.cities.filter(city => getCityRegionId(city) === activeRegionId);
  emitOnlineCityStateAnimations(previousVfxById, nextActiveCities, onlineCityVfxHydrated);
  onlineCityVfxHydrated = true;
  const nextOpenStronghold = openStrongholdId ? cityById(openStrongholdId) : null;
  const nextStrongholdLegacySignature = nextOpenStronghold
    && isStronghold(nextOpenStronghold)
    && !isCrownCitadel(nextOpenStronghold)
      ? `${String(nextOpenStronghold.ownerUid || "")}:${normalizeTimestampMs(nextOpenStronghold.lastCapturedAtMs ?? nextOpenStronghold.lastCapturedAt)}`
      : "";
  if (previousStrongholdLegacySignature
      && nextStrongholdLegacySignature
      && previousStrongholdLegacySignature !== nextStrongholdLegacySignature) {
    strongholdLegacyCache.delete(openStrongholdId);
    showCityInfoModal(openStrongholdId);
    if (wasStrongholdLegacyTabOpen) {
      modalBody?.querySelector('[data-stronghold-info-tab="legacy"]')?.click();
    }
  }
}

function normalizeOnlineCampState(raw = {}) {
  const id = String(raw.id || raw.campId || "").trim();
  if (!id) return null;
  const campType = String(raw.campType || "gold").toLowerCase();
  const base = WORLD_CAMPS_BY_ID.get(id) || {};
  const config = getRewardCampConfig({ ...raw, ...base, campType });
  if (!config) return null;
  const artSrc = String(base.artSrc || getCampConfigForType(campType).artSrc || "").trim();
  const holderUid = String(raw.holderUid || "").trim();
  const legacyNeutralCamp = !holderUid
    && Math.floor(Number(raw.combatVersion) || 0) < REWARD_CAMP_COMBAT_VERSION;
  const cleanRaw = { ...raw };
  delete cleanRaw.level;
  delete cleanRaw.defenseLevel;
  return {
    ...cleanRaw,
    id,
    campId: id,
    regionId: normalizeRegionId(raw.regionId || raw.mapId || getRegionIdFromOnlineIslandId(raw.islandId)),
    kind: config.kind,
    campType: config.type,
    rewardType: config.rewardType,
    holdDurationMs: config.holdSeconds * 1000,
    holderUid,
    holderName: String(raw.holderName || "").slice(0, 40),
    holderFlag: raw.holderFlag || null,
    heldSinceMs: normalizeTimestampMs(raw.heldSinceMs),
    payoutAtMs: normalizeTimestampMs(raw.payoutAtMs),
    payoutPending: Boolean(raw.payoutPending),
    currentGarrison: legacyNeutralCamp
      ? config.baseDefenders
      : Math.max(0, Math.floor(Number(raw.currentGarrison) || 0)),
    alliedReinforcementTroops: Math.max(0, Math.floor(Number(raw.alliedReinforcementTroops) || 0)),
    baseDefenders: config.baseDefenders,
    baseReward: config.baseReward,
    combatVersion: config.combatVersion,
    troopPower: config.troopPower,
    rewardSchedule: config.rewardSchedule,
    maxDailyRewards: config.maxDailyRewards,
    artSrc,
    size: readVisualSize(base.size, DEFAULT_CAMP_VISUAL_SIZE),
    flipX: Boolean(base.flipX),
    activeArmyIds: Array.isArray(raw.activeArmyIds) ? raw.activeArmyIds.map(String) : [],
    state: ["neutral", "held", "contested"].includes(raw.state) ? raw.state : raw.holderUid ? "held" : "neutral",
  };
}

function getCampAnimationType(camp = null) {
  const type = String(camp?.campType || camp?.rewardType || "").toLowerCase();
  if (type === "troops" || type === "warband") return "camp-warband";
  if (type === "items" || type === "item" || type === "relic") return "camp-relic";
  if (type === "deed" || type === "city") return "camp-deed";
  return "camp-gold";
}

function getCampVfxSnapshot(camp = null) {
  if (!camp) return null;
  const holderUid = String(camp.holderUid || "");
  const currentUid = getCurrentOnlineUid();
  return {
    id: String(camp.id || camp.campId || ""),
    regionId: normalizeRegionId(camp.regionId),
    x: Number(camp.x),
    y: Number(camp.y),
    campType: String(camp.campType || "gold"),
    holderUid,
    holderFlag: camp.holderFlag ? normalizeFlag(camp.holderFlag) : null,
    owner: holderUid ? holderUid === currentUid ? "player" : "enemy" : "neutral",
    heldSinceMs: normalizeTimestampMs(camp.heldSinceMs),
    payoutAtMs: normalizeTimestampMs(camp.payoutAtMs),
    state: String(camp.state || "neutral"),
  };
}

function playCampCaptureAnimation(before, after) {
  if (!after?.id || !after.holderUid || after.regionId !== getActiveMapRegionId()) return null;
  const colors = getAnimationFlagColors(after.holderFlag, after.owner);
  return requestAnimationFrame(() => {
    const camp = getCampTargetById(after.id) || after;
    emitCrownlandsAnimation(getCampAnimationType(after), {
      id: `camp-capture:${after.id}:${after.heldSinceMs}:${after.holderUid}`,
      intensity: getCampAnimationType(after) === "camp-relic" ? "major" : "standard",
      regionId: after.regionId,
      worldSpace: true,
      anchor: getWorldAnimationAnchor(camp),
      target: cityLayer?.querySelector(`[data-render-camp-id="${CSS.escape(after.id)}"]`) || null,
      payload: {
        campId: after.id,
        previousHolderUid: before?.holderUid || "",
        nextHolderUid: after.holderUid,
        primary: colors.primary,
        secondary: colors.secondary,
      },
    });
  });
}

function applyOnlineCamps(rawCamps, regionId = getActiveOnlineRegionId()) {
  const activeRegionId = normalizeRegionId(regionId);
  const previousCamps = new Map([...onlineCampStates].map(([id, camp]) => [id, getCampVfxSnapshot(getCampTargetById(id) || camp)]));
  const normalizedCamps = (Array.isArray(rawCamps) ? rawCamps : [])
    .map(normalizeOnlineCampState)
    .filter(camp => camp && camp.regionId === activeRegionId);
  onlineCampStates = new Map(normalizedCamps.map(camp => [camp.id, camp]));
  const currentUid = getCurrentOnlineUid();
  onlineHeldCampStates = new Map([...onlineHeldCampStates]
    .filter(([, camp]) => camp.regionId !== activeRegionId));
  normalizedCamps.forEach(camp => {
    if (currentUid && camp.holderUid === currentUid) onlineHeldCampStates.set(camp.id, camp);
  });
  cityRenderSignature = "";
  renderCities(true);
  if (onlineCampVfxHydrated) {
    normalizedCamps.forEach(rawCamp => {
      const after = getCampVfxSnapshot(getCampTargetById(rawCamp.id) || rawCamp);
      const before = previousCamps.get(rawCamp.id);
      if (after?.holderUid && before?.holderUid !== after.holderUid) playCampCaptureAnimation(before, after);
    });
  }
  onlineCampVfxHydrated = true;
  updateOutgoingAttackUi();
  syncWorldMusicState();
}

function applyOnlineHeldCamps(rawCamps = []) {
  const currentUid = getCurrentOnlineUid();
  onlineHeldCampStates = new Map((Array.isArray(rawCamps) ? rawCamps : [])
    .map(normalizeOnlineCampState)
    .filter(camp => camp && currentUid && camp.holderUid === currentUid)
    .map(camp => [camp.id, camp]));
  updateOutgoingAttackUi();
  syncWorldMusicState();
}

function getCampTargetById(campId) {
  const id = String(campId || "");
  const base = WORLD_CAMPS_BY_ID.get(id);
  if (!base) return null;
  const online = onlineCampStates.get(id) || onlineHeldCampStates.get(id) || {};
  const config = getRewardCampConfig({ ...online, ...base });
  if (!config) return null;
  const holderUid = String(online.holderUid || "").trim();
  const currentUid = getCurrentOnlineUid();
  const owner = holderUid ? (holderUid === currentUid ? "player" : "enemy") : "neutral";
  const onlineGarrison = Number(online.currentGarrison);
  const currentGarrison = Number.isFinite(onlineGarrison)
    ? Math.max(0, Math.floor(onlineGarrison))
    : Math.max(1, Math.floor(Number(online.baseDefenders) || config.baseDefenders));
  return {
    ...base,
    ...online,
    id,
    campId: id,
    name: config.name,
    kind: config.kind,
    targetType: "camp",
    campType: config.type,
    rewardType: config.rewardType,
    holdDurationMs: config.holdSeconds * 1000,
    rewardSchedule: config.rewardSchedule,
    maxDailyRewards: config.maxDailyRewards,
    owner,
    ownerKind: holderUid ? "player" : "neutral",
    ownerUid: holderUid || null,
    ownerName: online.holderName || (holderUid ? "Rival ruler" : "Neutral defenders"),
    ownerFlag: online.holderFlag || null,
    troops: currentGarrison,
    troopFloat: currentGarrison,
    currentGarrison,
    alliedReinforcementTroops: Math.max(0, Math.floor(Number(online.alliedReinforcementTroops) || 0)),
    baseDefenders: config.baseDefenders,
    combatVersion: config.combatVersion,
    troopPower: config.troopPower,
    baseReward: config.baseReward,
    size: readVisualSize(base.size, DEFAULT_CAMP_VISUAL_SIZE),
    flipX: Boolean(base.flipX),
    payoutAtMs: normalizeTimestampMs(online.payoutAtMs),
    heldSinceMs: normalizeTimestampMs(online.heldSinceMs),
    payoutPending: Boolean(online.payoutPending),
    state: online.state || (holderUid ? "held" : "neutral"),
    isMainCity: false,
    ownerShieldExpiresAtMs: 0,
  };
}

function getArmyTargetById(targetId) {
  return cityById(targetId) || getCampTargetById(targetId);
}

function isRewardCampTarget(target) {
  return Boolean(target && getRewardCampConfig(target));
}

function adoptServerArmyMovement(rawMovement) {
  const movement = normalizeOnlineArmyMovement(rawMovement);
  if (!movement) return null;
  const current = onlineArmiesByIsland.get(PLAYER_RELEVANT_ARMIES_CACHE_KEY) || [];
  onlineArmiesByIsland.set(PLAYER_RELEVANT_ARMIES_CACHE_KEY, [
    ...current.filter(army => getOnlineArmyResolutionId(army) !== movement.id),
    movement,
  ]);
  rebuildOnlineArmies();
  adoptOwnOnlineArmies();
  renderPaths();
  renderArmies(true);
  updateOutgoingAttackUi();
  return movement;
}

function registerDeedRewardAnimationEvent(eventId) {
  const normalizedEventId = String(eventId || "");
  if (!normalizedEventId) return false;
  const nowMs = Date.now();
  seenDeedRewardEventIds.forEach((expiresAtMs, seenEventId) => {
    if (expiresAtMs <= nowMs) seenDeedRewardEventIds.delete(seenEventId);
  });
  if (seenDeedRewardEventIds.has(normalizedEventId)) return false;
  seenDeedRewardEventIds.set(normalizedEventId, nowMs + 24 * 60 * 60 * 1000);
  while (seenDeedRewardEventIds.size > 256) {
    seenDeedRewardEventIds.delete(seenDeedRewardEventIds.keys().next().value);
  }
  return true;
}

function emitCompletedDeedCityHighlight(eventId, city, node) {
  if (!city || !node?.isConnected) return false;
  const anchor = getWorldAnimationAnchor(city);
  emitCrownlandsAnimation("deed-completed", {
    id: `${eventId}:city-highlight`,
    intensity: "major",
    regionId: getActiveMapRegionId(),
    worldSpace: true,
    anchor,
    targetAnchor: anchor,
    target: node,
    payload: { cityHighlightOnly: true, awardedCityId: String(city.id || "") },
  });
  return true;
}

function playCompletedDeedRewardAnimation(result, campBefore = null, sourceAnchor = null) {
  const awarded = result?.awardedCity;
  if (!awarded?.id || result?.status !== "paid") return false;
  const eventId = String(result.rewardEventId || `deed:${campBefore?.id || result.rewardSourceId || "camp"}:${awarded.regionId}:${awarded.id}:${result.rewardHistoryEntry?.awardedAtMs || Date.now()}`);
  if (!registerDeedRewardAnimationEvent(eventId)) return false;
  const targetRegionId = normalizeRegionId(awarded.regionId);
  const targetCity = cityById(awarded.id);
  const targetNode = targetCity && getCityRegionId(targetCity) === getActiveMapRegionId()
    ? cityLayer?.querySelector(`[data-city-id="${CSS.escape(String(awarded.id))}"]`)
    : null;
  const campAnchor = campBefore && normalizeRegionId(campBefore.regionId) === getActiveMapRegionId()
    ? getWorldAnimationAnchor(campBefore)
    : null;
  if (campAnchor || sourceAnchor) {
    emitCrownlandsAnimation("deed-completed", {
      id: eventId,
      intensity: "major",
      regionId: getActiveMapRegionId(),
      worldSpace: Boolean(campAnchor),
      anchor: campAnchor,
      source: sourceAnchor,
      payload: {
        sourceOnly: true,
        awardedCityId: String(awarded.id),
        awardedCityName: String(awarded.name || "Awarded city"),
        awardedRegionId: targetRegionId,
      },
    });
  }
  if (targetCity && targetNode) {
    emitCompletedDeedCityHighlight(eventId, targetCity, targetNode);
  } else {
    pendingDeedCityHighlights.set(eventId, {
      eventId,
      cityId: String(awarded.id),
      regionId: targetRegionId,
      cityName: String(awarded.name || "Awarded city"),
      expiresAtMs: Date.now() + 24 * 60 * 60 * 1000,
    });
    while (pendingDeedCityHighlights.size > 20) {
      pendingDeedCityHighlights.delete(pendingDeedCityHighlights.keys().next().value);
    }
  }
  return true;
}

function flushPendingDeedCityHighlights() {
  const activeRegionId = getActiveMapRegionId();
  pendingDeedCityHighlights.forEach((pending, eventId) => {
    if (pending.expiresAtMs <= Date.now()) {
      pendingDeedCityHighlights.delete(eventId);
      return;
    }
    if (pending.regionId !== activeRegionId) return;
    const city = cityById(pending.cityId);
    const node = city && cityLayer?.querySelector(`[data-city-id="${CSS.escape(pending.cityId)}"]`);
    if (!city || !node) return;
    pendingDeedCityHighlights.delete(eventId);
    emitCompletedDeedCityHighlight(eventId, city, node);
  });
}

async function requestDueRewardCampPayout(camp) {
  if (!camp?.id || camp.owner !== "player" || !camp.payoutPending || camp.payoutAtMs > Date.now()) return false;
  if (resolvingRewardCampPayoutIds.has(camp.id)) return false;
  const api = getOnlineApi();
  const resolvePayout = api?.resolveRewardCampPayout || api?.resolveGoldCampPayout;
  if (!resolvePayout) return false;
  resolvingRewardCampPayoutIds.add(camp.id);
  const campNode = cityLayer?.querySelector(`[data-camp-id="${CSS.escape(String(camp.id))}"]`);
  const rewardSourceAnchor = captureAnimationAnchor(campNode);
  const campBefore = { ...camp };
  try {
    const result = await resolvePayout({ campId: camp.id, regionId: camp.regionId });
    applyServerArmyResult(result);
    if (result?.movement) adoptServerArmyMovement(result.movement);
    const config = getRewardCampConfig(result?.campType || camp);
    if (["paid", "no-eligible-city", "daily-limit"].includes(result?.status)) {
      playGameSound("timer_tick_complete", { regionId: camp.regionId });
      if (result?.status === "paid") {
        playRewardSoundAfter(
          config?.type || result?.rewardType || config?.rewardType,
          REWARD_FOLLOWUP_AUDIO_DELAY_MS,
          { regionId: camp.regionId }
        );
        if (config?.type === "gold" && Number(result.reward) > 0) {
          playRewardAnimation("gold", {
            id: `camp-gold:${camp.id}:${camp.payoutAtMs}`,
            sourceAnchor: rewardSourceAnchor,
            tier: "medium",
          });
        } else if (config?.type === "troops" && Number(result.rewardedTroops || result.reward) > 0) {
          playRewardAnimation("troops", {
            id: `camp-troops:${camp.id}:${camp.payoutAtMs}`,
            sourceAnchor: rewardSourceAnchor,
            tier: "medium",
            destinationCityId: String(
              result.cityUpdates?.find(update => update?.id)?.id
              || state?.mainCityId
              || result.returnDestinationId
              || ""
            ),
          });
        } else if (config?.type === "deed") {
          playCompletedDeedRewardAnimation(result, campBefore, rewardSourceAnchor);
        }
      }
      if (config?.type === "deed") {
        deedCampHistoryCache.delete(getDeedCampHistoryCacheKey(camp));
      } else if (config && result.holderUid === getCurrentOnlineUid()) {
         const progress = cacheRewardCampProgress(config, {
           date: currentUtcDateKey(),
           count: result.dailyClaim,
           lastReward: result.reward,
           lastCampId: camp.id,
           lastClaimedAtMs: Date.now(),
           rewards: result.rewardsToday,
           maxDailyRewards: result.maxDailyRewards,
         });
        renderRewardCampProgressPanel(camp.id, config, progress);
      }
      const rewardMessage = config?.type === "deed"
        ? result.status === "daily-limit"
          ? "You already received a Deed Camp city today. The camp reset to neutral."
          : result.awardedCity
          ? `${config.name} reward: ${result.awardedCity.name} in ${result.awardedCity.regionName} is now yours.`
          : "No eligible neutral city was available. The Deed Camp reset to neutral."
        : config?.type === "items"
          ? result.status === "daily-limit"
            ? "Daily Relic Camp reward limit reached. The camp reset to neutral."
            : result.rewardItem
              ? `Relic Camp reward: ${result.rewardItem.itemName} (${result.rewardItem.rarity}) was added to your bag.`
              : "Relic Camp completed without an item reward."
        : result.reward > 0
          ? `${config?.name || camp.name} reward: +${formatNumber(result.reward)} ${result.rewardType || config?.rewardLabel || "reward"}`
          : `${config?.name || camp.name} daily reward limit reached.`;
      const returnMessage = result.returningTroops > 0
        ? ` ${formatNumber(result.returningTroops)} stationed troops are marching home.`
        : "";
      showToast(`${rewardMessage}${returnMessage}`);
    }
    return ["paid", "no-eligible-city", "daily-limit"].includes(result?.status);
  } catch (error) {
    console.warn("Could not resolve reward camp payout", error);
    return false;
  } finally {
    resolvingRewardCampPayoutIds.delete(camp.id);
  }
}

function ensureLoadedMainCityForRegion(regionId) {
  if (!state) return;
  const activeRegionId = normalizeRegionId(regionId);
  const homeRegionId = normalizeRegionId(state.online?.mainRegionId || (state.mainCityId ? getCityRegionId(state.mainCityId) : activeRegionId));
  if (activeRegionId !== homeRegionId) return;

  const currentMain = state.mainCityId ? cityById(state.mainCityId) : null;
  if (currentMain && !isStronghold(currentMain)) {
    restoreMainCityOwnership(currentMain);
    currentMain.isMainCity = true;
    if (state.online) {
      state.online.mainCityId = currentMain.id;
      state.online.mainRegionId = activeRegionId;
      state.online.mainIslandId = getOnlineIslandId(activeRegionId);
    }
    normalizeSingleMainCityAssignment(currentMain.id);
    return;
  }

  const fallbackMain = playerCities().find(city => city.isMainCity && !isStronghold(city))
    || playerCities().find(city => !isStronghold(city));
  if (!fallbackMain) return;
  state.mainCityId = fallbackMain.id;
  fallbackMain.isMainCity = true;
  if (state.online) {
    state.online.mainCityId = fallbackMain.id;
    state.online.mainRegionId = activeRegionId;
    state.online.mainIslandId = getOnlineIslandId(activeRegionId);
  }
  normalizeSingleMainCityAssignment(fallbackMain.id);
}

function restoreMainCityOwnership(city) {
  if (!state || !city || isStronghold(city)) return false;
  const uid = getCurrentOnlineUid();
  const foreignOwner = city.owner !== "player" || (uid && city.ownerUid && city.ownerUid !== uid);
  const needsRestore = foreignOwner || city.ownerKind !== "player" || city.ownerUid !== (uid || city.ownerUid || null);
  city.owner = "player";
  city.ownerKind = "player";
  city.ownerUid = uid || city.ownerUid || null;
  city.ownerName = state.playerName;
  city.ownerFlag = state.flag;
  city.ownerKingPower = getKingPower();
  city.ownerShieldExpiresAtMs = getActivePeaceShieldExpiresAtMs();
  city.isMainCity = true;
  if (foreignOwner) {
    city.troopFloat = 0;
    city.troops = 0;
  }
  if (needsRestore && isOnlineWorldActive()) {
    markOwnedCityChanged(city, false);
    syncCityStateToOnline(city);
    syncOwnedCitiesToOnline(true);
  }
  return needsRestore;
}

function getCityRecordOwnership(record = {}, currentUid = getCurrentOnlineUid(), { allowLocalPlayerFallback = false } = {}) {
  const rawOwnerKind = record.ownerKind || (record.owner === "player" || record.owner === "enemy" ? "player" : record.owner || "neutral");
  const ownerUid = String(record.ownerUid || "").trim();
  const hasPlayerOwner = Boolean(ownerUid) && (rawOwnerKind === "player" || record.owner === "player" || record.owner === "enemy");
  if (hasPlayerOwner) {
    const identity = resolvePlayerIdentityForUid(ownerUid, record);
    return {
      owner: ownerUid === currentUid ? "player" : "enemy",
      ownerKind: "player",
      ownerUid,
      ownerName: identity.displayName || record.ownerName || "",
      ownerFlag: identity.flag || record.ownerFlag || null,
      ownerKingPower: normalizePowerValue(identity.kingPower) || normalizePowerValue(record.ownerKingPower),
      ownerShieldExpiresAtMs: normalizeTimestampMs(record.ownerShieldExpiresAtMs),
      hasPlayerOwner: true,
    };
  }

  if (allowLocalPlayerFallback && record.owner === "player" && (!record.ownerUid || record.ownerUid === currentUid)) {
    const fallbackUid = currentUid || record.ownerUid || null;
    const identity = resolvePlayerIdentityForUid(fallbackUid, record);
    return {
      owner: "player",
      ownerKind: "player",
      ownerUid: fallbackUid,
      ownerName: identity.displayName || record.ownerName || state?.playerName || "",
      ownerFlag: identity.flag || record.ownerFlag || state?.flag || null,
      ownerKingPower: normalizePowerValue(identity.kingPower) || normalizePowerValue(record.ownerKingPower) || getKingPower(),
      ownerShieldExpiresAtMs: getActivePeaceShieldExpiresAtMs(),
      hasPlayerOwner: Boolean(fallbackUid),
    };
  }

  return {
    owner: "neutral",
    ownerKind: "neutral",
    ownerUid: null,
    ownerName: "",
    ownerFlag: null,
    ownerKingPower: 0,
    ownerShieldExpiresAtMs: 0,
    hasPlayerOwner: false,
  };
}

function markOwnedCityChanged(city, syncNow = true) {
  if (!state || !city || city.owner !== "player") return;
  localDirtyCityIds.add(city.id);
  city.ownerKind = "player";
  city.ownerUid = getCurrentOnlineUid() || city.ownerUid || null;
  city.ownerName = state.playerName;
  city.ownerFlag = state.flag;
  city.ownerKingPower = getKingPower();
  city.ownerShieldExpiresAtMs = isStronghold(city) ? 0 : getActivePeaceShieldExpiresAtMs();
  city.isMainCity = !isStronghold(city) && city.id === state.mainCityId;
  city.relinquishedAtMs = 0;
  city.relocatedAtMs = 0;
  if (syncNow && isOnlineWorldActive()) syncOwnedCitiesToOnline(true);
}

function toOnlineOwnedCity(city) {
  return {
    id: city.id,
    name: getCanonicalCityName(city),
    x: city.x,
    y: city.y,
    startPool: city.startPool || "",
    regionId: city.regionId || city.startPool || getCityRegionId(city),
    kind: city.kind || "",
    strongholdType: city.strongholdType || "",
    bonus: city.bonus || "",
    bonusPercent: Number(city.bonusPercent) || 0,
    size: isStronghold(city) ? getStrongholdVisualSize(city) : undefined,
    artSrc: isStronghold(city) ? getStrongholdArtSrc(city) : "",
    startTroops: isStronghold(city) ? getStrongholdStartTroops(city) : 0,
    ownerKind: "player",
    ownerUid: getCurrentOnlineUid(),
    ownerName: state.playerName,
    ownerFlag: state.flag,
    ownerKingPower: getKingPower(),
    ownerShieldExpiresAtMs: isStronghold(city) ? 0 : getActivePeaceShieldExpiresAtMs(),
    level: isStronghold(city) ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level),
    troops: Math.max(0, Math.floor(Number(city.troops) || 0)),
    troopFloat: Math.max(0, Number(city.troopFloat) || Number(city.troops) || 0),
    defense: 1,
    investedGold: isStronghold(city) ? 0 : Math.max(0, Math.floor(Number(city.investedGold) || 0)),
    lastCapturedAt: city.lastCapturedAt ?? null,
    isMainCity: !isStronghold(city) && (city.owner === "player" ? city.id === state.mainCityId : Boolean(city.isMainCity)),
    relinquishedAtMs: 0,
    relocatedAtMs: 0,
  };
}

function toOnlineCityState(city) {
  const currentUid = getCurrentOnlineUid();
  const ownerUid = city.owner === "player"
    ? currentUid || city.ownerUid || null
    : city.ownerUid || null;
  const hasPlayerOwner = Boolean(ownerUid) && (city.owner === "player" || city.owner === "enemy" || city.ownerKind === "player");
  const ownerKind = hasPlayerOwner ? "player" : "neutral";
  const ownerIdentity = hasPlayerOwner ? resolvePlayerIdentityForUid(ownerUid, city) : null;
  const ownerName = hasPlayerOwner
    ? city.owner === "player" ? state.playerName : ownerIdentity?.displayName || city.ownerName || ""
    : "";
  const ownerFlag = hasPlayerOwner
    ? city.owner === "player" ? state.flag : ownerIdentity?.flag || city.ownerFlag || null
    : null;
  const ownerKingPower = hasPlayerOwner
    ? city.owner === "player" ? getKingPower() : normalizePowerValue(ownerIdentity?.kingPower) || normalizePowerValue(city.ownerKingPower)
    : 0;
  const ownerShieldExpiresAtMs = hasPlayerOwner
    ? isStronghold(city) ? 0 : city.owner === "player" ? getActivePeaceShieldExpiresAtMs() : normalizeTimestampMs(city.ownerShieldExpiresAtMs)
    : 0;
  const relinquishedAtMs = hasPlayerOwner || isStronghold(city) ? 0 : timestampToMs(city.relinquishedAtMs);
  const relocatedAtMs = hasPlayerOwner || isStronghold(city) ? 0 : timestampToMs(city.relocatedAtMs);
  return {
    id: city.id,
    name: getCanonicalCityName(city),
    x: city.x,
    y: city.y,
    startPool: city.startPool || "",
    regionId: city.regionId || city.startPool || getCityRegionId(city),
    kind: city.kind || "",
    strongholdType: city.strongholdType || "",
    bonus: city.bonus || "",
    bonusPercent: Number(city.bonusPercent) || 0,
    size: isStronghold(city) ? getStrongholdVisualSize(city) : undefined,
    artSrc: isStronghold(city) ? getStrongholdArtSrc(city) : "",
    startTroops: isStronghold(city) ? getStrongholdStartTroops(city) : 0,
    ownerKind,
    ownerUid: hasPlayerOwner ? ownerUid : null,
    ownerName,
    ownerFlag,
    ownerKingPower,
    ownerShieldExpiresAtMs,
    level: isStronghold(city) ? getStrongholdDefenseLevel(city) : clampCityLevel(city.level),
    troops: Math.max(0, Math.floor(Number(city.troops) || 0)),
    troopFloat: Math.max(0, Number(city.troopFloat) || Number(city.troops) || 0),
    defense: 1,
    investedGold: isStronghold(city) ? 0 : Math.max(0, Math.floor(Number(city.investedGold) || 0)),
    lastCapturedAt: city.lastCapturedAt ?? null,
    isMainCity: !isStronghold(city) && (city.owner === "player" ? city.id === state.mainCityId : Boolean(city.isMainCity)),
    relinquishedAtMs,
    relocatedAtMs,
  };
}

function syncSharedCityState(city) {
  if (!city || !isOnlineWorldActive()) return;
  if (usesServerEconomyAuthority() && (city.owner === "player" || city.ownerUid === getCurrentOnlineUid())) return;
  const api = getOnlineApi();
  if (!api?.saveCityState) return;
  const cityId = city.id;
  const ownedAtSave = city.owner === "player";
  const savePromise = api.saveCityState(getOnlineIslandId(getCityRegionId(city)), toOnlineCityState(city))
    .then(() => {
      if (ownedAtSave) localDirtyCityIds.delete(cityId);
    })
    .catch(error => {
      onlineLastError = error?.message || String(error);
      console.warn("Could not sync city battle state", error);
    })
    .finally(() => {
      onlineCityStateSavePromises.delete(savePromise);
    });
  onlineCityStateSavePromises.add(savePromise);
  return savePromise;
}

function syncCityStateToOnline(city) {
  if (!city || !isOnlineWorldActive()) return;
  syncSharedCityState(city);
}

async function syncOwnedCitiesToOnline(force = false) {
  if (!isOnlineWorldActive()) return false;
  if (usesServerEconomyAuthority()) return false;
  if (!onlineCitiesLoaded) {
    if (force) onlineCitySyncQueued = true;
    return false;
  }
  if (onlineCitySyncInFlight) {
    if (force) onlineCitySyncQueued = true;
    return false;
  }
  const api = getOnlineApi();
  if (!api?.savePlayerCities) return false;
  const currentUid = getCurrentOnlineUid();
  const activeRegionId = getActiveOnlineRegionId();
  const dirtyCityIds = new Set(localDirtyCityIds);
  if (!dirtyCityIds.size) return false;
  const cities = playerCities()
    .filter(city => !city.ownerUid || city.ownerUid === currentUid)
    .filter(city => getCityRegionId(city) === activeRegionId)
    .filter(city => dirtyCityIds.has(city.id))
    .map(toOnlineOwnedCity);
  if (!cities.length) return false;

  onlineCitySyncInFlight = true;
  try {
    await api.savePlayerCities(getActiveOnlineIslandId(), cities);
    cities.forEach(city => localDirtyCityIds.delete(city.id));
    mergeOwnedCitySnapshots(cities.map(city => ({
      ...city,
      islandId: getActiveOnlineIslandId(),
    })), { complete: false });
    return true;
  } catch (error) {
    onlineLastError = error?.message || String(error);
    console.warn("Could not sync owned cities", error);
    return false;
  } finally {
    onlineCitySyncInFlight = false;
    if (onlineCitySyncQueued) {
      onlineCitySyncQueued = false;
      syncOwnedCitiesToOnline(true);
    }
  }
}

function normalizeArmyPath(points) {
  if (!Array.isArray(points)) return [];
  const cached = normalizedArmyPathCache.get(points);
  if (cached) return cached;
  const normalized = points
    .map(point => ({
      x: Number(point?.x),
      y: Number(point?.y),
    }))
    .filter(point => Number.isFinite(point.x) && Number.isFinite(point.y));
  normalizedArmyPathCache.set(points, normalized);
  normalizedArmyPathCache.set(normalized, normalized);
  return normalized;
}

function normalizeArmyPathSegments(segments) {
  if (!Array.isArray(segments)) return [];
  const cached = normalizedArmyPathSegmentsCache.get(segments);
  if (cached) return cached;
  const normalized = segments
    .map(segment => {
      const points = normalizeArmyPath(segment?.points);
      if (points.length < 2) return null;
      return {
        regionId: normalizeRegionId(segment.regionId),
        points,
        length: Math.max(0, Number(segment.length) || routeLength(points)),
      };
    })
    .filter(Boolean);
  normalizedArmyPathSegmentsCache.set(segments, normalized);
  normalizedArmyPathSegmentsCache.set(normalized, normalized);
  return normalized;
}

function getRouteSegments(route, fallbackRegionId = "") {
  const segments = normalizeArmyPathSegments(route?.segments);
  if (segments.length) return segments;
  const points = normalizeArmyPath(route?.points);
  if (points.length < 2) return [];
  return [{
    regionId: normalizeRegionId(fallbackRegionId || getActiveMapRegionId()),
    points,
    length: Math.max(0, Number(route?.length) || routeLength(points)),
  }];
}

function getMissionRouteSegments(mission) {
  const segments = normalizeArmyPathSegments(mission?.pathSegments);
  if (segments.length) return segments;
  const from = cityById(mission?.fromId);
  const to = getArmyTargetById(mission?.toId);
  const fromRegionId = from ? getCityRegionId(from) : (getKnownCityId(mission?.fromId) ? getCityRegionId(mission.fromId) : "");
  const toRegionId = to ? getCityRegionId(to) : mission?.targetRegionId ? normalizeRegionId(mission.targetRegionId) : "";
  const points = normalizeArmyPath(mission?.path);
  if (points.length >= 2 && fromRegionId === toRegionId) {
    return [{ regionId: fromRegionId, points, length: Math.max(0, Number(mission?.pathLength) || routeLength(points)) }];
  }
  return [];
}

function getMissionRegionIds(mission) {
  const ids = getMissionRouteSegments(mission).map(segment => segment.regionId);
  const fromRegionId = getKnownCityId(mission?.fromId) ? getCityRegionId(mission.fromId) : "";
  const target = getArmyTargetById(mission?.toId);
  const toRegionId = target ? getCityRegionId(target) : mission?.targetRegionId ? normalizeRegionId(mission.targetRegionId) : "";
  if (fromRegionId) ids.push(fromRegionId);
  if (toRegionId) ids.push(toRegionId);
  return [...new Set(ids.map(normalizeRegionId).filter(Boolean))];
}

function createOnlineArmyId(kind = "army") {
  const uidPart = String(getCurrentOnlineUid() || "player").replace(/[^a-z0-9_-]/gi, "").slice(0, 32) || "player";
  const kindPart = String(kind || "army").replace(/[^a-z0-9_-]/gi, "").slice(0, 16) || "army";
  return `${uidPart}_${kindPart}_${Date.now().toString(36)}_${attackIdCounter}`;
}

function prepareOnlineArmyMission(mission) {
  if (!mission || !isOnlineWorldActive() || mission.owner !== "player") return mission;
  const nowMs = Date.now();
  const source = cityById(mission.fromId);
  const target = getArmyTargetById(mission.toId);
  mission.onlineId = mission.onlineId || createOnlineArmyId(mission.kind);
  mission.ownerKind = "player";
  mission.ownerUid = getCurrentOnlineUid();
  mission.viewerAccess = "owner";
  mission.troopVisibility = "exact";
  mission.ownerName = state.playerName;
  mission.ownerFlag = state.flag;
  mission.ownerKingPower = getKingPower();
  mission.launchKind = ["attack", "transfer", "reinforce", "scout"].includes(mission.launchKind) || mission.launchKind === "rally_join"
    ? mission.launchKind
    : mission.kind;
  mission.attackerKingPower = normalizePowerValue(mission.attackerKingPower) || mission.ownerKingPower;
  mission.defenderKingPower = normalizePowerValue(mission.defenderKingPower);
  mission.attackProtection = normalizeAttackProtectionSnapshot(mission.attackProtection, mission.demoAttack);
  mission.acceptedAttackProtection = normalizeAttackProtectionSnapshot(mission.acceptedAttackProtection);
  mission.demoAttack = normalizeDemoAttackSnapshot(mission.demoAttack);
  mission.launchedAtMs = mission.launchedAtMs || nowMs;
  mission.arrivesAtMs = mission.arrivesAtMs || nowMs + Math.max(0, Number(mission.total) || 0) * 1000;
  mission.fromName = mission.fromName || source?.name || "";
  mission.toName = mission.toName || target?.name || "";
  mission.sourceRegionId = normalizeRegionId(mission.sourceRegionId || getCityRegionId(source || mission.fromId));
  mission.targetRegionId = normalizeRegionId(mission.targetRegionId || getCityRegionId(target || mission.toId));
  return mission;
}

function toOnlineArmyMovement(mission) {
  const onlineId = mission?.onlineId || "";
  if (!mission || !onlineId) return null;
  const from = cityById(mission.fromId);
  const to = getArmyTargetById(mission.toId);
  const pathSegments = getMissionRouteSegments(mission);
  return {
    id: onlineId,
    ownerKind: "player",
    ownerUid: mission.ownerUid || getCurrentOnlineUid(),
    ownerName: mission.ownerName || state.playerName,
    ownerFlag: mission.ownerFlag || state.flag,
    ownerKingPower: normalizePowerValue(mission.ownerKingPower) || getKingPower(),
    kind: mission.kind || "attack",
    launchKind: ["attack", "transfer", "reinforce", "scout"].includes(mission.launchKind) || mission.launchKind === "rally_join"
      ? mission.launchKind
      : mission.kind || "attack",
    targetType: mission.targetType === "camp" || isRewardCampTarget(to) ? "camp" : "city",
    fromId: mission.fromId,
    toId: mission.toId,
    fromName: from?.name || "",
    toName: to?.name || "",
    troops: Math.max(0, Math.floor(Number(mission.troops) || 0)),
    total: Math.max(0.1, Number(mission.total) || 0.1),
    path: normalizeArmyPath(mission.path),
    pathSegments,
    routeRegionIds: getMissionRegionIds(mission),
    pathLength: Math.max(0, Number(mission.pathLength) || pathSegments.reduce((total, segment) => total + segment.length, 0) || routeLength(normalizeArmyPath(mission.path))),
    targetOwnerAtLaunch: mission.targetOwnerAtLaunch || "neutral",
    requestedTroops: Math.max(0, Math.floor(Number(mission.requestedTroops) || 0)),
    attackerKingPower: normalizePowerValue(mission.attackerKingPower),
    defenderKingPower: normalizePowerValue(mission.defenderKingPower),
    attackProtection: normalizeAttackProtectionSnapshot(mission.attackProtection),
    acceptedAttackProtection: normalizeAttackProtectionSnapshot(mission.acceptedAttackProtection),
    demoAttack: normalizeDemoAttackSnapshot(mission.demoAttack),
    protectionHandling: mission.protectionHandling === "auto_cap" ? "auto_cap" : "reconfirm",
    useSwiftMarchOrder: Boolean(mission.useSwiftMarchOrder),
    rallyJoin: Boolean(mission.rallyJoin),
    rallyAttack: Boolean(mission.rallyAttack),
    rallyId: String(mission.rallyId || ""),
    rallyClanId: String(mission.rallyClanId || ""),
    rallyParticipantCount: Math.max(0, Math.floor(Number(mission.rallyParticipantCount) || 0)),
    participantUids: Array.isArray(mission.participantUids) ? mission.participantUids.map(String).filter(Boolean).slice(0, 8) : [],
    bulkAudioVersion: Math.max(0, Math.floor(Number(mission.bulkAudioVersion) || 0)),
    bulkOrderKind: mission.bulkOrderKind || "",
    bulkRequestId: mission.bulkRequestId || "",
    bulkArrivalCue: mission.bulkArrivalCue || "",
    bulkArrivalIndex: Math.max(0, Math.floor(Number(mission.bulkArrivalIndex) || 0)),
    bulkOrderCount: Math.max(0, Math.floor(Number(mission.bulkOrderCount) || 0)),
    launchedAtMs: Math.max(0, Number(mission.launchedAtMs) || Date.now()),
    arrivesAtMs: Math.max(0, Number(mission.arrivesAtMs) || Date.now()),
    status: "active",
  };
}

function rollbackServerArmyMission(mission, reason = "") {
  if (!state || !mission) return;
  const onlineId = getOnlineArmyResolutionId(mission);
  const source = cityById(mission.fromId);
  if (source?.owner === "player") {
    const returned = Math.max(0, Math.floor(Number(mission.troops) || 0));
    source.troopFloat = Math.max(0, Number(source.troopFloat) || Number(source.troops) || 0) + returned;
    source.troops = Math.floor(source.troopFloat);
  }
  state.attacks = state.attacks.filter(attack => {
    if (onlineId && getOnlineArmyResolutionId(attack) === onlineId) return false;
    return attack.id !== mission.id;
  });
  forgetPendingOnlineArmyMovement(onlineId);
  onlineLastError = reason || "Server rejected the army order.";
  addLog(`Army order canceled by server${reason ? `: ${reason}` : "."}`);
  showToast(reason || "Server canceled that army order.");
  saveGame();
  renderAll();
}

function rejectServerArmyMission(mission, reason = "", options = {}) {
  if (options.optimistic) {
    rollbackServerArmyMission(mission, reason);
    return;
  }
  const onlineId = getOnlineArmyResolutionId(mission);
  if (onlineId) forgetPendingOnlineArmyMovement(onlineId);
  onlineLastError = reason || "Server rejected the army order.";
  addLog(`Army order rejected by server${reason ? `: ${reason}` : "."}`);
  showToast(reason || "Server rejected that army order.");
  renderAll();
}

function getChangedAttackProtectionFromError(error) {
  const details = error?.details || error?.customData?.details || error?.data || {};
  if (details?.reason !== "attack-protection-changed") return null;
  return normalizeAttackProtectionSnapshot(details.attackProtection);
}

function reopenAttackProtectionConfirmation(mission, refreshedProtection) {
  const sourceId = mission?.fromId;
  const targetId = mission?.toId;
  const source = cityById(sourceId);
  const target = getArmyTargetById(targetId);
  if (!source || !target || source.owner !== "player") return;
  const refreshedProtectionSnapshot = normalizeAttackProtectionSnapshot(refreshedProtection);
  const requestedTroops = Math.max(1, Math.floor(Number(mission.requestedTroops) || 1));
  troopSliderActive = false;
  showToast("Protection changed. Confirm the refreshed limit.");
  window.setTimeout(() => {
    const freshSource = cityById(sourceId);
    const freshTarget = getArmyTargetById(targetId);
    if (!freshSource || !freshTarget || freshSource.owner !== "player") {
      showToast("Order canceled. The map changed.");
      return;
    }
    selectedSourceId = freshSource.id;
    selectedTargetId = freshTarget.id;
    sendMode = true;
    activeAttackProtectionPreview = refreshedProtectionSnapshot;
    selectedTroopAmount = clamp(
      requestedTroops,
      1,
      Math.max(1, Math.min(
        freshSource.troops,
        refreshedProtectionSnapshot?.maxTroops || freshSource.troops
      ))
    );
    void showTroopSliderModalAsync(freshSource, freshTarget, {
      attackProtection: refreshedProtectionSnapshot,
    });
  }, 0);
}

function applyServerMovementToMission(mission, movement = null) {
  if (!mission || !movement) return;
  const movementKind = String(movement.kind || "");
  const launchedAtMs = normalizeTimestampMs(movement.launchedAtMs);
  const arrivesAtMs = normalizeTimestampMs(movement.arrivesAtMs);
  const rawRemaining = Number(movement.remaining);
  mission.onlineId = movement.id || mission.onlineId;
  if (["attack", "transfer", "reinforce", "scout"].includes(movementKind) || movementKind === "rally_join") mission.kind = movementKind;
  if (["attack", "transfer", "reinforce", "scout"].includes(movement.launchKind) || movement.launchKind === "rally_join") {
    mission.launchKind = movement.launchKind;
  }
  if (["attack", "transfer", "reinforce", "scout"].includes(movement.retargetedFromKind) || movement.retargetedFromKind === "rally_join") {
    mission.retargetedFromKind = movement.retargetedFromKind;
  }
  const movementTroops = Number(movement.troops);
  const movementViewerAccess = ["owner", "target", "public"].includes(movement.viewerAccess)
    ? movement.viewerAccess
    : Number.isFinite(movementTroops) && movementTroops > 0 && isPersonalArmy(mission)
      ? "owner"
      : "";
  const mayApplyTroopVisibility = getArmyViewerAccessPriority(movementViewerAccess)
    >= getArmyViewerAccessPriority(mission.viewerAccess);
  mission.troops = Math.max(0, Math.floor((Number.isFinite(movementTroops) && movementTroops > 0 ? movementTroops : mission.troops) || 0));
  mission.requestedTroops = Math.max(0, Math.floor(Number(movement.requestedTroops) || mission.requestedTroops || mission.troops || 0));
  mission.adjustedByProtection = Boolean(movement.adjustedByProtection);
  mission.protectionHandling = movement.protectionHandling === "auto_cap" ? "auto_cap" : mission.protectionHandling || "reconfirm";
  if (mayApplyTroopVisibility) {
    mission.viewerAccess = movementViewerAccess || mission.viewerAccess || "public";
    mission.troopVisibility = movementViewerAccess === "owner"
      ? "exact"
      : ["exact", "estimate", "hidden"].includes(movement.troopVisibility)
        ? movement.troopVisibility
        : mission.troopVisibility || "exact";
    mission.troopEstimateMin = Math.max(0, Math.floor(Number(movement.troopEstimateMin) || 0));
    mission.troopEstimateMax = Math.max(0, Math.floor(Number(movement.troopEstimateMax) || 0));
    mission.troopEstimateLabel = String(movement.troopEstimateLabel || "");
  }
  mission.total = Math.max(0.1, Number(movement.total) || mission.total || 0.1);
  if (arrivesAtMs > 0) {
    mission.remaining = Math.max(0, (arrivesAtMs - Date.now()) / 1000);
  } else if (Number.isFinite(rawRemaining)) {
    mission.remaining = Math.max(0, rawRemaining);
  }
  mission.launchedAtMs = launchedAtMs || mission.launchedAtMs;
  mission.arrivesAtMs = arrivesAtMs || mission.arrivesAtMs;
  mission.swiftMarchUsedAtMs = normalizeTimestampMs(movement.swiftMarchUsedAtMs) || mission.swiftMarchUsedAtMs || 0;
  mission.swiftMarchOriginalArrivesAtMs = normalizeTimestampMs(movement.swiftMarchOriginalArrivesAtMs) || mission.swiftMarchOriginalArrivesAtMs || 0;
  mission.swiftMarchProgressAtUse = clamp(Number(movement.swiftMarchProgressAtUse) || mission.swiftMarchProgressAtUse || 0, 0, 1);
  mission.swiftMarchRemainingMultiplier = Math.max(0, Number(movement.swiftMarchRemainingMultiplier) || mission.swiftMarchRemainingMultiplier || 0);
  if (movement.returning !== undefined) mission.returning = Boolean(movement.returning);
  mission.returnReason = movement.returnReason || mission.returnReason || "";
  mission.recalledAtMs = normalizeTimestampMs(movement.recalledAtMs) || mission.recalledAtMs || 0;
  mission.recallOriginalArrivesAtMs = normalizeTimestampMs(movement.recallOriginalArrivesAtMs) || mission.recallOriginalArrivesAtMs || 0;
  mission.returnStartProgress = clamp(Number(movement.returnStartProgress) || mission.returnStartProgress || 0, 0, 1);
  mission.returnDestinationId = movement.returnDestinationId || mission.returnDestinationId || "";
  mission.returnDestinationRegionId = normalizeRegionId(movement.returnDestinationRegionId || mission.returnDestinationRegionId);
  mission.relinquishTransfer = Boolean(movement.relinquishTransfer || mission.relinquishTransfer);
  mission.campReturn = Boolean(movement.campReturn || mission.campReturn);
  mission.campRecall = Boolean(movement.campRecall || mission.campRecall);
  mission.reinforcementReturn = Boolean(movement.reinforcementReturn || mission.reinforcementReturn);
  mission.reinforcementId = String(movement.reinforcementId || mission.reinforcementId || "");
  mission.reinforcementTargetKey = String(movement.reinforcementTargetKey || mission.reinforcementTargetKey || "");
  mission.reinforcementRecipientUid = String(movement.reinforcementRecipientUid || mission.reinforcementRecipientUid || "");
  mission.reinforcementSourceId = String(movement.reinforcementSourceId || mission.reinforcementSourceId || "");
  mission.reinforcementSourceRegionId = normalizeRegionId(movement.reinforcementSourceRegionId || mission.reinforcementSourceRegionId);
  mission.reinforcementSourceCityName = String(movement.reinforcementSourceCityName || mission.reinforcementSourceCityName || "");
  mission.originalTargetOwnerUid = String(movement.originalTargetOwnerUid || mission.originalTargetOwnerUid || "");
  mission.rallyJoin = Boolean(movement.rallyJoin || mission.rallyJoin);
  mission.rallyAttack = Boolean(movement.rallyAttack || mission.rallyAttack);
  mission.rallyId = String(movement.rallyId || mission.rallyId || "");
  mission.rallyClanId = String(movement.rallyClanId || mission.rallyClanId || "");
  mission.rallyParticipantCount = Math.max(0, Math.floor(Number(movement.rallyParticipantCount) || mission.rallyParticipantCount || 0));
  mission.participantUids = Array.isArray(movement.participantUids)
    ? movement.participantUids.map(String).filter(Boolean).slice(0, 8)
    : mission.participantUids || [];
  mission.bulkAudioVersion = Math.max(0, Math.floor(Number(movement.bulkAudioVersion) || mission.bulkAudioVersion || 0));
  mission.bulkOrderKind = movement.bulkOrderKind || mission.bulkOrderKind || "";
  mission.bulkRequestId = movement.bulkRequestId || mission.bulkRequestId || "";
  mission.bulkArrivalCue = movement.bulkArrivalCue || mission.bulkArrivalCue || "";
  mission.bulkArrivalIndex = Math.max(0, Math.floor(Number(movement.bulkArrivalIndex) || mission.bulkArrivalIndex || 0));
  mission.bulkOrderCount = Math.max(0, Math.floor(Number(movement.bulkOrderCount) || mission.bulkOrderCount || 0));
  mission.attackerKingPower = normalizePowerValue(movement.attackerKingPower || mission.attackerKingPower);
  mission.defenderKingPower = normalizePowerValue(movement.defenderKingPower || mission.defenderKingPower);
  if (movement.attackProtection !== undefined) {
    mission.attackProtection = normalizeAttackProtectionSnapshot(movement.attackProtection, movement.demoAttack);
  }
  if (movement.demoAttack !== undefined) mission.demoAttack = normalizeDemoAttackSnapshot(movement.demoAttack);
  mission.targetType = movement.targetType === "camp" ? "camp" : mission.targetType || "city";
  if (movement.targetOwnerUid !== undefined) mission.targetOwnerUid = String(movement.targetOwnerUid || "");
  mission.fromName = movement.fromName || mission.fromName || "";
  mission.toName = movement.toName || mission.toName || "";
  mission.sourceRegionId = normalizeRegionId(movement.sourceRegionId || mission.sourceRegionId);
  mission.targetRegionId = normalizeRegionId(movement.targetRegionId || mission.targetRegionId);
  const movementRegionIds = Array.isArray(movement.routeRegionIds) ? movement.routeRegionIds : movement.onlineRegionIds;
  mission.onlineRegionIds = Array.isArray(movementRegionIds) ? movementRegionIds.map(normalizeRegionId).filter(Boolean) : mission.onlineRegionIds;
}

function addServerAcceptedMission(mission) {
  if (!state || !mission) return false;
  const onlineId = getOnlineArmyResolutionId(mission);
  if (onlineId && state.attacks.some(attack => getOnlineArmyResolutionId(attack) === onlineId)) return false;
  state.attacks.push(mission);
  return true;
}

function restoreRejectedArmyOrderSelection(mission) {
  const sourceId = String(mission?.fromId || "");
  const targetId = String(mission?.toId || "");
  if (!sourceId || !targetId) return;
  window.setTimeout(() => {
    if (modal.open || sendMode || selectedSourceId || selectedTargetId) return;
    const source = cityById(sourceId);
    const target = getArmyTargetById(targetId);
    if (!source || !target || source.owner !== "player" || source.troops < 1) return;
    if (mission.kind === "scout") {
      void scoutTarget(target);
      return;
    }
    selectedSourceId = source.id;
    selectedTargetId = target.id;
    sendMode = true;
    selectedTroopAmount = clamp(
      Math.max(1, Math.floor(Number(mission.requestedTroops) || 1)),
      1,
      source.troops
    );
    void showTroopSliderModalAsync(source, target, { orderKind: mission.kind });
  }, 0);
}

function isRetryableArmySubmissionError(error) {
  const code = String(error?.code || error?.name || "").toLowerCase();
  const message = String(error?.message || error || "").toLowerCase();
  return /unavailable|deadline-exceeded|internal|unknown|network|timeout/.test(`${code} ${message}`);
}

function publishOnlineArmyMovement(mission, options = {}) {
  if (!isOnlineWorldActive() || mission?.owner !== "player") return Promise.resolve(false);
  const api = getOnlineApi();
  if (!usesServerArmyAuthority() || !api?.sendArmyOrder) {
    onlineLastError = "Online army orders require the Crownlands server.";
    showToast("Online army orders need the server connection. Try again after reconnecting.");
    return Promise.resolve(false);
  }
  prepareOnlineArmyMission(mission);
  const movement = toOnlineArmyMovement(mission);
  if (!movement) return Promise.resolve(false);
  // The server always rebuilds geometry from the source and target. Keep online
  // launch payloads compact so confirmation never depends on a client route.
  const movementPayload = {
    ...movement,
    path: [],
    pathSegments: [],
    pathLength: 0,
    routeRegionIds: getMissionRegionIds(mission),
  };
  const regionIds = movement.routeRegionIds?.length ? movement.routeRegionIds : getMissionRegionIds(mission);
  mission.onlineRegionIds = regionIds;
  const sourceRegionId = getCityRegionId(mission.fromId);
  const target = getArmyTargetById(mission.toId);
  const targetRegionId = normalizeRegionId(mission.targetRegionId || target?.regionId || getCityRegionId(mission.toId));
  mission.fromName = mission.fromName || movement.fromName || "";
  mission.toName = mission.toName || movement.toName || "";
  mission.sourceRegionId = normalizeRegionId(mission.sourceRegionId || sourceRegionId);
  mission.targetRegionId = targetRegionId;
  mission.serverPending = true;
  mission.clientSubmitStartedAt = performance.now();
  pendingOutgoingMissions.set(movement.id, mission);
  updateOutgoingAttackUi();

  const orderPayload = {
    worldId: ONLINE_WORLD_ID,
    resetGeneration: RESET_GENERATION,
    army: {
      ...movementPayload,
      sourceRegionId,
      targetRegionId,
      targetType: movement.targetType,
    },
    sourceRegionId,
    targetRegionId,
    routeRegionIds: regionIds,
  };
  const submitOrder = () => api.sendArmyOrder(orderPayload);
  const savePromise = submitOrder()
    .catch(error => {
      if (!isRetryableArmySubmissionError(error)) throw error;
      mission.serverRetrying = true;
      updateOutgoingAttackUi();
      return new Promise(resolve => window.setTimeout(resolve, 350)).then(submitOrder);
    })
    .then(result => {
      recordMarchInteractionTiming("server-order-accepted", mission.clientSubmitStartedAt);
      if (result?.movement) applyServerMovementToMission(mission, result.movement);
      mission.peaceShieldDeactivated = Boolean(result?.peaceShieldDeactivated);
      mission.serverPending = false;
      mission.serverRetrying = false;
      applyServerArmyResult({
        currentUser: result?.currentUser,
        cityUpdates: Array.isArray(result?.cityUpdates)
          ? result.cityUpdates
          : result?.sourceCity ? [result.sourceCity] : [],
      });
      if (options.addLocalMissionOnAccept) addServerAcceptedMission(mission);
      pendingOutgoingMissions.delete(movement.id);
      onlineLastError = "";
      saveGame();
      renderAll();
      updateIncomingAttackUi();
      updateOutgoingAttackUi();
      return true;
    })
    .catch(error => {
      recordMarchInteractionTiming("server-order-rejected", mission.clientSubmitStartedAt);
      pendingOutgoingMissions.delete(movement.id);
      mission.serverPending = false;
      mission.serverRetrying = false;
      onlineLastError = error?.message || String(error);
      console.warn("Server rejected army movement", error);
      const refreshedProtection = getChangedAttackProtectionFromError(error);
      if (refreshedProtection) {
        reopenAttackProtectionConfirmation(mission, refreshedProtection);
        return false;
      }
      rejectServerArmyMission(mission, onlineLastError, options);
      restoreRejectedArmyOrderSelection(mission);
      return false;
    })
    .finally(() => {
      pendingOutgoingMissions.delete(movement.id);
      onlineArmySavePromises.delete(savePromise);
      updateOutgoingAttackUi();
    });
  onlineArmySavePromises.add(savePromise);
  return savePromise;
}

function deleteOnlineArmyMovement(mission) {
  if (!mission?.onlineId || mission.owner !== "player") return;
  forgetPendingOnlineArmyMovement(mission.onlineId);
}

function getOnlineArmyResolutionId(mission) {
  const id = mission?.onlineId || (typeof mission?.id === "string" ? mission.id : "");
  return String(id || "").trim();
}

function isOnlineArmyResolutionBlocked(mission) {
  const onlineId = getOnlineArmyResolutionId(mission);
  return Boolean(onlineId && (resolvedOnlineArmyIds.has(onlineId) || resolvingOnlineArmyIds.has(onlineId)));
}

function getOnlineArmyRemainingSeconds(army) {
  if (!army) return 0;
  if (Number.isFinite(army.arrivesAtMs) && army.arrivesAtMs > 0) {
    return (army.arrivesAtMs - Date.now()) / 1000;
  }
  return Number(army.remaining) || 0;
}

function isArrivedScoutMission(army, nowMs = Date.now()) {
  if (!army || army.kind !== "scout") return false;
  const arrivesAtMs = normalizeTimestampMs(army.arrivesAtMs);
  if (arrivesAtMs > 0) return arrivesAtMs <= nowMs;
  const remaining = Number(army.remaining);
  return Number.isFinite(remaining) && remaining <= 0;
}

function isServerArmyNotArrivedError(error) {
  const message = String(error?.message || error || "");
  return /not arrived/i.test(message);
}

function deferServerArmyResolutionRetry(mission) {
  if (!mission) return;
  const remaining = getOnlineArmyRemainingSeconds(mission);
  const retrySeconds = Math.min(5, Math.max(0.5, Number.isFinite(remaining) && remaining > 0 ? remaining : 1));
  mission.remaining = Math.max(Number(mission.remaining) || 0, retrySeconds);
  mission.resolveRetryAtMs = Date.now() + Math.ceil(retrySeconds * 1000);
}

function resolveOnlineArmyOwner(army) {
  if (army?.ownerUid && army.ownerUid === getCurrentOnlineUid()) return "player";
  if (army?.eventKind === CITADEL_ASSAULT_EVENT_KIND || army?.ownerKind === "npc") return "enemy";
  if (!army?.ownerUid) return "neutral";
  if (army?.ownerKind === "neutral") return "neutral";
  return "enemy";
}

function normalizeOnlineArmyMovement(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = String(raw.id || "").trim();
  if (!id) return null;
  const ownerUid = String(raw.ownerUid || "").trim();
  const rawOwnerKind = raw.ownerKind || raw.owner || "player";
  if (!["neutral", "npc"].includes(rawOwnerKind) && !ownerUid) return null;
  const targetOwnerUid = String(raw.targetOwnerUid || "").trim();
  const rawKind = ["attack", "transfer", "reinforce", "scout"].includes(raw.kind) || raw.kind === "rally_join" ? raw.kind : "attack";
  const effectiveKind = rawKind === "transfer"
    && targetOwnerUid
    && ownerUid
    && targetOwnerUid !== ownerUid
    && !raw.returning
    && !raw.campReturn
    && !raw.relinquishTransfer
    ? "attack"
    : rawKind;
  const total = Math.max(0.1, Number(raw.total) || 0.1);
  const launchedAtMs = Math.max(0, Number(raw.launchedAtMs) || 0);
  const arrivesAtMs = Math.max(
    0,
    Number(raw.arrivesAtMs) || (launchedAtMs ? launchedAtMs + total * 1000 : Date.now() + total * 1000)
  );
  const path = normalizeArmyPath(raw.path);
  const pathSegments = normalizeArmyPathSegments(raw.pathSegments);
  const ownerIdentity = ownerUid ? resolvePlayerIdentityForUid(ownerUid, raw) : null;
  const viewerAccess = ["owner", "target", "public"].includes(raw.viewerAccess)
    ? raw.viewerAccess
    : "public";
  const rawTroops = Number.isFinite(Number(raw.troops))
    ? Math.max(0, Math.floor(Number(raw.troops)))
    : null;
  const isAttackMovement = effectiveKind === "attack"
    || raw.launchKind === "attack"
    || Boolean(raw.rallyAttack);
  const isClanReinforcementMovement = effectiveKind === "reinforce"
    && !raw.returning
    && !raw.reinforcementReturn;
  const exactEventTroops = raw.eventKind === CITADEL_ASSAULT_EVENT_KIND && raw.troopVisibility === "exact";
  const estimateForViewer = !exactEventTroops
    && viewerAccess !== "owner"
    && (raw.troopVisibility === "estimate" || isAttackMovement || isClanReinforcementMovement);
  const hiddenForViewer = raw.troopVisibility === "hidden"
    && viewerAccess !== "owner";
  const troopEstimate = estimateForViewer
    ? normalizeArmyTroopEstimate(raw, rawTroops)
    : null;
  return {
    id,
    onlineId: id,
    owner: resolveOnlineArmyOwner(raw),
    ownerKind: rawOwnerKind === "npc" ? "npc" : ownerUid ? "player" : "neutral",
    ownerUid,
    ownerName: ownerIdentity?.displayName || raw.ownerName || "",
    ownerFlag: ownerIdentity?.flag || raw.ownerFlag || null,
    ownerKingPower: normalizePowerValue(ownerIdentity?.kingPower) || normalizePowerValue(raw.ownerKingPower),
    eventKind: String(raw.eventKind || ""),
    waveId: String(raw.waveId || ""),
    kind: effectiveKind,
    launchKind: ["attack", "transfer", "reinforce", "scout"].includes(raw.launchKind) ? raw.launchKind : raw.launchKind === "rally_join" ? "rally_join" : rawKind,
    retargetedFromKind: ["attack", "transfer", "reinforce", "scout"].includes(raw.retargetedFromKind) || raw.retargetedFromKind === "rally_join"
      ? raw.retargetedFromKind
      : "",
    targetType: raw.targetType === "camp" ? "camp" : "city",
    fromId: raw.fromId || "",
    toId: raw.toId || "",
    fromName: raw.fromName || "",
    toName: raw.toName || "",
    sourceRegionId: normalizeRegionId(raw.sourceRegionId),
    targetRegionId: normalizeRegionId(raw.targetRegionId),
    troops: estimateForViewer || hiddenForViewer ? null : rawTroops,
    troopVisibility: estimateForViewer ? "estimate" : hiddenForViewer ? "hidden" : "exact",
    troopEstimateMin: troopEstimate?.min || 0,
    troopEstimateMax: troopEstimate?.max || 0,
    troopEstimateLabel: troopEstimate?.label || "",
    viewerAccess,
    total,
    remaining: Math.max(0, (arrivesAtMs - Date.now()) / 1000),
    path,
    pathSegments,
    pathLength: Math.max(0, Number(raw.pathLength) || pathSegments.reduce((total, segment) => total + segment.length, 0) || routeLength(path)),
    targetOwnerAtLaunch: raw.targetOwnerAtLaunch || "neutral",
    targetOwnerUid,
    requestedTroops: estimateForViewer || hiddenForViewer
      ? null
      : Math.max(0, Math.floor(Number(raw.requestedTroops) || 0)),
    attackerKingPower: normalizePowerValue(raw.attackerKingPower || raw.ownerKingPower),
    defenderKingPower: normalizePowerValue(raw.defenderKingPower),
    attackProtection: normalizeAttackProtectionSnapshot(raw.attackProtection, raw.demoAttack),
    demoAttack: normalizeDemoAttackSnapshot(raw.demoAttack),
    siegeCombatVersion: Math.max(0, Math.floor(Number(raw.siegeCombatVersion) || 0)),
    defenseCombatVersion: Math.max(0, Math.floor(Number(raw.defenseCombatVersion) || 0)),
    launchedAtMs,
    arrivesAtMs,
    swiftMarchUsedAtMs: normalizeTimestampMs(raw.swiftMarchUsedAtMs),
    swiftMarchOriginalArrivesAtMs: normalizeTimestampMs(raw.swiftMarchOriginalArrivesAtMs),
    swiftMarchProgressAtUse: clamp(Number(raw.swiftMarchProgressAtUse) || 0, 0, 1),
    swiftMarchRemainingMultiplier: Math.max(0, Number(raw.swiftMarchRemainingMultiplier) || 0),
    returning: Boolean(raw.returning),
    returnReason: String(raw.returnReason || ""),
    recalledAtMs: normalizeTimestampMs(raw.recalledAtMs),
    recallOriginalArrivesAtMs: normalizeTimestampMs(raw.recallOriginalArrivesAtMs),
    returnStartProgress: clamp(Number(raw.returnStartProgress) || 0, 0, 1),
    returnDestinationId: String(raw.returnDestinationId || ""),
    returnDestinationRegionId: normalizeRegionId(raw.returnDestinationRegionId),
    relinquishTransfer: Boolean(raw.relinquishTransfer),
    campReturn: Boolean(raw.campReturn),
    campRecall: Boolean(raw.campRecall),
    reinforcementReturn: Boolean(raw.reinforcementReturn),
    reinforcementId: String(raw.reinforcementId || ""),
    reinforcementTargetKey: String(raw.reinforcementTargetKey || ""),
    reinforcementRecipientUid: String(raw.reinforcementRecipientUid || ""),
    reinforcementSourceId: String(raw.reinforcementSourceId || ""),
    reinforcementSourceRegionId: normalizeRegionId(raw.reinforcementSourceRegionId),
    reinforcementSourceCityName: String(raw.reinforcementSourceCityName || ""),
    originalTargetOwnerUid: String(raw.originalTargetOwnerUid || ""),
    rallyJoin: Boolean(raw.rallyJoin || rawKind === "rally_join"),
    rallyAttack: Boolean(raw.rallyAttack),
    rallyId: String(raw.rallyId || ""),
    rallyClanId: String(raw.rallyClanId || ""),
    rallyParticipantCount: Math.max(0, Math.floor(Number(raw.rallyParticipantCount) || 0)),
    participantUids: Array.isArray(raw.participantUids) ? raw.participantUids.map(String).filter(Boolean).slice(0, 8) : [],
    bulkAudioVersion: Math.max(0, Math.floor(Number(raw.bulkAudioVersion) || 0)),
    bulkOrderKind: raw.bulkOrderKind === "regroup" ? "regroup" : raw.bulkRequestId && rawKind === "scout" ? "nearby_scout" : String(raw.bulkOrderKind || ""),
    bulkRequestId: String(raw.bulkRequestId || ""),
    bulkArrivalCue: ["first", "last", "first_last", "mute"].includes(raw.bulkArrivalCue) ? raw.bulkArrivalCue : "",
    bulkArrivalIndex: Math.max(0, Math.floor(Number(raw.bulkArrivalIndex) || 0)),
    bulkOrderCount: Math.max(0, Math.floor(Number(raw.bulkOrderCount) || 0)),
    adjustedByProtection: Boolean(raw.adjustedByProtection),
    protectionHandling: raw.protectionHandling === "auto_cap" ? "auto_cap" : "reconfirm",
    status: raw.status || "active",
    onlineRegionIds: Array.isArray(raw.routeRegionIds) ? raw.routeRegionIds.map(normalizeRegionId) : [],
  };
}

function getArmyViewerAccessPriority(viewerAccess = "") {
  return ({ public: 0, target: 1, owner: 2 })[viewerAccess] ?? 0;
}

function rebuildOnlineArmies() {
  const armiesById = new Map();
  Array.from(onlineArmiesByIsland.values())
    .flat()
    .forEach(army => {
      const key = String(army?.id || army?.onlineId || "");
      if (!key) return;
      const current = armiesById.get(key);
      const currentPriority = getArmyViewerAccessPriority(current?.viewerAccess);
      const nextPriority = getArmyViewerAccessPriority(army?.viewerAccess);
      if (!current || nextPriority > currentPriority) armiesById.set(key, army);
    });
  onlineArmies = annotateClientBulkArrivalAudio([...armiesById.values()]);
}

function clearOnlineArmyWatchers({ clear = true } = {}) {
  onlineArmyUnsubscribes.forEach(unsubscribe => {
    if (typeof unsubscribe === "function") unsubscribe();
  });
  onlineArmyUnsubscribes = [];
  onlineArmySyncFailures.clear();
  updateOnlineArmySyncBadge();
  if (clear) {
    onlineArmiesByIsland = new Map();
    onlineArmies = [];
    pendingOutgoingMissions = new Map();
  }
}

function clearOnlineReinforcementWatcher({ clear = true } = {}) {
  if (typeof onlineReinforcementsUnsubscribe === "function") onlineReinforcementsUnsubscribe();
  onlineReinforcementsUnsubscribe = null;
  if (clear) {
    onlineReinforcements = [];
    reinforcementReturnRequests.clear();
  }
}

function clearOnlineHeldCampWatcher({ clear = true } = {}) {
  if (typeof onlineHeldCampsUnsubscribe === "function") onlineHeldCampsUnsubscribe();
  onlineHeldCampsUnsubscribe = null;
  if (clear) onlineHeldCampStates = new Map();
}

function purgeResolvedOnlineArmy(onlineId, { removeLocal = true } = {}) {
  const id = String(onlineId || "").trim();
  if (!id) return false;
  let changed = false;
  for (const [cacheKey, armies] of onlineArmiesByIsland) {
    const current = Array.isArray(armies) ? armies : [];
    const filtered = current.filter(army => getOnlineArmyResolutionId(army) !== id);
    if (filtered.length === current.length) continue;
    onlineArmiesByIsland.set(cacheKey, filtered);
    changed = true;
  }
  if (removeLocal && state?.attacks?.length) {
    const filtered = state.attacks.filter(army => getOnlineArmyResolutionId(army) !== id);
    if (filtered.length !== state.attacks.length) {
      state.attacks = filtered;
      changed = true;
    }
  }
  if (pendingOutgoingMissions.delete(id)) changed = true;
  forgetPendingOnlineArmyMovement(id);
  if (changed) rebuildOnlineArmies();
  return changed;
}

function clearOnlineIslandArmySnapshots() {
  const playerRelevantArmies = onlineArmiesByIsland.get(PLAYER_RELEVANT_ARMIES_CACHE_KEY);
  onlineArmiesByIsland = new Map();
  if (playerRelevantArmies?.length) {
    onlineArmiesByIsland.set(PLAYER_RELEVANT_ARMIES_CACHE_KEY, playerRelevantArmies);
  }
  rebuildOnlineArmies();
}

function clearOnlineServerReportWatcher() {
  if (typeof onlineServerReportsUnsubscribe === "function") onlineServerReportsUnsubscribe();
  onlineServerReportsUnsubscribe = null;
}

function isLoginPresentationSequenceActive(sequence = loginPresentationSequence) {
  return Boolean(
    sequence
    && !sequence.finished
    && sequence.generation === loginPresentationGeneration
  );
}

function isLoginPresentationModalOpen() {
  return Boolean(
    modal?.open
    && (
      modal.classList.contains("daily-login-reward-modal")
      || modal.classList.contains("offline-reward-modal")
    )
  );
}

function isLoginPresentationBlockingRealmAnnouncements() {
  return isLoginPresentationSequenceActive() || isLoginPresentationModalOpen();
}

function getLoginPresentationRealmFloorMs(sequence = loginPresentationSequence) {
  return Math.max(
    normalizeTimestampMs(sequence?.baselineAtMs),
    normalizeTimestampMs(state?.realmAnnouncementSeenThroughMs)
  );
}

function addLoginPresentationRealmCandidate(event = null, sequence = loginPresentationSequence) {
  if (!isLoginPresentationSequenceActive(sequence)) return false;
  const normalized = normalizeRealmActivityEvent(event);
  if (!normalized || normalized.occurredAtMs <= getLoginPresentationRealmFloorMs(sequence)) return false;
  if (sequence.finalizing) {
    if (!sequence.batchEventIds?.has(normalized.eventId)) {
      sequence.deferredLiveEvents.set(normalized.eventId, normalized);
    }
    return true;
  }
  sequence.realmCandidates.set(normalized.eventId, normalized);
  return true;
}

function collectLoginPresentationRealmCandidates(events = [], sequence = loginPresentationSequence) {
  if (!isLoginPresentationSequenceActive(sequence)) return false;
  let changed = false;
  normalizeRealmActivityEvents(events).forEach(event => {
    changed = addLoginPresentationRealmCandidate(event, sequence) || changed;
  });
  return changed;
}

function suspendRealmAnnouncementForLoginPresentation(sequence = loginPresentationSequence) {
  const active = activeRealmAnnouncement;
  if (active) {
    clearRealmAnnouncementPresentation();
    if (!addLoginPresentationRealmCandidate(active, sequence)) {
      realmAnnouncementQueue.unshift(active);
    }
  }
  if (!isLoginPresentationSequenceActive(sequence) || !realmAnnouncementQueue.length) return;
  realmAnnouncementQueue = realmAnnouncementQueue.filter(event => (
    !addLoginPresentationRealmCandidate(event, sequence)
  ));
}

function beginLoginPresentationSequence({ kind = "login", baselineAtMs = 0, welcomeExpected = false } = {}) {
  const generation = ++loginPresentationGeneration;
  const sequence = {
    generation,
    kind,
    baselineAtMs: normalizeTimestampMs(baselineAtMs) || Date.now(),
    mapReady: false,
    dailyResolved: false,
    dailyRequired: false,
    dailyOpen: false,
    dailyFinished: false,
    welcomeExpected: Boolean(welcomeExpected),
    welcomeResolved: !welcomeExpected,
    welcomeOpen: false,
    welcomeFinished: !welcomeExpected,
    realmCandidates: new Map(),
    deferredLiveEvents: new Map(),
    batchEventIds: new Set(),
    finalizing: false,
    finished: false,
  };
  loginPresentationSequence = sequence;
  collectLoginPresentationRealmCandidates(onlineRealmActivityEvents, sequence);
  suspendRealmAnnouncementForLoginPresentation(sequence);
  return generation;
}

function cancelLoginPresentationSequence() {
  loginPresentationGeneration += 1;
  loginPresentationSequence = null;
  showNextRealmAnnouncement();
}

function markLoginPresentationMapReady(generation = loginPresentationGeneration) {
  const sequence = loginPresentationSequence;
  if (!isLoginPresentationSequenceActive(sequence) || sequence.generation !== generation) return false;
  sequence.mapReady = true;
  advanceLoginPresentationSequence(sequence);
  return true;
}

function hasDailyLoginAutoOpenBeenUsed(status = dailyLoginRewardStatus) {
  const key = getDailyLoginRewardAutoOpenKey(status);
  if (!key) return true;
  try {
    return window.localStorage?.getItem(key) === "1";
  } catch (_) {
    return false;
  }
}

function resolveLoginPresentationDailyPhase(generation, status = null) {
  const sequence = loginPresentationSequence;
  if (!isLoginPresentationSequenceActive(sequence) || sequence.generation !== generation) return false;
  sequence.dailyResolved = true;
  sequence.dailyRequired = Boolean(status?.eligible && !hasDailyLoginAutoOpenBeenUsed(status));
  if (!sequence.dailyRequired) sequence.dailyFinished = true;
  advanceLoginPresentationSequence(sequence);
  return true;
}

function resolveLoginPresentationWelcomePhase(generation) {
  const sequence = loginPresentationSequence;
  if (!isLoginPresentationSequenceActive(sequence) || sequence.generation !== generation) return false;
  sequence.welcomeResolved = true;
  if (!pendingOfflineRewardsSummary && !sequence.welcomeOpen) sequence.welcomeFinished = true;
  advanceLoginPresentationSequence(sequence);
  return true;
}

function completeLoginPresentationModal(kind = "") {
  const sequence = loginPresentationSequence;
  if (!isLoginPresentationSequenceActive(sequence)) {
    showNextRealmAnnouncement();
    return false;
  }
  if (kind === "daily") {
    sequence.dailyOpen = false;
    sequence.dailyFinished = true;
  } else if (kind === "welcome") {
    sequence.welcomeOpen = false;
    sequence.welcomeFinished = true;
  }
  advanceLoginPresentationSequence(sequence);
  return true;
}

function finishLoginPresentationSequence(sequence, { catchUpEvent = null } = {}) {
  if (!isLoginPresentationSequenceActive(sequence)) return false;
  const deferredEvents = [...sequence.deferredLiveEvents.values()]
    .sort((a, b) => a.occurredAtMs - b.occurredAtMs || a.eventId.localeCompare(b.eventId));
  sequence.finished = true;
  loginPresentationSequence = null;
  if (catchUpEvent) {
    deliveredRealmAnnouncementEventIds.delete(catchUpEvent.eventId);
    enqueueRealmAnnouncement(catchUpEvent);
  }
  deferredEvents.forEach(event => enqueueRealmAnnouncement(event));
  showNextRealmAnnouncement();
  return true;
}

async function finalizeLoginPresentationRealmCatchUp(sequence) {
  if (!isLoginPresentationSequenceActive(sequence) || sequence.finalizing) return false;
  const floorMs = getLoginPresentationRealmFloorMs(sequence);
  const candidates = [...sequence.realmCandidates.values()]
    .filter(event => event.occurredAtMs > floorMs)
    .sort((a, b) => b.occurredAtMs - a.occurredAtMs || b.eventId.localeCompare(a.eventId));
  if (!candidates.length) return finishLoginPresentationSequence(sequence);

  const selected = candidates.find(event => event.eventType === "CITADEL_CAPTURED") || candidates[0];
  const seenThroughMs = candidates.reduce((latest, event) => Math.max(latest, event.occurredAtMs), 0);
  sequence.finalizing = true;
  sequence.batchEventIds = new Set(candidates.map(event => event.eventId));
  const api = getOnlineApi();
  if (!api?.markRealmAnnouncementSeen || !api?.isSignedIn?.()) {
    return finishLoginPresentationSequence(sequence);
  }

  try {
    const result = await api.markRealmAnnouncementSeen({
      eventId: selected.eventId,
      seenThroughMs,
    });
    if (!isLoginPresentationSequenceActive(sequence)) return false;
    const confirmedSeenThroughMs = normalizeTimestampMs(result?.realmAnnouncementSeenThroughMs);
    if (!confirmedSeenThroughMs) throw new Error("The server did not confirm the Realm announcement cursor.");
    state.realmAnnouncementSeenThroughMs = Math.max(
      normalizeTimestampMs(state.realmAnnouncementSeenThroughMs),
      confirmedSeenThroughMs
    );
    state.lastRealmAnnouncementEventId = String(result?.lastRealmAnnouncementEventId || state.lastRealmAnnouncementEventId || "").slice(0, 180);
    const claimed = result?.claimed === true && String(result?.eventId || "") === selected.eventId;
    return finishLoginPresentationSequence(sequence, { catchUpEvent: claimed ? selected : null });
  } catch (error) {
    console.warn("Could not synchronize the Realm catch-up announcement", error);
    return finishLoginPresentationSequence(sequence);
  }
}

function advanceLoginPresentationSequence(sequence = loginPresentationSequence) {
  if (!isLoginPresentationSequenceActive(sequence) || sequence.finalizing || !sequence.mapReady) return false;
  if (!sequence.dailyResolved) return false;
  if (!sequence.dailyFinished) {
    if (sequence.dailyOpen || modal?.open || profileScreen?.classList.contains("open") || document.visibilityState !== "visible") return false;
    if (!sequence.dailyRequired || hasDailyLoginAutoOpenBeenUsed()) {
      sequence.dailyFinished = true;
    } else {
      const opened = maybeAutoOpenDailyLoginRewards({ presentationGeneration: sequence.generation });
      if (opened) sequence.dailyOpen = true;
      return opened;
    }
  }
  if (!sequence.welcomeResolved) return false;
  if (!sequence.welcomeFinished) {
    if (sequence.welcomeOpen || modal?.open || profileScreen?.classList.contains("open") || document.visibilityState !== "visible") return false;
    if (pendingOfflineRewardsSummary) {
      const opened = showPendingOfflineRewardsSummary({ presentationGeneration: sequence.generation });
      if (opened) sequence.welcomeOpen = true;
      return opened;
    }
    sequence.welcomeFinished = true;
  }
  if (!realmActivityAuthoritativeHydrated) return false;
  void finalizeLoginPresentationRealmCatchUp(sequence);
  return true;
}

function startLoginPresentationDailyRefresh(generation = loginPresentationGeneration) {
  void refreshDailyMissionStatus({ silent: true });
  void refreshSeasonalAchievementStatus({ silent: true });
  Promise.resolve(refreshDailyLoginRewardStatus({ silent: true }))
    .then(status => resolveLoginPresentationDailyPhase(generation, status))
    .catch(error => {
      console.warn("Daily Login presentation status failed", error);
      resolveLoginPresentationDailyPhase(generation, null);
    });
}

function clearRealmAnnouncementPresentation() {
  window.clearTimeout(realmAnnouncementTimer);
  window.clearTimeout(realmAnnouncementExitTimer);
  realmAnnouncementTimer = 0;
  realmAnnouncementExitTimer = 0;
  activeRealmAnnouncement = null;
  if (!realmAnnouncement) return;
  realmAnnouncement.hidden = true;
  realmAnnouncement.classList.remove("is-visible", "is-leaving", "stronghold", "citadel");
}

function clearRealmAnnouncementQueue() {
  realmAnnouncementQueue = [];
  clearRealmAnnouncementPresentation();
}

function showNextRealmAnnouncement() {
  if (
    activeRealmAnnouncement
    || !realmAnnouncementQueue.length
    || !realmAnnouncement
    || isLoginPresentationBlockingRealmAnnouncements()
  ) return;
  const event = realmAnnouncementQueue.shift();
  const copy = getRealmActivityCopy(event);
  activeRealmAnnouncement = event;
  deliveredRealmAnnouncementEventIds.add(event.eventId);
  realmAnnouncement.classList.remove("is-visible", "is-leaving", "stronghold", "citadel");
  realmAnnouncement.classList.add(copy.tone);
  realmAnnouncement.hidden = false;
  if (realmAnnouncementIcon) realmAnnouncementIcon.src = getRealmActivityArtSrc(event);
  if (realmAnnouncementTitle) realmAnnouncementTitle.textContent = copy.liveTitle;
  if (realmAnnouncementMessage) realmAnnouncementMessage.textContent = copy.liveMessage;
  window.requestAnimationFrame(() => {
    if (activeRealmAnnouncement?.eventId === event.eventId) {
      realmAnnouncement.classList.add("is-visible");
    }
  });
  const visibleMs = event.eventType === "CITADEL_CAPTURED"
    ? REALM_ANNOUNCEMENT_CITADEL_MS
    : REALM_ANNOUNCEMENT_STRONGHOLD_MS;
  realmAnnouncementTimer = window.setTimeout(() => {
    realmAnnouncementTimer = 0;
    realmAnnouncement.classList.remove("is-visible");
    realmAnnouncement.classList.add("is-leaving");
    realmAnnouncementExitTimer = window.setTimeout(() => {
      realmAnnouncementExitTimer = 0;
      activeRealmAnnouncement = null;
      realmAnnouncement.hidden = true;
      realmAnnouncement.classList.remove("is-leaving", "stronghold", "citadel");
      showNextRealmAnnouncement();
    }, getEffectiveAnimationMode() === "off" ? 0 : REALM_ANNOUNCEMENT_TRANSITION_MS);
  }, visibleMs);
}

function enqueueRealmAnnouncement(event = null) {
  const normalized = normalizeRealmActivityEvent(event);
  if (!normalized) return false;
  if (activeRealmAnnouncement?.eventId === normalized.eventId) return false;
  if (realmAnnouncementQueue.some(entry => entry.eventId === normalized.eventId)) return false;
  if (deliveredRealmAnnouncementEventIds.has(normalized.eventId)) return false;
  if (isLoginPresentationSequenceActive()) return addLoginPresentationRealmCandidate(normalized);
  realmAnnouncementQueue.push(normalized);
  realmAnnouncementQueue.sort((a, b) => {
    const aPriority = a.eventType === "CITADEL_CAPTURED" ? 0 : 1;
    const bPriority = b.eventType === "CITADEL_CAPTURED" ? 0 : 1;
    return aPriority - bPriority || a.occurredAtMs - b.occurredAtMs;
  });
  showNextRealmAnnouncement();
  return true;
}

function mergeRealmActivitySnapshot(events = [], metadata = {}) {
  const nextEvents = normalizeRealmActivityEvents(events);
  const previousSignature = onlineRealmActivityEvents
    .map(event => `${event.eventId}:${event.occurredAtMs}`)
    .join("|");
  const nextSignature = nextEvents
    .map(event => `${event.eventId}:${event.occurredAtMs}`)
    .join("|");
  const changed = previousSignature !== nextSignature;
  onlineRealmActivityEvents = nextEvents;

  const authoritative = metadata.fromCache !== true && metadata.hasPendingWrites !== true;
  const initial = metadata.initial === true || !realmActivityHydrated;
  const addedEvents = (Array.isArray(metadata.changes) ? metadata.changes : [])
    .filter(change => change?.type === "added")
    .map(change => normalizeRealmActivityEvent(change.event))
    .filter(Boolean);
  if (authoritative) {
    realmActivityAuthoritativeHydrated = true;
    if (isLoginPresentationSequenceActive() && !loginPresentationSequence.finalizing) {
      collectLoginPresentationRealmCandidates(nextEvents, loginPresentationSequence);
    }
    addedEvents.forEach(event => {
      const newDuringSession = event.occurredAtMs >= realmActivityLiveSinceMs;
      if (newDuringSession && !seenRealmActivityEventIds.has(event.eventId)) {
        if (isLoginPresentationSequenceActive()) {
          addLoginPresentationRealmCandidate(event, loginPresentationSequence);
        } else {
          enqueueRealmAnnouncement(event);
        }
      }
    });
  }
  nextEvents.forEach(event => seenRealmActivityEventIds.add(event.eventId));
  if (seenRealmActivityEventIds.size > REALM_ACTIVITY_HISTORY_LIMIT * 2) {
    seenRealmActivityEventIds = new Set(nextEvents.map(event => event.eventId));
  }
  realmActivityHydrated = true;
  if (authoritative && isLoginPresentationSequenceActive()) {
    advanceLoginPresentationSequence(loginPresentationSequence);
  }

  if (changed) {
    updateReportUnreadBadge();
    const reportsPanelOpen = Boolean(modal?.open && modal.classList.contains("battle-report-modal"));
    const reportListOpen = reportsPanelOpen && !String(modal.dataset.battleReportDetailId || "");
    if (reportListOpen && battleReportFilter === "realm_activity") {
      const scrollTop = modalBody.scrollTop;
      showLogModal({ silentAudio: true, preserveScrollTop: scrollTop });
    } else if (reportsPanelOpen) {
      void markLoadedReportsViewed();
    }
  } else if (initial) {
    updateReportUnreadBadge();
  }
  return changed;
}

function clearOnlineRealmActivityWatcher({ clear = true } = {}) {
  if (typeof onlineRealmActivityUnsubscribe === "function") onlineRealmActivityUnsubscribe();
  onlineRealmActivityUnsubscribe = null;
  realmActivityHydrated = false;
  realmActivityAuthoritativeHydrated = false;
  if (!clear) return;
  onlineRealmActivityEvents = [];
  realmActivityLiveSinceMs = 0;
  seenRealmActivityEventIds = new Set();
  deliveredRealmAnnouncementEventIds = new Set();
  clearRealmAnnouncementQueue();
  updateReportUnreadBadge();
}

function getArmyRouteSummary(route, source, target) {
  const regionIds = getRouteSegments(route, getCityRegionId(source)).map(segment => segment.regionId);
  const sourceRegionId = getCityRegionId(source);
  const targetRegionId = getCityRegionId(target);
  if (sourceRegionId) regionIds.unshift(sourceRegionId);
  if (targetRegionId) regionIds.push(targetRegionId);
  const orderedRegionIds = regionIds
    .map(normalizeRegionId)
    .filter((regionId, index, values) => regionId && (index === 0 || regionId !== values[index - 1]));
  const portalCount = Math.max(0, orderedRegionIds.length - 1);
  const chain = orderedRegionIds.map(getRegionLabel).join(" -> ");
  return portalCount > 0
    ? `${portalCount} portal ${portalCount === 1 ? "crossing" : "crossings"}: ${chain}`
    : `Same-island route: ${chain || getRegionLabel(sourceRegionId)}`;
}

function clearOnlineGlobalStatsWatcher() {
  if (typeof onlineGlobalStatsUnsubscribe === "function") onlineGlobalStatsUnsubscribe();
  onlineGlobalStatsUnsubscribe = null;
}

function clearOnlineCrownCitadelWatcher({ clear = true } = {}) {
  if (typeof onlineCrownCitadelUnsubscribe === "function") onlineCrownCitadelUnsubscribe();
  onlineCrownCitadelUnsubscribe = null;
  if (clear) {
    onlineCrownCitadelSnapshot = null;
    onlineCrownCitadelLoaded = false;
  }
}

async function loadServerReportsOnce() {
  const api = getOnlineApi();
  if (!state || !api?.loadServerReports || !api?.isSignedIn?.()) return false;
  try {
    const reports = await withTimeout(api.loadServerReports(120), 5000, "Server reports are taking too long.");
    return mergeServerReports(reports, { notify: audioServerReportsHydrated });
  } catch (error) {
    onlineLastError = error?.message || String(error);
    console.warn("Could not load server reports", error);
    return false;
  }
}

function subscribeOnlineServerReports() {
  const api = getOnlineApi();
  if (typeof onlineServerReportsUnsubscribe === "function") return;
  if (!state || !api?.subscribeServerReports || !api?.isSignedIn?.()) return;
  onlineServerReportsUnsubscribe = api.subscribeServerReports({
    onReports: (reports, metadata = {}) => {
      const authoritative = metadata.fromCache !== true;
      const changed = mergeServerReports(reports, { notify: audioServerReportsHydrated, authoritative });
      if (authoritative) audioServerReportsHydrated = true;
      if (!changed || !usesServerEconomyAuthority()) return;
      const newestReportAtMs = (Array.isArray(reports) ? reports : []).reduce((latest, report) => (
        Math.max(
          latest,
          normalizeTimestampMs(report?.occurredAtMs),
          normalizeTimestampMs(report?.createdAtMs) || timestampToMs(report?.createdAt)
        )
      ), 0);
      const latestKnownAccountAtMs = Math.max(
        lastAuthoritativeProfileRevisionMs,
        lastReportDrivenEconomyRefreshAtMs
      );
      if (newestReportAtMs <= latestKnownAccountAtMs) return;
      lastReportDrivenEconomyRefreshAtMs = newestReportAtMs;
      refreshServerEconomy(true);
    },
    onError: error => {
      onlineLastError = error?.message || String(error);
      markOnlineRealtimeRecoveryNeeded(error);
      clearOnlineServerReportWatcher();
      console.warn("Could not subscribe to server reports", error);
    },
  });
}

